export const CONDITION_STRINGS: Record<string, { title?: string; description?: string }> = {
  "albedo_calcite_might": { title: "Calcite Might", description: "Transient Blossoms generated by Abiogenesis: Solar Isotoma deal {dmg_skill_albedo} more DMG to opponents whose HP is below 50%." },
  "albedo_descent_of_divinity": { title: "Descent of Divinity", description: "Active party members within the Solar Isotoma field have their Plunging Attack DMG increased by {dmg_plunge}." },
  "albedo_dust_of_purification": { title: "Dust of Purification", description: "Active party members within the Solar Isotoma field who are protected by a shield created by Crystallize have their DMG increased by {dmg_all}." },
  "albedo_favonius_bladework_weiss": { title: "Favonius Bladework - Weiss", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "albedo_flower_of_eden": { title: "Flower of Eden", description: "Transient Blossoms generated by Albedo's Abiogenesis: Solar Isotoma regenerate 1.2 Energy for Albedo." },
  "albedo_grace_of_helios": { title: "Grace of Helios" },
  "albedo_homuncular_nature": { title: "Homuncular Nature", description: "Using Rite of Progeniture: Tectonic Tide increases the Elemental Mastery of nearby party members by {mastery} for 10s." },
  "albedo_opening_of_phanerozoic": { title: "Opening of Phanerozoic", description: "Transient Blossoms generated by Abiogenesis: Solar Isotoma grant Albedo Fatal Reckoning for 30s: ·Unleashing Rite of Progeniture: Tectonic Tide consumes all stacks of Fatal Reckoning. Each stack of Fatal Reckoning consumed increases the DMG dealt by Fatal Blossoms and Rite of Progeniture: Tectonic Tide's burst DMG by {text_percent_dmg} of Albedo's DEF. ·This effect stacks up to 4 times." },
  "albedo_solar_isotoma": { title: "Abiogenesis: Solar Isotoma", description: "<p>Albedo creates a Solar Isotoma using alchemy, which deals AoE Geo DMG on appearance.</p><p>Solar Isotoma has the following properties: ·When opponents within the Solar Isotoma field take DMG, the Solar Isotoma will generate Transient Blossoms which deal AoE Geo DMG. DMG dealt scales off Albedo's DEF. ·Transient Blossoms can only be generated once every 2s. ·When a character is located at the locus of the Solar Isotoma, the Solar Isotoma will accumulate Geo power to form a crystallized platform that lifts the character up to a certain height. Only one crystallized platform can exist at a time. ·Solar Isotoma is considered a Geo construct. Only one Solar Isotoma created by Albedo himself can exist at a time. </p><p>Hold to designate the location of the skill.</p><p><i>This Geo bloom has an unusual property mirrored in the aim of alchemy. To rise from the earth, soar into the sky, and become the sun.</i></p>" },
  "albedo_tectonic_tide": { title: "Rite of Progeniture: Tectonic Tide", description: "<p>Under Albedo's command, Geo crystals surge and burst forth, dealing AoE Geo DMG in front of him. If a Solar Isotoma created by Albedo himself is on the field, 7 Fatal Blossoms will be generated in the Solar Isotoma field, bursting violently into bloom and dealing AoE Geo DMG.</p><p>Tectonic Tide DMG and Fatal Blossom DMG will not generate Transient Blossoms.</p><p><i>Under the Kreideprinz's command, the tectonic tide of creation seethes into life.</i></p>" },
  "albedo_tide_of_hadean": { title: "Tide of Hadean" },
  "alhaitham_abductive_reasoning": { title: "Abductive Reasoning", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "alhaitham_an_elaboration_on_form": { title: "Universality: An Elaboration on Form", description: "<p>Rushes forward, dealing Dendro DMG to nearby opponents when the rush ends, causing a Chisel-Light Mirror to form. Holding this skill will cause it to behave differently.</p><p>Hold Enters Aiming Mode to adjust the direction of Alhaitham's rush attack.</p><p>Chisel-Light Mirror When this skill is unleashed, Alhaitham will generate 1 Chisel-Light Mirror. If there are no Mirrors at this time, he will generate 1 additional Mirror. Chisel-Light Mirrors will have the following properties: ·When he possesses Chisel-Light Mirrors, Alhaitham's Normal, Charged, and Plunging Attacks will be converted to Dendro DMG. This cannot be overridden. ·When attacks of the aforementioned kind hit opponents, the Chisel-Light Mirrors will unleash a Projection Attack that deals AoE Dendro DMG based on the number of Mirrors on the field. ·A total of 3 Chisel-Light Mirrors can exist at once. ·The Chisel-Light Mirrors will disappear one after the other over time, and will all disappear when Alhaitham leaves the field.</p><p><i>\"Truth inherently exists amidst uncertainty. Even the greatest of scholars are not immune to error.\"</i></p>" },
  "alhaitham_debate": { title: "Debate", description: "When Alhaitham generates a Chisel-Light Mirror, his Elemental Mastery will be increased by {mastery} for 8 seconds, max 4 stacks. Each stack's duration is counted independently. This effect can be triggered even when the maximum number of Chisel-Light Mirrors has been reached." },
  "alhaitham_elucidation": { title: "Elucidation", description: "When Particular Field: Fetters of Phenomena is unleashed, the following effects will become active based on the number of Chisel-Light Mirrors consumed and created this time around: ·Each Mirror consumed will increase the Elemental Mastery of all other nearby party members by {text_value_mastery} for 15s. ·Each Mirror generated will grant Alhaitham a {text_value_dendro} Dendro DMG Bonus for 15s. The pre-existing duration of the aforementioned effects will be cleared if you use Particular Field: Fetters of Phenomena again while they are in effect." },
  "alhaitham_fetters_of_phenomena": { title: "Particular Field: Fetters of Phenomena", description: "<p>Creates a Particular Binding Field and deals multiple instances of AoE Dendro DMG. If Chisel-Light Mirrors exist when this ability is unleashed, all such Mirrors will be consumed and increase the number of DMG instances dealt. 2s after this ability is unleashed, if 0/1/2/3 Mirrors were consumed, Alhaitham will generate 3/2/1/0 new Mirrors in turn.</p><p><i>\"If a researcher makes wisdom their goal, then they should be prepared to make an enemy of every word they read. Only then can they avoid bias.\"</i></p>" },
  "alhaitham_four_causal_correction": { title: "Four-Causal Correction", description: "When Alhaitham's Charged or Plunging Attacks hit opponents, they will generate 1 Chisel-Light Mirror. This effect can be triggered once every 12s." },
  "alhaitham_intuition": { title: "Intuition", description: "When a Projection Attack hits an opponent, Universality: An Elaboration on Form's CD is decreased by 1.2s. This effect can be triggered once every 1s." },
  "alhaitham_mirror": { title: "Chisel-Light Mirror", description: "When he possesses Chisel-Light Mirrors, Alhaitham's Normal, Charged, and Plunging Attacks will be converted to Dendro DMG. This cannot be overridden." },
  "alhaitham_mysteries_laid_bare": { title: "Mysteries Laid Bare", description: "Each point of Alhaitham's Elemental Mastery will increase the DMG dealt by Projection Attacks and Particular Field: Fetters of Phenomena by {text_percent_dmg}. The DMG of both aforementioned abilities can be increased by a maximum of {text_percent_max} this way." },
  "alhaitham_negation": { title: "Negation" },
  "alhaitham_sagacity": { title: "Sagacity" },
  "alhaitham_structuration": { title: "Structuration", description: "Alhaitham gains the following effects: · 2 seconds after Particular Field: Fetters of Phenomena is unleashed, he will generate 3 Chisel-Light Mirrors regardless of the number of mirrors consumed. · If Alhaitham generates Chisel-Light Mirrors when their numbers have already maxed out, his CRIT Rate and CRIT DMG will increase by {crit_rate} and {crit_dmg} respectively for 6s. If this effect is triggered again during its initial duration, the duration remaining will be increased by 6s." },
  "aloy_coils": { title: "Frozen Wilds", description: "When a Freeze Bomb or Chillwater Bomblet hits an opponent, the opponent's ATK is reduced and Aloy receives 1 Coil stack. Aloy can gain up to 1 Coil stack every 0.1s. • Each stack increases Aloy's Normal Attack DMG. • When Aloy has 4 Coil stacks, she gains Rushing Ice, which converts her Normal Attack DMG to Cryo DMG. While under the effect of Rushing Ice, Aloy cannot receive new Coil stacks. Coil effects will be cleared 30s after Aloy leaves the field." },
  "aloy_combat_override": { title: "Combat Override", description: "When Aloy receives the Coil effect from Frozen Wilds, her ATK is increased by {text_percent_1}, while nearby party members' ATK is increased by {text_percent_2}. This effect lasts 10s." },
  "aloy_frozen_wilds": { title: "Frozen Wilds", description: "<p>Aloy throws a Freeze Bomb in the targeted direction that explodes on impact, dealing Cryo DMG. After it explodes, the Freeze Bomb will split up into many Chillwater Bomblets that explode on contact with opponents or after a short delay, dealing Cryo DMG. When a Freeze Bomb or Chillwater Bomblet hits an opponent, the opponent's ATK is decreased and Aloy receives 1 Coil stack. Aloy can gain up to 1 Coil stack every 0.1s.</p><p>Coil ·Each stack increases Aloy's Normal Attack DMG. ·When Aloy has 4 Coil stacks, all stacks of Coil are cleared. She then enters the Rushing Ice state, which further increases the DMG dealt by her Normal Attacks and converts her Normal Attack DMG to Cryo DMG.</p><p>While in the Rushing Ice state, Aloy cannot obtain new Coil stacks. Coil effects will be cleared 30s after Aloy leaves combat.</p><p><i>You think that's cold? Guess you've never been to The Cut.</i></p>" },
  "aloy_prophecies_of_dawn": { title: "Prophecies of Dawn", description: "<p>Aloy throws a Power Cell filled with Cryo in the targeted direction, then detonates it with an arrow, dealing AoE Cryo DMG.</p><p><i>Whether \"Zero Dawn\" referred to hope or extinction no longer matters. Aloy has already saved her world, and the fate of this one is still being forged by its own heroes.</i></p>" },
  "aloy_rapid_fire": { title: "Rapid Fire", description: "<p>Normal Attack Performs up to 4 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, biting frost will accumulate on the arrowhead. A fully charged frost arrow will deal Cryo DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "aloy_star_of_another_world": { title: "Star of Another World", description: "The time has not yet come for this person's corner of the night sky to light up." },
  "aloy_strong_strike": { title: "Strong Strike", description: "When Aloy is in the Rushing Ice state conferred by Frozen Wilds, her Cryo DMG Bonus increases by {dmg_cryo} every 1s. A maximum Cryo DMG Bonus increase of {text_percent} can be gained in this way." },
  "amber_bunny_triggered": { title: "Bunny Triggered", description: "Baron Bunny, new and improved! Hitting Baron Bunny's foot with a fully-charged Aimed Shot manually detonates it. Explosion via manual detonation deals {dmg_skill_amber} additional DMG." },
  "amber_every_arrow_finds_its_target": { title: "Every Arrow Finds Its Target", description: "Increases the CRIT Rate of Fiery Rain by {crit_rate_amber} and widens its AoE by {text_percent_radius}." },
  "amber_explosive_puppet": { title: "Explosive Puppet", description: "<p>The ever-reliable Baron Bunny takes the stage.</p><p>Baron Bunny ·Continuously taunts the enemy, drawing their fire. ·Baron Bunny's HP scales with Amber's Max HP. ·When destroyed or when its timer expires, Baron Bunny explodes, dealing AoE Pyro DMG.</p><p>Hold Adjusts the throwing direction of Baron Bunny. The longer the button is held, the further the throw.</p><p><i>Baron Bunny hails from a storied lineage, but Amber has stopped keeping count since Baron Bunny the 893rd.</i></p>" },
  "amber_fiery_rain": { title: "Fiery Rain", description: "<p>Fires off a shower of arrows, dealing continuous AoE Pyro DMG.</p><p><i>Amber's passion truly burns hot.</i></p>" },
  "amber_it_burns": { title: "It Burns!" },
  "amber_its_baron_bunny": { title: "It's Baron Bunny!" },
  "amber_its_not_just_any_doll": { title: "It's Not Just Any Doll...", description: "Decreases Explosive Puppet's CD by {text_percent_cd}. Adds 1 additional charge." },
  "amber_one_arrow_to_rule_them_all": { title: "One Arrow to Rule Them All", description: "Fires 2 arrows per Aimed Shot. The second arrow deals {text_percent_dmg} of the first arrow's DMG." },
  "amber_precise_shot": { title: "Precise Shot", description: "Aimed Shot hits on weak points increase ATK by {atk_percent} for 10s." },
  "amber_sharpshooter": { title: "Sharpshooter", description: "<p>Normal Attack Performs up to 5 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, flames will accumulate on the arrowhead. A fully charged flaming arrow will deal Pyro DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "amber_wildfire": { title: "Wildfire", description: "Fiery Rain increases all party members' Movement SPD by {move_speed} and ATK by {atk_percent} for 10s." },
  "aqua_simulacra": { title: "The Cleansing Form" },
  "aqua_simulacra_1": { description: "HP is increased by {hp_percent}." },
  "aqua_simulacra_2": { description: "When there are opponents nearby, the DMG dealt by the wielder of this weapon is increased by {dmg_all}. This will take effect whether the character is on-field or not." },
  "arataki_itto_10_years_of_hanamizaka_fame": { title: "10 Years of Hanamizaka Fame" },
  "arataki_itto_akaushi_burst": { title: "Masatsu Zetsugi: Akaushi Burst!", description: "<p>Hurls Ushi, the young akaushi bull and auxiliary member of the Arataki Gang, dealing Geo DMG to opponents on hit. When Ushi hits opponents, Arataki Itto gains 1 stack of Superlative Superstrength.</p><p>Ushi will remain on the field and provide support in the following ways: · Taunts surrounding opponents and draws their attacks. · Inherits HP based on a percentage of Arataki Itto's Max HP. · When Ushi takes DMG, Arataki Itto gains 1 stack of Superlative Superstrength. Only 1 stack can be gained in this way every 2s. · Ushi will flee when its HP reaches 0 or its duration ends. It will grant Arataki Itto 1 stack of Superlative Superstrength when it leaves.</p><p>Hold Adjust throwing angle.</p><p>Ushi is considered a Geo construct. Arataki Itto can only deploy 1 Ushi on the field at any one time.</p><p><i>The name of this technique is derived from Onibudou (a light novel series written by Junkichi). However, calling it \"Onisatsu Zetsugi\" probably constitutes copyright infringement — not to mention how Itto himself is an oni and all...</i></p>" },
  "arataki_itto_arataki_ichiban": { title: "Arataki Ichiban", description: "When Arataki Itto uses consecutive Arataki Kesagiri, he obtains the following effects: · Each slash increases the ATK SPD of the next slash by {atk_speed_charged}. Max ATK SPD increase is {text_percent_max}. · Increases his resistance to interruption. These effects will be cleared once he stops performing consecutive slashes." },
  "arataki_itto_arataki_itto_present": { title: "Arataki Itto, Present!", description: "Arataki Itto's Charged Attacks deal +{crit_dmg_charged} CRIT DMG. Additionally, when he uses Arataki Kesagiri, he has a 50% chance to not consume stacks of Superlative Superstrength." },
  "arataki_itto_behold_itto_the_evil": { title: "Royal Descent: Behold, Itto the Evil!", description: "<p>Time to show 'em the might of the Arataki Gang! For a time, Itto lets out his inner Raging Oni King, wielding his Oni King's Kanabou in battle. This state has the following special properties: · Converts Itto's Normal, Charged, and Plunging Attacks to Geo DMG. This cannot be overridden. · Increases Itto's Normal Attack SPD. Also increases his ATK based on his DEF. · On hit, the 1st and 3rd strikes of his attack combo will each grant Arataki Itto 1 stack of Superlative Superstrength. · Decreases Itto's Elemental and Physical RES by 20%.</p><p>The Raging Oni King state will be cleared when Itto leaves the field.</p><p><i>This is the pinnacle technique of the ultimate fighting style (according to Itto). It would be pointless for Arataki Itto to reference any other fighting styles to improve his own, for he, and no other, is the strongest, most terrible oni in the land.</i> <i>Shouta thinks it looks really cool.</i></p>" },
  "arataki_itto_bloodline_of_the_crimson_oni": { title: "Bloodline of the Crimson Oni", description: "Arataki Kesagiri DMG is increased by {text_percent} of Arataki Itto's DEF." },
  "arataki_itto_fight_club_legend": { title: "Fight Club Legend", description: "<p>Normal Attack Performs up to 4 consecutive strikes. When the 2nd and 4th strikes hit opponents, Itto will gain 1 and 2 stacks of Superlative Superstrength, respectively. Max 5 stacks. Triggering this effect will refresh the current duration of any existing stacks.</p><p>Additionally, Itto's Normal Attack combo does not immediately reset after sprinting or using his Elemental Skill, \"Masatsu Zetsugi: Akaushi Burst!\"</p><p>Charged Attack When holding to perform a Charged Attack, Itto unleashes a series of Arataki Kesagiri slashes without consuming Stamina. Instead, each Arataki Kesagiri slash consumes 1 stack of Superlative Superstrength. When the final stack is consumed, Itto delivers a powerful final slash. If no stacks of Superlative Superstrength are available, Itto will perform a single Saichimonji Slash.</p><p>Plunging Attack Plunges from mid-air to strike the ground, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "arataki_itto_gather_round_its_a_brawl": { title: "Gather 'Round, It's a Brawl!", description: "After using Royal Descent: Behold, Itto the Evil!, each party member whose Element is Geo will decrease that skill's CD by 1.5s and restore 6 Energy to Arataki Itto. CD can be decreased by up to 4.5s in this manner. Max 18 Energy can be restored in this manner." },
  "arataki_itto_horns_lowered_coming_through": { title: "Horns Lowered, Coming Through" },
  "arataki_itto_jailhouse_bread_and_butter": { title: "Jailhouse Bread and Butter", description: "When the Raging Oni King state caused by Royal Descent: Behold, Itto the Evil! ends, all nearby party members gain {def_percent} DEF and {atk_percent} ATK for 10s." },
  "arataki_itto_stay_a_while_and_listen_up": { title: "Stay a While and Listen Up", description: "After using Royal Descent: Behold, Itto the Evil!, Arataki Itto gains 2 stacks of Superlative Superstrength. After 1s, Itto will gain 1 stack of Superlative Superstrength every 0.5s for 1.5s." },
  "arlecchino_agony_alone_may_be_repaid": { title: "Agony Alone May Be Repaid", description: "Blood-Debt Directives have the following characteristics: ·Arlecchino will be granted a Bond of Life worth {text_percent} of her Max HP when an opponent to which she herself applied a Directive is defeated. ·5s after a Directive is applied, it will be upgraded to a Blood-Debt Due. When absorbed, it will instead grant Arlecchino a Bond of Life worth {text_percent}. A Bond of Life created in the aforementioned ways cannot exceed the original limit on the value of Bonds of Life obtained through All Is Ash." },
  "arlecchino_all_is_ash": { title: "All Is Ash", description: "<p>Summons forth Balemoon Bloodfire, dealing Pyro DMG to multiple nearby opponents and performing a dash-cleave against one of them, dealing AoE Pyro DMG. Opponents hit by the aforementioned attack will have a Blood-Debt Directive applied to them.</p><p>Blood-Debt Directive ·Lasts 30s. Every 5s, it will deal 1 instance of Pyro DMG to the opponent. Max 2 instances. This DMG will be considered Elemental Skill DMG. ·When Arlecchino uses a Charged Attack or her Elemental Burst, Balemoon Rising, she will absorb and clear nearby Blood-Debt Directives. Each Directive absorbed grants her a Bond of Life worth 65% of her Max HP. ·The maximum value of the Bond of Life she can be granted through Blood-Debt Directives within 35s after using her Elemental Skill is 145% of her Max HP. Using the Elemental Skill again during this duration will restart the count on duration and the limit on the value of Bond of Life she may gain from Blood-Debt Directives.</p><p><i>As she sees it, not every grain of wheat that falls upon the earth will grow into an ear, while those who obstruct her, once burned to ashes, can certainly be used to nourish flowers.</i></p>" },
  "arlecchino_all_reprisals_and_arrears_mine_to_bear": { title: "\"All Reprisals and Arrears, Mine to Bear...\"", description: "Masque of the Red Death is further enhanced, the value of the increase is {text_percent_dmg}. Additionally, Arlecchino's interruption resistance is increased when she performs Normal or Charged Attacks while affected by the Masque of the Red Death." },
  "arlecchino_all_rewards_and_retribution_mine_to_bestow": { title: "\"All Rewards and Retribution, Mine to Bestow...\"", description: "Blood-Debt Directives are now already Blood-Debt Due when first applied. When Arlecchino absorbs such a Due, she unleashes Balemoon Bloodfire in front of her, dealing {text_percent_dmg} of her ATK as AoE Pyro DMG and increasing her All Elemental RES and Physical RES by {text_percent} for 15s. This effect can trigger once every 10s. You must first unlock the Passive Talent \"Agony Alone May Be Repaid.\"" },
  "arlecchino_balemoon_rising": { title: "Balemoon Rising", description: "<p>Arlecchino's great wing of Balemoon Bloodfire beats as she absorbs and clears Blood-Debt Directives around her. She deals AoE Pyro DMG before clearing the CD of All Is Ash and healing herself. The healing is based on her Bond of Life value and ATK.</p><p><i>It is commonly believed throughout Teyvat that moon phases other than the full moon are mere metaphors of ill-omen, used only by those who practice alchemy and astrology. She saw this crimson moon in her dreams many times. Were those portents of disaster? Indeed they were, but the destined catastrophes belonged to those who enraged her.</i></p>" },
  "arlecchino_for_alone_we_are_as_good_as_dead": { title: "\"For Alone, We Are as Good as Dead...\"" },
  "arlecchino_from_this_day_on_we_shall_delight_in_new_life_together": { title: "\"From This Day On, We Shall Delight in New Life Together.\"" },
  "arlecchino_from_this_day_on_we_shall_delight_in_new_life_together_1": { description: "The DMG of Balemoon Rising is increased by Arlecchino's ATK multiplied by {text_percent_dmg} of Arlecchino's current Bond of Life percentage." },
  "arlecchino_from_this_day_on_we_shall_delight_in_new_life_together_2": { description: "For 20s after Arlecchino uses All Is Ash, both her Normal Attacks and Elemental Burst gain {crit_rate_normal_arlecchino} increased CRIT Rate and {crit_dmg_normal_arlecchino} increased CRIT DMG. This effect can be triggered up to once every 15s." },
  "arlecchino_invitation_to_a_beheading": { title: "Invitation to a Beheading", description: "<p>Normal Attack Performs up to 6 consecutive spear strikes.</p><p>Charged Attack Consumes a fixed amount of Stamina, dashing toward a nearby opponent and cleaving once. Continuously holding this button will cause Arlecchino to consume Stamina and engage in up to 5s of high-speed movement.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p><p>Masque of the Red Death When Arlecchino has a Bond of Life equal to or greater than 30% of her Max HP, she will enter the \"Masque of the Red Death\" state, where her Normal, Charged, and Plunging Attacks will be converted to deal Pyro DMG. This cannot be overridden. When in the \"Masque of the Red Death\" state, Arlecchino's Normal Attacks will deal extra DMG to opponents on hit that scales off her ATK multiplied by a certain ratio of her current Bond of Life percentage. This will consume 7.5% of said current Bond of Life. Her Bond of Life can be consumed this way every 0.03s. When her Bond of Life is consumed in this manner, All Is Ash's CD will decrease by 0.8s.</p>" },
  "arlecchino_strength_alone_can_defend": { title: "Strength Alone Can Defend", description: "Arlecchino gains {text_percent} All Elemental and Physical RES for every 100 ATK she has in excess of 1,000. The maximum RES increase she can gain this way for each is {text_percent_max}." },
  "arlecchino_you_shall_become_a_new_member_of_our_family": { title: "\"You Shall Become a New Member of Our Family...\"" },
  "arlecchino_you_shall_love_and_protect_each_other_henceforth": { title: "\"You Shall Love and Protect Each Other Henceforth...\"", description: "When Arlecchino successfully absorbs a Blood-Debt Directive, Balemoon Rising's CD will decrease by 2s and 15 Elemental Energy will be restored to her. This effect can occur once every 10s." },
  "ayato_bloomwater_blades": { title: "Bloomwater Blades", description: "Unveils a garden of purity that silences the cacophony within. While this space exists, Bloomwater Blades will constantly rain down and attack opponents within its AoE, dealing Hydro DMG and increasing the Normal Attack DMG of characters within." },
  "ayato_namisen": { title: "Namisen stacks", description: "Increase the DMG dealt by Shunsuiken based on Ayato's current Max HP" },
  "ayato_takimeguri_kanka": { title: "Takimeguri Kanka", description: "In this state, Kamisato Ayato uses his Shunsuiken to engage in blindingly fast attacks, causing DMG from his Normal Attacks to be converted into AoE Hydro DMG. This cannot be overridden. It also has the following properties: ·After a Shunsuiken attack hits an opponent, it will grant Ayato the Namisen effect, increasing the DMG dealt by Shunsuiken based on Ayato's current Max HP. The initial maximum number of Namisen stacks is 4, and 1 stack can be gained through Shunsuiken every 0.1s. This effect will be dispelled when Takimeguri Kanka ends. ·Kamisato Ayato's resistance to interruption is increased. ·Unable to use Charged or Plunging Attacks. Takimeguri Kanka will be cleared when Ayato leaves the field." },
  "baal_eye_of_stormy_judgment": { title: "Eye of Stormy Judgment", description: "Characters who gain the Eye of Stormy Judgment will have their Elemental Burst DMG increased based on the Energy Cost of the Elemental Burst during the Eye's duration." },
  "baal_musou_isshin": { title: "Musou Isshin", description: "While in this state, the Raiden Shogun will wield her tachi in battle, while her Normal, Charged, and Plunging Attacks will be infused with Electro DMG, which cannot be overridden. When such attacks hit opponents, she will regenerate Energy for all nearby party members. Energy can be restored this way once every 1s, and this effect can be triggered 5 times throughout this skill's duration. While in this state, the Raiden Shogun's resistance to interruption is increased, and she is immune to Electro-Charged reaction DMG. While Musou Isshin is active, the Raiden Shogun's Normal, Charged, and Plunging Attack DMG will be considered Elemental Burst DMG." },
  "baal_resolve_stacks": { title: "Resolve stacks", description: "The DMG dealt by Musou no Hitotachi and Musou Isshin's attacks will be increased based on the number of Chakra Desiderata's Resolve stacks consumed when this skill is used." },
  "baizhu_all_aspects_stabilized": { title: "All Aspects Stabilized" },
  "baizhu_all_things_are_of_the_earth": { title: "All Things Are of the Earth", description: "Characters who are healed by Seamless Shields will gain the Year of Verdant Favor effect: Each 1,000 Max HP that Baizhu possesses that does not exceed 50,000 will increase the Burning, Bloom, Hyperbloom, and Burgeon reaction DMG dealt by these characters by 2%, while the Aggravate and Spread reaction DMG dealt by these characters will be increased by 0.8%. This effect lasts 6s." },
  "baizhu_ancient_art_of_perception": { title: "Ancient Art of Perception", description: "For 15s after Holistic Revivification is used, Baizhu will increase all nearby party members' Elemental Mastery by {mastery}." },
  "baizhu_attentive_observation": { title: "Attentive Observation", description: "Universal Diagnosis gains 1 additional charge." },
  "baizhu_elimination_of_malicious_qi": { title: "Elimination of Malicious Qi", description: "Increases the DMG dealt by Holistic Revivification's Spiritveins by {burst_base_hp_percent} of Baizhu's Max HP. Additionally, when a Gossamer Sprite or Gossamer Sprite: Splice hits opponents, there is a 100% chance of generating one of Holistic Revivification's Seamless Shields. This effect can only be triggered once by each Gossamer Sprite or Gossamer Sprite: Splice." },
  "baizhu_five_fortunes_forever": { title: "Five Fortunes Forever" },
  "baizhu_five_fortunes_forever_1": { description: "Baizhu gains different effects according to the current HP of your current active character: When their HP is less than 50%, Baizhu gains {healing} Healing Bonus." },
  "baizhu_five_fortunes_forever_2": { description: "Baizhu gains different effects according to the current HP of your current active character: When their HP is equal to or more than 50%, Baizhu gains {dmg_dendro} Dendro DMG Bonus." },
  "baizhu_holistic_revivification": { title: "Holistic Revivification", description: "<p>Enters the Pulsing Clarity state, creating a Seamless Shield that absorbs Dendro DMG with 250% effectiveness. While in this state, Baizhu will generate a new Seamless Shield every 2.5s.</p><p>The Seamless Shield will heal your own active character based on Baizhu's Max HP and attack opponents by unleashing Spiritveins, dealing Dendro DMG under the following circumstances: ·When a character is under the protection of a Seamless Shield and a new Seamless Shield is generated. ·When the Seamless Shield's effects expire, or when it is shattered.</p><p><i>If you can perceive the heavens and the earth, defend against malignant auras with the flow of qi, and keep your mind clear, surely nothing can hinder you.</i></p>" },
  "baizhu_incisive_discernment": { title: "Incisive Discernment", description: "When your own active character hits a nearby opponent with their attacks, Baizhu will unleash a Gossamer Sprite: Splice. Gossamer Sprite: Splice will initiate 1 attack before returning, dealing 250% of Baizhu's ATK as Dendro DMG and healing for 20% of Universal Diagnosis's Gossamer Sprite's normal healing. DMG dealt this way is considered Elemental Skill DMG. This effect can be triggered once every 5s." },
  "baizhu_the_classics_of_acupuncture": { title: "The Classics of Acupuncture", description: "<p>Normal Attack Performs up to 4 attacks that deal Dendro DMG to opponents in front of him.</p><p>Charged Attack Consumes a certain amount of Stamina to deal AoE Dendro DMG to opponents in front of him after a short casting time.</p><p>Plunging Attack Calling upon the might of Dendro, Baizhu plunges towards the ground from mid-air, damaging all opponents in his path. Deals AoE Dendro DMG upon impact with the ground.</p>" },
  "baizhu_the_hidden_ebb_and_flow": { title: "The Hidden Ebb and Flow" },
  "baizhu_universal_diagnosis": { title: "Universal Diagnosis", description: "<p>Controls a Gossamer Sprite that cruises and attacks nearby opponents, dealing Dendro DMG. After it performs 3 attacks or if there are no opponents nearby, the Sprite will return, healing all nearby party members based on Baizhu's Max HP.</p><p><i>Those in the medical field who can read true signs of illness from false ones may even cure people before any symptoms can show.</i></p>" },
  "barbara_attentiveness_be_my_power": { title: "Attentiveness Be My Power", description: "Every opponent Barbara hits with her Charged Attack regenerates 1 Energy for her. A maximum of 5 energy can be regenerated in this manner with any one Charged Attack." },
  "barbara_dedicating_everything_to_you": { title: "Dedicating Everything to You", description: "When Barbara is in the party but not on the field, and one of your own party members falls: ·Automatically revives the fallen character. ·Fully restores the revived character's HP to 100%. This effect can only occur once every 15 mins." },
  "barbara_encore": { title: "Encore", description: "When your active character gains an Elemental Orb/Particle, the duration of the Melody Loop of Let the Show Begin♪ is extended by 1s. The maximum extension is 5s." },
  "barbara_gleeful_songs": { title: "Gleeful Songs", description: "Barbara regenerates 1 Energy every 10s." },
  "barbara_glorious_season": { title: "Glorious Season", description: "The Stamina Consumption of characters within Let the Show Begin♪'s Melody Loop is reduced by {stamina_consume}." },
  "barbara_let_the_show_begin": { title: "Let the Show Begin♪", description: "<p>Summons water droplets resembling musical notes that form a Melody Loop, dealing Hydro DMG to surrounding opponents and applying the Wet status to them.</p><p>Melody Loop ·On hit, Barbara's Normal Attacks heal your own party members and nearby teammates for a certain amount of HP, which scales with Barbara's Max HP. ·On hit, Barbara's Charged Attack generates 4 times the amount of healing. ·Periodically regenerates your own active character's HP. ·Applies the Wet status to the character and to opponents who come in contact with them.</p><p><i>Barbara's music is the magic that heals her companions.</i></p>" },
  "barbara_shining_miracle": { title: "Shining Miracle♪", description: "<p>Heals your own party members and nearby teammates for a large amount of HP that scales with Barbara's Max HP.</p><p><i>Barbara's desire to heal strengthens her will to fight and sing.</i></p>" },
  "barbara_star_of_tomorrow": { title: "Star of Tomorrow" },
  "barbara_the_purest_companionship": { title: "The Purest Companionship" },
  "barbara_vitality_burst": { title: "Vitality Burst", description: "Decreases the CD of Let the Show Begin♪ by {text_percent_cd}. During the ability's duration, your active character gains a {dmg_hydro} Hydro DMG Bonus." },
  "barbara_whisper_of_water": { title: "Whisper of Water", description: "<p>Normal Attack Performs up to 4 water splash attacks that deal Hydro DMG.</p><p>Charged Attack Consumes a certain amount of Stamina to deal AoE Hydro DMG after a short casting time.</p><p>Plunging Attack Gathering the might of Hydro, Barbara plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Hydro DMG upon impact with the ground.</p>" },
  "beidou_bane_of_evil": { title: "Bane of Evil", description: "During the duration of Stormbreaker, the Electro RES of surrounding opponents is decreased by {enemy_res_electro}." },
  "beidou_crimson_tidewalker": { title: "Crimson Tidewalker" },
  "beidou_lightning_storm": { title: "Lightning Storm", description: "Gain the following effects for 10s after unleashing Tidecaller with its maximum DMG Bonus: ·DMG dealt by Normal and Charged Attacks is increased by {dmg_normal}. ATK SPD of Normal and Charged Attacks is increased by {atk_speed}. ·Greatly reduced delay before unleashing Charged Attacks." },
  "beidou_oceanborne": { title: "Oceanborne", description: "<p>Normal Attack Performs up to 5 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous slashes. At the end of the sequence, performs a more powerful slash.</p><p>Plunging Attack Plunges from mid-air to strike the ground, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "beidou_retribution": { title: "Retribution", description: "Counterattacking with Tidecaller at the precise moment when the character is hit grants the maximum DMG Bonus." },
  "beidou_sea_beasts_scourge": { title: "Sea Beast's Scourge", description: "When Stormbreaker is used: Creates a shield that absorbs up to {text_percent_shield} of Beidou's Max HP for 15s. This shield absorbs Electro DMG 250% more effectively." },
  "beidou_stormbreaker": { title: "Stormbreaker", description: "<p>Recalling her slaying of the great beast Haishan, Beidou calls upon that monstrous strength and the lightning to create a Thunderbeast's Targe around herself, dealing Electro DMG to nearby opponents.</p><p>Thunderbeast's Targe ·When Normal and Charged Attacks hit, they create a lightning discharge that can jump between opponents, dealing Electro DMG. ·Increases the character's resistance to interruption, and decreases DMG taken.</p><p>A maximum of 1 lightning discharge can be triggered per second.</p><p><i>With a peal of thunder, Haishan is slain.</i></p>" },
  "beidou_stunning_revenge": { title: "Stunning Revenge", description: "Upon being attacked, Beidou's Normal Attacks gain an additional instance of {text_percent_dmg} Electro DMG for 10s." },
  "beidou_summoner_of_storm": { title: "Summoner of Storm" },
  "beidou_tidecaller": { title: "Tidecaller", description: "<p>Nothing to worry about. Should anyone raise a hand against her or her men, she will avenge it ten-fold with sword and thunder.</p><p>Press Accumulating the power of lightning, Beidou swings her blade forward fiercely, dealing Electro DMG.</p><p>Hold Lifts her weapon up as a shield. Max DMG absorbed scales off Beidou's Max HP. Attacks using the energy stored within the greatsword upon release or once this ability's duration expires, dealing Electro DMG. DMG dealt scales with the number of times Beidou is attacked in the skill's duration. The greatest DMG Bonus will be attained once this effect is triggered twice. The shield possesses the following properties: ·Has 250% Electro DMG Absorption Efficiency. ·Applies the Electro element to Beidou upon activation.</p><p><i>Conquer the high seas! Pursue the waves and chase the storm!</i></p>" },
  "beidou_upon_the_turbulent_sea_the_thunder_arises": { title: "Upon the Turbulent Sea, the Thunder Arises", description: "Stormbreaker's arc lightning can jump to 2 additional targets." },
  "bennett_fantastic_voyage": { title: "Fantastic Voyage", description: "<p>Bennett performs a jumping attack that deals Pyro DMG, creating an Inspiration Field.</p><p>Inspiration Field ·If the health of a character within the AoE is equal to or falls below 70%, their health will continuously regenerate. The amount of HP restored scales off Bennett's Max HP. ·If the health of a character within the AoE is higher than 70%, they gain an ATK Bonus that is based on Bennett's Base ATK. ·Imbues characters within the AoE with Pyro.</p><p><i>Benny's Adventure Team's adventures are always fraught with unexpected danger. However, Bennett is more inclined to call them \"journeys full of wonder, excitement, and beauty.\"</i></p>" },
  "bennett_fantastic_voyage_talent": { description: "• If the health of a character within the AoE is equal to or falls below 70%, their health will continuously regenerate. The amount of HP restored scales off Bennett's Max HP. • If the health of a character within the AoE is higher than 70%, they gain an ATK Bonus that is based on Bennett's Base ATK. • Imbues characters within the AoE with Pyro." },
  "bennett_fearnaught": { title: "Fearnaught", description: "Within the area created by Fantastic Voyage, Passion Overload takes on the following effects: ·CD is reduced by {text_percent_cd}. ·Bennett will not be launched by the effects of Charge Level 2." },
  "bennett_fire_ventures_with_me": { title: "Fire Ventures With Me", description: "Sword, Claymore, or Polearm-wielding characters inside Fantastic Voyage's radius gain a {text_percent} Pyro DMG Bonus and their weapons are infused with Pyro." },
  "bennett_grand_expectation": { title: "Grand Expectation", description: "Fantastic Voyage's ATK increase no longer has an HP restriction, and gains an additional {bonus_bennet_atk} of Bennett's Base ATK." },
  "bennett_impasse_conqueror": { title: "Impasse Conqueror", description: "When Bennett's HP falls below {text_percent_hp}, his Energy Recharge is increased by {recharge}." },
  "bennett_passion_overload": { title: "Passion Overload", description: "<p>Bennett puts all his fire and passion for adventuring into his sword. Results may vary based on how fired up he is...</p><p>Press A single, swift flame strike that deals Pyro DMG.</p><p>Hold (Short) Charges up, resulting in different effects when unleashed based on the Charge Level. ·Level 1: Strikes twice, dealing Pyro DMG and launching opponents. ·Level 2: Unleashes 3 consecutive attacks that deal impressive Pyro DMG, but the last attack triggers an explosion that launches both Bennett and the enemy. Bennett takes no damage from being launched.</p><p><i>An attack that combines Bennett's dreams and passion with Pyro. But passion is sometimes overblown, and Pyro sometimes blows over.</i></p>" },
  "bennett_rekindle": { title: "Rekindle", description: "Decreases Passion Overload's CD by {text_percent_cd}." },
  "bennett_strike_of_fortune": { title: "Strike of Fortune", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "bennett_true_explorer": { title: "True Explorer" },
  "bennett_unexpected_odyssey": { title: "Unexpected Odyssey", description: "Using a Normal Attack as the second attack of Passion Overload's Charge Level 1 will perform a follow-up attack. This additional attack does {text_percent_dmg} of the second attack's DMG." },
  "bennett_unstoppable_fervor": { title: "Unstoppable Fervor" },
  "candace_aegis_of_crossed_arrows": { title: "Aegis of Crossed Arrows", description: "If Candace is hit by an attack in the Hold duration of Sacred Rite: Heron's Sanctum, that skill will finish charging instantly." },
  "candace_celestial_dome_of_sand": { title: "Celestial Dome of Sand", description: "Characters affected by the Prayer of the Crimson Crown caused by Sacred Rite: Wagtail's Tide will deal 0.5% increased DMG to opponents for every 1,000 points of Candace's Max HP when they deal Elemental DMG with their Normal Attacks." },
  "candace_gleaming_spear_guardian_stance": { title: "Gleaming Spear - Guardian Stance", description: "<p>Normal Attack Performs up to 4 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "candace_herons_sanctum": { title: "Sacred Rite: Heron's Sanctum", description: "<p>Candace's fighting style is capable of warding off an entire tide of foes.</p><p>Tap Rushes forward with her shield, dealing Hydro DMG to opponents in front of her.</p><p>Hold Raises her shield to block incoming attacks from nearby opponents, forming a barrier that absorbs DMG based on her Max HP and absorbs Hydro DMG 250% more effectively. This barrier lasts until the Elemental Skill is unleashed. After holding for a certain period of time, Candace will finish charging, and when the skill button is released, the skill duration expires, or when the barrier is broken, she will perform a leaping strike that deals Hydro DMG to opponents in front of her.</p><p><i>The oath of the guardians is more stalwart yet than the shields they inherit.</i></p>" },
  "candace_heterochromatic_gaze": { title: "Heterochromatic Gaze" },
  "candace_hunters_supplication": { title: "Hunter's Supplication" },
  "candace_moon_piercing_brilliance": { title: "Moon-Piercing Brilliance", description: "When Sacred Rite: Heron's Sanctum hits opponents, Candace's Max HP will be increased by {hp_percent} for 15s." },
  "candace_prayer_of_the_crimson_crown": { title: "Prayer of the Crimson Crown", description: "This effect has the following properties: ·Characters deal increased Elemental DMG with their Normal Attacks. ·Whenever a character takes the field, they will unleash a rippling wave of water that deals Hydro DMG to nearby opponents. There is a limited number of waves that can be triggered in the duration of this skill. ·Sword, Claymore, and Polearm-wielding characters under this effect will obtain a Hydro Infusion." },
  "candace_returning_heiress_of_the_scarlet_sands": { title: "Returning Heiress of the Scarlet Sands", description: "The duration of Prayer of the Crimson Crown effect triggered by Sacred Rite: Wagtail's Tide is increased by 3s." },
  "candace_sentinel_oath": { title: "Sentinel Oath", description: "Shortens the Hold CD of Sacred Rite: Heron's Sanctum to be the same as that of the Tapping CD." },
  "candace_the_overflow": { title: "The Overflow", description: "When characters (excluding Candace herself) affected by the Prayer of the Crimson Crown caused by Sacred Rite: Wagtail's Tide deal Elemental DMG to opponents using Normal Attacks, an attack wave will be unleashed that deals AoE Hydro DMG equal to {text_percent_dmg} of Candace's Max HP. This effect can trigger once every 2.3s and is considered Elemental Burst DMG." },
  "candace_wagtails_tide": { title: "Sacred Rite: Wagtail's Tide", description: "<p>Raising her weapon on high, Candace calls upon a divine blessing that deals AoE Hydro DMG based on her Max HP and continuously confers the Prayer of the Crimson Crown on your active character.</p><p>Prayer of the Crimson Crown This effect has the following properties: ·Characters deal increased Elemental DMG with their Normal Attacks. ·Whenever a character takes the field, they will unleash a rippling wave of water that deals Hydro DMG to nearby opponents. There is a limited number of waves that can be triggered in the duration of this skill. ·Sword, Claymore, and Polearm-wielding characters under this effect will obtain a Hydro Infusion.</p><p><i>This secret rite has been passed down through Candace's clan from generation to generation. Though the old faiths have become lost over the years, the sands still protect the heirs of the ancient realm.</i></p>" },
  "charlotte_a_duty_to_pursue_truth": { title: "A Duty to Pursue Truth", description: "When using Framing: Freezing Point Composition, when Monsieur Verite hits 1/2/3 (or more) opponents, Charlotte's own ATK will be increased by 10%/20%/30% for 12s." },
  "charlotte_a_need_to_verify_facts": { title: "A Need to Verify Facts", description: "After Still Photo: Comprehensive Confirmation heals a character, it will mark them with Verification, which will heal them once every 2s for {text_percent_heal} of Charlotte's ATK. This effect lasts 6s." },
  "charlotte_a_principle_of_conscience": { title: "A Principle of Conscience" },
  "charlotte_a_responsibility_to_oversee": { title: "A Responsibility to Oversee", description: "When Still Photo: Comprehensive Confirmation hits an opponent marked by Snappy Silhouette or Focused Impression, it will deal {text_percent_dmg} more DMG and restore 2 Energy to Charlotte. This restoration can be triggered 5 times every 20s." },
  "charlotte_a_summation_of_interest": { title: "A Summation of Interest", description: "When the active character's Normal and Charged Attacks hit an opponent marked by Framing: Freezing Point Composition's Focused Impression, Monsieur Verite will initiate a coordinated attack that deals {text_percent_dmg} of Charlotte's ATK as AoE Cryo DMG and heals active character(s) within the AoE for {text_percent_heal} of Charlotte's ATK. This effect can be triggered once every 6s and both DMG and healing dealt in this way will be considered as having been done by Charlotte's Elemental Burst." },
  "charlotte_an_imperative_to_independence": { title: "An Imperative to Independence" },
  "charlotte_comprehensive_confirmation": { title: "Still Photo: Comprehensive Confirmation", description: "<p>Condensing ice to create The Steambird's signature, Charlotte creates a Newsflash Field that will deal AoE Cryo DMG and restores HP for all nearby party members based on Charlotte's ATK. Newsflash Field ·While the ability is active, Monsieur Verite will deal Cryo DMG at intervals to opponents within its AoE. ·Will continuously restore HP to active character(s) within its AoE based on Charlotte's ATK.</p><p><i>\"Hearing stories from multiple perspectives to recreate what really happened is key to a good report... I mean, that's how you can pick the best angle for your article!\"</i></p>" },
  "charlotte_cool_color_capture": { title: "Cool-Color Capture", description: "<p>Normal Attack Taking aim at targets using Monsieur Verite, her custom Kamera, Charlotte performs up to 3 consecutive attacks, dealing Cryo DMG.</p><p>Charged Attack Consumes a fixed amount of Stamina, and after a moment's preparation, will deploy Monsieur Verite to deal AoE Cryo DMG.</p><p>Plunging Attack Gathering the power of Cryo, Charlotte plunges toward the ground, dealing DMG to all opponents in her path and dealing AoE Cryo DMG upon landing.</p><p>Arkhe: Pneuma At certain intervals, upon using a Charged Attack, Charlotte will cause a Spiritbreath Thorn to descend and pierce opponents, dealing Pneuma-aligned AoE Cryo DMG.</p>" },
  "charlotte_diversified_investigation": { title: "Diversified Investigation" },
  "charlotte_diversified_investigation_1": { description: "When the party contains 1/2/3 Fontainians other than herself, Charlotte gains a 5/10/15% Healing Bonus." },
  "charlotte_diversified_investigation_2": { description: "When the party contains 1/2/3 non-Fontainians, Charlotte gains a 5/10/15% Cryo DMG Bonus." },
  "charlotte_freezing_point_composition": { title: "Framing: Freezing Point Composition", description: "<p>Using the keen instincts of an ace reporter, Charlotte uses her photography skills to produce different effects based on whether the ability is Tapped or Held.</p><p>Tap Takes a snapshot using Monsieur Verite, dealing AoE Cryo DMG to opponents in front of her and applying Snappy Silhouette to a maximum of 5 opponents. During this effect's duration, it will deal Cryo DMG to affected opponents at intervals.</p><p>Hold Popping Monsieur Verite's viewfinder open, Charlotte enters Composition Mode, and during this time, the viewfinder will expand as you hold until you reach a Finisher Frame state. In this state, Charlotte can move and change direction freely. When the hold state ends, Monsieur Verite will deal Cryo DMG to all opponents locked on within the viewfinder, and apply the same Snappy Silhouette as Tap Mode does to them. If you unleash this ability only after reaching Finisher Frame, you will instead apply Focused Impression, which lasts longer and deals more DMG, although the Skill CD will be longer. Composition Mode lasts a maximum of 15s and allows a maximum of 5 opponents to be selected.</p><p><i>\"Press photography requires simple shots with exceptional theming, but most of all, you need to have a knack for capturing the moment!\"</i></p>" },
  "charlotte_moment_of_impact": { title: "Moment of Impact", description: "When opponents marked by \"Focused Impression\" are defeated, Framing: Freezing Point Composition's CD will be decreased by 2s. This CD decrease can be triggered 4 times every 12s." },
  "chasca_brim_the_sandshadows_silhouette": { title: "Brim, the Sandshadow's Silhouette" },
  "chasca_bullet_trick": { title: "Bullet Trick", description: "When the Elemental Skill Spirit Reins, Shadow Hunt's Multitarget Fire is being charged, if there are party members who meet the Elemental Conversion Type requirements, gain the following effects based on the number of different eligible Elemental Types present: ·There is a 33.3%/66.7%/100% chance for each Type to trigger \"Spiritbinding Conversion\" and cause the 3rd Shadowhunt Shell loaded into the cylinder to be randomly converted into a Shining Shadowhunt Shell from one of the corresponding Elemental Types. ·Each Elemental Type will grant Chasca 1 stack of Spirit of the Radiant Shadow, increasing the DMG of Shining Shadowhunt Shell by {text_percent_dmg_1}/{text_percent_dmg_2}/{text_percent_dmg_3}. This effect lasts until the current Multitarget Fire ends. Max 3 stacks." },
  "chasca_cylinder_the_restless_roulette": { title: "Cylinder, the Restless Roulette", description: "When triggering the Passive Talent \"Bullet Trick\"'s \"Spiritbinding Conversion,\" the 2nd Shadowhunt Shell loaded into the cylinder will be additionally converted into a Shining Shadowhunt Shell. The chance to trigger \"Spiritbinding Conversion\" is increased: If there are party members who meet the Elemental Conversion Type requirements, the chance to trigger \"Spiritbinding Conversion\" is increased by 33.3%, up to a maximum of 100%. You must first unlock the Passive Talent \"Bullet Trick.\" In addition, Chasca's Nightsoul point and Phlogiston consumption in her Nightsoul's Blessing state is decreased by 30% while out of combat." },
  "chasca_intent_to_cover": { title: "Intent to Cover", description: "When a nearby party member triggers a Nightsoul Burst, Chasca will fire a \"Burning Shadowhunt Shot\" at a nearby opponent, dealing Nightsoul-aligned Anemo DMG equal to {text_percent_anemo} of the Shadowhunt Shell DMG from her Elemental Skill Spirit Reins, Shadow Hunt. If the party has Pyro, Hydro, Cryo, or Electro characters, the Burning Shadowhunt Shot will be converted to deal Nightsoul-aligned Elemental DMG of the corresponding Elemental Type equal to {text_percent_elemental} of the DMG dealt by Spirit Reins, Shadow Hunt's Shining Shadowhunt Shells. The DMG done in this way is considered Charged Attack DMG." },
  "chasca_muzzle_the_searing_smoke": { title: "Muzzle, the Searing Smoke" },
  "chasca_muzzle_the_searing_smoke_1": { description: "When Chasca takes the field, she will obtain 1 stack of \"Spirit of the Radiant Shadow\" from the Passive Talent \"Bullet Trick.\" You must first unlock the Passive Talent \"Bullet Trick\" for this effect." },
  "chasca_muzzle_the_searing_smoke_2": { description: "In addition, when the Shining Shadowhunt Shells from Spirit Reins, Shadow Hunt's Multitarget Fire hit opponents, they will deal AoE Elemental DMG of the corresponding Elemental Type of the Shining Shadowhunt Shells equal to {text_percent_dmg} of Chasca's ATK. This DMG is considered Charged Attack DMG. This effect can be triggered once each time Chasca uses Multitarget Fire." },
  "chasca_phantom_feather_flurry": { title: "Phantom Feather Flurry", description: "<p>Normal Attack Performs up to 4 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, mighty winds will accumulate on the arrowhead. A fully charged wind arrow will deal Anemo DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, hitting opponents along the path and dealing AoE DMG upon impact.</p>" },
  "chasca_reins_her_careful_control": { title: "Reins, Her Careful Control" },
  "chasca_showdown_the_glory_of_battle": { title: "Showdown, the Glory of Battle", description: "Chasca's Multitarget Fire charge time is decreased, and after the Passive Talent \"Bullet Trick\"'s \"Spiritbinding Conversion\" is triggered, Chasca will gain the \"Fatal Rounds\" state: For the next 3s, the next time Chasca uses Spirit Reins, Shadow Hunt's Multitarget Fire, the shots will finish charging instantly, and the CRIT DMG of that instance of Multitarget Fire's Shadowhunt Shells and Shining Shadowhunt Shells increases by {crit_dmg_chasca}. 1 \"Fatal Rounds\" effect can be gained once every 3s. You must first unlock the Passive Talent \"Bullet Trick\" to gain access to the above effect." },
  "chasca_soul_reapers_fatal_round": { title: "Soul Reaper's Fatal Round", description: "<p>Chasca concentrates her will, firing a single \"Galesplitting Soulseeker Shell\" that deals Nightsoul-aligned AoE Anemo DMG. Afterward, the Galesplitting Soulseeker Shell will split into 6 Soulseeker Shells, which attack nearby opponents.</p><p>Soulseeker Shells ·Deal Nightsoul-aligned Anemo DMG. ·For each Pyro, Hydro, Cryo, or Electro character in the party, two Soulseeker Shells will undergo corresponding Elemental Conversions to become \"Radiant Soulseeker Shells,\" which deal Nightsoul-aligned Elemental DMG from a randomly selected one of the corresponding Elemental Types.</p><p><i>None can escape from the moonlight or the whispers of the night, just as no foe can flee her attentive eyes once she's got them in her sights.</i></p>" },
  "chasca_sparks_the_sudden_shot": { title: "Sparks, the Sudden Shot", description: "When the Radiant Soulseeker Shells from Soul Reaper's Fatal Round hit opponents, they will restore 1.5 Elemental Energy to Chasca, and deal AoE Elemental DMG of the corresponding Elemental Type of the Radiant Soulseeker Shells equal to {text_percent_dmg} of Chasca's ATK. This DMG is considered Charged Attack DMG. The aforementioned corresponding elemental AoE DMG effect can be triggered once each time Chasca uses Soul Reaper's Fatal Round." },
  "chasca_spirit_reins_shadow_hunt": { title: "Spirit Reins, Shadow Hunt", description: "<p>Chasca and the will residing in her weapon resonate, dealing Nightsoul-aligned AoE Anemo DMG. After using this Skill, Chasca gains 80 Nightsoul points and enters the Nightsoul's Blessing state.</p><p>Nightsoul's Blessing: Chasca Continually consume Nightsoul points. When Nightsoul points are fully depleted or the skill is used again, Chasca's Nightsoul's Blessing state will end. Her Nightsoul's Blessing has the following traits: ·Mounts \"Soulsniper: Ritual Staff,\" increasing Chasca's Movement SPD and interruption resistance. In this state, Chasca will continually consume Nightsoul points to remain airborne. When Sprinting or increasing height, extra Nightsoul points will be consumed. ·When using Normal or Charged Attacks, Tap or Hold to switch between using \"Multitarget Fire\" in different ways.</p><p>Multitarget Fire Tap Deal Nightsoul-aligned Anemo DMG to opponents in front. This DMG is considered Normal Attack DMG. Hold Enter Aiming Mode and choose a certain number of opponents within a certain range, before loading up to 6 Shadowhunt Shells based on the duration for which the skill was charged. When 6 Shells have been loaded or charging is stopped, these Shells will be fired at the chosen opponents in sequence.</p><p>Shadowhunt Shells ·Deal Nightsoul-aligned Anemo DMG, which is considered Charged Attack DMG. ·The 4th, 5th, and 6th Shells loaded into the cylinder will undergo Elemental Conversion based on the Elemental Types of the other characters in the party: For each Pyro, Hydro, Cryo, or Electro character in the party, one Shadowhunt Shell will randomly be Converted into a \"Shining Shadowhunt Shell\" of one of these corresponding Elemental Types, dealing Nightsoul-aligned DMG corresponding to that Elemental Type. This DMG is considered Charged Attack DMG. ·The Shells loaded into the cylinder are fired starting from the last Shadowhunt Shell to be loaded, in a \"last in, first out\" order.</p><p>Additionally, when Chasca is in the Nightsoul's Blessing state, Holding her Elemental Skill Spirit Reins, Shadow Hunt will cause her to execute a Nightsoul-aligned Plunging Attack. Release the Elemental Skill to interrupt this Plunging Attack and maintain her airborne state. Should Chasca hit the ground with her Plunging Attack, her Nightsoul's Blessing state will end.</p><p><i>In theory, as long as she's willing, those reins can bridle anything... But what could possibly be as cool as a giant hand cannon?</i></p>" },
  "chevreuse_enhanced_incendiary_firepower": { title: "Enhanced Incendiary Firepower" },
  "chevreuse_in_pursuit_of_ending_evil": { title: "In Pursuit of Ending Evil", description: "After 12s of the healing effect from Short-Range Rapid Interdiction Fire, all nearby party members recover HP equivalent to {text_percent_heal} of Chevreuse's Max HP once. After a party member is healed by Short-Range Rapid Interdiction Fire, they gain a 20% Pyro DMG Bonus and Electro DMG Bonus for {dmg_pyro}s. Max 3 stacks. Each stack's duration is counted independently." },
  "chevreuse_line_bayonet_thrust_ex": { title: "Line Bayonet Thrust EX", description: "<p>Normal Attack Performs up to 4 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "chevreuse_practiced_field_stripping_technique": { title: "Practiced Field Stripping Technique" },
  "chevreuse_ring_of_bursting_grenades": { title: "Ring of Bursting Grenades", description: "<p>Chevreuse fires an explosive grenade at opponents with her musket, dealing AoE Pyro DMG. After the projectile hits, it will split into many secondary explosive shells. The secondary explosive shells will burst after a short interval, dealing Pyro DMG to nearby opponents.</p><p><i>\"Theoretically, a rectangular blast would be most efficient at destroying enemy formations. Unfortunately, the cross-section of an explosive shock wave is round, like most cakes. So, the secondary explosive shells can only be arranged like the fruit on a cake, forming a ring around the edge.\"</i></p>" },
  "chevreuse_short_range_rapid_interdiction_fire": { title: "Short-Range Rapid Interdiction Fire", description: "<p>Chevreuse quickly shoulders her musket and fires at her opponent(s), dealing AoE Pyro DMG. For a short duration after Chevreuse fires a shot, she will continuously restore HP to your active character on the field. The amount healed is based on her Max HP. Hold to fire in a different fashion.</p><p>Hold Enter Aiming Mode, locking a target in her sights to fire a precise interdiction shot. If Chevreuse has an Overcharged Ball, then she will fire the Overcharged Ball instead, dealing greater Pyro DMG in a larger area. Chevreuse gains 1 Overcharged Ball every time a nearby character in the party triggers an Overloaded reaction, and can have up to 1 Overcharged Ball at a time.</p><p>Arkhe: Ousia Periodically, after Chevreuse's Short-Range Rapid Interdiction Fire hits, a Surging Blade will be called forth that deals Ousia-aligned Pyro DMG.</p><p><i>\"Actually, training regulations only had the phrase \"interdiction fire,\" but the protagonist of this novel believes that even how stylish your terminology is can affect how motivated your troops are, which can put your opponents on the back foot right from the get-go... I think that's a good point, so I changed the regulations!\"</i></p>" },
  "chevreuse_sniper_induced_explosion": { title: "Sniper Induced Explosion", description: "After Holding Short-Range Rapid Interdiction Fire and hitting a target, 2 chain explosions will be triggered near the location where said target is hit. Each explosion deals Pyro DMG equal to {text_percent_dmg} of Chevreuse's ATK. This effect can be triggered up to once every 10s, and DMG dealt this way is considered Elemental Skill DMG." },
  "chevreuse_stable_front_lines_resolve": { title: "Stable Front Line's Resolve", description: "When the active character with the \"Coordinated Tactics\" status (not including Chevreuse herself) triggers the Overloaded reaction, they will recover 6 Energy. This effect can be triggered once every 10s. You must first unlock the Passive Talent \"Vanguard's Coordinated Tactics.\"" },
  "chevreuse_the_secret_to_rapid_fire_multishots": { title: "The Secret to Rapid-Fire Multishots", description: "After using Ring of Bursting Grenades, the Hold mode of Short-Range Rapid Interdiction Fire will not go on cooldown when Chevreuse uses it. This effect is removed after Short-Range Rapid Interdiction Fire has been fired twice using Hold or after 6s." },
  "chevreuse_vanguards_coordinated_tactics": { title: "Vanguard's Coordinated Tactics", description: "When all party members are Pyro and Electro characters and there is at least one Pyro and one Electro character each in the party: Chevreuse grants \"Coordinated Tactics\" to nearby party members: After a character triggers the Overloaded reaction, the Pyro and Electro RES of the opponent(s) affected by this Overloaded reaction will be decreased by {enemy_res_pyro} for 6s. The \"Coordinated Tactics\" effect will be removed when the Elemental Types of the characters in the party do not meet the basic requirements for the Passive Talent." },
  "chevreuse_vertical_force_coordination": { title: "Vertical Force Coordination", description: "After Chevreuse fires an Overcharged Ball using Short-Range Rapid Interdiction Fire, nearby Pyro and Electro characters in the party gain {text_percent} increased ATK for every {text_value} Max HP Chevreuse has for 30s. ATK can be increased by up to {text_percent_max} in this way." },
  "chiori_a_tailors_three_courtesies": { title: "A Tailor's Three Courtesies", description: "For 8s after triggering either follow-up effect of the Passive Talent \"Tailor-Made,\" when your current active character's Normal, Charged, or Plunging Attacks hit a nearby opponent, a simplified automaton doll, \"Kinu,\" will be summoned near this opponent. You can summon 1 Kinu every 1s in this way, and up to 3 Kinu may be summoned this way during each instance of \"Tailor-Made\"'s Seize the Moment or Tailoring effect. The above effect can be triggered up to once every 15s. Must unlock the Passive Talent \"Tailor-Made\" first." },
  "chiori_fluttering_hasode": { title: "Fluttering Hasode", description: "<p>Dashes nimbly forward with silken steps. Once this dash ends, Chiori will summon the automaton doll \"Tamoto\" beside her and sweep her blade upward, dealing AoE Geo DMG to nearby opponents based on her ATK and DEF. Holding the Skill will cause it to behave differently.</p><p>Hold Enter Aiming Mode to adjust the dash direction.</p><p>Tamoto · Will slash at nearby opponents at intervals, dealing AoE Geo DMG based on Chiori's ATK and DEF. · While active, if there are nearby Geo Construct(s) or Geo Construct(s) are created nearby, an additional Tamoto will be summoned next to your active character. Only 1 additional Tamoto can be summoned in this manner, and its duration is independently counted.</p><p><i>\"Sakura red dyes the brocade, the fragrance suffuses the sleeves, the orioles intoxicated.\"</i></p>" },
  "chiori_four_brocade_embellishments": { title: "Four Brocade Embellishments" },
  "chiori_in_five_colors_dyed": { title: "In Five Colors Dyed", description: "For 10s after using Hiyoku: Twin Blades, a simplified automaton doll, \"Kinu,\" will be summoned next to your active character every 3s. Kinu will attack nearby opponents, dealing AoE Geo DMG equivalent to {text_percent_dmg} of Tamoto's DMG. DMG dealt this way is considered Elemental Skill DMG. Kinu will leave the field after 1 attack or after lasting 3s." },
  "chiori_six_paths_of_sage_silkcraft": { title: "Six Paths of Sage Silkcraft", description: "The AoE of the automaton doll \"Tamoto\" summoned by Fluttering Hasode is increased by 50%. Additionally, if there is a Geo party member other than Chiori, Fluttering Hasode will trigger the following after the dash is completed: · Summon an additional Tamoto. Only one additional Tamoto can exist at the same time, whether summoned by Chiori this way or through the presence of a Geo Construct. · Triggers the Passive Talent \"The Finishing Touch.\" This effect requires you to first unlock the Passive Talent \"The Finishing Touch.\"" },
  "chiori_sole_principle_pursuit": { title: "Sole Principle Pursuit", description: "After triggering a follow-up effect of the Passive Talent \"Tailor-Made,\" Chiori's own Fluttering Hasode's CD is decreased by 12s. Must unlock the Passive \"Tailor-Made\" first. In addition, the DMG dealt by Chiori's own Normal Attacks is increased by an amount equal to {text_percent_dmg} of her own DEF." },
  "chiori_tailor_made": { title: "Tailor-Made" },
  "chiori_tailor_made_1": { description: "Gain different effects depending on the next action you take within a short duration after using Fluttering Hasode's upward sweep. If you Press the Elemental Skill, you will trigger the Tapestry effect. If you Press your Normal Attack, the Tailoring effect will be triggered instead. When on the field, if Chiori does not either Press her Elemental Skill or use a Normal Attack within a short time after using Fluttering Hasode's upward sweep, the Tailoring effect will be triggered by default." },
  "chiori_tailor_made_2": { description: "· Switches to the next character in your roster. · Grants all your party members \"Seize the Moment\": When your active party member's Normal Attacks, Charged Attacks, and Plunging Attacks hit a nearby opponent, \"Tamoto\" will execute a coordinated attack, dealing {text_percent_dmg} of Fluttering Hasode's upward sweep DMG as AoE Geo DMG at the opponent's location. DMG dealt this way is considered Elemental Skill DMG. · \"Seize the Moment\" lasts 8s, and 1 of \"Tamoto\"'s coordinated attack can be unleashed every 2s. 2 such coordinated attacks can occur per \"Seize the Moment\" effect duration." },
  "chiori_tailor_made_3": { description: "· Chiori gains Geo infusion for 5s." },
  "chiori_the_finishing_touch": { title: "The Finishing Touch", description: "When a nearby party member creates a Geo Construct, Chiori will gain {dmg_geo} Geo DMG Bonus for 20s." },
  "chiori_twin_blades": { title: "Hiyoku: Twin Blades", description: "<p>Twin blades leave their sheaths as Chiori slices with the clean cuts of a master tailor, dealing AoE Geo DMG based on her ATK and DEF.</p><p><i>\"Master one principle, and the path to all others shall open to you.\"</i></p>" },
  "chiori_two_silken_plumules": { title: "Two Silken Plumules" },
  "chiori_weaving_blade": { title: "Weaving Blade", description: "<p>Normal Attack Performs up to 4 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "chongyun_atmospheric_revolution": { title: "Atmospheric Revolution", description: "Elemental Skills and Elemental Bursts cast within the Frost Field created by Spirit Blade: Chonghua's Layered Frost have their CD time decreased by {text_percent_cd}." },
  "chongyun_chonghuas_layered_frost": { title: "Spirit Blade: Chonghua's Layered Frost", description: "<p>Chongyun strikes the ground with his greatsword, causing a Cryo explosion in a circular AoE in front of him that deals Cryo DMG. After a short delay, the cold air created by the Cryo explosion will coalesce into a Chonghua Frost Field, within which all Sword, Claymore and Polearm-wielding characters' weapons will be infused with Cryo.</p><p><i>\"A crystal-clear ring, and all is silent. The rivers move not, and the clouds are heavy with frost. The altar gates open, and evil is banished.\"</i></p>" },
  "chongyun_cloud_parting_star": { title: "Spirit Blade: Cloud-Parting Star", description: "<p>Performing the secret hand seals, Chongyun summons 3 giant spirit blades in mid-air that fall to the earth one by one after a short delay, exploding as they hit the ground. When the spirit blades explode, they will deal AoE Cryo DMG and launch opponents.</p><p><i>\"As ice doth give the biting frost birth, My transcendent blade shakes heaven and earth. Heed my summons and come hence!\"</i></p>" },
  "chongyun_cloudburst": { title: "Cloudburst" },
  "chongyun_demonbane": { title: "Demonbane", description: "<p>Normal Attack Performs up to 4 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous spinning attacks against all nearby opponents. At the end of the sequence, performs a more powerful slash. </p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "chongyun_frost_field": { title: "Within Chonghua Frost Field", description: "Chonghua Frost Field created by Spirit Blade: Chonghua's Layered Frost" },
  "chongyun_frozen_skies": { title: "Frozen Skies", description: "Chongyun regenerates 1 Energy every time he hits an opponent affected by Cryo. This effect can only occur once every 2s." },
  "chongyun_ice_unleashed": { title: "Ice Unleashed", description: "The last attack of Chongyun's Normal Attack combo releases 3 ice blades. Each blade deals {text_percent_dmg} of Chongyun's ATK as Cryo DMG to all opponents in its path." },
  "chongyun_layered_frost": { title: "Spirit Blade: Chonghua's Layered Frost", description: "Within area of Chonghua Frost Field all Sword, Claymore and Polearm-wielding characters' weapons infused with Cryo." },
  "chongyun_rally_of_four_blades": { title: "Rally of Four Blades", description: "Spirit Blade: Cloud-Parting Star deals {dmg_burst_chongyun} more DMG to opponents with a lower percentage of their Max HP remaining than Chongyun. This skill will also summon 1 additional spirit blade." },
  "chongyun_rimechaser_blade": { title: "Rimechaser Blade" },
  "chongyun_rimechaser_blade_1": { description: "When the field created by Spirit Blade: Chonghua's Layered Frost disappears, another spirit blade will be summoned to strike nearby opponents, dealing {text_percent_dmg} of Chonghua's Layered Frost's Skill DMG as AoE Cryo DMG." },
  "chongyun_rimechaser_blade_2": { description: "Opponents hit by this blade will have their Cryo RES decreased by {enemy_res_cryo} for 8s." },
  "chongyun_steady_breathing": { title: "Steady Breathing", description: "Sword, Claymore, or Polearm-wielding characters within the field created by Spirit Blade: Chonghua's Layered Frost have their Normal ATK SPD increased by {atk_speed_normal}." },
  "chongyun_the_true_path": { title: "The True Path" },
  "citlali_cloud_serpents_feathered_crown": { title: "Cloud Serpent's Feathered Crown" },
  "citlali_dawnfrost_darkstar": { title: "Dawnfrost Darkstar", description: "<p>Invoking secret pacts passed down by her tribe over the millennia, Citlali deploys an Opal Shield and calls forth \"Obsidian Tzitzimitl: Itzpapa,\" a creature that is (reputedly) terrifying beyond compare, dealing Nightsoul-aligned AoE Cryo DMG. The Opal Shield's DMG absorption scales based on Citlali's Elemental Mastery, and absorbs Cryo DMG with 250% efficiency. When it is deployed, it will cause Citlali to briefly be affected by Cryo. After using this skill, Citlali gains 24 Nightsoul points and enters the Nightsoul's Blessing state.</p><p>Nightsoul's Blessing: Citlali When Itzpapa leaves the field, Citlali exits the Nightsoul's Blessing state.</p><p>Itzpapa ·Itzpapa will follow the character. ·If Citlali has at least 50 Nightsoul points, Itzpapa enters the Opal Fire state and continuously consumes Nightsoul points to whip up a Frostfall Storm that follows the character and attacks opponents within its AoE, dealing Nightsoul-aligned Cryo DMG. ·When Citlali's Nightsoul points are fully depleted, Itzpapa's Opal Fire state also ends.</p><p><i>Usually, the wills that symbolize different stars cannot coexist, for how can purest black be reflected in purest white? Be that as it may, Citlali has never harbored a particular preference for colors themselves, and that is just how things played out.</i></p>" },
  "citlali_death_defiers_spirit_skull": { title: "Death Defier's Spirit Skull", description: "While the Elemental Skill Dawnfrost Darkstar is active, when Itzpapa's Frostfall Storm hits opponents, an additional Obsidian Spiritvessel Skull will be summoned. When a Spiritvessel Skull summoned this way explodes, it deals {text_percent_dmg} of Citlali's Elemental Mastery as Nightsoul-aligned AoE Cryo DMG and restores 16 Nightsoul points and 8 Energy for Citlali. This effect can trigger once every 8s. This DMG is not considered Elemental Burst DMG." },
  "citlali_edict_of_entwined_splendor": { title: "Edict of Entwined Splendor", description: "<p>Summons \"allies\" from the starry skies and the vast earth, hurling forth an ice storm to bombard the area in front and deal Nightsoul-aligned AoE Cryo DMG. This restores a set amount of Nightsoul points for Citlali, and also summons a Spiritvessel Skull near a maximum of 3 opponents within the AoE, with 1 Skull for each opponent. Spiritvessel Skulls explode after some time, dealing Nightsoul-aligned AoE Cryo DMG and restoring a set amount of Nightsoul points for Citlali.</p><p><i>\"Ugh, enough of this 'dark star, opal star' stuff! Citlalin, Itzpapa, get 'em!\"</i></p>" },
  "citlali_heart_devourers_travail": { title: "Heart Devourer's Travail" },
  "citlali_heart_devourers_travail_1": { description: "Citlali gains {text_value_self} Elemental Mastery, and other characters shielded by her Opal Shield, or who have Itzpapa following them, gain {text_value_other} Elemental Mastery. Additionally, when the Elemental Skill Dawnfrost Darkstar is used, nearby active characters will also be granted an Opal Shield." },
  "citlali_heart_devourers_travail_2": { description: "Also, the Passive Talent \"Mamaloaco's Frigid Rain\" has its effects enhanced: While Itzpapa is on the field, after nearby party members trigger Frozen or Melt, the opponent(s) affected by this reaction will have their Pyro and Hydro RES additionally decreased by {enemy_res_pyro} for 12s. You must first unlock the Passive Talent \"Mamaloaco's Frigid Rain\" to gain access to the above effect." },
  "citlali_itzpapalotls_star_garments": { title: "Itzpapalotl's Star Garments", description: "During the Elemental Skill Dawnfrost Darkstar, Itzpapa's Frostfall Storm DMG is increased by {text_percent_1} of Citlali's Elemental Mastery. During the Elemental Burst Edict of Entwined Splendor, Ice Storm DMG is increased by {text_percent_2} of Citlali's Elemental Mastery. In addition, when nearby party members trigger Nightsoul Bursts, Citlali regains 4 Nightsoul points." },
  "citlali_mamaloacos_frigid_rain": { title: "Mamaloaco's Frigid Rain", description: "While Itzpapa is on the field, after nearby party members trigger the Frozen or Melt reactions, the Pyro and Hydro RES of opponents affected by that reaction decreases by {enemy_res_pyro} for 12s. Additionally, Citlali will regain 16 Nightsoul points. Nightsoul points can be restored this way once every 8s." },
  "citlali_nemontemis_hex": { title: "Nemontemi's Hex" },
  "citlali_radiant_blades_of_centzon_mimixcoah": { title: "Radiant Blades of Centzon Mimixcoah", description: "When she uses the Elemental Skill Dawnfrost Darkstar, Citlali gains the \"Opalstar Vestments\" effect until Itzpapa leaves the field. During this time, she will obtain 10 stacks of Stellar Blade. When a nearby active character other than Citlali deals DMG using Normal, Charged, or Plunging Attacks, or Elemental Skills and Bursts, 1 stack of Stellar Blade will be consumed to increase the DMG dealt by {text_percent} of Citlali's Elemental Mastery. After nearby party members trigger Frozen or Melt, Citlali will gain another 3 stacks of Stellar Blade. This effect can trigger once every 8s. Using the Elemental Skill Dawnfrost Darkstar will reset Stellar Blade stacks. Additionally, when Citlali is using her leap, or is Aiming or using her Charged Attack in mid-air, her Phlogiston consumption is decreased by 45%." },
  "citlali_shadow_stealing_spirit_vessel": { title: "Shadow-Stealing Spirit Vessel", description: "<p>Normal Attack Calls upon secret arts passed down through the Masters of the Night-Wind from generation to generation, performing up to three strikes that deal Cryo DMG.</p><p>Charged Attack Enters Aiming Mode, and after Holding, consumes a certain amount of Stamina to call forth a Frost Star that deals Cryo DMG to opponents in its path.</p><p>Plunging Attack Gathers the power of Cryo and plunges towards the ground from mid-air, damaging all opponents in her path. Deals Aoe Cryo DMG upon impact with the ground.</p>" },
  "citlali_teoiztacs_secret_pact": { title: "Teoiztac's Secret Pact" },
  "citlali_teoiztacs_secret_pact_1": { description: "After being summoned with the Elemental Skill Dawnfrost Darkstar, Itzpapa will always be in the Opal Fire state, and when Nightsoul points are exhausted, this state will not end." },
  "citlali_teoiztacs_secret_pact_2": { description: "Additionally, when Dawnfrost Darkstar is used, Itzpapa will consume all Nightsoul points, and while it is on the field, it will continuously consume Nightsoul points. Each Nightsoul point consumed in this way will grant Citlali 1 \"Cifra of the Secret Law\" point. A maximum of 40 such points can be gained, and each point Citlali possesses will grant all nearby party members a {text_percent_1} Pyro and Hydro DMG Bonus, and increase the DMG Citlali deals by {text_percent_2}. When Itzpapa leaves the field, or upon using Citlali's Elemental Skill again, all \"Cifra of the Secret Law\" points she has will be removed." },
  "clorinde_and_so_shall_i_never_despair": { title: "\"And So Shall I Never Despair\"" },
  "clorinde_and_so_shall_i_never_despair_1": { description: "For 12s after Hunter's Vigil is used, Clorinde's CRIT Rate will be increased by {crit_rate}, and her CRIT DMG by {crit_dmg}." },
  "clorinde_and_so_shall_i_never_despair_2": { description: "Additionally, while Night Vigil is active, a Glimbright Shade will appear under specific circumstances, executing an attack that deals {text_percent_dmg} of Clorinde's ATK as Electro DMG. DMG dealt this way is considered Normal Attack DMG. The Glimbright Shade will appear under the following circumstances: · When Clorinde is about to be hit by an attack. · When Clorinde uses Impale the Night: Pact. 1 Glimbright Shade can be summoned in the aforementioned ways every 1s. 6 Shades can be summoned per single Night Vigil duration. In addition, while Night Vigil is active, the DMG Clorinde receives is decreased by 80% and her interruption resistance is increased. This effect will disappear after the Night Vigil state ends or 1s after she summons 6 Glimbright Shades." },
  "clorinde_dark_shattering_flame": { title: "Dark-Shattering Flame", description: "After a nearby party member triggers an Electro-related reaction against an opponent, Electro DMG dealt by Clorinde's Normal Attacks and Last Lightfall will be increased by {dmg_electro_clorinde} of Clorinde's ATK for 15s. Max 3 stacks. Each stack is counted independently. The Maximum DMG increase achievable this way for the above attacks is {text_value_max}." },
  "clorinde_from_this_day_i_pass_the_candles_shadow_veil": { title: "\"From This Day, I Pass the Candle's Shadow-Veil\"", description: "While Hunter's Vigil's Night Vigil state is active, when Electro DMG from Clorinde's Normal Attacks hit opponents, they will trigger 2 coordinated attacks from a Nightvigil Shade summoned near the hit opponent, each dealing {text_percent_dmg} of Clorinde's ATK as Electro DMG. This effect can occur once every 1.2s. DMG dealt this way is considered Normal Attack DMG." },
  "clorinde_holding_dawns_coming_as_my_votive": { title: "\"Holding Dawn's Coming as My Votive\"" },
  "clorinde_hunters_vigil": { title: "Hunter's Vigil", description: "<p>Preparing her pistolet, she enters the \"Night Vigil\" state, using steel and shot together. In this state, Clorinde's Normal Attacks will be transformed into \"Swift Hunt\" pistolet attacks, and the DMG dealt is converted into Electro DMG that cannot be overridden by infusions, and she will be unable to use Charged Attacks. Using her Elemental Skill will transform it into \"Impale the Night\": Perform a lunging attack, dealing Electro DMG. The DMG done through the aforementioned method is considered Normal Attack DMG.</p><p>Swift Hunt · When her Bond of Life is equal to or greater than 100% of her max HP: Performs a pistolet shot. · When her Bond of Life is less than 100%, firing her pistolet will grant her Bond of Life, with the amount gained based on her max HP. The shots she fires can pierce opponents, and DMG dealt to opponents in their path is increased.</p><p>Impale the Night The current percentage value of Clorinde's Bond of Life determines its effect: · When the Bond of Life value is 0%, perform a normal lunging strike; · When the Bond of Life value is less than 100% of her max HP, Clorinde is healed based on the Bond of Life value, and the AoE of the lunging attack and the DMG dealt is increased; · When the value of the Bond of Life is equal to or greater than 100% of her max HP, use Impale the Night: Pact. The healing multiplier is increased, and the AoE and DMG dealt by the lunge is increased even further.</p><p>In addition, when Clorinde is in the Night Vigil state, healing effects other than Impale the Night will not take effect and will instead be converted into a Bond of Life that is a percentage of the healing that would have been received.</p><p>Clorinde will exit the \"Night Vigil\" state when she leaves the field.</p><p>Arkhe: Ousia Periodically, when Clorinde's Swift Hunt shots strike opponents, she will summon a Surging Blade at the position hit that deals Ousia-aligned Electro DMG.</p><p><i>Though the evil that lurked in the shadows of the night had been purged across thousands of years, a shadow that the light could not reach clouded human hearts. Even now, the warning left by the Golden Hunter is etched into her memory: Those of the Night Vigil, carrying aloft lit candles against the blackness, have greater need still to remain vigilant. Be not corrupted by the cold dark.</i></p>" },
  "clorinde_i_pledge_to_remember_the_oath_of_daylight": { title: "\"I Pledge to Remember the Oath of Daylight\"" },
  "clorinde_last_lightfall": { title: "Last Lightfall", description: "<p>Grants herself a Bond of Life based upon her own max HP before swiftly evading and striking with saber and sidearm as one, dealing AoE Electro DMG.</p><p><i>It is said the legacy of the ancient art of resisting non-human beings with but a mortal body can be traced back to the Lochknights who resisted the Remurian Empire. Be that as it may, so long as one can find a way to control the level of force used, it's not as if it cannot be used in duels against ordinary opponents.</i></p>" },
  "clorinde_lawful_remuneration": { title: "Lawful Remuneration", description: "If Clorinde's Bond of Life is equal to or greater than 100% of her Max HP, her CRIT Rate will increase by {crit_rate} for 15s whenever her Bond of Life value increases or decreases. Max 2 stacks. Each stack is counted independently. Additionally, Hunter's Vigil's Night Vigil state is buffed: While it is active, the percent of healing converted to Bond of Life increases to 100%." },
  "clorinde_now_as_we_face_the_perils_of_the_long_night": { title: "\"Now, As We Face the Perils of the Long Night\"", description: "Enhance the Passive Talent \"Dark-Shattering Flame\": After a nearby party member triggers an Electro-related reaction against an opponent, Electro DMG dealt by Clorinde's Normal Attacks and Last Lightfall will be increased by {text_percent} of Clorinde's ATK for 15s. Max 3 stacks. Each stack is counted independently. When you have 3 stacks, Clorinde's interruption resistance will be increased. The Maximum DMG increase achievable this way for the above attacks is {text_value}. You must first unlock the Passive Talent \"Dark-Shattering Flame.\"" },
  "clorinde_oath_of_hunting_shadows": { title: "Oath of Hunting Shadows", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina and fires Suppressing Shots in a fan pattern with her pistolet.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "clorinde_to_enshrine_tears_life_and_love": { title: "\"To Enshrine Tears, Life, and Love\"", description: "When Last Lightfall deals DMG to opponent(s), DMG dealt is increased based on Clorinde's Bond of Life percentage. Every 1% of her current Bond of Life will increase Last Lightfall DMG by {text_percent}. The maximum Last Lightfall DMG increase achievable this way is {text_percent_max}." },
  "collei_all_embers": { title: "All Embers" },
  "collei_deepwood_patrol": { title: "Deepwood Patrol", description: "When in the party and not on the field, Collei's Energy Recharge is increased by {recharge}." },
  "collei_floral_brush": { title: "Floral Brush", description: "<p>Throws out a Floral Ring that deals 1 instance of Dendro DMG to targets it comes into contact with. The Floral Ring will return after a set time, dealing Dendro DMG once again.</p><p><i>This is Collei's go-to gadget for dealing with unruly wild beasts. A few good thwacks from this tool will generally improve their behavior. This same principle works just as well on evildoers.</i></p>" },
  "collei_floral_sidewinder": { title: "Floral Sidewinder", description: "If one of your party members has triggered Burning, Quicken, Aggravate, Spread, Bloom, Hyperbloom, or Burgeon reactions before the Floral Ring returns, it will grant the character the Sprout effect upon return, which will continuously deal Dendro DMG equivalent to {text_percent} of Collei's ATK to nearby opponents for 3s. If another Sprout effect is triggered during its initial duration, the initial effect will be removed. DMG dealt by Sprout is considered Elemental Skill DMG." },
  "collei_forest_of_falling_arrows": { title: "Forest of Falling Arrows", description: "When the Floral Ring hits, it will create a miniature Cuilein-Anbar that will deal {text_percent_dmg} of Collei's ATK as Dendro DMG. Each Floral Brush can only create one such miniature Cuilein-Anbar." },
  "collei_gift_of_the_woods": { title: "Gift of the Woods", description: "Using Trump-Card Kitty will increase all nearby characters' Elemental Mastery by {text_value} for 12s (not including Collei herself)." },
  "collei_scent_of_summer": { title: "Scent of Summer" },
  "collei_supplicants_bowmanship": { title: "Supplicant's Bowmanship", description: "<p>Normal Attack Performs up to 4 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, Dendro energy will accumulate on the arrowhead. A fully charged arrow will deal Dendro DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "collei_the_languid_wood": { title: "The Languid Wood", description: "When a character within the Cuilein-Anbar Zone triggers Burning, Quicken, Aggravate, Spread, Bloom, Hyperbloom, or Burgeon reactions, the Zone's duration will be increased by 1s. A single Trump-Card Kitty can be extended this way by up to 3s." },
  "collei_through_hill_and_copse": { title: "Through Hill and Copse", description: "The Passive Talent Floral Sidewinder is changed to this: The Floral Ring will grant the character the Sprout effect from Floral Sidewinder upon return, dealing {text_percent} of Collei's ATK as Dendro DMG to nearby opponents for 3s. From the moment of using Floral Brush to the moment when this instance of Sprout effect ends, if any of your party members triggers Burning, Quicken, Aggravate, Spread, Bloom, Hyperbloom, or Burgeon reactions, the Sprout effect will be extended by 3s. The Sprout effect can only be extended this way once. If another Sprout effect is triggered during its initial duration, the initial effect will be removed. DMG dealt by Sprout is considered Elemental Skill DMG. Requires you to have unlocked the Floral Sidewinder Passive Talent." },
  "collei_trump_card_kitty": { title: "Trump-Card Kitty", description: "<p>Trusty Cuilein-Anbar comes to save the day! Throws the doll named Cuilein-Anbar, causing an explosion that deals AoE Dendro DMG, creating a Cuilein-Anbar Zone. Cuilein-Anbar will bounce around within this zone, dealing AoE Dendro DMG.</p><p><i>\"Pretty impressive, huh? ... Eh? You want to know how I came up with the name Cuilein-Anbar? Uh, well, I...\"</i></p>" },
  "cyno_authority_over_the_nine_bows": { title: "Authority Over the Nine Bows", description: "Cyno's DMG values will be increased based on his Elemental Mastery as follows: ·Pactsworn Pathclearer's Normal Attack DMG is increased by {text_percent_dmg} of his Elemental Mastery. ·Duststalker Bolt DMG from his Passive Talent Featherfall Judgment is increased by {text_percent_dmg2} of his Elemental Mastery." },
  "cyno_chasmic_soulfarer": { title: "Secret Rite: Chasmic Soulfarer", description: "<p>Performs a swift thrust, dealing Electro DMG to opponents along the path.</p><p>When Cyno is under the Pactsworn Pathclearer state triggered by Sacred Rite: Wolf's Swiftness, he will instead unleash a Mortuary Rite that deals thunderous AoE Electro DMG and extends the duration of Pactsworn Pathclearer.</p><p><i>\"This judgment brooks no choice. There is no rejection or acceptance here... We have both long been bound up in this conviction.\"</i></p>" },
  "cyno_featherfall_judgment": { title: "Featherfall Judgment", description: "When Cyno is in the Pactsworn Pathclearer state activated by Sacred Rite: Wolf's Swiftness, Cyno will enter the Endseer stance at intervals. If he activates Secret Rite: Chasmic Soulfarer while affected by this stance, he will activate the Judication effect, increasing the DMG of this Secret Rite: Chasmic Soulfarer by {dmg_skill_cyno}, and firing off 3 Duststalker Bolts that deal {text_percent_dmg} of Cyno's ATK as Electro DMG. Duststalker Bolt DMG is considered Elemental Skill DMG." },
  "cyno_forbidding_guard": { title: "Austerity: Forbidding Guard", description: "When Cyno is in the Pactsworn Pathclearer state triggered by Sacred Rite: Wolf's Swiftness, after he triggers an Electro-Charged, Lunar-Charged, Superconduct, Overloaded, Quicken, Aggravate, Hyperbloom, or Electro Swirl reaction, he will restore 3 Elemental Energy for all nearby party members (except himself.) This effect can occur 5 times within one use of Sacred Rite: Wolf's Swiftness." },
  "cyno_homecoming_of_spirits": { title: "Ceremony: Homecoming of Spirits", description: "When Cyno's Normal Attacks hit opponents, his Electro DMG Bonus will increase by {dmg_electro} for 4s. This effect can be triggered once every 0.1s. Max 5 stacks." },
  "cyno_invokers_spear": { title: "Invoker's Spear", description: "<p>Normal Attack Performs up to 4 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "cyno_just_scales": { title: "Raiment: Just Scales", description: "After using Sacred Rite: Wolf's Swiftness or triggering the Judication effect of the Passive Talent \"Featherfall Judgment,\" Cyno will gain 4 stacks of the \"Day of the Jackal\" effect. When he hits opponents with Normal Attacks, he will consume 1 stack of \"Day of the Jackal\" to fire off one Duststalker Bolt. \"Day of the Jackal\" lasts for 8s. Max 8 stacks. It will be canceled once Pactsworn Pathclearer ends. A maximum of 1 Duststalker Bolt can be unleashed this way every 0.4s. You must first unlock the Passive Talent \"Featherfall Judgment.\"" },
  "cyno_lawful_enforcer": { title: "Precept: Lawful Enforcer" },
  "cyno_pactsworn_pathclearer": { title: "Pactsworn Pathclearer", description: "Cyno's Normal, Charged, and Plunging Attacks will be converted to Electro DMG that cannot be overridden. ·Cyno's Elemental Mastery and resistance to interruption will increase, and he gains immunity to Electro-Charged DMG. This effect will be canceled when Cyno leaves the field and lasts a maximum of 18s." },
  "cyno_the_passing_of_starlight": { title: "Funerary Rite: The Passing of Starlight" },
  "cyno_unceasing_vigil": { title: "Ordinance: Unceasing Vigil", description: "After using Sacred Rite: Wolf's Swiftness, Cyno's Normal Attack SPD will be increased by {atk_speed_normal} for 10s. If the Judication effect of his Passive Talent Featherfall Judgment is triggered during Secret Rite: Chasmic Soulfarer, the duration of this increase will be refreshed. You need to unlock the Passive Talent \"Featherfall Judgment.\"" },
  "cyno_wolfs_swiftness": { title: "Sacred Rite: Wolf's Swiftness", description: "<p>Calls upon a divine spirit to indwell him, morphing into the Pactsworn Pathclearer.</p><p>Pactsworn Pathclearer Cyno's Normal, Charged, and Plunging Attacks will be converted to Electro DMG that cannot be overridden. ·Cyno's Elemental Mastery and resistance to interruption will increase, and he gains immunity to Electro-Charged DMG.</p><p>This effect will be canceled when Cyno leaves the field and lasts a maximum of 18s.</p><p><i>The secret rituals passed down within the ancient nation are as a final judgment to the General Mahamatra.</i> <i>Whether now or in the past, whether great storm or serpent, none shall shake the majesty of the law.</i></p>" },
  "dahlia_collect_of_the_assembly": { title: "Collect of the Assembly", description: "The Favonian Favor from Dahlia's Elemental Burst Radiant Psalter lasts 3 more seconds." },
  "dahlia_favonius_bladework_ritual": { title: "Favonius Bladework - Ritual", description: "<p>Normal Attack Performs up to 4 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "dahlia_immersive_ordinance": { title: "Immersive Ordinance", description: "<p>Time for a fun little trick! Summons the Sacramental Shower in different ways depending on whether you Tap or Hold it.</p><p>Tap After a short prayer, summons the Sacramental Shower in front.</p><p>Hold Engages in continuous prayer, and when done, summons forth a Sacramental Shower in the designated position.</p><p>Sacramental Shower When opponents or nearby party members touch the Sacramental Shower, different effects will occur depending on the one who touches it: If an opponent touches the Shower, it will explode and deal AoE Hydro DMG to nearby opponents. If a nearby party member touches it, it will bounce the one who touches it high in the air.</p><p>Only 1 Sacramental Shower summoned by Dahlia himself can be on the field at once.</p>" },
  "dahlia_infallible_procession": { title: "Infallible Procession", description: "Each time Dahlia gains 1 of his Elemental Burst Radiant Psalter's Benison stacks, he will regain 2.5 Elemental Energy." },
  "dahlia_let_it_be_subtly_so": { title: "Let It Be Subtly So" },
  "dahlia_prayer_of_well_wrought_joy": { title: "Prayer of Well-Wrought Joy", description: "When your active party member is affected by the Favonian Favor effect of the Elemental Burst \"Radiant Psalter,\" their ATK SPD will increase based on Dahlia's Max HP: Every 1,000 Max HP will cause an increase of {text_percent}, up to a maximum of {text_percent_max}." },
  "dahlia_radiant_psalter": { title: "Radiant Psalter", description: "<p>Appeals to the divine with earnestness and song, dealing AoE Hydro DMG to nearby opponents and granting his party members Favonian Favor, summoning a Shield of Sacred Favor. The Shield of Sacred Favor's DMG absorption is based on Dahlia's Max HP, and it will absorb Hydro DMG with 250% effectiveness.</p><p>Favonian Favor While this effect is active, 1 Benison stack may be consumed to summon a new Shield of Sacred Favor when an existing Shield is broken via DMG.</p><p>Dahlia can obtain Benison via the following methods: · He will gain 1 Benison stack when his own active party member hits opponents 4 times with Normal Attacks while affected by Favonian Favor. · After triggering the effect of his Passive Talent, \"The Wind's Gentle Grace\" (You must first unlock this Passive Talent.) Dahlia can gain a maximum of 4 Benison stacks per Favonian Favor duration.</p>" },
  "dahlia_revelation_of_mercy": { title: "Revelation of Mercy", description: "After Dahlia consumes his Elemental Burst Radiant Psalter's Benison stacks to summon a Shield of Sacred Favor, the character protected by said Shield will gain {shield} increased Shield Strength for 12s." },
  "dahlia_the_winds_gentle_grace": { title: "The Wind's Gentle Grace", description: "When characters affected by the Favonian Favor effect of the Elemental Burst Radiant Psalter trigger Frozen reactions on opponents, they will grant Dahlia 2 Benison stacks. This effect can trigger once every 8s." },
  "dahlia_windblume_offertory": { title: "Windblume Offertory" },
  "dahlia_you_shall_go_out_with_joy": { title: "You Shall Go Out With Joy", description: "The current active character affected by the Elemental Burst Radiant Psalter's Favonian Favor has their ATK SPD increased by {atk_speed}. Additionally, when an active character affected by Favonian Favor falls, immediately: · Revive them. · Restore their HP to 100%. This effect can trigger once every 15 minutes." },
  "dehya_a_rage_swift_as_fire": { title: "A Rage Swift as Fire" },
  "dehya_an_oath_abiding": { title: "An Oath Abiding", description: "When Flame-Mane's Fist and Incineration Drive attacks unleashed during Leonine Bite hit opponents, they will restore 1.5 Energy for Dehya and {text_percent_heal} of her Max HP. This effect can be triggered once every 0.2s." },
  "dehya_leonine_bite": { title: "Leonine Bite", description: "<p>Unleashing her burning anger and casting her inconvenient blade aside, Dehya enters the Blazing Lioness state and increases her resistance to interruption. In this state, Dehya will automatically and continuously unleash the Flame-Mane's Fists, dealing Pyro DMG based on her ATK and Max HP, and when its duration ends, she will unleash an Incineration Drive, dealing AoE Pyro DMG based on her ATK and Max HP. If a Fiery Sanctum field created by Dehya's own Elemental Skill \"Molten Inferno\" exists when this ability is unleashed, Dehya will retrieve it, and then create another field once Blazing Lioness's duration expires. This field will take on the retrieved field's duration at the moment of its retrieval. In this state, Dehya will be unable to cast her Elemental Skill, or perform Normal, Charged, and Plunging Attacks. \"Normal Attack: Sandstorm Assault\" and Elemental Skill \"Molten Inferno\" will be replaced by \"Roaring Barrage.\"</p><p>Roaring Barrage Unleashing Roaring Barrage within 0.4s after each Flame-Mane's Fist strike will increase the speed at which the next Flame-Mane's Fist strike will be triggered.</p><p><i>Even the flowing flames must obey her rage and at her command become her fangs and claws.</i></p>" },
  "dehya_molten_inferno": { title: "Molten Inferno", description: "<p>This art of Dehya's own invention changes its method of use depending on the combat situation.</p><p>Indomitable Flame This skill will be unleashed should there be no Fiery Sanctum field created by Dehya herself present at the time. Deals AoE Pyro DMG, and creates a field known as Fiery Sanctum.</p><p>Ranging Flame This skill will be unleashed should a Fiery Sanctum field created by Dehya herself already exist. Dehya will perform a leaping attack, dealing AoE Pyro DMG before recreating a Fiery Sanctum field at her new position. A Fiery Sanctum field created this way will inherit the remaining duration of the previous field.</p><p>Ranging Flame can be used only once throughout a single Fiery Sanctum field's duration.</p><p>Fiery Sanctum When an opponent within a Fiery Sanctum field takes DMG, the field will unleash a coordinated attack, dealing AoE Pyro DMG to them based on Dehya's ATK and Max HP. This effect can be triggered once every 2.5s. Active characters within this field have their resistance to interruption increased, and when such characters take DMG, a portion of that damage will be mitigated and flow into Redmane's Blood. Dehya will then take this DMG over 10s. When the mitigated DMG stored by Redmane's Blood reaches or goes over a certain percentage of Dehya's Max HP, she will stop mitigating DMG in this way.</p><p>Only 1 Fiery Sanctum created by Dehya herself can exist at the same time.</p><p><i>Walk this fiery ordeal with me and purge all impurity, just as a beast of flames that must descend from the blaze.</i></p>" },
  "dehya_sandstorm_assault": { title: "Sandstorm Assault", description: "<p>Normal Attack Performs up to 4 consecutive strikes using her Claymore and her martial arts.</p><p>Charged Attack Drains Stamina over time to perform continuous slashes. At the end of the sequence, performs a more powerful slash.</p><p>Plunging Attack Plunges from mid-air to strike the ground, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "dehya_stalwart_and_true": { title: "Stalwart and True", description: "When her HP is less than 40%, Dehya will recover 20% of her Max HP and will restore 6% of her Max HP every 2s for the next 10s. This effect can be triggered once every 20s." },
  "dehya_the_alpha_unleashed": { title: "The Alpha Unleashed" },
  "dehya_the_burning_claws_cleaving": { title: "The Burning Claws Cleaving" },
  "dehya_the_burning_claws_cleaving_1": { description: "The CRIT Rate of Leonine Bite is increased by {crit_rate_burst}." },
  "dehya_the_burning_claws_cleaving_2": { description: "Additionally, after a Flame-Mane's Fist attack hits an opponent and deals CRIT Hits during a single Blazing Lioness state, it will cause the CRIT DMG of Leonine Bite to increase by {crit_dmg_burst} for the rest of Blazing Lioness's duration and extend that duration by 0.5s. This effect can be triggered every 0.2s. The duration can be extended for a maximum of 2s and CRIT DMG can be increased by a maximum of 60% this way." },
  "dehya_the_flame_incandescent": { title: "The Flame Incandescent", description: "Dehya's Max HP is increased by {hp_percent}, and she deals bonus DMG based on her Max HP when using the following attacks: ·Molten Inferno's DMG will be increased by {skill_base_hp_percent} of her Max HP. ·Leonine Bite's DMG will be increased by {burst_base_hp_percent} of her Max HP." },
  "dehya_the_sand_blades_glittering": { title: "The Sand-Blades Glittering", description: "When Dehya uses Molten Inferno: Ranging Flame, the duration of the recreated Fiery Sanctum field will be increased by 6s. Additionally, when a Fiery Sanctum exists on the field, DMG dealt by its next coordinated attack will be increased by {dmg_skill_dehya} when active character(s) within the Fiery Sanctum field are attacked." },
  "dehya_unstinting_succor": { title: "Unstinting Succor", description: "Within 6 seconds after Dehya retrieves the Fiery Sanctum field through Molten Inferno: Ranging Flame or Leonine Bite, she will take 60% less DMG when receiving DMG from Redmane's Blood. This effect can be triggered once every 2s. Additionally, within 9s after Dehya unleashes Molten Inferno: Indomitable Flame, she will grant all party members the Gold-Forged Form state. This state will further increase a character's resistance to interruption when they are within the Fiery Sanctum field. Gold-Forged Form can be activated once every 18s." },
  "diluc_blessing_of_phoenix": { title: "Blessing of Phoenix", description: "The Pyro Infusion provided by Dawn lasts for 4s longer. Additionally, Diluc gains {dmg_pyro} Pyro DMG Bonus during the duration of this effect." },
  "diluc_conviction": { title: "Conviction", description: "Diluc deals {dmg_all} more DMG to opponents whose HP is above 50%." },
  "diluc_dawn": { title: "Dawn", description: "<p>Releases intense flames to knock back nearby opponents, dealing Pyro DMG. The flames then converge into the weapon, summoning a Phoenix that flies forward and deals massive Pyro DMG to all opponents in its path. The Phoenix explodes upon reaching its destination, causing a large amount of AoE Pyro DMG. The searing flames that run down his blade cause it to be infused with Pyro.</p><p><i>The only reason to walk in the darkness is to light it up. Behold, that fleeing light in the dead of night is the herald of the coming dawn.</i></p>" },
  "diluc_dawn_talent": { description: "The searing flames that run down his blade cause it to be infused with Pyro." },
  "diluc_fire_and_steel": { title: "Fire and Steel" },
  "diluc_flaming_sword_nemesis_of_the_dark": { title: "Flaming Sword, Nemesis of the Dark", description: "After casting Searing Onslaught, the next 2 Normal Attacks within the next 6s will have their DMG and ATK SPD increased by {atk_speed_normal}. Additionally, Searing Onslaught will not interrupt the Normal Attack combo." },
  "diluc_flowing_flame": { title: "Flowing Flame", description: "Casting Searing Onslaught in rhythm greatly increases damage dealt. 2s after casting Searing Onslaught, casting the next Searing Onslaught in the combo deals {dmg_skill_diluc_bonus} additional DMG. This effect lasts for 2s." },
  "diluc_phoenix_harbinger_of_dawn": { title: "Phoenix, Harbinger of Dawn" },
  "diluc_relentless": { title: "Relentless", description: "Diluc's Charged Attack Stamina Cost is decreased by {stamina_consume_charged}, and its duration is increased by 3s." },
  "diluc_searing_ember": { title: "Searing Ember", description: "When Diluc takes DMG, his ATK increases by {atk_percent} and his ATK SPD increases by {atk_speed_normal}. Lasts for 10s. This effect can stack up to 3 times and can only occur once every 1.5s." },
  "diluc_searing_onslaught": { title: "Searing Onslaught", description: "<p>Performs a forward slash that deals Pyro DMG.</p><p>This skill can be consecutively used 3 times. Enters CD if not cast again within a short period.</p><p><i>The slashes represent the values that Diluc holds dear: one for justice, one for courage, and one for duty.</i></p>" },
  "diluc_tempered_sword": { title: "Tempered Sword", description: "<p>Normal Attack Performs up to 4 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous slashes. At the end of the sequence, performs a more powerful slash.</p><p>Plunging Attack Plunges from mid-air to strike the ground, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "diona_a_lingering_flavor": { title: "A Lingering Flavor", description: "Regenerates 15 Energy for Diona after the effects of Signature Mix end." },
  "diona_aanother_round": { title: "A—Another Round?" },
  "diona_cats_tail_closing_time": { title: "Cat's Tail Closing Time" },
  "diona_cats_tail_closing_time_1": { description: "Characters within Signature Mix's radius will gain the following effects based on their HP amounts: Elemental Mastery increased by {mastery} when HP is above 50%." },
  "diona_cats_tail_closing_time_2": { description: "Increases Incoming Healing Bonus by {healing_recv} when HP falls below or is equal to 50%." },
  "diona_cats_tail_secret_menu": { title: "Cat's Tail Secret Menu", description: "Characters shielded by Icy Paws have their Movement SPD increased by {move_speed} and their Stamina Consumption decreased by {stamina_consume}." },
  "diona_double_shot_on_the_rocks": { title: "Double Shot, on the Rocks" },
  "diona_drunkards_farce": { title: "Drunkards' Farce", description: "Opponents who enter the AoE of Signature Mix have {text_percent_dmg} decreased ATK for 15s." },
  "diona_icy_paws": { title: "Icy Paws", description: "<p>Fires an Icy Paw that deals Cryo DMG to opponents and forms a shield on hit. The shield's DMG Absorption scales based on Diona's Max HP, and its duration scales off the number of Icy Paws that hit their target.</p><p>Press Rapidly fires off 2 Icy Paws.</p><p>Hold Dashes back quickly before firing 5 Icy Paws. The shield created by a Hold attack will gain a 75% DMG Absorption Bonus.</p><p>The shield has a 250% Cryo DMG Absorption Bonus, and will cause your active character to become affected by Cryo at the point of formation for a short duration.</p><p><i>When she first started bartending, Diona found that no matter how much ice she put in her cocktails, it would never do a drunkard any harm. That all changed when she received her Vision — now she can form ice cold enough to cause severe brainfreeze. Five out of five stars!</i></p>" },
  "diona_katzlein_style": { title: "Kätzlein Style", description: "<p>Normal Attack Performs up to 5 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, biting frost will accumulate on the arrowhead. A fully charged frost arrow will deal Cryo DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "diona_shaken_not_purred": { title: "Shaken, Not Purred", description: "Increases Icy Paws' DMG by {dmg_skill_diona}, and increases its shield's DMG Absorption by {diona_shield}. Additionally, when paws hit their targets, creates a shield for other nearby characters on the field with {text_percent} of the Icy Paws shield's DMG Absorption for 5s." },
  "diona_signature_mix": { title: "Signature Mix", description: "<p>Tosses out a special cold brew that deals AoE Cryo DMG and creates a Drunken Mist in an AoE.</p><p>Drunken Mist ·Deals continuous Cryo DMG to opponents within the AoE. ·Continuously regenerates the HP of characters within the AoE.</p><p><i>A horrific mix that even Diona considers inhumane. The horrifying foretaste should be left for one's opponents. It has a crisp aftertaste, but unfortunately, one can only feel it on one's nose and skin.</i></p>" },
  "diona_wine_industry_slayer": { title: "Wine Industry Slayer", description: "Within the radius of Signature Mix, Diona's charge time for aimed shots is reduced by {text_percent}" },
  "dori_additional_investment": { title: "Additional Investment", description: "The number of After-Sales Service Rounds created by Troubleshooter Shots is increased by 1." },
  "dori_alcazarzarays_exactitude": { title: "Alcazarzaray's Exactitude", description: "<p>Summons forth the Jinni within the lamp to give the client various kinds of aid.</p><p>Jinni Connects to a nearby character. The connected character will: · Continuously restore HP based on Dori's Max HP. · Continuously regenerate Energy. · Be affected by Electro. When the connector between the Jinni and the character touches opponents, it will deal one instance of Electro DMG to them every 0.4s.</p><p>Only one Jinni can exist at one time.</p><p><i>\"Hmm? You'll pick this lamp, will you? Oh my, you've got good taste! Unfortunately, there's no price on this treasure — comparable, I'd say, to how you will not sell that mascot by your side for any price in the world.\"</i></p>" },
  "dori_an_eye_for_gold": { title: "An Eye for Gold", description: "After a character connected to the Jinni triggers an Electro-Charged, Lunar-Charged, Superconduct, Overloaded, Quicken, Aggravate, Hyperbloom, Electro Swirl, or Electro Crystallize reaction, the CD of Spirit-Warding Lamp: Troubleshooter Cannon is decreased by 1s. This effect can be triggered once every 3s." },
  "dori_compound_interest": { title: "Compound Interest", description: "When the Troubleshooter Shots or After-Sales Service Rounds from Spirit-Warding Lamp: Troubleshooter Cannon hit opponents, Dori will restore 5 Elemental Energy for every 100% Energy Recharge possessed. Per Spirit-Warding Lamp: Troubleshooter Cannon, only one instance of Energy restoration can be triggered and a maximum of 15 Energy can be restored this way." },
  "dori_discretionary_supplement": { title: "Discretionary Supplement" },
  "dori_discretionary_supplement_1": { description: "The character connected to the Jinni will obtain the following buffs based on their current HP and Energy: · When their HP is lower than 50%, they gain {healing_recv} Incoming Healing Bonus." },
  "dori_discretionary_supplement_2": { description: "The character connected to the Jinni will obtain the following buffs based on their current HP and Energy: · When their Energy is less than 50%, they gain {recharge} Energy Recharge." },
  "dori_marvelous_sword_dance_modified": { title: "Marvelous Sword-Dance (Modified)", description: "<p>Normal Attack Performs up to 3 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous spinning attacks against all nearby opponents. At the end of the sequence, performs a more powerful slash. </p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "dori_special_franchise": { title: "Special Franchise", description: "When you are in combat and the Jinni heals the character it is connected to, it will fire a Jinni Toop from that character's position that deals {text_percent} of Dori's ATK DMG." },
  "dori_sprinkling_weight": { title: "Sprinkling Weight", description: "Dori gains the following effects for 3s after using Spirit-Warding Lamp: Troubleshooter Cannon: ·Electro Infusion. ·When Normal Attacks hit opponents, all nearby party members will heal HP equivalent to {text_percent} of Dori's Max HP. This type of healing can occur once every 0.1s." },
  "dori_troubleshooter_cannon": { title: "Spirit-Warding Lamp: Troubleshooter Cannon", description: "<p>Directs a Spirit-Warding Lamp to fire off a Troubleshooter Shot at opponents, dealing Electro DMG. After the Troubleshooter Shot hits, it will create 2 After-Sales Service Rounds that will automatically track nearby opponents and deal Electro DMG.</p><p><i>It is said that Dori can fix any problem for you... for the right price.</i></p>" },
  "dori_value_for_mora": { title: "Value for Mora" },
  "dori_wonders_never_cease": { title: "Wonders Never Cease" },
  "emilie_aromatic_explication": { title: "Aromatic Explication", description: "<p>Guiding the fragrances collected within the Case, Emilie converts them into pure Dendro energy, creating a Level 3 Lumidouce Case and stowing existing Cases away. While it exists, the Level 3 Lumidouce Case will not gather nearby Scents, but it will continuously cause Scented Dew to descend, attacking opponents within range and dealing Dendro DMG. During this time, 1 drop of Scented Dew will descend every 0.3 seconds, and 1 opponent can become the target every 0.7 seconds. When the duration ends, a Level 1 Lumidouce Case will be recreated. If a Lumidouce Case was stowed away when using Aromatic Explication, then the Case that was stowed away will be deployed instead, and its duration will be reset. While Aromatic Explication is active, the Elemental Skill \"Fragrance Extraction\" will not create a Lumidouce Case.</p><p><i>No matter the perfume, it will begin to change the instant it comes into contact with the air, before finally dissipating amidst the whispers of wind, trees, and grass. In that sense, no two people will appreciate the exact same fragrance. So it is for the paths taken by all who live. In that sense, you can consider perfumes an explication of human life.</i></p>" },
  "emilie_exquisite_essence": { title: "Exquisite Essence" },
  "emilie_fragrance_extraction": { title: "Fragrance Extraction", description: "<p>Creates a Lumidouce Case that deals AoE Dendro DMG.</p><p>Lumidouce Case ·Fires Puffs of Puredew at nearby opponents at intervals, dealing Dendro DMG. ·When nearby opponents are affected by Burning, they will give off Scents at intervals, and 1 Scent can be created this way every 2s. The Lumidouce Case collects nearby Scents. The Lumidouce Case will level up after gathering 2 of them, after which it will fire 1 extra Puff of Puredew when firing, while the DMG dealt by and DMG AoE of the above attack will also be increased. ·1 Lumidouce Case created by Emilie herself can exist at any one time. The Case starts at Level 1 and can go up to Level 2. If the Case does not collect any Scents for 8s while it is on the field, it will go back to Level 1.</p><p>Arkhe: Pneuma At intervals, after Emilie creates a Lumidouce Case this way, a Spiritbreath Thorn will descend in front of her and pierce her opponent, dealing Pneuma-aligned Dendro DMG.</p><p><i>\"The world is an endless harmony of fragrance, color, and song.\"</i></p>" },
  "emilie_lakelight_top_note": { title: "Lakelight Top Note", description: "When Fragrance Extraction, Aromatic Explication, or Cleardew Cologne produced by the Passive Talent \"Lingering Fragrance\" (the last of which requires Passive Talent activation) hits opponents, those opponents' Dendro RES is decreased by {enemy_res_dendro} for 10s." },
  "emilie_light_fragrance_leaching": { title: "Light Fragrance Leaching", description: "Increases the DMG dealt by Fragrance Extraction and her Passive Talent's Cleardew Cologne \"Lingering Fragrance\" by {dmg_skill_emilie}. The latter requires unlocking said Passive Talent first. Additionally, when nearby party members trigger the Burning reaction on opponents or deal Dendro DMG to Burning opponents, they will generate an additional Scent. This effect can be triggered once every 2.9s." },
  "emilie_lingering_fragrance": { title: "Lingering Fragrance", description: "Each time it collects 2 Scents, the Level 2 Lumidouce Case will consume Scents and release Cleardew Cologne that deals AoE Dendro DMG equal to {text_percent_dmg} of Emilie's ATK to opponents. This DMG is not considered Elemental Skill DMG." },
  "emilie_lumidouce_heart_note": { title: "Lumidouce Heart Note", description: "Aromatic Explication's duration is increased by 2s. The interval between opponents being selected as the target for Scented Dew is decreased by 0.3s." },
  "emilie_marcotte_sillage": { title: "Marcotte Sillage", description: "When using Fragrance Extraction or Aromatic Explication, Emilie will gain Abiding Fragrance for 5s. While this is active, after Emilie uses Normal or Charged Attacks, she will generate 1 Scent, and her Normal and Charged Attack DMG will be converted into Dendro DMG that cannot be overridden, and the DMG dealt will be increased by {text_percent_dmg} of Emilie's ATK. The Abiding Fragrance effect will be removed after 4 Scents are created this way or after its duration expires. Abiding Fragrance can be triggered once every 12s." },
  "emilie_puredew_aroma": { title: "Puredew Aroma" },
  "emilie_rectification": { title: "Rectification", description: "Emilie deals increased DMG to Burning opponents based on her ATK, with every 1,000 ATK increasing DMG dealt by {text_percent_dmg}. The maximum DMG bonus that can be gained this way is {text_percent_max}." },
  "emilie_shadow_hunting_spear_custom": { title: "Shadow-Hunting Spear (Custom)", description: "<p>Normal Attack Performs up to 4 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to perform an upward slash.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "escoffier_better_to_salivate_than_medicate": { title: "Better to Salivate Than Medicate", description: "After using the Elemental Burst Scoring Cuts, Escoffier will obtain the Rehab Diet effect for 9s: Restores HP for nearby active characters every 1s based on {text_percent_dmg} of Escoffier's ATK." },
  "escoffier_fresh_fragrant_stew_is_an_art": { title: "Fresh, Fragrant Stew Is an Art", description: "When Escoffier activates her Cooking Mek in its Cold Storage Mode, she will gain the \"Freshly-Prepped Delicacy\" effect for 15s. During this time, Escoffier will gain 5 Cold Dish stacks. When nearby active characters apart from Escoffier deal Cryo DMG with a Normal, Charged, or Plunging Attack, or an Elemental Skill or Elemental Burst, they will expend 1 Cold Dish stack to increase their DMG dealt by {text_percent_dmg} of Escoffier's ATK. If you hit multiple opponents with a single instance of Cryo DMG, Cold Dish stacks will be consumed based on the number of opponents hit." },
  "escoffier_inspiration_immersed_seasoning": { title: "Inspiration-Immersed Seasoning", description: "When there are 1/2/3/4 Hydro or Cryo characters in the party, Escoffier will decrease the Hydro RES and Cryo RES of any opponents hit by her Elemental Skill, Low-Temperature Cooking, or her Elemental Burst, Scoring Cuts, by 5/10/15/55% for 12s." },
  "escoffier_kitchen_skills": { title: "Kitchen Skills", description: "<p>Normal Attack Performs up to 3 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to perform an upward thrust.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "escoffier_low_temperature_cooking": { title: "Low-Temperature Cooking", description: "<p>Behold the true meaning of \"cooking\"! Escoffier will demonstrate different cooking techniques when you Tap or Hold this skill, but rest assured, each of them is Fontaine's pride and joy.</p><p>Tap Activates her All-Spectrum Multi-Use Cooking Mek in its Cold Storage mode and deals AoE Cryo DMG to nearby opponents.</p><p>Cooking Mek: Cold Storage Mode Follows the current active character and fires Frosty Parfaits at nearby opponents at intervals, dealing Cryo DMG.</p><p>Arkhe: Ousia At intervals, Escoffier will summon a Surging Blade when activating her Cooking Mek in Cold Storage mode, dealing Ousia-aligned AoE Cryo DMG.</p><p>Hold Activates her All-Spectrum Multi-Use Cooking Mek's Off-the-Cuff Cookery Mode.</p>" },
  "escoffier_pre_dinner_dance_for_your_taste_buds": { title: "Pre-Dinner Dance for Your Taste Buds", description: "When 4 party members are Hydro or Cryo, all nearby party members will have their Cryo DMG CRIT DMG increased by {crit_dmg_cryo} for 15s after Escoffier uses her Elemental Skill Low-Temperature Cooking or Elemental Burst Scoring Cuts. You must first unlock the Passive Talent \"Inspiration-Immersed Seasoning.\"" },
  "escoffier_scoring_cuts": { title: "Scoring Cuts", description: "<p>Displaying her exceptional knife skills, Escoffier deals AoE Cryo DMG and restores HP to all nearby party members based on her ATK.</p>" },
  "escoffier_secret_rosemary_recipe": { title: "Secret Rosemary Recipe", description: "Rehab Diet lasts 6 more seconds. While it is active, you have a chance of healing {crit_dmg_escofier_heal} extra HP and restoring 2 Energy to Escoffier when you trigger healing through Rehab Diet. This chance corresponds to Escoffier's CRIT Rate. You can trigger this effect 7 times during any one Rehab Diet's duration. You must first unlock the Passive Talent \"Better to Salivate Than Medicate.\"" },
  "escoffier_symphony_of_a_thousand_sauces": { title: "Symphony of a Thousand Sauces" },
  "escoffier_tea_parties_bursting_with_color": { title: "Tea Parties Bursting With Color", description: "Cooking Mek: Cold Storage Mode is enhanced: · When your party's active character's Normal, Charged, or Plunging Attacks hit opponents, Cooking Mek: Cold Storage Mode will fire off another Special-Grade Frosty Parfait, dealing {text_percent_dmg} of Escoffier's ATK as AoE Cryo DMG. This DMG is considered Elemental Skill DMG. This effect can be triggered once every 0.5s, and this effect can be triggered 6 times within the duration of one Cooking Mek: Cold Storage Mode." },
  "escoffier_the_bakery_magic_of_caramel_browning": { title: "The Bakery Magic of Caramel Browning" },
  "eula_chivalric_quality": { title: "Chivalric Quality" },
  "eula_constellation_5": { title: "Chivalric Quality" },
  "eula_favonius_bladework_edel": { title: "Favonius Bladework - Edel", description: "<p>Normal Attack Performs up to 5 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous slashes. At the end of the sequence, performs a more powerful slash.</p><p>Plunging Attack Plunges from mid-air to strike the ground, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "eula_glacial_illumination": { title: "Glacial Illumination", description: "<p>Brandishes her greatsword, dealing Cryo DMG to nearby opponents and creating a Lightfall Sword that follows her around for a duration of up to 7s. While present, the Lightfall Sword increases Eula's resistance to interruption. When Eula's own Normal Attack, Elemental Skill, and Elemental Burst deal DMG to opponents, they will charge the Lightfall Sword, which can gain an energy stack once every 0.1s. Once its duration ends, the Lightfall Sword will descend and explode violently, dealing Physical DMG to nearby opponents. This DMG scales on the number of energy stacks the Lightfall Sword has accumulated. If Eula leaves the field, the Lightfall Sword will explode immediately.</p><p><i>It is easy to sink. But even so, she desires to freeze this oncoming tide.</i></p>" },
  "eula_grimheart": { title: "Grimheart", description: "Increases Eula's resistance to interruption and DEF by {def_percent}." },
  "eula_icetide_vortex": { title: "Icetide Vortex", description: "<p>Sharp frost, swift blade.</p><p>Press Slashes swiftly, dealing Cryo DMG. When it hits an opponent, Eula gains a stack of Grimheart that stacks up to 2 times. These stacks can only be gained once every 0.3s.</p><p>Grimheart Increases Eula's resistance to interruption and DEF.</p><p>Hold Wielding her sword, Eula consumes all the stacks of Grimheart and lashes forward, dealing AoE Cryo DMG to opponents in front of her. If Grimheart stacks are consumed, surrounding opponents will have their Physical RES and Cryo RES decreased. Each consumed stack of Grimheart will be converted into an Icewhirl Brand that deals Cryo DMG to nearby opponents.</p><p><i>\"So the waves roiled, swallowing the crown of the nobles. And ever after did each drop amidst the icy waves reflect a golden crown, each and every droplet of the spray shining with its light.\"</i></p>" },
  "eula_icewhirl_brand": { title: "Icetide Vortex", description: "If Grimheart stacks are consumed, surrounding opponents will have their Physical RES and Cryo RES decreased." },
  "eula_lady_of_seafoam": { title: "Lady of Seafoam", description: "Decreases the CD of Icetide Vortex's Holding Mode, rendering it identical to Press CD." },
  "eula_lawrence_pedigree": { title: "Lawrence Pedigree" },
  "eula_lightfall_stacks": { title: "Lightfall Sword energy stacks", description: "Lightfall Sword DMG scales on the number of energy stacks the Lightfall Sword has accumulated." },
  "eula_noble_obligation": { title: "Noble Obligation", description: "Lightfall Swords created by Glacial Illumination start with 5 stacks of energy. Normal Attacks, Elemental Skills, and Elemental Bursts have a 50% chance to grant the Lightfall Sword an additional stack of energy." },
  "eula_roiling_rime": { title: "Roiling Rime", description: "If 2 stacks of Grimheart are consumed upon unleashing the Holding Mode of Icetide Vortex, a Shattered Lightfall Sword will be created that will explode immediately, dealing {text_percent_dmg} of the basic Physical DMG dealt by a Lightfall Sword created by Glacial Illumination." },
  "eula_the_obstinacy_of_ones_inferiors": { title: "The Obstinacy of One's Inferiors", description: "Lightfall Swords deal {dmg_burst_eula} increased DMG against opponents with less than 50% HP." },
  "eula_tidal_illusion": { title: "Tidal Illusion", description: "Every time Icetide Vortex's Grimheart stacks are consumed, Eula's Physical DMG is increased by {dmg_phys} for 6s. Each stack consumed will increase the duration of this effect by 6s up to a maximum of 18s." },
  "eula_wellspring_of_war_lust": { title: "Wellspring of War-Lust", description: "When Glacial Illumination is cast, the CD of Icetide Vortex is reset and Eula gains 1 stack of Grimheart." },
  "fading_twilight": { title: "Radiance of the Deeps", description: "Has three states, Evengleam, Afterglow, and Dawnblaze, which increase DMG dealt. When attacks hit opponents, this weapon will switch to the next state. This weapon can change states once every 7s. The character equipping this weapon can still trigger the state switch while not on the field." },
  "faruzan_divine_comprehension": { title: "Divine Comprehension", description: "The vortex created by Pressurized Collapses will restore Energy to Faruzan based on the number of opponents hit: If it hits 1 opponent, it will restore 2 Energy for Faruzan. Each additional opponent hit will restore 0.5 more Energy for Faruzan. A maximum of 4 Energy can be restored to her per vortex." },
  "faruzan_impetuous_flow": { title: "Impetuous Flow", description: "When Faruzan is in the Manifest Gale state created by Wind Realm of Nasamjnin, the amount of time taken to charge a shot is decreased by 60%, and she can apply The Wind's Secret Ways' Perfidious Wind's Bale to opponents who are hit by the vortex created by Pressurized Collapse." },
  "faruzan_lost_wisdom_of_the_seven_caverns": { title: "Lost Wisdom of the Seven Caverns", description: "When characters affected by The Wind's Secret Ways' Prayerful Wind's Benefit deal Anemo DMG using Normal, Charged, Plunging Attacks, Elemental Skills, or Elemental Bursts to opponents, they will gain the Hurricane Guard effect: This DMG will be increased based on {text_percent_dmg} of Faruzan's Base ATK. 1 instance of Hurricane Guard can occur once every 0.8s. This DMG Bonus will be cleared after Prayerful Wind's Benefit expires or after the effect is triggered once." },
  "faruzan_overzealous_intellect": { title: "Overzealous Intellect", description: "The duration of the Dazzling Polyhedron created by The Wind's Secret Ways is increased by 6s." },
  "faruzan_parthian_shot": { title: "Parthian Shot", description: "<p>Normal Attack Performs up to 4 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, mighty winds will accumulate on the arrowhead. A fully charged wind arrow will deal Anemo DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, hitting opponents along the path and dealing AoE DMG upon impact.</p>" },
  "faruzan_spirit_orchard_stroll": { title: "Spirit-Orchard Stroll" },
  "faruzan_the_winds_secret_ways": { title: "The Wind's Secret Ways", description: "<p>Faruzan deploys a Dazzling Polyhedron that unleashes a Whirlwind Pulse and deals AoE Anemo DMG. While the Dazzling Polyhedron persists, it will continuously move along a triangular path. Once it reaches each corner of that triangular path, it will unleash 1 more Whirlwind Pulse.</p><p>Whirlwind Pulse ·When the Whirlwind Pulse is unleashed, it will apply Perfidious Wind's Bale to nearby opponents, decreasing their Anemo RES. ·The Whirlwind Pulse will also apply Prayerful Wind's Benefit to all nearby party members when it is unleashed, granting them an Anemo DMG Bonus.</p><p><i>One must have respect for the unknown wisdom that one might find hidden in ancient ruins.</i></p>" },
  "faruzan_the_wondrous_path_of_truth": { title: "The Wondrous Path of Truth" },
  "faruzan_the_wondrous_path_of_truth_1": { description: "Characters affected by The Wind's Secret Ways' Prayerful Wind's Benefit have {crit_dmg_anemo} increased CRIT DMG when they deal Anemo DMG." },
  "faruzan_the_wondrous_path_of_truth_2": { description: "When the active character deals DMG while affected by Prayerful Wind's Benefit, they will apply Pressurized Collapse to the opponent damaged. This effect can be triggered once every 3s. This CD is shared between all party members." },
  "faruzan_truth_by_any_means": { title: "Truth by Any Means", description: "Faruzan can fire off a maximum of 2 Hurricane Arrows using fully charged Aimed Shots while under the effect of a single Manifest Gale created by Wind Realm of Nasamjnin." },
  "faruzan_wind_bale": { title: "Perfidious Wind's Bale", description: "When the Whirlwind Pulse is unleashed, it will apply Perfidious Wind's Bale to nearby opponents, decreasing their Anemo RES." },
  "faruzan_wind_benefit": { title: "Prayerful Wind's Benefit", description: "The Whirlwind Pulse will apply Prayerful Wind's Benefit to all nearby party members when it is unleashed, granting them an Anemo DMG Bonus." },
  "faruzan_wind_realm_of_nasamjnin": { title: "Wind Realm of Nasamjnin", description: "<p>Faruzan deploys a polyhedron that deals AoE Anemo DMG to nearby opponents. She will also enter the Manifest Gale state. While in the Manifest Gale state, Faruzan's next fully charged shot will consume this state and will become a Hurricane Arrow that contains high-pressure currents. This arrow deals Anemo DMG based on the DMG of a fully charged Aimed Shot from \"Normal Attack: Parthian Shot.\"</p><p>Pressurized Collapse The Hurricane Arrow will apply a Pressurized Collapse effect to the opponent or character hit. This effect will be removed after a short delay, creating a vortex that deals AoE Anemo DMG and pulls nearby objects and opponents in. If the Hurricane Arrow does not hit any opponent or character, it will create a Pressurized Collapse effect at its point of impact. The vortex DMG is considered Elemental Skill DMG.</p><p><i>The winds of truth buffet the spirits of those who seek truth, dispersing the miasma of preconception.</i></p>" },
  "faruzan_wonderland_of_rumination": { title: "Wonderland of Rumination" },
  "fischl_against_the_fleeing_light": { title: "Against the Fleeing Light" },
  "fischl_bolts_of_downfall": { title: "Bolts of Downfall", description: "<p>Normal Attack Performs up to 5 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, the dark lightning spirits of Immernachtreich shall heed the call of their Prinzessin and indwell the enchanted arrowhead. When fully indwelt, the Rachsüchtig Blitz shall deal immense Electro DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "fischl_devourer_of_all_sins": { title: "Devourer of All Sins", description: "When Nightrider is used, it deals an additional {text_percent_dmg} ATK as DMG, and its AoE is increased by 50%." },
  "fischl_evernight_raven": { title: "Evernight Raven", description: "Extends the duration of Oz's presence on the field by 2s. Additionally, Oz performs coordinated attacks with your active character when present, dealing {text_percent_dmg} of Fischl's ATK as Electro DMG." },
  "fischl_gaze_of_the_deep": { title: "Gaze of the Deep", description: "Even when Oz is not present in combat, he can still watch over Fischl through his raven eyes. When Fischl performs a Normal Attack against an opponent, Oz fires a coordinated attack, dealing DMG equal to {text_percent_dmg} of Fischl's ATK." },
  "fischl_her_pilgrimage_of_bleak": { title: "Her Pilgrimage of Bleak", description: "When Midnight Phantasmagoria is used, it deals {text_percent_dmg} of ATK as Electro DMG to surrounding opponents. When the skill duration ends, Fischl regenerates {text_percent_hp} of her HP." },
  "fischl_midnight_phantasmagoria": { title: "Midnight Phantasmagoria", description: "<p>Summons Oz to spread his twin wings of twilight and defend Fischl. Has the following properties during the ability's duration: ·Fischl takes on Oz's form, greatly increasing her Movement Speed. ·Strikes nearby opponents with lightning, dealing Electro DMG to opponents she comes into contact with. Each opponent can only be struck once. ·Once this ability's effects end, Oz will remain on the battlefield and attack his Prinzessin's foes. If Oz is already on the field, then this will reset the duration of his presence.</p><p><i>\"...In the hordes of beasts that follow the cursed blood, only Prince Nachtraben, who bore witness to the extinction of a thousand worlds, knows her true greatness. Thus the night wings he spreads are his eternal promise to protect Her Royal Highness.\"</i> <i>—Flowers for Princess Fischl (I): End Time Zersetzung</i></p>" },
  "fischl_nightrider": { title: "Nightrider", description: "<p>Summons Oz. The night raven forged of darkness and lightning descends upon the land, dealing Electro DMG in a small AoE. For the ability's duration, Oz will continuously attack nearby opponents with Freikugel.</p><p>Hold to adjust the location Oz will be summoned to. Press again any time during the ability's duration to once again summon him to Fischl's side.</p><p><i>\"My time is most precious, and I shall not waste it on the likes of you... Go, Oz, fall upon them, and bring down upon them your Rachsüchtig Blitz, that which tears open the long night.\"</i> <i>—Flowers for Princess Fischl (IV): Farewell Frau Welt</i></p>" },
  "fischl_stellar_predator": { title: "Stellar Predator", description: "When Fischl hits Oz with a fully-charged Aimed Shot, Oz brings down Thundering Retribution, dealing AoE Electro DMG equal to {text_percent_dmg} of the arrow's DMG." },
  "fischl_undone_be_thy_sinful_hex": { title: "Undone Be Thy Sinful Hex", description: "If your current active character triggers an Electro-related Elemental Reaction when Oz is on the field, the opponent shall be stricken with Thundering Retribution that deals Electro DMG equal to {text_percent_dmg} of Fischl's ATK." },
  "fischl_wings_of_nightmare": { title: "Wings of Nightmare" },
  "freminet_dance_of_the_snowy_moon_and_flute": { title: "Dance of the Snowy Moon and Flute", description: "After Freminet triggers Frozen, Shatter, or Superconduct against opponents, his ATK will be increased by {atk_percent} for 6s. Max 2 stacks. This can be triggered once every 0.3s." },
  "freminet_dreams_of_the_foamy_deep": { title: "Dreams of the Foamy Deep", description: "The CRIT Rate of Pressurized Floe: Shattering Pressure will be increased by {crit_rate_freminet}." },
  "freminet_flowing_eddies": { title: "Flowing Eddies", description: "<p>Normal Attack Performs up to 4 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous spinning attacks against all nearby opponents. At the end of the sequence, performs a more powerful slash. </p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "freminet_moment_of_waking_and_resolve": { title: "Moment of Waking and Resolve", description: "After Freminet triggers Frozen, Shatter, or Superconduct against opponents, his CRIT DMG will be increased by {crit_dmg} for 6s. Max 3 stacks. This can be triggered once every 0.3s." },
  "freminet_nights_of_hearth_and_happiness": { title: "Nights of Hearth and Happiness" },
  "freminet_parallel_condensers": { title: "Parallel Condensers", description: "When Freminet triggers Shatter against opponents, the DMG dealt by Pressurized Floe: Shattering Pressure will be increased by {dmg_skill_freminet} for 5s." },
  "freminet_penguins_and_the_land_of_plenty": { title: "Penguins and the Land of Plenty", description: "Unleashing Pressurized Floe: Shattering Pressure will restore 2 Energy to Freminet. If a Pressure Level 4 Shattering Pressure is unleashed, this will restore 3 Energy." },
  "freminet_pressurized_floe": { title: "Pressurized Floe", description: "<p>Performs an upward thrust that deals Cryo DMG and causes Freminet to enter Pers Timer for 10s. While Pers Timer is active, his Elemental Skill will turn into Shattering Pressure.</p><p>Shattering Pressure Executes different sorts of attacks based on the Pressure Level of Pers Timer, and then cancels Pers Timer. ·Level 0: Unleashes a vertical cut, dealing Cryo DMG. ·Levels 1 to 3: Unleashes a vertical cut alongside Pers, dealing Cryo DMG and Physical DMG. DMG dealt scales based on Pressure Level. ·Level 4: Borrows the power of a fully-pressurized Pers to deal Physical DMG. Meanwhile, Normal Attack: Flowing Eddies will be replaced by Shattering Pressure.</p><p>Pers Timer When Freminet uses Normal Attacks, he will also unleash waves of frost that deal Cryo DMG and increase Pers's Pressure Level. The accompanying Cryo DMG dealt this way is considered Elemental Skill DMG.</p><p>Arkhe: Pneuma At certain intervals, after using the upward thrust, a Spiritbreath Thorn in the form of another upward thrust will be created, dealing Pneuma-aligned Cryo DMG.</p><p><i>To immobilize one's opponent without taking their life can also be considered something of a \"survival\" strategy that one may choose.</i> <i>\"Pers... I leave the rest to you.\"</i></p>" },
  "freminet_saturation_deep_dive": { title: "Saturation Deep Dive", description: "When Freminet unleashes Pressurized Floe: Shattering Pressure, if Pers Timer has yet to reach Pressure Level 4, the CD of Pressurized Floe will be decreased by 1s." },
  "freminet_shadowhunters_ambush": { title: "Shadowhunter's Ambush", description: "<p>Unleashes a wave of untouchable cold, dealing AoE Cryo DMG, resetting the CD of the Elemental Skill \"Pressurized Floe,\" and causing Freminet to enter the Subnautical Hunter mode for 10s.</p><p>While in Subnautical Hunter mode, Freminet's resistance to interruption will increase, and his Elemental Skill \"Pressurized Floe\" will obtain the following buffs: ·CD is decreased by 70%. ·Normal Attacks will increase the Pers Timer by 1 additional Pressure Level, and the frost released by his Normal Attacks deal 200% of their original DMG.</p><p>These effects will be canceled when Freminet leaves the field.</p><p><i>\"Now... I have no need of any extraneous noise.\"</i></p>" },
  "freminet_song_of_the_eddies_and_bleached_sands": { title: "Song of the Eddies and Bleached Sands" },
  "furina_a_woman_adapts_like_duckweed_in_water": { title: "\"A Woman Adapts Like Duckweed in Water\"", description: "While Let the People Rejoice lasts, Furina's Fanfare gain from increases or decreases in nearby characters' HP is increased by 250%. Each point of Fanfare above the limit will increase Furina's Max HP by {text_percent}. Her maximum Max HP increase is {text_percent_max}." },
  "furina_endless_waltz": { title: "Endless Waltz", description: "When the active character in your party receives healing, if the source of the healing is not Furina herself and the healing overflows, then Furina will heal nearby party members for {text_percent_heal} of their Max HP once every 2s for the next 4s." },
  "furina_hear_me_let_us_raise_the_chalice_of_love": { title: "\"Hear Me — Let Us Raise the Chalice of Love!\"", description: "When using Salon Solitaire, Furina gains \"Center of Attention\" for 10s. Throughout the duration, Furina's Normal Attacks, Charged Attacks, and Plunging Attacks are converted into Hydro DMG which cannot be overridden by any other elemental infusion. DMG is also increased by an amount equivalent to {text_percent_dmg_1} of Furina's max HP. Throughout the duration, Furina's Normal Attacks (not including Arkhe: Seats Sacred and Secular Attacks), Charged Attacks, and the impact of Plunging Attacks will cause different effects up to every 0.1s after hitting opponents depending on her current Arkhe alignment: Arkhe: Ousia Every 1s, all nearby characters in the party will be healed by {text_percent_heal} of Furina's max HP, for a duration of 2.9s. Triggering this effect again will extend its duration. Arkhe: Pneuma This Normal Attack (not including Arkhe: Seats Sacred and Secular Attacks), Charged Attack, or Plunging Attack ground impact DMG will be further increased by an amount equivalent to {text_percent_dmg_2} of Furina's max HP. When any of the attacks mentioned previously hit an opponent, all nearby characters in the party will consume 1% of their current HP. During the duration of each instance of \"Center of Attention,\" the above effects can be triggered up to 6 times. \"Center of Attention\" will end when its effects have triggered 6 times or when the duration expires." },
  "furina_his_name_i_now_know_it_is": { title: "\"His Name I Now Know, It Is...!\"" },
  "furina_let_the_people_rejoice": { title: "Let the People Rejoice", description: "<p>Rouses the impulse to revel, creating a stage of foam that will deal AoE Hydro DMG based on Furina's Max HP and cause nearby party members to enter the Universal Revelry state: During this time, when nearby party members' HP increases or decreases, 1 Fanfare point will be granted to Furina for each percentage point of their Max HP by which their HP changes. At the same time, Furina will increase the DMG dealt by and Incoming Healing Bonus of all nearby party members based on the amount of Fanfare she has. When the duration ends, Furina's Fanfare points will be cleared.</p><p><i>\"Cheer! Give praise! Be awed! Raise your glasses! Every night bereft of banqueting is a sordid squandering of sore, sober daylight... And, uh, those who are not yet of age may have grape juice instead!\"</i></p>" },
  "furina_love_is_a_rebellious_bird_that_none_can_tame": { title: "\"Love Is a Rebellious Bird That None Can Tame\"", description: "When using Let the People Rejoice, Furina will gain {text_value} Fanfare. Additionally, Furina's Fanfare limit is increased by {text_value_max}." },
  "furina_my_secret_is_hidden_within_me_no_one_will_know_my_name": { title: "\"My Secret Is Hidden Within Me, No One Will Know My Name\"" },
  "furina_salon_solitaire": { title: "Salon Solitaire", description: "<p>Invites the guests of the Salon Solitaire to come forth and aid in Furina's performance. Will summon either the Salon Members or the Singer of Many Waters based on Furina's current Arkhe alignment.</p><p>Ousia Foaming bubbles like celebrants shall dance, dealing AoE Hydro DMG based on Furina's Max HP and summoning 3 Salon Members: the Ball Octopus-shaped Gentilhomme Usher, the Bubbly Seahorse-shaped Surintendante Chevalmarin, and the Armored Crab-shaped Mademoiselle Crabaletta. They will attack nearby opponents at intervals, prioritizing the target of the active character, dealing Hydro DMG based on Max HP. When they attack, if character(s) with more than 50% HP are nearby, the Members will increase their current attack's power based on the number of such characters, and consume said characters' HP. If 1/2/3/4 (or more) characters meet these requirements, the Members' attacks will deal 110%/120%/130%/140% of their original DMG.</p><p>Pneuma Summons the Singer of Many Waters, who will heal nearby active character(s) based on Max HP at intervals.</p><p>The Salon Members and Singer of Many Waters share a duration, and when Furina uses her Charged Attack to change the guest type, the new guests will inherit the remaining duration. While the Salon Members or the Singer of Many Waters is on the field, Furina can move on the water's surface.</p><p><i>A fixed roster of regulars frequent Furina's Salon Solitaire. At other times, Mademoiselle Crabaletta, Surintendante Chevalmarin, and Gentilhomme Usher shall visit, and on gloomy Wednesdays, it is the singer who comes by.</i></p>" },
  "furina_soloists_solicitation": { title: "Soloist's Solicitation", description: "<p>Normal Attack Performs up to 4 consecutive strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash a solo dance, dealing Physical DMG to nearby opponents and changing her Arkhe alignment. If Salon Members or the Singer of Many Waters summoned by her Elemental Skill \"Salon Solitaire\" is present, their lineup will switch in response.</p><p>Arkhe: Seats Sacred and Secular At intervals, when Furina's Normal Attacks hit, a Spiritbreath Thorn or a Surging Blade will descend based on her current Arkhe alignment, dealing Pneuma- or Ousia-aligned Hydro DMG. When Furina takes the field, her starting Arkhe alignment will be Ousia.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "furina_they_know_not_life_who_dwelt_in_the_netherworld_not": { title: "\"They Know Not Life, Who Dwelt in the Netherworld Not!\"", description: "When the Salon Members from Salon Solitaire hit an opponent, or the Singer of Many Waters restores HP to nearby active characters, Furina will restore 4 Energy. This effect can be triggered once every 5s." },
  "furina_unheard_confession": { title: "Unheard Confession", description: "Every 1,000 points of Furina's Max HP can buff the different Arkhe-aligned Salon Solitaire in the following ways: Will increase Salon Members' DMG dealt by {text_percent_dmg}, up to a maximum of {text_percent_dmg_max}. Will decrease the Singer of Many Waters' healing interval for nearby active characters by {text_percent_heal}, up to a maximum of {text_percent_heal_max}." },
  "gaming_air_of_prosperity": { title: "Air of Prosperity" },
  "gaming_air_of_prosperity_1": { description: "When Gaming has less than 50% HP, he will receive a {healing_recv} Incoming Healing Bonus." },
  "gaming_air_of_prosperity_2": { description: "When Gaming has 50% HP or more, Plunging Attack: Charmed Cloudstrider will deal {dmg_skill_gaming} more DMG." },
  "gaming_awakening_spirit": { title: "Awakening Spirit" },
  "gaming_bestial_ascent": { title: "Bestial Ascent", description: "<p>Pounces forward using the Wushou arts, leaping high into the air after coming into contact with a target or surface. After Gaming has used Bestial Ascent to rise into the air, if he immediately uses a Plunging Attack, he will use the especially powerful Plunging Attack: Charmed Cloudstrider instead.</p><p>Plunging Attack: Charmed Cloudstrider The DMG from Plunging Attacks caused by Bestial Ascent is converted to Pyro DMG that cannot be overridden by other elemental infusions. Upon landing, Gaming will consume a fixed amount of HP. Gaming's HP cannot be reduced below 10% by this method. Charmed Cloudstrider DMG is considered Plunging Attack DMG.</p><p><i>\"Auspicious beasts leap high to pluck the greens — that symbolizes good fortune and knowing how to make some serious green, y'know — so may we all rise to new heights, one step at a time!\"</i></p>" },
  "gaming_bringer_of_blessing": { title: "Bringer of Blessing", description: "When the Suanni Man Chai from Suanni's Gilded Dance meets back up with Gaming, it will heal {text_percent_heal} of Gaming's HP." },
  "gaming_dance_of_amity": { title: "Dance of Amity", description: "After Bestial Ascent's Plunging Attack: Charmed Cloudstrider hits an opponent, Gaming will regain {text_percent_heal} of his Max HP once every 0.2s for 0.8s." },
  "gaming_evil_daunting_roar": { title: "Evil-Daunting Roar" },
  "gaming_plum_blossoms_underfoot": { title: "Plum Blossoms Underfoot", description: "When Gaming receives healing and this instance of healing overflows, his ATK will be increased by {atk_percent} for 5s." },
  "gaming_soar_across_mountains": { title: "Soar Across Mountains", description: "When Bestial Ascent's Plunging Attack: Charmed Cloudstrider hits an opponent, it will restore 2 Energy to Gaming. This effect can be triggered once every 0.2s." },
  "gaming_stellar_rend": { title: "Stellar Rend", description: "<p>Normal Attack Performs up to 4 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous spinning attacks against all nearby opponents. At the end of the sequence, performs a more powerful slash. </p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "gaming_suannis_gilded_dance": { title: "Suanni's Gilded Dance", description: "<p>Gaming enters Wushou Stance, briefly applying Pyro to him, recovering a fixed amount of HP, and summons his companion, the Suanni Man Chai, to smash into his target, dealing AoE Pyro DMG. After bashing its target, Man Chai will roll to a nearby location before moving towards Gaming. When it links up with Gaming, Man Chai will leave the field and reset the CD for Gaming's Elemental Skill, Bestial Ascent. While Wushou Stance is active, his resistance to interruption is increased, and when Gaming lands with Charmed Cloudstrider attack or completes the forward pounce attack from Bestial Ascent with over 50% HP, he will summon Man Chai again. Each Gaming can only have 1 Man Chai on the field simultaneously. This effect will be canceled once Gaming leaves the field.</p><p><i>\"The gilded Suanni spits out fortune like a fireworks show! Hey, now that's what's called prosperity, when business is really 'booming'!\"</i></p>" },
  "gaming_to_tame_all_beasts": { title: "To Tame All Beasts", description: "Bestial Ascent's Plunging Attack: Charmed Cloudstrider CRIT Rate increased by {crit_rate_gaming} and CRIT DMG increased by {crit_dmg_gaming}, and its attack radius will be increased." },
  "ganyu_celestial_shower": { title: "Celestial Shower", description: "<p>Coalesces atmospheric frost and snow to summon a Sacred Cryo Pearl that exorcises evil. During its ability duration, the Sacred Cryo Pearl will continuously rain down shards of ice, striking opponents within an AoE and dealing Cryo DMG.</p><p><i>Ganyu can bring down sweet rains as a matter of course. But against demons and heretics, they become bitter, freezing snow.</i></p>" },
  "ganyu_cloud_strider": { title: "Cloud-Strider" },
  "ganyu_dew_drinker": { title: "Dew-Drinker", description: "Charge Level 2 Frostflake Arrows or Frostflake Arrow Blooms decrease opponents' Cryo RES by {enemy_res_cryo} for 6s upon hit. A hit also regenerates 2 Energy for Ganyu. This effect can only occur once per Charge Level 2 Frostflake Arrow, regardless if Frostflake Arrow itself or its Bloom hits the target." },
  "ganyu_harmony_between_heaven_and_earth": { title: "Harmony Between Heaven and Earth", description: "Celestial Shower grants a {dmg_cryo} Cryo DMG Bonus to active party members in the AoE." },
  "ganyu_liutian_archery": { title: "Liutian Archery", description: "<p>Normal Attack Performs up to 6 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, an icy aura will accumulate on the arrowhead before the arrow is fired. Has different effects based on how long the energy has been charged: ·Charge Level 1: Fires off an icy arrow that deals Cryo DMG. ·Charge Level 2: Fires off a Frostflake Arrow that deals Cryo DMG. The Frostflake Arrow blooms after hitting its target, dealing AoE Cryo DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "ganyu_the_auspicious": { title: "The Auspicious", description: "Trail of the Qilin gains 1 additional charge." },
  "ganyu_the_clement": { title: "The Clement", description: "Using Trail of the Qilin causes the next Frostflake Arrow shot within 30s to not require charging." },
  "ganyu_the_merciful": { title: "The Merciful" },
  "ganyu_trail_of_the_qilin": { title: "Trail of the Qilin", description: "<p>Leaving a single Ice Lotus behind, Ganyu dashes backward, shunning all impurity and dealing AoE Cryo DMG.</p><p>Ice Lotus ·Continuously taunts surrounding opponents, attracting them to attack it. ·Endurance scales based on Ganyu's Max HP. ·Blooms profusely when destroyed or once its duration ends, dealing AoE Cryo DMG.</p><p><i>\"You saw me, you say? You must be mistaken. I was working overtime then.\"</i></p>" },
  "ganyu_undivided_heart": { title: "Undivided Heart", description: "After firing a Frostflake Arrow, the CRIT Rate of subsequent Frostflake Arrows and their resulting bloom effects is increased by {crit_rate_ganyu} for 5s." },
  "ganyu_westward_sojourn": { title: "Westward Sojourn", description: "Opponents standing within the AoE of Celestial Shower take increased DMG. This effect strengthens over time. Increased DMG taken begins at {dmg_all} and increases by {dmg_all} every 3s, up to a maximum of 25%. The effect lingers for 3s after the opponent leaves the AoE." },
  "gorou_a_favor_repaid": { title: "A Favor Repaid", description: "Gorou receives the following DMG Bonuses to his attacks based on his DEF: · Inuzaka All-Round Defense: Skill DMG increased by {text_percent_1} of DEF · Juuga: Forward Unto Victory: Skill DMG and Crystal Collapse DMG increased by {text_percent_2} of DEF" },
  "gorou_crunch": { title: "Crunch", description: "Having 3 Geo party members adds the \"Crunch\" effect: grants a Geo DMG Bonus." },
  "gorou_fierce_as_fire": { title: "Mauling Hound: Fierce as Fire" },
  "gorou_forward_unto_victory": { title: "Juuga: Forward Unto Victory", description: "<p>Displaying his valor as a general, Gorou deals AoE Geo DMG and creates a field known as General's Glory to embolden his comrades.</p><p>General's Glory This field has the following properties: · Like the General's War Banner created by Inuzaka All-Round Defense, provides buffs to active characters within the skill's AoE based on the number of Geo characters in the party. Also moves together with your active character. · Generates 1 Crystal Collapse every 1.5s that deals AoE Geo DMG to 1 opponent within the skill's AoE. · Pulls 1 elemental shard in the skill's AoE to your active character's position every 1.5s (elemental shards are created by Crystallize reactions).</p><p>If a General's War Banner created by Gorou currently exists on the field when this ability is used, it will be destroyed. In addition, for the duration of General's Glory, Gorou's Elemental Skill \"Inuzaka All-Round Defense\" will not create the General's War Banner. If Gorou falls, the effects of General's Glory will be cleared.</p><p><i>\"We have the high ground!\" Gorou can ever so slightly change the terrain of the battlefield to help win victory. This technique has seen him through many battles against seemingly superior opposition.</i></p>" },
  "gorou_generals_war_banner": { title: "General's War Banner", description: "Provides the following buffs to active characters within the ability's AoE based on the number of party members in-field at the time who are of the Geo Element. Only 1 General's War-Banner that Gorou created himself can exist on the field at any one time. Characters can only benefit from 1 General's War-Banner at a time. When members leave the field, the field's effects will last for 2s." },
  "gorou_heedless_of_the_wind_and_weather": { title: "Heedless of the Wind and Weather", description: "After using Juuga: Forward Unto Victory, all nearby party members' DEF is increased by {def_percent} for 12s." },
  "gorou_impregnable": { title: "Impregnable", description: "Having 2 Geo party members adds the \"Impregnable\" effect: grants resistance to interruption." },
  "gorou_inuzaka_all_round_defense": { title: "Inuzaka All-Round Defense", description: "<p>Deals AoE Geo DMG and sets up a General's War Banner.</p><p>General's War Banner Provides up to 3 buffs to active characters within the skill's AoE based on the number of Geo characters in the party at the time of casting: · 1 Geo character: Adds \"Standing Firm\" - DEF Bonus. · 2 Geo characters: Adds \"Impregnable\" - Increased resistance to interruption. · 3 Geo characters: Adds \"Crunch\" - Geo DMG Bonus.</p><p>Gorou can deploy only 1 General's War Banner on the field at any one time. Characters can only benefit from 1 General's War Banner at a time. When a party member leaves the field, the active buff will last for 2s.</p><p>Hold Adjust the location of the skill.</p><p><i>\"Take up this formation and we'll be safe — I guarantee it!\" As a general and a leader of troops, the last thing Gorou wants is to see is those who follow him getting hurt.</i></p>" },
  "gorou_mountainous_fealty": { title: "Valiant Hound: Mountainous Fealty", description: "For 12s after using Inuzaka All-Round Defense or Juuga: Forward Unto Victory, increases the CRIT DMG of all nearby party members' Geo DMG based on the buff level of the skill's field at the time of use: · \"Standing Firm\": +10% · \"Impregnable\": +20% · \"Crunch\": +40% This effect cannot stack and will take reference from the last instance of the effect that is triggered." },
  "gorou_ripping_fang_fletching": { title: "Ripping Fang Fletching", description: "<p>Normal Attack Performs up to 4 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, stone crystals will accumulate on the arrowhead. A fully charged crystalline arrow will deal Geo DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "gorou_standing_firm": { title: "Standing Firm", description: "Having 1 Geo party member grants \"Standing Firm\": DEF Bonus." },
  "gorou_steady_as_a_clock": { title: "Sitting Hound: Steady as a Clock", description: "While General's Glory is in effect, its duration is extended by 1s when a nearby active character obtains an Elemental Shard from a Crystallize reaction. This effect can occur once every 0.1s. Max extension is 3s." },
  "gorou_swift_as_the_wind": { title: "Rushing Hound: Swift as the Wind", description: "When characters (other than Gorou) within the AoE of Gorou's General's War Banner or General's Glory deal Geo DMG to opponents, the CD of Gorou's Inuzaka All-Round Defense is decreased by 2s. This effect can occur once every 10s." },
  "gorou_thunderous_force": { title: "Striking Hound: Thunderous Force" },
  "gorou_warm_as_water": { title: "Lapping Hound: Warm as Water", description: "When General's Glory is in the \"Impregnable\" or \"Crunch\" states, it will also heal active characters within its AoE by {text_percent} of Gorou's own DEF every 1.5s." },
  "haran_geppaku_futsu": { title: "Honed Flow" },
  "haran_geppaku_futsu_1": { description: "Obtain {dmg_pyro} All Elemental DMG Bonus." },
  "haran_geppaku_futsu_2": { title: "Rippling Upheaval", description: "When other nearby party members use Elemental Skills, the character equipping this weapon will gain 1 Wavespike stack. Max 2 stacks. This effect can be triggered once every 0.3s. When the character equipping this weapon uses an Elemental Skill, all stacks of Wavespike will be consumed to gain Rippling Upheaval: each stack of Wavespike consumed will increase Normal Attack DMG by {dmg_normal} for 8s." },
  "heizou_declension_stacks": { title: "Declension stacks", description: "Increases the power of the next Heartstopper Strike." },
  "hu_tao_butterflys_embrace": { title: "Butterfly's Embrace", description: "Triggers when Hu Tao's HP drops below 25%, or when she suffers a lethal strike: Hu Tao will not fall as a result of the DMG sustained. Additionally, for the next 10s, her All Elemental and Physical RES is increased by {res_phys}, her CRIT Rate is increased by {crit_rate}, and her resistance to interruption is greatly increased. This effect triggers automatically when Hu Tao has 1 HP left. Can only occur once every 60s." },
  "hu_tao_crimson_bouquet": { title: "Crimson Bouquet", description: "While in a Paramita Papilio state activated by Guide to Afterlife, Hu Tao's Charged Attacks do not consume Stamina." },
  "hu_tao_floral_incense": { title: "Floral Incense" },
  "hu_tao_flutter_by": { title: "Flutter By", description: "When a Paramita Papilio state activated by Guide to Afterlife ends, all allies in the party (excluding Hu Tao herself) will have their CRIT Rate increased by {text_percent} for 8s." },
  "hu_tao_garden_of_eternal_rest": { title: "Garden of Eternal Rest", description: "Upon defeating an enemy affected by a Blood Blossom that Hu Tao applied herself, all nearby allies in the party (excluding Hu Tao herself) will have their CRIT Rate increased by {text_percent} for 15s." },
  "hu_tao_guide_to_afterlife": { title: "Guide to Afterlife", description: "<p>Only an unwavering flame can cleanse the impurities of this world. Hu Tao consumes a set portion of her HP to knock the surrounding enemies back and enter the Paramita Papilio state.</p><p>Paramita Papilio ·Increases Hu Tao's ATK based on her Max HP at the time of entering this state. ATK Bonus gained this way cannot exceed 400% of Hu Tao's Base ATK. ·Converts attack DMG to Pyro DMG, which cannot be overridden by any other elemental infusion. ·Charged Attacks apply the Blood Blossom effect to the enemies hit. ·Increases Hu Tao's resistance to interruption.</p><p>Blood Blossom Enemies affected by Blood Blossom will take Pyro DMG every 4s. This DMG is considered Elemental Skill DMG. Each enemy can be affected by only one Blood Blossom effect at a time, and its duration may only be refreshed by Hu Tao herself.</p><p>Paramita Papilio ends when its duration is over, or Hu Tao has left the battlefield or fallen.</p><p><i>Hu Tao's Secret Spear technique is based on several rules, the first of which is: \"The spear opens the path to the afterlife, and the butterflies bridge this world and the next.\"</i></p>" },
  "hu_tao_lingering_carmine": { title: "Lingering Carmine" },
  "hu_tao_ominous_rainfall": { title: "Ominous Rainfall", description: "Increases the Blood Blossom DMG by an amount equal to {text_percent} of Hu Tao's Max HP at the time the effect is applied. Additionally, Spirit Soother will also apply the Blood Blossom effect." },
  "hu_tao_sanguine_rouge": { title: "Sanguine Rouge", description: "When Hu Tao's HP is equal to or less than 50%, her Pyro DMG Bonus is increased by {dmg_pyro}." },
  "hu_tao_secret_spear_of_wangsheng": { title: "Secret Spear of Wangsheng", description: "<p>Normal Attack Performs up to 6 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "hu_tao_spirit_soother": { title: "Spirit Soother", description: "<p>Commands a blazing spirit to attack, dealing Pyro DMG in a large AoE. Upon striking the enemy, regenerates a percentage of Hu Tao's Max HP. This effect can be triggered up to 5 times, based on the number of enemies hit. If Hu Tao's HP is below or equal to 50% when the enemy is hit, both the DMG and HP Regeneration are increased.</p><p><i>Supernatural activity by those who have already left this world is a source of great anxiety for the Wangsheng Funeral Parlor. In such cases, cremation always lets Hu Tao find peace of mind. The more anxious she feels, the stronger the flame.</i></p>" },
  "hutao_paramita_papilio": { title: "Paramita Papilio", description: "Increases Hu Tao's ATK based on her Max HP at the time of entering this state. ATK Bonus gained this way cannot exceed {text_percent_hp} of Hu Tao's Base ATK. Hu Tao's attack DMG is converted to Pyro DMG, which cannot be overridden by any other elemental infusion." },
  "iansan_enhanced_resistance_training": { title: "Enhanced Resistance Training", description: "After Swift Stormflight hits opponents, Iansan will gain the Precise Movement effect for 15s. During this time, her ATK is increased by {atk_percent}, and whenever she regains Nightsoul points through the Kinetic Energy Scale in her Elemental Burst, The Three Principles of Power, she will gain 1 extra Nightsoul point. Additionally, when your current active party member consumes or restores Nightsoul points, the extra Nightsoul points Iansan gains the next time she restores Nightsoul points via the Scale will be increased to 4. This effect can occur once every 2.8s. \"Precise Movement\" will expire when Iansan's Nightsoul's Blessing state ends." },
  "iansan_kinetic_energy_gradient_test": { title: "Kinetic Energy Gradient Test", description: "When a nearby party member triggers a Nightsoul Burst, Iansan will obtain the Warming Up effect for 10s. During this time, when Iansan restores at least 1 Nightsoul point, she will heal your current active character for {text_percent_heal} of her ATK. This effect can be triggered once every 2.8s." },
  "iansan_laziness_is_the_enemy": { title: "Laziness is the Enemy!" },
  "iansan_laziness_is_the_enemy_1": { description: "When using the Elemental Burst The Three Principles of Power, Iansan will also gain the Precise Movement effect from her Passive Talent \"Enhanced Resistance Training\" for 15s." },
  "iansan_laziness_is_the_enemy_2": { description: "If Iansan is off-field while Precise Movement is active, she will also increase your current active character's ATK by {text_percent}. You must first unlock the Passive Talent \"Enhanced Resistance Training\" to access the above effect." },
  "iansan_scientific_diet_planning": { title: "Scientific Diet Planning" },
  "iansan_slow_and_steady_wins_the_race": { title: "Slow and Steady Wins the Race", description: "When the Kinetic Energy Scale is present, Iansan will gain 2 stacks of Surging Force after your current active character (excluding herself) uses their Elemental Burst. The stacks last until the Scale leaves the field, and Surging Force can be gained once per Scale summoning. Whenever Iansan restores Nightsoul points via the Scale, she will consume 1 Surging Force stack and restore 4 additional Nightsoul points. Additionally, if her Nightsoul restoration from the Scale overflows, Iansan will gain 50% of the overflow the next time she restores Nightsoul points via the Scale." },
  "iansan_startings_never_easy": { title: "Starting's Never Easy", description: "When Iansan is in combat and is in the Nightsoul's Blessing state, she will restore 15 Elemental Energy for every 6 Nightsoul points she consumes. This effect can trigger once every 18s." },
  "iansan_teachings_of_the_collective_of_plenty": { title: "Teachings of the Collective of Plenty" },
  "iansan_teachings_of_the_collective_of_plenty_1": { description: "The Kinetic Energy Scale's duration is increased by 3s." },
  "iansan_teachings_of_the_collective_of_plenty_2": { description: "When Iansan triggers Nightsoul point restoration, if there is any overflow, she will gain the Extreme Force effect, which increases the DMG dealt by your current active character by {dmg_all} for 3s." },
  "iansan_the_three_principles_of_power": { title: "The Three Principles of Power", description: "<p>Iansan's stomping foot shatters the very earth with \"Power,\" dealing Nightsoul-aligned AoE Electro DMG. She then whips out her \"Limited-Edition Kinetic Energy Scale (For Workouts).\" When this Skill is used, Iansan will gain 15 Nightsoul points and enter the Nightsoul's Blessing state. When the Kinetic Energy Scale leaves the field, Iansan's Nightsoul's Blessing state will end.</p><p>Kinetic Energy Scale The Kinetic Energy Scale will follow the character around, boosting the ATK of your current active party member in different ways based on Iansan's Nightsoul points. · If Iansan has less than 42 Nightsoul points, the ATK bonus will be based on her Nightsoul points and ATK. · If Iansan has at least 42 Nightsoul points, the Kinetic Energy Scale will switch to the \"Ardent Support!\" state, in which the ATK bonus will be stronger and based on her ATK alone. Additionally, the Scale will log the distance your current active character (excluding Iansan) has moved so long as it is active, restoring Nightsoul points to Iansan every second based on the distance moved in the previous second. The Scale will disappear once her Nightsoul's Blessing state ends. It will also disappear after 1 second when you are not in a state of combat. While it is active, Iansan's Nightsoul's Blessing state will not end even if she is not on the field.</p><p><i>\"Power is not about natural talent. Power stems from unceasing practice. Power must be exercised correctly.\"</i></p>" },
  "iansan_thunderbolt_rush": { title: "Thunderbolt Rush", description: "<p>Iansan charges forward a certain distance, dealing Nightsoul-aligned Electro DMG to all opponents in her path. After this Skill is used, Iansan will regain 54 Nightsoul points and enter the Nightsoul's Blessing state. Within 5s after this is done, using a Normal Attack will trigger 1 quick Swift Stormflight stomp from Iansan that will not consume Stamina.</p><p>Nightsoul's Blessing: Iansan Continuously consumes Nightsoul points. If she runs out, or uses this Skill again, her Nightsoul's Blessing state will end. It has the following properties: · Increases Iansan's Movement SPD. · Holding sprint will switch Iansan to Rushing Thunderbolt mode, greatly increasing her Movement SPD temporarily. In this mode, Iansan can make flying leaps using terrain, or consume additional Nightsoul points to move on water or liquid Phlogiston while being immune to DMG from the latter.</p><p><i>\"Faster, stronger! That's what all that hard work is for!\"</i></p>" },
  "iansan_we_can_push_it_further": { title: "We Can Push It Further!" },
  "iansan_weighted_spike": { title: "Weighted Spike", description: "<p>Normal Attack Performs up to 3 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p><p>Nightsoul State: Swift Stormflight While in the Nightsoul's Blessing state: Iansan's Charged Attack will be transformed into the formidable Swift Stormflight, consuming a certain amount of Stamina to stomp fiercely down, dealing Nightsoul-aligned AoE Electro DMG.</p>" },
  "ifa_airborne_disease_prevention": { title: "Airborne Disease Prevention", description: "<p>It's time for the real bash bros to step up! Ifa calls Cacucu in as backup. After using this skill, Ifa gains 80 Nightsoul points and enters the Nightsoul's Blessing state. In the Nightsoul's Blessing state, Ifa will hover with Cacucu's help. When he uses Normal Attacks in this state, he will use different kinds of Supporting Fire depending on whether you Tap or Hold, firing Tonicshots that are capable of healing all party members.</p><p>Additionally, Holding the Elemental Skill Airborne Disease Prevention while Ifa is in Nightsoul's Blessing will cause him to use a Nightsoul-aligned Plunging Attack. Letting go of the skill button will interrupt this Plunging Attack to maintain his hover. If Ifa lands due to this Plunging Attack, his Nightsoul's Blessing state will end.</p>" },
  "ifa_compound_sedation_field": { title: "Compound Sedation Field", description: "<p>Fires a Therapeutic Sedative at a (temporarily aggressive) opponent. The sedative will explode on impact, creating a restraining wind current that pulls nearby objects and opponents in while dealing Nightsoul-aligned AoE Anemo DMG. When the Therapeutic Sedative hits an opponent affected by Hydro/Pyro/Cryo/Electro, it will apply a Sedation Mark to them.</p>" },
  "ifa_decayed_vessels_permutation": { title: "Decayed Vessel's Permutation", description: "The restraining wind current created by the Elemental Burst Compound Sedation Field has its duration extended to 3s. Additionally, Ifa gains {mastery} Elemental Mastery for 15s after using his Elemental Burst Compound Sedation Field." },
  "ifa_field_medics_vision": { title: "Field Medic's Vision", description: "When Ifa is in the Nightsoul's Blessing state, every 1 Nightsoul point out of the total in his entire party will grant him 1 Rescue Essentials point. Rescue Essentials will increase the Swirl, Electro-Charged, and Lunar-Charged DMG dealt by nearby party members." },
  "ifa_guiding_spirit_of_ballistic_prayer": { title: "Guiding Spirit of Ballistic Prayer", description: "When Ifa is in the Nightsoul's Blessing state, every Nightsoul point the party has above a total of 60 will grant Ifa 4 additional Rescue Essentials points. Additionally, Ifa's Rescue Essentials limit is increased by 50. You must first unlock the Passive Talent Field Medic's Vision." },
  "ifa_mutual_aid_agreement": { title: "Mutual Aid Agreement", description: "When nearby party members trigger Nightsoul Bursts, Ifa's Elemental Mastery increases by {mastery} for 10s." },
  "ifa_oath_on_a_feathered_knot": { title: "Oath on a Feathered Knot", description: "When Ifa uses the Hold version of his Supporting Fire, there is a 50% chance that he will fire an additional Tonicshot that deals {text_percent_dmg} of Ifa's ATK as Anemo DMG. This DMG is considered Normal Attack DMG. Additionally, when he is not in combat, Ifa will consume 20% less Nightsoul points and Phlogiston in his Nightsoul's Blessing state." },
  "ifa_rebuttal_in_negotiations_with_the_night": { title: "Rebuttal in Negotiations With the Night" },
  "ifa_rite_of_dispelling_winds": { title: "Rite of Dispelling Winds", description: "<p>Normal Attack Performs up to 3 attacks, dealing Anemo DMG.</p><p>Charged Attack Consumes a certain amount of Stamina and fires off a shot, dealing AoE Anemo DMG.</p><p>Plunging Attack Plunges towards the ground from mid-air, damaging all opponents along the path. Deals AoE Anemo DMG upon impact with the ground.</p>" },
  "ifa_vitiferous_elixirs_concoction": { title: "Vitiferous Elixir's Concoction", description: "When Supporting Fire hits an opponent, it will restore 6 Energy for Ifa. One such Energy restoration can be triggered once every 8s." },
  "ifa_vow_of_universal_coexistence": { title: "Vow of Universal Coexistence" },
  "ineffa_a_dawning_morn_for_you": { title: "A Dawning Morn for You", description: "When Ineffa is affected by the Carrier Flow Composite effect, she will deal AoE Electro DMG equal to {text_percent_dmg} of her ATK to opponents in the current active character's vicinity after nearby thunderclouds release bursts of lightning at opponents. This DMG is considered Lunar-Charged DMG. The aforementioned effect can trigger once every 3.5s." },
  "ineffa_assemblage_hub": { title: "Moonsign Benediction: Assemblage Hub", description: "When a party member triggers an Electro-Charged reaction, it will be converted into the Lunar-Charged reaction, with every 100 ATK that Ineffa has increasing Lunar-Charged's Base DMG by {text_percent}, up to a maximum of {text_percent_max}. Further blessings may follow the new moon's rise..." },
  "ineffa_carrier_frequency": { title: "Cleaning Mode: Carrier Frequency", description: "<p>Ineffa engages her Enhanced Cleaning Module, dealing a single instance of AoE Electro DMG to nearby opponents, activating her Optical Flow Shield Barrier, and summoning the Multipurpose Smart Assistance Unit, Birgitta. The Optical Flow Shield Barrier absorbs DMG based on Ineffa's ATK, and it will absorb Electro DMG with 250% effectiveness.</p>" },
  "ineffa_cyclonic_duster": { title: "Cyclonic Duster", description: "<p>Normal Attack Performs up to 4 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to perform a spinning attack.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "ineffa_cyclonic_exterminator": { title: "Supreme Instruction: Cyclonic Exterminator", description: "<p>Through Multipurpose Smart Assistance Unit, Birgitta, Ineffa can use Rocket Punches to quickly clean up opponents! Shoots Birgitta into the fray, dealing AoE Electro DMG and allowing Birgitta to remain on the field.</p><p>If Birgitta is already on the field, having been summoned by Ineffa, this Skill will re-summon Birgitta at the target's location and reset her duration.</p>" },
  "ineffa_enhanced_emotion_emulator": { title: "Enhanced Emotion Emulator" },
  "ineffa_mirrors_dream_transcension": { title: "Mirror's Dream Transcension" },
  "ineffa_overclocking_circuit": { title: "Overclocking Circuit", description: "If there are thunderclouds created by Lunar-Charged reactions nearby when Birgitta unleashes Discharge attacks, she will initiate an additional attack, dealing AoE Electro DMG equal to {text_percent_dmg} of Ineffa's ATK. This DMG is considered Lunar-Charged DMG." },
  "ineffa_panoramic_permutation_protocol": { title: "Panoramic Permutation Protocol", description: "When using the Elemental Burst Supreme Instruction: Cyclonic Exterminator, all your party members will gain the Parameter Permutation effect: Increases Ineffa and your own active party member's Elemental Mastery by {text_percent} of Ineffa's ATK for 20s." },
  "ineffa_rectifying_processor": { title: "Rectifying Processor", description: "When Ineffa activates her Optical Flow Shield Barrier, all nearby party members will gain the Carrier Flow Composite effect for 20s: Increases Lunar-Charged DMG by {text_percent} for every 100 ATK that Ineffa has, up to a maximum of {text_percent_max}." },
  "ineffa_support_cleaning_module": { title: "Support Cleaning Module", description: "After the Elemental Burst Supreme Instruction: Cyclonic Exterminator hits opponents, it will inflict the Punishment Edict status on one of those hit opponents: After a brief delay, or when this opponent is defeated, nearby opponents will take AoE Electro DMG equal to {text_percent_dmg} of Ineffa's ATK. This DMG is considered Lunar-Charged DMG. Additionally, when the Elemental Burst Supreme Instruction: Cyclonic Exterminator is unleashed, nearby party members will gain Optical Flow Shield Barriers." },
  "ineffa_the_edictless_path": { title: "The Edictless Path", description: "When your own party members trigger Lunar-Charged reactions, recover 5 Elemental Energy. This effect can occur once every 4s." },
  "itto_royal_descent": { title: "The Raging Oni King", description: "This state has the following special properties: • Normal, Charged, and Plunging Attacks will be converted to Geo DMG. This cannot be overridden. • namew{Itto}'s Normal Attack SPD will be increased by {atk_speed_normal}. His ATK will be increased based on his DEF. • The first and third combos of his attacks will grant Arataki Itto himself 1 stack of Superlative Superstrength when they hit opponents. • bane{Itto}'s Elemental and Physical RES are decreased by {res_phys}. The Raging Oni King state will be cleared when Itto leaves the field." },
  "jean_dandelion_breeze": { title: "Dandelion Breeze", description: "<p>Calling upon the wind's protection, Jean creates a swirling Dandelion Field, launching surrounding opponents and dealing Anemo DMG. At the same time, she instantly regenerates a large amount of HP for all party members. The amount of HP restored scales off Jean's ATK.</p><p>Dandelion Field ·Continuously regenerates HP of characters within the AoE and continuously imbues them with Anemo. ·Deals Anemo DMG to opponents entering or exiting the Dandelion Field.</p><p><i>Jean's magnanimity is as vast as the dandelion fields, and it is the root of her wish to protect others.</i></p>" },
  "jean_favonius_bladework": { title: "Favonius Bladework", description: "<p>Normal Attack Performs up to 5 consecutive strikes.</p><p>Charged Attack Consumes a certain amount of stamina to launch an opponent using the power of wind. Launched opponents will slowly fall to the ground.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "jean_gale_blade": { title: "Gale Blade", description: "<p>Focusing the might of the formless wind around her blade, Jean releases a miniature storm, launching opponents in the direction she aims at, dealing massive Anemo DMG.</p><p>Hold At the cost of continued stamina consumption, Jean can command the whirlwind to pull surrounding opponents and objects towards her front. Direction can be adjusted. Character is immobile during skill duration.</p><p><i>That which follows Jean, the wholehearted defender, is a guardian wind that can banish danger from her comrades' presence.</i></p>" },
  "jean_lands_of_dandelion": { title: "Lands of Dandelion", description: "Within the Field created by Dandelion Breeze, all opponents have their Anemo RES decreased by {enemy_res_anemo}." },
  "jean_let_the_wind_lead": { title: "Let the Wind Lead", description: "Using Dandelion Breeze will regenerate {text_percent} of its Energy." },
  "jean_lions_fang_fair_protector_of_mondstadt": { title: "Lion's Fang, Fair Protector of Mondstadt", description: "Incoming DMG is decreased by {dmg_reduction} within the Field created by Dandelion Breeze. Upon leaving the Dandelion Field, this effect lasts for 3 attacks or 10s." },
  "jean_outbursting_gust": { title: "Outbursting Gust" },
  "jean_peoples_aegis": { title: "People's Aegis", description: "When Jean picks up an Elemental Orb/Particle, all party members have their Movement SPD and ATK SPD increased by {atk_speed_normal} for 15s." },
  "jean_spiraling_tempest": { title: "Spiraling Tempest", description: "Increases the pulling speed of Gale Blade after holding for more than 1s, and increases the DMG dealt by {dmg_skill_jean}." },
  "jean_when_the_west_wind_arises": { title: "When the West Wind Arises" },
  "jean_wind_companion": { title: "Wind Companion", description: "On hit, Jean's Normal Attacks have a 50% chance to regenerate HP equal to {text_percent_dmg} of Jean's ATK for all party members." },
  "kachina_all_ive_collected_till_now": { title: "All I've Collected Till Now" },
  "kachina_cragbiter": { title: "Cragbiter", description: "<p>Normal Attack Performs up to 4 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "kachina_go_go_turbo_twirly": { title: "Go, Go Turbo Twirly!", description: "<p>Fight alongside the turbo trusty Turbo Twirly! Summons Turbo Twirly. When the skill is Held and released, Kachina will summon and ride Turbo Twirly. After the Skill is used, Kachina will gain 60 Nightsoul points and enter the Nightsoul's Blessing state.</p><p>Nightsoul's Blessing: Kachina Turbo Twirly's various actions consume Kachina's Nightsoul points. The Nightsoul's Blessing state will end when these points have been depleted.</p><p>Turbo Twirly Can exist independently or be ridden and operated by Kachina. When Turbo Twirly is present, Kachina's Elemental Skill, \"Go, Go Turbo Twirly!\", will change to an option to Mount/Dismount Turbo Twirly. ·When present independent of Kachina, it will slam the ground at intervals, dealing Nightsoul-aligned AoE Geo DMG based on Kachina's DEF. ·When Kachina is riding Turbo Twirly, she can control it to move and climb swiftly, and use Normal Attacks to slam the ground, dealing Nightsoul-aligned AoE Geo DMG based on Kachina's DEF.</p><p>Turbo Twirly will disappear once Kachina's Nightsoul's Blessing state ends, and it is considered a Geo Construct. Only 1 Turbo Twirly created by Kachina herself can exist on the field at any one time.</p><p><i>Turbo Twirly only looks like a top — it is, in fact, a drill that can split even the strongest rock asunder!</i></p>" },
  "kachina_improved_stabilizer": { title: "Improved Stabilizer" },
  "kachina_more_foes_more_caution": { title: "More Foes, More Caution", description: "When there are 1/2/3/4 (or more) opponents within the Turbo Drill Field created by \"Time to Get Serious!\", the active character within the field gains 8%/12%/16%/20% increased DEF." },
  "kachina_mountain_echoes": { title: "Mountain Echoes", description: "After nearby party members trigger a Nightsoul Burst, Kachina's Geo DMG Bonus increases by {dmg_geo} for 12s." },
  "kachina_never_leave_home_without_turbo_twirly": { title: "Never Leave Home Without... Turbo Twirly", description: "When Kachina uses \"Time to Get Serious!\", she will regain 20 Nightsoul points. If there is no Turbo Twirly belonging to her on the field, she will enter Nightsoul's Blessing and summon one." },
  "kachina_shards_are_gems_too": { title: "Shards Are Gems Too", description: "When Kachina mounts or dismounts Turbo Twirly, she will absorb nearby Elemental Shards created by Crystallize. Additionally, when a party member picks up such a Shard, 3 Energy will be restored to Kachina. Energy can be restored this way once every 5s." },
  "kachina_the_weight_of_stone": { title: "The Weight of Stone", description: "Turbo Twirly's DMG is increased by {text_percent} of Kachina's DEF." },
  "kachina_this_time_ive_gotta_win": { title: "This Time, I've Gotta Win", description: "When your active character's Shield is replaced or destroyed for any reason, Kachina will deal {text_percent_dmg} of her DEF as AoE Geo DMG. This effect can be triggered once every 5s." },
  "kachina_time_to_get_serious": { title: "Time to Get Serious!", description: "<p>Striking the ground, Kachina deals AoE Geo DMG based on her DEF and creates a Turbo Drill Field. The Field increases Turbo Twirly's attack AoE and its Movement SPD when Kachina is riding it.</p><p>If Kachina's own Turbo Twirly is present when this is used, the Turbo Twirly will be summoned to her side.</p><p><i>Just as nervous performers might imagine audience members as wooden puppets, Kachina imagines that her opponents are the loveliest of gem-bearing ores — the kind you'd be proud to bring home and hoard.</i></p>" },
  "kaedehara_kazuha_chihayaburu": { title: "Chihayaburu", description: "<p>Unleashes a secret technique as fierce as the rushing wind that pulls objects and opponents towards Kazuha's current position before launching opponents within the AoE, dealing Anemo DMG and lifting Kazuha into the air on a rushing gust of wind. Within 10s of remaining airborne after casting Chihayaburu, Kazuha can unleash a powerful Plunging Attack known as Midare Ranzan.</p><p>Press Can be used in mid-air.</p><p>Hold Charges up before unleashing greater Anemo DMG over a larger AoE than Press Mode.</p><p>Plunging Attack: Midare Ranzan When a Plunging Attack is performed using the effects of the Elemental Skill Chihayaburu, Plunging Attack DMG is converted to Anemo DMG. On landing, Kazuha creates a small wind tunnel via a secret blade technique that pulls in nearby objects and opponents. Midare Ranzan's DMG is considered Plunging Attack DMG.</p><p><i>\"Wind in branches grieves Bygone ages, gods of old Withered autumn leaves\"</i></p>" },
  "kaedehara_kazuha_crimson_momiji": { title: "Crimson Momiji", description: "After using Chihayaburu or Kazuha Slash, Kaedehara Kazuha gains an Anemo Infusion for 5s. Additionally, each point of Elemental Mastery will increase the DMG dealt by Kaedehara Kazuha's Normal, Charged, and Plunging Attacks by {text_percent_dmg}." },
  "kaedehara_kazuha_garyuu_bladework": { title: "Garyuu Bladework", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact. If this Plunging Attack is triggered by Chihayaburu, it will be converted to Plunging Attack: Midare Ranzan.</p><p>Plunging Attack: Midare Ranzan When a Plunging Attack is performed using the effects of the Elemental Skill Chihayaburu, Plunging Attack DMG is converted to Anemo DMG and will create a small wind tunnel via a secret blade technique that pulls in nearby objects and opponents.</p>" },
  "kaedehara_kazuha_kazuha_slash": { title: "Kazuha Slash", description: "<p>The signature technique of Kazuha's self-styled bladework — a single slash that strikes with the force of the first winds of autumn, dealing AoE Anemo DMG. The blade's passage will leave behind a field named \"Autumn Whirlwind\" that periodically deals AoE Anemo DMG to opponents within its range.</p><p>Elemental Absorption If Autumn Whirlwind comes into contact with Hydro/Pyro/Cryo/Electro, it will deal additional elemental DMG of that type. Elemental Absorption may only occur once per use.</p><p><i>\"I see eternity go by in an instant, the autumns of many years from a single leaf. Thus I shall slice this maple in a flash, and ask a question of the ages.\"</i></p>" },
  "kaedehara_kazuha_maple_monogatari": { title: "Maple Monogatari" },
  "kaedehara_kazuha_oozora_genpou": { title: "Oozora Genpou", description: "When Kaedehara Kazuha's Energy is lower than 45, he obtains the following effects: ·Pressing or Holding Chihayaburu regenerates 3 or 4 Energy for Kaedehara Kazuha, respectively. ·When gliding, Kaedehara Kazuha regenerates 2 Energy per second." },
  "kaedehara_kazuha_poetics_of_fuubutsu": { title: "Poetics of Fuubutsu", description: "Upon triggering a Swirl reaction, Kaedehara Kazuha will grant all party members a 0.04% Elemental DMG Bonus to the element absorbed by Swirl for every point of Elemental Mastery he has for 8s. Bonuses for different elements obtained through this method can co-exist." },
  "kaedehara_kazuha_scarlet_hills": { title: "Scarlet Hills", description: "Decreases Chihayaburu's CD by {text_percent_cd}. Using Kazuha Slash resets the CD of Chihayaburu." },
  "kaedehara_kazuha_soumon_swordsmanship": { title: "Soumon Swordsmanship", description: "If Chihayaburu comes into contact with Hydro/Pyro/Cryo/Electro when cast, this Chihayaburu will absorb that element and if Plunging Attack: Midare Ranzan is used before the effect expires, it will deal an additional {text_percent_dmg} ATK of the absorbed elemental type as DMG. This will be considered Plunging Attack DMG. Elemental Absorption may only occur once per use of Chihayaburu." },
  "kaedehara_kazuha_wisdom_of_bansei": { title: "Wisdom of Bansei" },
  "kaedehara_kazuha_yamaarashi_tailwind": { title: "Yamaarashi Tailwind", description: "The Autumn Whirlwind field created by Kazuha Slash has the following effects: · Increases Kaedehara Kazuha's own Elemental Mastery by {mastery} for its duration. · Increases the Elemental Mastery of characters within the field by {mastery}. The Elemental Mastery-increasing effects of this Constellation do not stack." },
  "kaeya_ceremonial_bladework": { title: "Ceremonial Bladework", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "kaeya_cold_blooded_strike": { title: "Cold-Blooded Strike", description: "Every hit with Frostgnaw regenerates HP for Kaeya equal to {text_percent_dmg} of his ATK." },
  "kaeya_dance_of_frost": { title: "Dance of Frost" },
  "kaeya_excellent_blood": { title: "Excellent Blood", description: "The CRIT Rate of Kaeya's Normal and Charge Attacks against opponents affected by Cryo is increased by {crit_rate_kaeya}." },
  "kaeya_frostbiting_embrace": { title: "Frostbiting Embrace" },
  "kaeya_frostgnaw": { title: "Frostgnaw", description: "<p>Unleashes a frigid blast, dealing Cryo DMG to opponents in front of Kaeya.</p><p><i>Kaeya seems affable, but his nature is that of unyielding ice.</i></p>" },
  "kaeya_frozen_kiss": { title: "Frozen Kiss", description: "Triggers automatically when Kaeya's HP falls below 20%: Creates a shield that absorbs damage equal to {text_percent} of Kaeya's Max HP. Lasts for 20s. This shield absorbs Cryo DMG with 250% efficiency. Can only occur once every 60s." },
  "kaeya_glacial_heart": { title: "Glacial Heart", description: "Opponents Frozen by Frostgnaw will drop additional Elemental Particles. Frostgnaw may only produce a maximum of 2 additional Elemental Particles per use." },
  "kaeya_glacial_waltz": { title: "Glacial Waltz", description: "<p>Coalescing the frost in the air, Kaeya summons 3 icicles that revolve around him. These icicles will follow the character around and deal Cryo DMG to opponents in their path for the ability's duration.</p><p><i>A winsome smile, genial words, and the merciless hoarfrost that lies beneath... These are all Kaeya's weapons.</i></p>" },
  "kaeya_glacial_whirlwind": { title: "Glacial Whirlwind", description: "Glacial Waltz will generate 1 additional icicle, and will regenerate 15 Energy when cast." },
  "kaeya_never_ending_performance": { title: "Never-Ending Performance", description: "While Glacial Waltz is in effect, for each opponent defeated, its duration is increased by 2.5s, up to a maximum of 15s." },
  "kamisato_ayaka_amatsumi_kunitsumi_sanctification": { title: "Amatsumi Kunitsumi Sanctification", description: "After using Kamisato Art: Hyouka, Kamisato Ayaka's Normal and Charged Attacks deal {dmg_normal} increased DMG for 6s." },
  "kamisato_ayaka_blizzard_blade_seki_no_to": { title: "Blizzard Blade Seki no To", description: "When casting Kamisato Art: Soumetsu, unleashes 2 smaller additional Frostflake Seki no To, each dealing {text_percent_dmg} of the original storm's DMG." },
  "kamisato_ayaka_blossom_cloud_irutsuki": { title: "Blossom Cloud Irutsuki" },
  "kamisato_ayaka_dance_of_suigetsu": { title: "Dance of Suigetsu", description: "Kamisato Ayaka gains Usurahi Butou every 10s, increasing her Charged Attack DMG by {dmg_charged}. This buff will be cleared 0.5s after Ayaka's Charged ATK hits an opponent, after which the timer for this ability will restart." },
  "kamisato_ayaka_ebb_and_flow": { title: "Ebb and Flow", description: "Opponents damaged by Kamisato Art: Soumetsu's Frostflake Seki no To will have their DEF decreased by {enemy_def_reduce} for 6s." },
  "kamisato_ayaka_frostbloom_kamifubuki": { title: "Frostbloom Kamifubuki" },
  "kamisato_ayaka_hyouka": { title: "Kamisato Art: Hyouka", description: "<p>Summons blooming ice to launch nearby opponents, dealing AoE Cryo DMG.</p><p><i>\"Clouds shroud the moonlit night. Longing descends like a fog, filling the one detained with wanderlust.\"</i></p>" },
  "kamisato_ayaka_kabuki": { title: "Kamisato Art: Kabuki", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash a flurry of sword ki.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging enemies along the path and dealing AoE DMG upon impact.</p>" },
  "kamisato_ayaka_kanten_senmyou_blessing": { title: "Kanten Senmyou Blessing", description: "When the Cryo application at the end of Kamisato Art: Senho hits an opponent, Kamisato Ayaka gains the following effects: ·Restores 10 Stamina ·Gains {dmg_cryo} Cryo DMG Bonus for 10s." },
  "kamisato_ayaka_senho": { title: "Kamisato Art: Senho", description: "<p>Alternate Sprint Ayaka consumes Stamina and cloaks herself in a frozen fog that moves with her.</p><p>In Senho form, she moves swiftly upon water. When she reappears, the following effects occur: ·Ayaka unleashes frigid energy to apply Cryo on nearby opponents. ·Coldness condenses around Ayaka's blade, infusing her attacks with Cryo for a brief period.</p><p><i>\"Feathers fleeting wet / the white heron treads water / a sight without flaw\"</i></p>" },
  "kamisato_ayaka_senho_talent": { description: "In Senho form, she moves at high speed on water. When she reappears, the following effects occur: • Unleashes frigid energies to apply Cryo on nearby opponents. • Cold congeals along Ayaka's blade, infusing her attacks a Cryo for a brief period." },
  "kamisato_ayaka_snowswept_sakura": { title: "Snowswept Sakura", description: "When Kamisato Ayaka's Normal or Charged Attacks deal Cryo DMG to opponents, it has a {text_percent_chance} chance of decreasing the CD of Kamisato Art: Hyouka by 0.3s. This effect can occur once every 0.1s." },
  "kamisato_ayaka_soumetsu": { title: "Kamisato Art: Soumetsu", description: "<p>Summons forth a snowstorm with flawless poise, unleashing a Frostflake Seki no To that moves forward continuously.</p><p>Frostflake Seki no To ·A storm of whirling icy winds that slashes repeatedly at every enemy it touches, dealing Cryo DMG. ·The snowstorm explodes after its duration ends, dealing AoE Cryo DMG.</p><p><i>\"The blizzard veils the heron's thoughts, pity heavy in its heart.\"</i></p>" },
  "kamisato_ayato_bansui_ichiro": { title: "Bansui Ichiro" },
  "kamisato_ayato_boundless_origin": { title: "Boundless Origin", description: "After using Kamisato Art: Kyouka, Ayato's next Shunsuiken attack will create 2 extra Shunsuiken strikes when they hit opponents, each one dealing {text_percent_dmg} of Ayato's ATK as DMG. Both these Shunsuiken attacks will not be affected by Namisen." },
  "kamisato_ayato_endless_flow": { title: "Endless Flow", description: "After using Kamisato Art: Suiyuu, all nearby party members will have {atk_speed_normal} increased Normal Attack SPD for 15s." },
  "kamisato_ayato_kyouka": { title: "Kamisato Art: Kyouka", description: "<p>Kamisato Ayato shifts positions and enters the Takimeguri Kanka state. After this shift, he will leave a watery illusion at his original location. After it is formed, the watery illusion will explode if opponents are nearby or after its duration ends, dealing AoE Hydro DMG.</p><p>Takimeguri Kanka In this state, Kamisato Ayato uses his Shunsuiken to engage in blindingly fast attacks, causing DMG from his Normal Attacks to be converted into AoE Hydro DMG. This cannot be overridden. It also has the following properties: ·After a Shunsuiken attack hits an opponent, it will grant Ayato the Namisen effect, increasing the DMG dealt by Shunsuiken based on Ayato's current Max HP. The initial maximum number of Namisen stacks is 4, and 1 stack can be gained through Shunsuiken every 0.1s. This effect will be dispelled when Takimeguri Kanka ends. ·Kamisato Ayato's resistance to interruption is increased. ·Unable to use Charged or Plunging Attacks.</p><p>Takimeguri Kanka will be cleared when Ayato leaves the field. Using Kamisato Art: Kyouka again while in the Takimeguri Kanka state will reset and replace the pre-existing state.</p><p><i>\"When, I wonder, did you come under the illusion that you were winning?\"</i> <i>— Ayato is like this in both matter of martial prowess and political intrigue, but to preserve the dignity of his fellow Commissioners, he does not say such things to them. As such, only Thoma, Itto, and Ayaka have ever heard this line.</i></p>" },
  "kamisato_ayato_kyouka_fuushi": { title: "Kyouka Fuushi", description: "Shunsuiken DMG is increased by {dmg_normal_ayato} against opponents with 50% HP or less." },
  "kamisato_ayato_marobashi": { title: "Kamisato Art: Marobashi", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to dash forward and performs an iai.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "kamisato_ayato_michiyuku_hagetsu": { title: "Kamisato Art: Michiyuku Hagetsu", description: "If Kamisato Ayato is not on the field and his Energy is less than 40, he will regenerate 2 Energy for himself every second." },
  "kamisato_ayato_mine_wo_matoishi_kiyotaki": { title: "Kamisato Art: Mine Wo Matoishi Kiyotaki", description: "Kamisato Art: Kyouka has the following properties: ·After it is used, Kamisato Ayato will gain 2 Namisen stacks. ·When the water illusion explodes, Ayato will gain a Namisen effect equal to the maximum number of stacks possible." },
  "kamisato_ayato_suiyuu": { title: "Kamisato Art: Suiyuu", description: "<p>Unveils a garden of purity that silences the cacophony within. While this space exists, Bloomwater Blades will constantly rain down and attack opponents within its AoE, dealing Hydro DMG and increasing the Normal Attack DMG of characters within.</p><p><i>\"I can see them, you know. The ripples of your beating heart within this realm of still waters.\"</i></p>" },
  "kamisato_ayato_to_admire_the_flowers": { title: "To Admire the Flowers" },
  "kamisato_ayato_world_source": { title: "World Source" },
  "kamisato_ayato_world_source_1": { description: "Namisen's maximum stack count is increased to 5." },
  "kamisato_ayato_world_source_2": { description: "When Kamisato Ayato has at least 3 Namisen stacks, his Max HP is increased by {hp_percent}." },
  "kaveh_a_craftsmans_curious_conceptions": { title: "A Craftsman's Curious Conceptions", description: "During Painted Dome, after Kaveh's Normal, Charged, or Plunging Attacks hit opponents, his Elemental Mastery will increase by {mastery}. This effect can be triggered once every 0.1s. Max 4 stacks. This effect will be canceled when Painted Dome's effects end." },
  "kaveh_an_architects_undertaking": { title: "An Architect's Undertaking", description: "When DMG dealt by a Dendro Core (including DMG from Burgeon and Hyperbloom) hits Kaveh, Kaveh will regain HP equal to {text_percent_heal} of his Elemental Mastery. This effect can be triggered once every 0.5s." },
  "kaveh_artistic_ingenuity": { title: "Artistic Ingenuity", description: "<p>Uses Mehrak's mapping ability for offensive purposes, initiating a radial scan that deals AoE Dendro DMG. It will also scan all Dendro Cores in its AoE and cause them to immediately burst.</p><p><i>Mehrak was created through the modification of ancient technology and may have some other functions apart from mapping work...</i></p>" },
  "kaveh_feast_of_apadana": { title: "Feast of Apadana", description: "Dendro Cores created from Bloom reactions Kaveh triggers will deal {dmg_reaction_rupture} more DMG when they burst." },
  "kaveh_grace_of_royal_roads": { title: "Grace of Royal Roads", description: "Kaveh's Normal Attack SPD increases by {atk_speed_normal} during Painted Dome." },
  "kaveh_painted_dome": { title: "Painted Dome", description: "<p>Completely unleashes Mehrak's energy and creates a cubic scanned space, dealing AoE Dendro DMG to all opponents within it, causing all Dendro Cores in its AoE to immediately burst, and granting Kaveh the following enhanced combat abilities for a specific duration: ·Increases Kaveh's Normal, Charged, and Plunging Attack AoE, and converts his attack DMG to Dendro DMG that cannot be overridden. ·All Dendro Cores created by all your own party members through Bloom reactions will deal additional DMG when they burst. ·Increases Kaveh's resistance to interruption. These effects will be canceled once Kaveh leaves the field.</p><p><i>\"Every building style includes the architect's unique worldview, and from this angle, one can say that the buildings themselves are coalescences of human memories.\"</i></p>" },
  "kaveh_painted_dome_talent": { description: "Granting Kaveh the following enhanced combat abilities for a specific duration: ·Increases Kaveh's Normal, Charged, and Plunging Attack AoE, and converts his attack DMG to Dendro DMG that cannot be overridden. ·All Dendro Cores created by all your own party members through Bloom reactions will deal additional DMG when they burst. ·Increases Kaveh's resistance to interruption." },
  "kaveh_painted_dome_talent_2": { description: "All Dendro Cores created by all your own party members through Bloom reactions will deal additional DMG when they burst." },
  "kaveh_pairidaezas_dreams": { title: "Pairidaeza's Dreams", description: "When Kaveh's Normal, Charged, or Plunging Attacks hit opponents during Painted Dome, they will unleash Pairidaeza's Light upon the opponent's position, dealing 61.8% of Kaveh's ATK as AoE Dendro DMG and causing all Dendro Cores within that AoE to burst. This effect can be triggered once every 3s." },
  "kaveh_profferings_of_dur_untash": { title: "Profferings of Dur Untash" },
  "kaveh_schematic_setup": { title: "Schematic Setup", description: "<p>Normal Attack Uses Mehrak to perform up to 4 consecutive attacks.</p><p>Charged Attack Drains Stamina over time to perform continuous slashes. At the end of the sequence, performs a more powerful slash.</p><p>Plunging Attack Plunges from mid-air to strike the ground, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "kaveh_sublime_salutations": { title: "Sublime Salutations", description: "Within 3s after using Artistic Ingenuity, Kaveh's Dendro RES and Incoming Healing Bonus will be increased by {res_dendro} and {healing_recv} respectively." },
  "kaveh_treasures_of_bonkhanak": { title: "Treasures of Bonkhanak" },
  "keqing_aristocratic_dignity": { title: "Aristocratic Dignity", description: "When casting Starward Sword, Keqing's CRIT Rate is increased by {crit_rate}, and her Energy Recharge is increased by {recharge}. This effect lasts for 8s." },
  "keqing_attunement": { title: "Attunement", description: "For 10s after Keqing triggers an Electro-related Elemental Reaction, her ATK is increased by {atk_percent}." },
  "keqing_beckoning_stars": { title: "Beckoning Stars" },
  "keqing_foreseen_reformation": { title: "Foreseen Reformation" },
  "keqing_keen_extraction": { title: "Keen Extraction", description: "When Keqing's Normal and Charged Attacks hit opponents affected by Electro, they have a 50% chance of producing an Elemental Particle. This effect can only occur once every 5s." },
  "keqing_starward_sword": { title: "Starward Sword", description: "<p>Keqing unleashes the power of lightning, dealing Electro DMG in an AOE. She then blends into the shadow of her blade, striking a series of thunderclap-blows to nearby opponents simultaneously that deal multiple instances of Electro DMG. The final attack deals massive AoE Electro DMG.</p><p><i>The swiftest technique in Keqing's personal arsenal is fast enough to bring stars crashing down.</i></p>" },
  "keqing_stellar_restoration": { title: "Stellar Restoration", description: "<p>Hurls a Lightning Stiletto that annihilates her opponents like the swift thunder. When the Stiletto hits its target, it deals Electro DMG to opponents in a small AoE, and places a Stiletto Mark on the spot hit.</p><p>Hold Hold to adjust the direction in which the Stiletto shall be thrown. Stilettos thrown by the Hold attack mode can be suspended in mid-air, allowing Keqing to jump to them when using Stellar Restoration a second time.</p><p>Lightning Stiletto If Keqing uses Stellar Restoration again or uses a Charged Attack while its duration lasts, it will clear the Stiletto Mark and produce different effects: ·If she uses Stellar Restoration again, she will blink to the location of the Mark and unleash one slashing attack that deals AoE Electro DMG. When blinking to a Stiletto that was thrown from a Holding attack, Keqing can leap across obstructing terrain. ·If Keqing uses a Charged Attack, she will ignite a series of thundering cuts at the Mark's location, dealing AoE Electro DMG.</p><p><i>\"Humans are like moths, endlessly chasing the flame we call gods and adepti. But this light that I have here is my own.\"</i></p>" },
  "keqing_tenacious_star": { title: "Tenacious Star", description: "When initiating a Normal Attack, a Charged Attack, Elemental Skill or Elemental Burst, Keqing gains a {dmg_electro} Electro DMG Bonus for 8s. Effects triggered by Normal Attacks, Charged Attacks, Elemental Skills and Elemental Bursts are considered independent entities." },
  "keqing_thundering_might": { title: "Thundering Might", description: "Recasting Stellar Restoration while a Lightning Stiletto is present causes Keqing to deal {text_percent_dmg} of her ATK as AoE Electro DMG at the start point and terminus of her Blink." },
  "keqing_thundering_penance": { title: "Thundering Penance", description: "After recasting Stellar Restoration while a Lightning Stiletto is present, Keqing's weapon gains an Electro Infusion for 5s." },
  "keqing_yunlai_swordsmanship": { title: "Yunlai Swordsmanship", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "kinich_auspicious_beasts_shape": { title: "Auspicious Beast's Shape", description: "After Scalespiker Cannon hits an opponent, it will bounce between opponents once, dealing {text_percent_dmg} of Kinich's ATK as Dendro DMG. If this Scalespiker Cannon triggers the buffs that Passive Talent \"Flame Spirit Pact\" or the Constellation \"Tiger Beetle's Palm\" grant to the Cannon, the bouncing attack will also obtain the relevant buffs." },
  "kinich_flame_spirit_pact": { title: "Flame Spirit Pact", description: "After a nearby party member triggers a Nightsoul Burst, Kinich will gain 1 stack of Hunter's Experience that lasts 15s. Max 2 stacks. When Kinich uses Canopy Hunter: Riding High's Scalespiker Cannon, all stacks of Hunter's Experience will be consumed, with each stack consumed increasing the DMG dealt by this Cannon shot by {text_percent} of Kinich's ATK." },
  "kinich_hail_to_the_almighty_dragonlord": { title: "Hail to the Almighty Dragonlord", description: "<p>Unleashes the power of the Almighty Dragonlord, K'uhul Ajaw (on a limited, conditional, restricted, contractual, partial, temporary basis), dealing Nightsoul-aligned AoE Dendro DMG. Ajaw will unleash his Dragon Breath at intervals, dealing Nightsoul-aligned AoE Dendro DMG. If Kinich is in Nightsoul's Blessing when this is used, this Blessing's duration is extended by 1.7s.</p><p><i>\"Yes, yes! You stand before K'uhul Ajaw the Almighty Dragonlord! Come forward, then! Kneel, and kiss our feet!\"</i></p>" },
  "kinich_howler_monkeys_tail": { title: "Howler Monkey's Tail" },
  "kinich_hummingbirds_feather": { title: "Hummingbird's Feather", description: "When in Nightsoul's Blessing, Kinich will restore 5 Energy after using his Loop Shots or after unleashing the Scalespiker Cannon. Energy can be regenerated this way once every 2.8s. Additionally, Hail to the Almighty Dragonlord deals {dmg_burst_kinich} more DMG." },
  "kinich_nightsun_style": { title: "Nightsun Style", description: "<p>Normal Attack Performs up to 3 rapid strikes. After using his Elemental Skill \"Canopy Hunter: Riding High\"'s mid-air swing, he can perform a Normal Attack in mid-air before landing.</p><p>Charged Attack Consumes a certain amount of Stamina to spin and throw his Claymore forward to attack opponents.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "kinich_parrots_beak": { title: "Parrot's Beak", description: "After Kinich lands from Canopy Hunter: Riding High's mid-air swing, his Movement SPD will increase by {move_speed} for 6s. Additionally, Scalespiker Cannon's CRIT DMG is increased by {crit_dmg_skill_kinich}." },
  "kinich_protosuchians_claw": { title: "Protosuchian's Claw" },
  "kinich_riding_high": { title: "Canopy Hunter: Riding High", description: "<p>Kinich uses his big-game hunting skills to either move swiftly or attack his opponent. When there is an opponent or object that can be attacked nearby, he will attach a grappling hook to the target and enter Nightsoul's Blessing with 0 Nightsoul points. If neither is nearby, he fires a grappling hook forward and swings in mid-air, and this Skill's CD is decreased by 60%. This skill can be Held to release. When it is Held, Kinich can aim the grappling hook.</p><p>Nightsoul's Blessing: Kinich Kinich's Nightsoul's Blessing lasts 10s and generates 2 Nightsoul points every second. In this state, Kinich will hook onto a nearby opponent and perform a variable attack: ·When using a Normal Attack, Kinich will fire Loop Shots as he loops around the grappled target based on his current movement direction, dealing Nightsoul-aligned Dendro DMG and generating 3 Nightsoul points. Loop Shot DMG is considered Elemental Skill DMG. ·When Nightsoul points are at max, he can use the Elemental Skill \"Scalespiker Cannon\": Consume all Nightsoul points to deal Nightsoul-aligned Dendro DMG. When \"Scalespiker Cannon\" is Held, Kinich can aim this shot. After firing the Cannon, Kinich will try to grapple to its target. While in Nightsoul's Blessing, after grappling an opponent or firing \"Scalespiker Cannon,\" a Blind Spot will be generated next to the opponent. When Kinich enters this Blind Spot, it will disappear and he will generate 4 Nightsoul points. If the grapple connection should snap due to exceeding the maximum distance or some other reason, using a Normal Attack will establish a new connection with a nearby opponent before performing Loop Shots.</p><p><i>\"All things come with a cost. I suggest you make a suitable offer... What? No, I don't do installments.\"</i></p>" },
  "kinich_the_price_of_desolation": { title: "The Price of Desolation", description: "When Kinich is in Nightsoul's Blessing state, opponents hit by his Elemental Skill will enter the Desolation state, and when affected by Burning or Burgeon reaction DMG, they will restore 7 Nightsoul points to him. Nightsoul points can be gained this way once every 0.8s. The Desolation state will persist until this instance of Kinich's Nightsoul's Blessing state ends." },
  "kinich_tiger_beetles_palm": { title: "Tiger Beetle's Palm" },
  "kinich_tiger_beetles_palm_1": { description: "When Kinich's Elemental Skill hits an opponent, it will decrease their Dendro RES by {enemy_res_dendro} for 6s." },
  "kinich_tiger_beetles_palm_2": { description: "Additionally, the first Scalespiker Cannon Kinich fires after entering Nightsoul's Blessing has increased AoE, and its DMG increases by {dmg_skill_kinich}." },
  "kirara_a_thousand_miles_in_a_day": { title: "A Thousand Miles in a Day" },
  "kirara_bewitching_betwitching_tails": { title: "Bewitching, Betwitching Tails", description: "When Kirara is in the Urgent Neko Parcel state of Meow-teor Kick, each impact against an opponent will grant her a stack of Reinforced Packaging. This effect can be triggered once for each opponent hit every 0.5s. Max 3 stacks. When the Urgent Neko Parcel state ends, each stack of Reinforced Packaging will create 1 Shield of Safe Transport for Kirara. The shields that are created this way will have {text_percent} of the DMG absorption that the Shield of Safe Transport produced by Meow-teor Kick would have. If Kirara is already protected by a Shield of Safe Transport created by Meow-teor Kick, its DMG absorption will stack with these shields and its duration will reset." },
  "kirara_boxcutter": { title: "Boxcutter", description: "<p>Normal Attack Performs up to 4 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 3 rapid claw strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "kirara_countless_sights_to_see": { title: "Countless Sights to See", description: "All nearby party members gain a {dmg_pyro} All Elemental DMG Bonus for 15s after Kirara uses her Elemental Skill or Burst." },
  "kirara_material_circulation": { title: "Material Circulation", description: "Every {text_value_hp} Max HP Kirara possesses will cause her to create 1 extra Cat Grass Cardamom when she uses Secret Art: Surprise Dispatch. A maximum of 4 extra can be created this way." },
  "kirara_meow_teor_kick": { title: "Meow-teor Kick", description: "<p>Press Leaps into the air with all the agility of a cat passing through the bushes, and thwacks her foes with a flying kick that deals AoE Dendro DMG while creating a Shield of Safe Transport. This will also briefly apply Dendro to Kirara. The shield will absorb Dendro DMG with 250% effectiveness. The shield's DMG absorption will be based on Kirara's Max HP and will not exceed a certain percentage of that Max HP. The remaining DMG absorption on a Shield of Safe Transport will stack on a new one when it is created, and its duration will reset.</p><p>Hold Out of her desire to \"deliver within half a day,\" Kirara deploys a Shield of Safe Transport identical to the one that can be created by pressing the skill. She will also curl up into a special express delivery box, entering the Urgent Neko Parcel state in order to move and fight more swiftly.</p><p>Urgent Neko Parcel · Deals Dendro DMG to opponents she crashes into. This effect can be triggered once on each opponent every 0.5s. · When in this state, Kirara's movement speed, climbing speed, and jumping power are all increased, and her Stamina Consumption from climbing is increased. · When the duration ends or the skill is used again, a Flipclaw Strike more powerful than the attack in the Press Mode will be unleashed, dealing AoE Dendro DMG. · The Urgent Neko Parcel state lasts a maximum of 10s. When the state ends, the skill will enter CD. The longer Kirara spends in this state, the longer the CD will be. · Sprinting or actively canceling climbing will end this state early.</p><p><i>\"So you wanna know the secret to speedy deliveries? Well, it's all in the legs!\"</i></p>" },
  "kirara_perfectly_packaged": { title: "Perfectly Packaged", description: "When Kirara is in the Urgent Neko Parcel state of Meow-teor Kick, she will grant other party members she crashes into Critical Transport Shields. The DMG absorption of Critical Transport Shield is {text_percent_shield} of the maximum absorption Meow-teor Kick's normal Shields of Safe Transport are capable of, and will absorb Dendro DMG with 250% effectiveness. Critical Transport Shields last 12s and can be triggered once on each character every 10s." },
  "kirara_pupillary_variance": { title: "Pupillary Variance", description: "Every 1,000 Max HP Kirara possesses will increase the DMG dealt by Meow-teor Kick by {text_percent_skill}, and the DMG dealt by Secret Art: Surprise Dispatch by {text_percent_burst}." },
  "kirara_steed_of_skanda": { title: "Steed of Skanda", description: "After active character(s) protected by Shields of Safe Transport or Critical Transport Shields hit opponents with Normal, Charged, or Plunging Attacks, Kirara will perform a coordinated attack with them using Small Cat Grass Cardamoms, dealing {text_percent_atk} of her ATK as Dendro DMG. DMG dealt this way is considered Elemental Burst DMG. This effect can be triggered once every 3.8s. This CD is shared between all party members." },
  "kirara_surprise_dispatch": { title: "Secret Art: Surprise Dispatch", description: "<p>Smash opponents with a Special Delivery Package used for punishing parcel thieves, dealing AoE Dendro DMG. After the Special Delivery Package explodes, it will split up into many Cat Grass Cardamoms that will explode either upon contact with opponents or after a period of time, dealing AoE Dendro DMG.</p><p><i>\"Hehe, that's right, this stuff was made to deal with those parcel thieves! Remember to leave a 5-star rating once you've received yours!\"</i></p>" },
  "kirara_universal_recognition": { title: "Universal Recognition" },
  "klee_blazing_delight": { title: "Blazing Delight", description: "While under the effects of Sparks 'n' Splash, Klee will regenerate 3 Energy for all members of the party (excluding Klee) every 3s. When Sparks 'n' Splash is used, all party members will gain a {dmg_pyro} Pyro DMG Bonus for 25s." },
  "klee_chained_reactions": { title: "Chained Reactions", description: "Attacks and Skills have a certain chance to summon sparks that bombard opponents, dealing DMG equal to {text_percent_dmg} of Sparks 'n' Splash's DMG." },
  "klee_explosive_frags": { title: "Explosive Frags", description: "Being hit by Jumpy Dumpty's mines decreases opponents' DEF by {enemy_def_reduce} for 10s." },
  "klee_exquisite_compound": { title: "Exquisite Compound" },
  "klee_jumpy_dumpty": { title: "Jumpy Dumpty", description: "<p>Jumpy Dumpty is tons of boom-bang-fun! When thrown, Jumpy Dumpty bounces thrice, igniting and dealing AoE Pyro DMG with every bounce.</p><p>On the third bounce, the bomb splits into many mines. The mines will explode upon contact with opponents, or after a short period of time, dealing AoE Pyro DMG.</p><p>Starts with 2 charges.</p><p><i>Jumpy Dumpty is Klee's good friend! She can't help but introduce him to everyone.</i></p>" },
  "klee_kaboom": { title: "Kaboom!", description: "<p>Normal Attack Throws things that go boom when they hit things! Performs up to 3 explosive attacks, dealing AoE Pyro DMG.</p><p>Charged Attack Consumes a certain amount of Stamina and deals AoE Pyro DMG to opponents after a short casting time.</p><p>Plunging Attack Gathering the power of Pyro, Klee plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Pyro DMG upon impact with the ground.</p>" },
  "klee_nova_burst": { title: "Nova Burst" },
  "klee_pounding_surprise": { title: "Pounding Surprise", description: "When Jumpy Dumpty and Normal Attacks deal DMG, Klee has a 50% chance to obtain an Explosive Spark. This Explosive Spark is consumed by the next Charged Attack, which costs no Stamina and deals {dmg_charged} increased DMG." },
  "klee_sparkling_burst": { title: "Sparkling Burst", description: "When Klee's Charged Attack results in a CRIT Hit, all party members gain 2 Elemental Energy." },
  "klee_sparkly_explosion": { title: "Sparkly Explosion", description: "If Klee leaves the field during the duration of Sparks 'n' Splash, her departure triggers an explosion that deals {text_percent_dmg} of her ATK as AoE Pyro DMG." },
  "klee_sparks_n_splash": { title: "Sparks 'n' Splash", description: "<p>Klee's Blazing Delight! For the duration of this ability, continuously summons Sparks 'n' Splash to attack nearby opponents, dealing AoE Pyro DMG.</p><p><i>The knights all believe that Klee must have a lucky star watching over her to have never been hurt by any of her own bombs...</i></p>" },
  "kokomi_ceremonial_garment": { title: "Ceremonial Garment", description: "• Sangonomiya Kokomi's Normal Attack, Charged Attack and Bake-Kurage DMG are increased based on her Max HP. • When her Normal and Charged Attacks hit opponents, Kokomi will restore HP for all nearby party members, and the amount restored is based on her Max HP. • Increases Sangonomiya Kokomi's resistance to interruption and allows her to move on the water's surface. These effects will be cleared once Sangonomiya Kokomi leaves the field." },
  "kokomi_flawless_strategy": { title: "Flawless Strategy", description: "Sangonomiya Kokomi has a {healing} Healing Bonus, but a {crit_rate} decrease in CRIT Rate." },
  "kujou_sara_conclusive_proof": { title: "Conclusive Proof", description: "The number of Tengu Juurai: Stormcluster released by Subjugation: Koukou Sendou is increased to 6." },
  "kujou_sara_crows_eye": { title: "Crow's Eye", description: "When Tengu Juurai grants characters ATK Bonuses or hits opponents, the CD of Tengu Stormcall is decreased by 1s. This effect can be triggered once every 3s." },
  "kujou_sara_dark_wings": { title: "Dark Wings", description: "Unleashing Tengu Stormcall will leave a weaker Crowfeather at Kujou Sara's original position that will deal {text_percent_dmg} of its original DMG." },
  "kujou_sara_decorum": { title: "Decorum", description: "When Tengu Juurai: Ambush hits opponents, Kujou Sara will restore 1.2 Energy to all party members for every 100% Energy Recharge she has. This effect can be triggered once every 3s." },
  "kujou_sara_immovable_will": { title: "Immovable Will", description: "While in the Crowfeather Cover state provided by Tengu Stormcall, Aimed Shot charge times are decreased by {text_percent}." },
  "kujou_sara_koukou_sendou": { title: "Subjugation: Koukou Sendou", description: "<p>Casts down Tengu Juurai: Titanbreaker, dealing AoE Electro DMG. Afterwards, Tengu Juurai: Titanbreaker spreads out into 4 consecutive bouts of Tengu Juurai: Stormcluster, dealing AoE Electro DMG. Tengu Juurai: Titanbreaker and Tengu Juurai: Stormcluster can provide the active character within their AoE with the same ATK Bonus as given by the Elemental Skill, Tengu Stormcall.</p><p>The ATK Bonus provided by various kinds of Tengu Juurai will not stack, and their effects and duration will be determined by the last Tengu Juurai to take effect.</p><p><i>Sara departed from her people, the tengu, and also temporarily lost her faith in the Tenryou Commission. But once the clouds over her heart cleared, she found her own lightning anew.</i></p>" },
  "kujou_sara_sin_of_pride": { title: "Sin of Pride", description: "The Electro DMG of characters who have had their ATK increased by Tengu Juurai has its CRIT DMG increased by {crit_dmg_electro}." },
  "kujou_sara_spellsinger": { title: "Spellsinger" },
  "kujou_sara_tengu_bowmanship": { title: "Tengu Bowmanship", description: "<p>Normal Attack Performs up to 5 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, crackling lightning will accumulate on the arrowhead. An arrow fully charged with the storm's might will deal Electro DMG. When in the Crowfeather Cover state, a fully-charged arrow will leave a Crowfeather behind after it hits.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "kujou_sara_tengu_stormcall": { title: "Tengu Stormcall", description: "<p>Retreats rapidly with the speed of a tengu, summoning the protection of the Crowfeather. Gains Crowfeather Cover for 18s, and when Kujou Sara fires a fully-charged Aimed Shot, Crowfeather Cover will be consumed, and will leave a Crowfeather at the target location. Crowfeathers will trigger Tengu Juurai: Ambush after a short time, dealing Electro DMG and granting the active character within its AoE an ATK Bonus based on Kujou Sara's Base ATK.</p><p>The ATK Bonuses from different Tengu Juurai will not stack, and their effects and duration will be determined by the last Tengu Juurai to take effect.</p><p><i>The tengu race have never lacked for exceptional talents who have received an Electro Vision. It's just that they often habitually chant praises to the Electro Archon while manipulating Electro. The chants go something like this</i> <i>\"Show forth your might, O praiseworthy Narukami, and grant this supplicant your thunderous might! Sowaka!\"</i></p>" },
  "kujou_sara_the_war_within": { title: "The War Within" },
  "kuki_shinobu_breaking_free": { title: "Breaking Free", description: "When Shinobu's HP is not higher than 50%, her Healing Bonus is increased by {healing}." },
  "kuki_shinobu_gyoei_narukami_kariyama_rite": { title: "Gyoei Narukami Kariyama Rite", description: "<p>Stabs an evil-excoriating blade into the ground, creating a field that cleanses the area of all that is foul, dealing continuous Electro DMG to opponents within its AoE based on Shinobu's Max HP. If Shinobu's HP is less than or equal to 50% when this skill is used, the field will last longer.</p><p><i>This was originally a technique used in weeding and in ritual prayers for the yearly harvest, but Shinobu has not forgotten it, though her career as a shrine maiden may have ended.</i></p>" },
  "kuki_shinobu_hearts_repose": { title: "Heart's Repose", description: "Sanctifying Ring's abilities will be boosted based on Shinobu's Elemental Mastery: ·Healing amount will be increased by {text_percent_healing} of Elemental Mastery. ·DMG dealt is increased by {text_percent_dmg} of Elemental Mastery." },
  "kuki_shinobu_sanctifying_ring": { title: "Sanctifying Ring", description: "<p>Creates a Grass Ring of Sanctification at the cost of part of her HP, dealing Electro DMG to nearby opponents.</p><p>Grass Ring of Sanctification Follows your current active character around. Deals Electro DMG to nearby opponents every 1.5s and restores HP for active character(s) within the ring's AoE based on Kuki Shinobu's Max HP.</p><p>The HP consumption from using this skill can only bring her to 20% HP.</p><p>\"<i>Band the Naku Weed into a loop around your waist, and it shall exorcise evil.</i>\"</p>" },
  "kuki_shinobu_shinobus_shadowsword": { title: "Shinobu's Shadowsword", description: "<p>Normal Attack Performs up to 4 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "kuki_shinobu_to_cease_courtesies": { title: "To Cease Courtesies" },
  "kuki_shinobu_to_cloister_compassion": { title: "To Cloister Compassion", description: "Gyoei Narukami Kariyama Rite's AoE is increased by 50%." },
  "kuki_shinobu_to_forsake_fortune": { title: "To Forsake Fortune", description: "Grass Ring of Sanctification's duration is increased by 3s." },
  "kuki_shinobu_to_sequester_sorrow": { title: "To Sequester Sorrow" },
  "kuki_shinobu_to_sever_sealing": { title: "To Sever Sealing", description: "When the Normal, Charged, or Plunging Attacks of the character affected by Shinobu's Grass Ring of Sanctification hit opponents, a Thundergrass Mark will land on the opponent's position and deal AoE Electro DMG based on {text_percent} of Shinobu's Max HP. This effect can occur once every 5s." },
  "kuki_shinobu_to_ward_weakness": { title: "To Ward Weakness", description: "When Kuki Shinobu takes lethal DMG, this instance of DMG will not take her down. This effect will automatically trigger when her HP reaches 1 and will trigger once every 60s. When Shinobu's HP drops below 25%, she will gain {mastery} Elemental Mastery for 15s. This effect will trigger once every 60s." },
  "lan_yan_as_one_might_stride_betwixt_the_clouds": { title: "\"As One Might Stride Betwixt the Clouds\"", description: "After triggering the Elemental Absorption from the Passive Talent \"Four Sealing Divination Charms,\" this instance of Lan Yan's Elemental Skill Swallow-Wisp Pinion Dance will produce another Feathermoon Ring when they are thrown at opponents. You must first unlock the Passive Talent \"Four Sealing Divination Charms.\"" },
  "lan_yan_black_pheasant_strides_on_water": { title: "Black Pheasant Strides on Water", description: "<p>Normal Attack Wields her Feathermoon Rings to perform up to 4 attacks, dealing Anemo DMG.</p><p>Charged Attack Consumes a certain amount of Stamina to throw out a Feathermoon Ring, dealing Anemo DMG.</p><p>Plunging Attack Gathers the power of Anemo and plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Anemo DMG upon impact with the ground.</p>" },
  "lan_yan_dance_vestments_billow_like_rainbow_jade": { title: "\"Dance Vestments Billow Like Rainbow Jade\"", description: "While the Swallow-Wisp Shield is active, when your active party member's Normal Attacks deal DMG, 40% of the Shield's DMG absorption will be restored, up to its original maximum absorption. This effect can occur once every 2s." },
  "lan_yan_four_sealing_divination_charms": { title: "Four Sealing Divination Charms", description: "When the dash from the Elemental Skill Swallow-Wisp Pinion Dance hits a target, if it interacts with Hydro/Pyro/Cryo/Electro, the Swallow-Wisp Shield will undergo Elemental Absorption, with the converted shield absorbing DMG from the corresponding element with 250% efficiency. Additionally, if this use of Swallow-Wisp Pinion Dance causes the Swallow-Wisp Shield to undergo Elemental Absorption, the Feathermoon Rings that Lan Yan throws at her foes additionally deal Elemental DMG equal to {text_percent_dmg} of the original in the corresponding Elemental Type. This DMG is considered Elemental Skill DMG." },
  "lan_yan_having_met_you_my_heart_is_gladdened": { title: "\"Having Met You, My Heart is Gladdened\"" },
  "lan_yan_let_us_away_on_sylphic_wing_the_silvered_ornaments_to_ring": { title: "\"Let Us Away on Sylphic Wing, the Silvered Ornaments to Ring\"", description: "Swallow-Wisp Pinion Dance gains 1 additional charge." },
  "lan_yan_lustrous_moonrise": { title: "Lustrous Moonrise", description: "<p>Lan Yan creates a Feathermoon Swallow Array, pulling in nearby opponents and objects and dealing multiple instances of AoE Anemo DMG.</p><p><i>Strictly speaking, with only Lan Yan herself present, it cannot properly be called an \"array.\" However, if her Rattan Figures are brought into the picture, she can sort of fulfill the requirements... Probably.</i></p>" },
  "lan_yan_on_white_wings_pierce_through_cloud_and_fog": { title: "\"On White Wings Pierce Through Cloud and Fog\"" },
  "lan_yan_skyfeather_evil_subduing_charm": { title: "Skyfeather Evil-Subduing Charm", description: "The Elemental Skill Swallow-Wisp Pinion Dance and the Elemental Burst Lustrous Moonrise deal increased DMG equal to {skill_base_mastery_percent} and {burst_base_mastery_percent} of Lan Yan's Elemental Mastery respectively." },
  "lan_yan_swallow_wisp_pinion_dance": { title: "Swallow-Wisp Pinion Dance", description: "<p>Summoning forth the Swallow-Wisp Shield, a secret art passed down across generations, Lan Yan dashes forward and, upon making contact with her target, will leap back into the air. The Swallow-Wisp Shield's DMG absorption scales based on her ATK, and has a 250% absorption efficiency against Anemo DMG. While in mid-air due to the effects of her Elemental Skill: Swallow-Wisp Pinion Dance, pressing her Elemental Skill again or pressing Normal Attack will cause Lan Yan to hurl her Feathermoon Rings at an opponent, and they will spin between nearby opponents twice upon hit, dealing Anemo DMG. Holding the Skill will cause it to behave differently.</p><p>Hold Enter Aiming Mode to adjust the dash direction.</p><p><i>\"The clouds cut the lunar light, like shadows silver gracing one's sight.\"</i></p>" },
  "lan_yan_with_drakefalcons_blood_pearls_adorned": { title: "\"With Drakefalcon's Blood-Pearls Adorned\"", description: "After Lan Yan uses her Elemental Burst Lustrous Moonrise, the Elemental Mastery of all nearby party members increases by {mastery} for 12s." },
  "layla_dream_of_the_star_stream_shaker": { title: "Dream of the Star-Stream Shaker", description: "<p>Unleashes a Celestial Dreamsphere that constantly fires Starlight Slugs at opponents within its AoE, dealing Cryo DMG. When a Starlight Slug hits, it will generate 1 Night Star for nearby Curtains of Slumber. Each Curtain of Slumber can gain 1 Night Star this way every 0.5s.</p><p><i>\"Sleep now, sleep now; and may many destinies be revealed before your slumbering eyes, within your star-paved dreams.\"</i></p>" },
  "layla_fortress_of_fantasy": { title: "Fortress of Fantasy", description: "The Shield Absorption of the Curtain of Slumber generated by Nights of Formal Focus is increased by {text_percent_bonus}. Additionally, when unleashing Nights of Formal Focus, she will generate a shield for any nearby party members who are not being protected by a Curtain of Slumber. This shield will have {text_percent_shield} of the absorption of a Curtain of Slumber, will last for 12s, and will absorb Cryo DMG with 250% effectiveness." },
  "layla_lights_remit": { title: "Light's Remit", description: "When Shooting Stars from Nights of Formal Focus strike opponents, they will each restore 1 Energy to Layla. Each Shooting Star can restore Energy to her in this manner once." },
  "layla_like_nascent_light": { title: "Like Nascent Light", description: "While the Curtain of Slumber is active, the Deep Sleep effect will activate each time the Curtain gains 1 Night Star: ·The Shield Strength of a character under the effect of the Curtain of Slumber increases by {shield}. ·This effect can have a maximum of 4 stacks and persists until the Curtain of Slumber disappears." },
  "layla_nights_of_formal_focus": { title: "Nights of Formal Focus", description: "<p>Puts forth a shield known as the Curtain of Slumber, dealing AoE Cryo DMG. The Curtain of Slumber's DMG Absorption is based on Layla's Max HP and absorbs Cryo DMG with 250% effectiveness. When the shield is deployed, Layla will have Cryo applied to her briefly.</p><p>Night Stars and Shooting Stars While the Curtain of Slumber is active, it will create 1 Night Star that will be attached to it every 1.5s. When a character protected by this shield uses an Elemental Skill, 2 Night Stars will be created. Night Stars can be created once every 0.3s in this way. A maximum of 4 Night Stars can be accumulated at any one time. Once the Curtain of Slumber has accumulated 4 Night Stars and there are opponents nearby, these Night Stars will transform into homing Shooting Stars that will be fired off in sequence, dealing Cryo DMG to any opponents hit. If the Curtain of Slumber's duration ends or it is destroyed, the Night Stars will disappear. If they are already being fired off as Shooting Stars, these Shooting Stars will last until this wave of shots ends.</p><p>New Night Stars cannot be created until the previous wave of Shooting Stars has been fired completely.</p><p><i>\"She and I are like two master artisans who have never met, yet who sit at the same cushioned seat, embroidering the same dream-flower.\"</i></p>" },
  "layla_radiant_soulfire": { title: "Radiant Soulfire", description: "Shooting Stars from Nights of Formal Focus deal {dmg_skill_layla} increased DMG, and Starlight Slugs from Dream of the Star-Stream Shaker deal {dmg_burst_layla} increased DMG. Additionally, the interval between the creation of Night Stars via Nights of Formal Focus is decreased by 20%." },
  "layla_secrets_of_the_night": { title: "Secrets of the Night" },
  "layla_starry_illumination": { title: "Starry Illumination", description: "When Nights of Formal Focus starts to fire off Shooting Stars, it will grant all nearby party members the Dawn Star effect, causing their Normal and Charged Attack DMG to increase based on {text_percent_dmg} of Layla's Max HP. Dawn Star can last up to 3s and will be removed 0.05s after dealing Normal or Charged Attack DMG." },
  "layla_stream_of_consciousness": { title: "Stream of Consciousness" },
  "layla_sweet_slumber_undisturbed": { title: "Sweet Slumber Undisturbed", description: "The DMG dealt by the Shooting Stars fired by Nights of Formal Focus is increased by {text_percent} of Layla's Max HP." },
  "layla_sword_of_the_radiant_path": { title: "Sword of the Radiant Path", description: "<p>Normal Attack Performs up to 3 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "lisa_electrocute": { title: "Electrocute" },
  "lisa_electromagnetic_field": { title: "Electromagnetic Field", description: "Holding Violet Arc has the following effects: ·Increases DEF by {def_percent}. ·Increases Lisa's resistance to interruption." },
  "lisa_induced_aftershock": { title: "Induced Aftershock", description: "Hits by Charged Attacks apply Violet Arc's Conductive status to opponents." },
  "lisa_infinite_circuit": { title: "Infinite Circuit", description: "Lisa regenerates 2 Energy for every opponent hit while holding Violet Arc. A maximum of 10 Energy can be regenerated in this manner at any one time." },
  "lisa_lightning_rose": { title: "Lightning Rose", description: "<p>Summons a Lightning Rose that unleashes powerful lightning bolts, launching surrounding opponents and dealing Electro DMG. The Lightning Rose will continuously emit lightning to knock back opponents and deal Electro DMG throughout the ability's duration.</p><p><i>This rose is beautiful, but beware its mortal thorns.</i></p>" },
  "lisa_lightning_touch": { title: "Lightning Touch", description: "<p>Normal Attack Performs up to 4 lightning attacks that deal Electro DMG.</p><p>Charged Attack Consumes a certain amount of Stamina to deal AoE Electro DMG after a short casting time.</p><p>Plunging Attack Gathering the might of Electro, Lisa plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Electro DMG upon impact with the ground.</p>" },
  "lisa_plasma_eruption": { title: "Plasma Eruption", description: "Lightning Rose now unleashes 1-3 lightning bolts when it attacks." },
  "lisa_pulsating_witch": { title: "Pulsating Witch", description: "When Lisa takes the field, she applies 3 stacks of Violet Arc's Conductive status onto nearby opponents. This effect can only occur once every 5s." },
  "lisa_resonant_thunder": { title: "Resonant Thunder" },
  "lisa_static_electricity_field": { title: "Static Electricity Field", description: "Opponents hit by Lightning Rose have their DEF decreased by {enemy_def_reduce} for 10s." },
  "lisa_violet_arc": { title: "Violet Arc", description: "<p>Channels the power of lightning to sweep bothersome matters away.</p><p>Press Releases a homing Lightning Orb. On hit, it deals Electro DMG and applies a stack of the Conductive status (max 3 stacks) to opponents in a small AoE.</p><p>Hold After an extended casting time, calls down lightning from the heavens, dealing massive Electro DMG to all nearby opponents. Deals great amounts of extra damage to opponents based on the number of Conductive stacks applied to them, and clears their Conductive status.</p><p><i>Electro Purple is the raiment of the Witch of Purple Rose.</i></p>" },
  "lynette_a_cold_blade_like_a_shadow": { title: "A Cold Blade Like a Shadow", description: "When Enigmatic Feint's Enigma Thrust hits an opponent with Shadowsign, a vortex will be created at that opponent's position that will pull nearby opponents in." },
  "lynette_astonishing_shift": { title: "Magic Trick: Astonishing Shift", description: "<p>Lynette raises her mantle high, dealing AoE Anemo DMG, using skillful sleight of hand to make a giant Bogglecat Box appear!</p><p>Bogglecat Box ·Taunts nearby opponents, attracting their attacks. ·Deals Anemo DMG to nearby opponents at intervals. ·When the Bogglecat Box comes into contact with Hydro/Pyro/Cryo/Electro, it will gain the corresponding element and additionally fire Vivid Shots that will deal DMG from that element at intervals. Elemental Absorption of this kind will only occur once during this ability's duration.</p><p><i>\"Look this way, and look closely. This is a time for miracles, just for us.\"</i></p>" },
  "lynette_cognition_inverting_gaze": { title: "Cognition-Inverting Gaze" },
  "lynette_endless_mysteries": { title: "Endless Mysteries", description: "Whenever the Bogglecat Box summoned by Magic Trick: Astonishing Shift fires a Vivid Shot, it will fire an extra Vivid Shot." },
  "lynette_enigmatic_feint": { title: "Enigmatic Feint", description: "<p>Flicks her mantle and executes an Enigma Thrust, dealing Anemo DMG. When the Enigma Thrust hits an opponent, it will restore Lynette's HP based on her Max HP, and in the 4s afterward, she will lose a certain amount of HP per second. Based on whether you press or hold this ability, she will use Enigma Thrust differently.</p><p>Press She swiftly uses an Enigma Thrust.</p><p>Hold Lynette will enter a high-speed Pilfering Shadow state and apply Shadowsign to a nearby opponent. You can control her movement direction during this state, and you can end it prematurely by using this skill again. When this high-speed state ends, Lynette will unleash her Enigma Thrust. If there is an opponent with Shadowsign applied to them nearby, Lynette will approach them in a flash before using Enigma Thrust.</p><p>A maximum of 1 opponent can have Shadowsign at any one time. When this opponent gets too far from Lynette, the Shadowsign will be canceled.</p><p>Arkhe: Ousia At specific intervals, Lynette will unleash a Surging Blade when she uses Enigma Thrust, dealing Ousia-aligned Anemo DMG.</p><p><i>\"Now then, turn your eyes to the stage and continue to enjoy the performance. When I next appear, I'll be where you least expect.\"</i></p>" },
  "lynette_obscuring_ambiguity": { title: "Obscuring Ambiguity" },
  "lynette_props_positively_prepped": { title: "Props Positively Prepped", description: "After the Bogglecat Box summoned by Magic Trick: Astonishing Shift performs Elemental Conversion, Lynette's Elemental Burst will deal {dmg_burst_lynette} more DMG. This effect will persist until the Bogglecat Box's duration ends." },
  "lynette_rapid_ritesword": { title: "Rapid Ritesword", description: "<p>Normal Attack Performs up to 4 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "lynette_sophisticated_synergy": { title: "Sophisticated Synergy", description: "Within 10s after using Magic Trick: Astonishing Shift, when there are 1/2/3/4 Elemental Types in the party, all party members' ATK will be increased by 8/12/16/20% respectively." },
  "lynette_tacit_coordination": { title: "Tacit Coordination", description: "Increases Enigmatic Feint's charges by 1." },
  "lynette_watchful_eye": { title: "Watchful Eye", description: "When Lynette uses Enigmatic Feint's Enigma Thrust, she will gain an Anemo Infusion and {dmg_anemo} Anemo DMG Bonus for 6s." },
  "lyney_bewildering_lights": { title: "Bewildering Lights", description: "<p>Lyney does a flourish with his hat, unleashing a firework surprise! When used, he will clear all current Prop Surplus stacks and deal AoE Pyro DMG to opponents in front of him. DMG will be increased according to the stacks cleared, and this will also regenerate Lyney's HP based on his Max HP.</p><p>When a Grin-Malkin Hat created by Lyney is on the field, the fireworks will cause it to explode, dealing AoE Pyro DMG equal to that of a Pyrotechnic Strike. The DMG dealt through the Grin-Malkin Hat in this way is considered Charged Attack DMG.</p><p><i>\"Everyone knows that magicians will intentionally misdirect the audience... Ah, yes, while you were looking my way, the hat and assistant over there have both disappeared... Fascinating, is it not?\"</i></p>" },
  "lyney_card_force_translocation": { title: "Card Force Translocation", description: "<p>Normal Attack Performs up to 4 consecutive shots with a bow.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, flames will run across the arrowhead before being fired. Different effects will occur based on the time spent charging. ·Charge Level 1: Fires off a Pyro-infused arrow, dealing Pyro DMG. ·Charge Level 2: Fires off a Prop Arrow that deals Pyro DMG, and upon hit, it will summon a Grin-Malkin Hat. When firing the Prop Arrow, and when Lyney has more than 60% HP, he will consume a portion of his HP to obtain 1 Prop Surplus stack. Max 5 stacks. The effect will be removed after the character spends 30s out of combat. The lowest Lyney can drop to through this method is 60% of his Max HP.</p><p>Grin-Malkin Hat ·Can taunt nearby opponents and attract their attacks. Each opponent can only be taunted by the Hat once every 5s. ·The Hat will inherit a percentage of Lyney's Max HP. ·If destroyed, or if its duration expires, it will fire off a Pyrotechnic Strike at 1 nearby opponent, dealing Pyro DMG. Only 1 Hat can exist at any given time.</p><p>Arkhe: Pneuma At certain intervals, the Prop Arrow will cause a Spiritbreath Thorn to descend upon its hit location, dealing Pneuma-aligned Pyro DMG.</p>" },
  "lyney_conclusive_ovation": { title: "Conclusive Ovation", description: "The DMG Lyney deals to opponents affected by Pyro will receive the following buffs: ·Increases the DMG dealt by {text_percent_dmg}. ·Each Pyro party member other than Lyney will cause the DMG dealt to increase by an additional {text_percent_bonus}. Lyney can deal up to {text_percent_max} increased DMG to opponents affected by Pyro in this way." },
  "lyney_guarded_smile": { title: "Guarded Smile", description: "When Lyney fires a Prop Arrow, he will fire a Pyrotechnic Strike: Reprised that will deal {text_percent_dmg} of a Pyrotechnic Strike's DMG. This DMG is considered Charged Attack DMG." },
  "lyney_loquacious_cajoling": { title: "Loquacious Cajoling", description: "When Lyney is on the field, he will gain a stack of Crisp Focus every 2s. Each stack will increase his CRIT DMG by 20%. Max 3 stacks. This effect will be canceled when Lyney leaves the field." },
  "lyney_miracle_parade": { title: "Wondrous Trick: Miracle Parade", description: "<p>Unleashing his magic, Lyney turns himself into a Grin-Malkin Cat that can move around quickly. (Not to be mistaken for the Grin-Malkin Hat. They're two different props!) When the Grin-Malkin Cat gets close to opponents, it will send flames falling down on them, dealing at most 1 instance of Pyro DMG to each opponent. When the duration ends, he will dismiss the Grin-Malkin Cat and ignite fireworks that deal AoE Pyro DMG, summon 1 Grin-Malkin Hat, and grant himself 1 Prop Surplus stack.</p><p>Grin-Malkin Cat can be actively canceled.</p><p><i>\"Watch closely now. This is a time for miracles, and it belongs to just the two of us!\"</i></p>" },
  "lyney_perilous_performance": { title: "Perilous Performance", description: "If Lyney consumes HP when firing off a Prop Arrow, the Grin-Malkin hat summoned by the arrow will, upon hitting an opponent, restore 3 Energy to Lyney and increase DMG dealt by {text_percent_dmg} of his ATK." },
  "lyney_prestidigitation": { title: "Prestidigitation" },
  "lyney_to_pierce_enigmas": { title: "To Pierce Enigmas" },
  "lyney_well_versed_well_rehearsed": { title: "Well-Versed, Well-Rehearsed", description: "After an opponent is hit by Lyney's Pyro Charged Attack, this opponent's Pyro RES will be decreased by {enemy_res_pyro} for 6s." },
  "lyney_whimsical_wonders": { title: "Whimsical Wonders", description: "Lyney can have 2 Grin-Malkin Hats present at once. Additionally, Prop Arrows will summon 2 Grin-Malkin Hats and grant Lyney 1 extra stack of Prop Surplus. This effect can occur once every 15s." },
  "mavuika_flames_weave_life": { title: "Flames Weave Life", description: "<p>Normal Attack Performs up to 4 consecutive claymore strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to perform an especially powerful Severing Splendor strike toward the front.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "mavuika_gift_of_flaming_flowers": { title: "Gift of Flaming Flowers", description: "When a nearby party member triggers a Nightsoul Burst, Mavuika's ATK increases by {atk_percent} for 10s." },
  "mavuika_hour_of_burning_skies": { title: "Hour of Burning Skies", description: "<p>Let the people's inner voices reach the divine throne in the heavens. Mavuika's Elemental Burst is not reliant on Energy, but instead, on \"Fighting Spirit.\"</p><p>Fighting Spirit When Mavuika has at least 50% Fighting Spirit, she can consume it all to unleash her Elemental Burst. Mavuika can obtain Fighting Spirit via the following methods: · When in combat, Nightsoul points consumed by nearby party members are converted to Fighting Spirit. · When nearby party members' Normal Attacks hit opponents, Mavuika gains 1.5 Fighting Spirit. This can trigger once every 0.1s.</p><p>After using this, Mavuika gains 10 Nightsoul points and enters the Nightsoul's Blessing state. Riding her Flamestrider high in the air, she uses a powerful Sunfell Slice against opponents on the ground, dealing Nightsoul-aligned AoE Pyro DMG and entering the \"Crucible of Death and Life\" state.</p><p>Crucible of Death and Life During this time, Mavuika's various actions will no longer consume Nightsoul points, and her interruption resistance is increased. Also, the DMG dealt by Sunfell Slice and \"Ancient Name Unbound\"'s Normal and Charged Attacks is increased based on the amount of Fighting Spirit she has when using the Elemental Burst. Crucible of Death and Life will be canceled when Mavuika leaves the field.</p><p><i>\"—But this time, I want to break the cycle and free us from this fate for good.\"</i></p>" },
  "mavuika_humanitys_name_unfettered": { title: "\"Humanity's Name\" Unfettered" },
  "mavuika_humanitys_name_unfettered_1": { description: "Ring of Searing Radiance: When the Ring's attacks hit opponents, a Flamestrider will crash into the struck opponent, dealing {text_percent_dmg1} of ATK as Nightsoul-aligned AoE Pyro DMG." },
  "mavuika_humanitys_name_unfettered_2": { description: "Flamestrider: When Mavuika is riding the Flamestrider, she will also summon a Scorching Ring of Searing Radiance to follow her, which will decrease nearby opponents' DEF by {text_percent_def} and deal {text_percent_dmg2} of ATK as Nightsoul-aligned AoE Pyro DMG to nearby opponents once every 3s. Mavuika's terrain-crossing abilities will also be further improved." },
  "mavuika_humanitys_name_unfettered_3": { description: "Additionally, when Mavuika is riding her Flamestrider and is not in combat, when her Nightsoul points drop to 5, she will gain 80 Nightsoul points. This effect can trigger once every 15s." },
  "mavuika_kiongozi": { title: "\"Kiongozi\"", description: "After using her Elemental Burst, Hour of Burning Skies, every point of Fighting Spirit present when it is used increases the DMG that the current active party member deals by {text_percent_dmg}. The maximum increase obtainable this way is {text_percent_max}, and this effect lasts 20s, decaying over this duration until it reaches 0." },
  "mavuika_the_ashen_price": { title: "The Ashen Price" },
  "mavuika_the_ashen_price_1": { description: "When in the Nightsoul's Blessing State, Mavuika's Base ATK is increased by {atk_base}, and she obtains the following effects based on All-Fire Armaments' form:" },
  "mavuika_the_ashen_price_2": { description: "Ring of Searing Radiance: Nearby opponents' DEF is decreased by {text_percent_def}." },
  "mavuika_the_ashen_price_3": { description: "Flamestrider: Mavuika's Normal Attacks, Charged Attacks, and her Sunfell Slice from the Elemental Burst Hour of Burning Skies deal {text_percent_dmg1}, {text_percent_dmg2}, and {text_percent_dmg3} of her ATK as increased DMG respectively." },
  "mavuika_the_burning_sun": { title: "The Burning Sun" },
  "mavuika_the_leaders_resolve": { title: "The Leader's Resolve", description: "Enhances the effects of the Passive Talent \"Kiongozi\": The DMG increase gained after using the Elemental Burst Hour of Burning Skies will not decay over time, and an additional {dmg_all} DMG Bonus will be gained. You must first unlock the Passive Talent \"Kiongozi.\"" },
  "mavuika_the_meaning_of_truth": { title: "The Meaning of Truth" },
  "mavuika_the_named_moment": { title: "The Named Moment", description: "<p>Calling upon her authority over \"conflict,\" Mavuika summons the All-Fire Armaments passed down through the line of human Archons, dealing Nightsoul-aligned Pyro DMG. After using this, Mavuika's Nightsoul points are restored to max value, and she enters the Nightsoul's Blessing state.</p><p>All-Fire Armaments Has different forms when Tapped or Held.</p><p>Tap \"Divine Name Unleashed\": The All-Fire Armaments manifest as a Ring of Searing Radiance. The Ring follows the current active character and attacks nearby opponents at intervals, dealing Nightsoul-aligned Pyro DMG.</p><p>Hold \"Ancient Name Unbound\": The All-Fire Armaments manifest as a Flamestrider. In this state, Mavuika can ride the Flamestrider at high speed, or activate its hidden backup propulsion module to temporarily cross various terrain types and glide in mid-air. Mavuika's Normal, Charged, and Plunging Attacks will also be converted to deal Nightsoul-aligned Pyro DMG which cannot be overridden. When sprinting, she also deals Nightsoul-aligned Pyro DMG to opponents along her path.</p><p>While in the Nightsoul's Blessing state, Tapping the Elemental Skill can switch the All-Fire Armaments' form. The Armaments will disappear once Mavuika's Nightsoul's Blessing state ends.</p><p>Nightsoul's Blessing: Mavuika Continuously consumes Nightsoul points according to the All-Fire Armaments' form. Mavuika's Nightsoul's Blessing state ends once her Nightsoul points are exhausted.</p><p><i>If you told Mavuika that in another world vehicles like the Flamestrider required license plates for identification, that would make her happy too: \"Well, mine's the only one that exists here. Guess that means I get to pick whatever plate number I want, huh?\"</i></p>" },
  "mavuika_the_night_lords_explication": { title: "The Night-Lord's Explication", description: "Mavuika's maximum Nightsoul points are increased to 120, and she gains Fighting Spirit 25% more efficiently. Additionally, she gains {atk_percent} ATK for 8s after gaining Fighting Spirit." },
  "mika_companions_counsel": { title: "Companion's Counsel" },
  "mika_companions_counsel_1": { description: "The maximum number of Detector stacks that Starfrost Swirl's Soulwind can gain is increased by 1. You need to have unlocked the Passive Talent \"Suppressive Barrage\" first." },
  "mika_companions_counsel_2": { description: "Additionally, active characters affected by Soulwind will deal {crit_dmg_phys} more Physical CRIT DMG." },
  "mika_companions_ingress": { title: "Companion's Ingress", description: "When Starfrost Swirl's Flowfrost Arrow first hits an opponent, or its Rimestar Flare hits an opponent, 1 Detector stack from Passive Talent \"Suppressive Barrage\" will be generated. You must have unlocked the Passive Talent \"Suppressive Barrage\" first." },
  "mika_factor_confluence": { title: "Factor Confluence", description: "The Soulwind state of Starfrost Swirl can decrease the healing interval between instances caused by Skyfeather Song's Eagleplume state. This decrease percentage is equal to the ATK SPD increase provided by Soulwind." },
  "mika_reconnaissance_experience": { title: "Reconnaissance Experience" },
  "mika_signal_arrow": { title: "Signal Arrow" },
  "mika_skyfeather_song": { title: "Skyfeather Song", description: "<p>Derives the ability to spur his teammates on from the recited prayers of the knightly order, regenerating HP for all nearby party members. This healing is based on Mika's Max HP and will grant them the Eagleplume state.</p><p>Eagleplume When the Normal Attacks of active characters affected by Eagleplume hit an opponent, Mika will help them regenerate HP based on his Max HP. Characters affected by this state can only regenerate HP in this way once per short interval of time.</p><p><i>\"Carry hope when in dire straits, and keep vigil when all is well... For that pure white plume shall at last guide the lost wayfarers.\"</i></p>" },
  "mika_soulwind": { title: "Soulwind", description: "When characters in the Soulwind state are on the field, their ATK SPD will be increased." },
  "mika_spear_of_favonius_arrows_passage": { title: "Spear of Favonius - Arrow's Passage", description: "<p>Normal Attack Performs up to 5 consecutive strikes using his crossbow and spear.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "mika_starfrost_swirl": { title: "Starfrost Swirl", description: "<p>Mika uses his crossbow to attack, granting all nearby characters in your party Soulwind. When characters in the Soulwind state are on the field, their ATK SPD will be increased. Will take effect in different ways if Tapped or Held.</p><p>Tap Fires a Flowfrost Arrow that can pierce through opponents, dealing Cryo DMG to enemies it comes into contact with.</p><p>Hold Goes into Aiming Mode, locking on to an opponent and firing a Rimestar Flare at them, dealing Cryo DMG. When the Rimestar Flare hits, it will rise before exploding, launching Rimestar Shards into a maximum of 3 other opponents, dealing Cryo DMG.</p><p><i>Stars burst 'neath the frosted skies.</i></p>" },
  "mika_sunfrost_encomium": { title: "Sunfrost Encomium", description: "When Mika's own Skyfeather Song's Eagleplume state heals party members, this will restore 3 Energy to Mika. This form of Energy restoration can occur 5 times during the Eagleplume state created by 1 use of Skyfeather Song." },
  "mika_suppressive_barrage": { title: "Suppressive Barrage", description: "Per the following circumstances, the Soulwind state caused by Starfrost Swirl will grant characters the Detector effect, increasing their Physical DMG by {dmg_phys} when they are on the field. ·If the Flowfrost Arrow hits more than one opponent, each additional opponent hit will generate 1 Detector stack. ·When a Rimestar Shard hits an opponent, it will generate 1 Detector stack. Each Rimestar Shard can trigger the effect 1 time. The Soulwind state can have a maximum of 3 Detector stacks, and if Starfrost Swirl is cast again during this duration, the pre-existing Soulwind state and all its Detector stacks will be cleared." },
  "mika_topographical_mapping": { title: "Topographical Mapping", description: "When an active character affected by both Skyfeather Song's Eagleplume and Starfrost Swirl's Soulwind at once scores a CRIT Hit with their attacks, Soulwind will grant them 1 stack of Detector from Suppressive Barrage. During a single instance of Soulwind, 1 Detector stack can be gained in this manner. Additionally, the maximum number of stacks that can be gained through Soulwind alone is increased by 1. Requires Suppressive Barrage to be unlocked first." },
  "mona_come_n_get_me_hag": { title: "\"Come 'n' Get Me, Hag!\"", description: "After she has used Illusory Torrent for 2s, if there are any opponents nearby, Mona will automatically create a Phantom. A Phantom created in this manner lasts for 2s, and its explosion DMG is equal to {text_percent_dmg} of Mirror Reflection of Doom." },
  "mona_illusory_torrent": { title: "Illusory Torrent", description: "<p>Alternate Sprint Mona cloaks herself within the water's flow, consuming Stamina to move rapidly.</p><p>When under the effect of Illusory Torrent, Mona can move at high speed on water. Applies the Wet status to nearby opponents when she reappears.</p><p><i>This is something that Mona can do, but her teacher cannot. Well, but it's not as if her teacher would pursue any matter concerning Hydro Visions anyway...</i></p>" },
  "mona_lunar_chain": { title: "Lunar Chain", description: "When a Normal Attack hits, there is a {text_percent_chance} chance that it will be automatically followed by a Charged Attack. This effect can only occur once every 5s." },
  "mona_mirror_reflection_of_doom": { title: "Mirror Reflection of Doom", description: "<p>Creates an illusory Phantom of Fate from coalesced waterspouts.</p><p>Phantom Has the following special properties: ·Continuously taunts nearby opponents, attracting their fire. ·Continuously deals Hydro DMG to nearby opponents. ·When its duration expires, the Phantom explodes, dealing AoE Hydro DMG.</p><p>Hold Utilizes water currents to move backwards swiftly before conjuring a Phantom.</p><p>Only one Phantom created by Mirror Reflection of Doom can exist at any time.</p><p><i>Skilled astrologers have always dreamed of using a phantom facsimile of themselves to ward off imminent ill fate, but Mona must be the first to make such a mockery of it in all of Teyvat.</i></p>" },
  "mona_mockery_of_fortuna": { title: "Mockery of Fortuna" },
  "mona_omen": { title: "Omen", description: "During Stellaris Phantasm duration, increases DMG taken by opponents." },
  "mona_prophecy_of_oblivion": { title: "Prophecy of Oblivion", description: "When any party member attacks an opponent affected by an Omen, their CRIT Rate is increased by {crit_rate}." },
  "mona_prophecy_of_submersion": { title: "Prophecy of Submersion", description: "When any of your own party members hits an opponent affected by an Omen, the effects of Hydro-related Elemental Reactions are enhanced for 8s: · Electro-Charged DMG increases by {dmg_reaction_electrocharged}. · Lunar-Charged DMG increases by {dmg_reaction_lunarcharged}. · Vaporize DMG increases by {dmg_reaction_vaporize}. · Hydro Swirl DMG increases by {dmg_reaction_swirl_hydro}. · Frozen duration is extended by {duration_frozen}." },
  "mona_restless_revolution": { title: "Restless Revolution" },
  "mona_rhetorics_of_calamitas": { title: "Rhetorics of Calamitas", description: "Upon entering Illusory Torrent, Mona gains a {dmg_charged} increase to the DMG of her next Charged Attack per second of movement. A maximum DMG Bonus of 180% can be achieved in this manner. The effect lasts for no more than 8s." },
  "mona_ripple_of_fate": { title: "Ripple of Fate", description: "<p>Normal Attack Performs up to 4 water splash attacks that deal Hydro DMG.</p><p>Charged Attack Consumes a certain amount of Stamina to deal AoE Hydro DMG after a short casting time.</p><p>Plunging Attack Gathering the might of Hydro, Mona plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Hydro DMG upon impact with the ground.</p>" },
  "mona_stellaris_phantasm": { title: "Stellaris Phantasm", description: "<p>Mona summons the sparkling waves and creates a reflection of the starry sky, applying the Illusory Bubble status to opponents in a large AoE.</p><p>Illusory Bubble Traps opponents inside a pocket of destiny and also makes them Wet. Renders weaker opponents immobile. When an opponent affected by Illusory Bubble sustains DMG, it has the following effects: ·Applies an Omen to the opponent, which gives a DMG Bonus, also increasing the DMG of the attack that causes it. ·Removes the Illusory Bubble, dealing Hydro DMG in the process.</p><p>Omen During its duration, increases DMG taken by opponents.</p><p><i>It was from the time that gods first traced the lights in the heavens with their eyes that the notion of \"fate\" was born.</i></p>" },
  "mona_waterborne_destiny": { title: "Waterborne Destiny", description: "Increases Mona's Hydro DMG Bonus by a degree equivalent to {text_percent} of her Energy Recharge rate." },
  "mualani_boomsharka_laka": { title: "Boomsharka-laka", description: "<p>Fires a Super Shark Missile that can track opponents, dealing Nightsoul-aligned AoE Hydro DMG based on Mualani's Max HP.</p><p><i>Mualani picked this moniker for launching her Shark Missile because it combines the warmth of explosive passion with a more chill, laid-back vibe — most hot spring-ish.</i></p>" },
  "mualani_cooling_treatment": { title: "Cooling Treatment", description: "<p>Normal Attack Performs up to 3 attacks that deal Hydro DMG.</p><p>Charged Attack Consumes a certain amount of Stamina to smack a Pufferball into the air that deals AoE Hydro DMG upon landing.</p><p>Plunging Attack Gathers the power of Hydro and plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Hydro DMG upon impact with the ground.</p>" },
  "mualani_heat_resistant_freshwater_floater": { title: "Heat-Resistant Freshwater Floater", description: "When Sharky's Surging Bite hits an opponent, a Puffer will be generated nearby. Mualani will restore 20 Nightsoul points when she picks up a Puffer. Only 2 such Puffers can be created in this way during a single instance of being in Nightsoul's Blessing." },
  "mualani_mualani_going_all_out": { title: "Mualani, Going All Out!", description: "Mualani gains 2 of Surfshark Wavebreaker's Wave Momentum stacks when she enters Nightsoul's Blessing state. She will gain 1 stack when obtaining a Puffer. In addition, whenever Mualani obtains 2 Puffers within a single instance of the Nightsoul's Blessing state, she will recover an additional 12 Nightsoul points over 2s. This effect requires the Passive Talent \"Heat-Resistant Freshwater Floater\" to be unlocked first." },
  "mualani_natlans_greatest_guide": { title: "Natlan's Greatest Guide", description: "After a nearby party member triggers a Nightsoul Burst, Mualani will gain 1 stack of Wavechaser's Exploits, which lasts for 20s. Max 3 stacks. When she uses Boomsharka-laka, Mualani will clear all Wavechaser's Exploits stacks and increase the DMG of this Boomsharka-laka by {text_percent_1}/{text_percent_2}/{text_percent_3} of her Max HP based on the number of stacks cleared." },
  "mualani_same_style_of_surfboard_on_sale": { title: "Same Style of Surfboard on Sale!" },
  "mualani_sharky_eats_puffies": { title: "Sharky Eats Puffies", description: "Mualani regenerates 8 Energy when obtaining a Puffer. Must first unlock the Passive Talent \"Heat-Resistant Freshwater Floater.\" Additionally, Boomsharka-laka deals {dmg_burst_mualani} increased DMG." },
  "mualani_spirit_of_the_springs_people": { title: "Spirit of the Springs' People", description: "The DMG increase from the Constellation \"The Leisurely 'Meztli'...\" is no longer limited to being triggered once every Nightsoul's Blessing." },
  "mualani_surfing_atop_joyous_seas": { title: "Surfing Atop Joyous Seas" },
  "mualani_surfshark_wavebreaker": { title: "Surfshark Wavebreaker", description: "<p>Combining her mastery of speed and the waves and water, Mualani can surf anytime, anywhere. After using this skill, Mualani will gain 60 Nightsoul points and enter the Nightsoul's Blessing state.</p><p>Nightsoul's Blessing: Mualani Continuously consume Nightsoul points. When they are depleted or when the skill is used again, Mualani's Nightsoul's Blessing will end. The state itself has the following traits: ·Mualani mounts her Sharky Surfboard, increasing Mualani's Movement SPD and interruption resistance. Mualani can move on water and liquid Phlogiston while this state is active, and she will take no DMG from the latter. ·Normal Attacks will be converted to Sharky's Bites, dealing Nightsoul-aligned Hydro DMG based on Mualani's Max HP. Sharky's Bites can be used in mid-air. DMG dealt this way is considered Normal Attack DMG. ·When she makes contact with opponents in this state, Mualani applies \"Marked as Prey\" to them and gains 1 Wave Momentum stack. Max 3 stacks. 1 stack can be gained from the same opponent every 0.7s.</p><p>Wave Momentum and Marked as Prey When Mualani uses Sharky's Bite, her DMG dealt increases based on Wave Momentum stacks. When she has 3 stacks, Sharky's Bite will be converted to Sharky's Surging Bite, further increasing her DMG and removing all her stacks when hitting an opponent. When Sharky's Bite hits an opponent Marked as Prey, that mark will be removed, and she will fire Shark Missiles at up to 5 nearby opponents Marked as Prey, dealing DMG to them equal to this Sharky's Bite instance and clearing their Marks. If more than 1 opponent is the target of Sharky's Bite and Shark Missiles, the DMG dealt will decrease, decreasing at most to 72% of the original DMG when 3 opponents are targeted.</p><p><i>First off, Sharky is a freshwater shark on top of being a surfboard. Second, it's not that it wants to eat for real, just that it definitely bites for real.</i></p>" },
  "mualani_the_leisurely_meztli": { title: "The Leisurely \"Meztli\"...", description: "The DMG dealt by the first Sharky's Surging Bite after Mualani enters Nightsoul's Blessing and the Shark Missiles it triggers is increased by {text_percent_dmg} of Mualani's Max HP. This instance of increased DMG is subject to the diminishing DMG rules of Surfshark Wavebreaker. In addition, while out of combat, Mualani's Nightsoul's Blessing state consumes 30% less Phlogiston and Nightsoul points." },
  "n11120001": { title: "Cold Storage Mode", description: "<p>Tap Activates her All-Spectrum Multi-Use Cooking Mek in its Cold Storage mode and deals AoE Cryo DMG to nearby opponents.</p><p>Cooking Mek: Cold Storage Mode Follows the current active character and fires Frosty Parfaits at nearby opponents at intervals, dealing Cryo DMG.</p>" },
  "n11120002": { title: "Off-the-Cuff Cookery Mode", description: "<p>Cooking Mek: Off-the-Cuff Cookery Mode · Places the Cooking Mek on the field. The Cooking Mek can absorb elemental attacks. When the absorbed elemental energy hits a certain limit, Escoffier can convert the ingredients placed within it into wonderful food. · Escoffier needs time to purchase new ingredients, so she can only make a certain number of dishes like this each week. The number of dishes Escoffier can make resets every Monday at 4:00 AM.</p>" },
  "n11130001": { title: "Supporting Fire", description: "<p>In the Nightsoul's Blessing State, Ifa's Normal Attacks will turn into Supporting Fire. Tap Fires a Tonicshot. Hold Continuously fires Tonicshots. Tonicshot Deals Nightsoul-aligned Anemo DMG, and will heal all nearby party members based on Ifa's Elemental Mastery upon hitting an opponent.</p>" },
  "n11130002": { title: "Rescue Essentials", description: "<p>Max 150 points. Each Rescue Essentials point Ifa has will increase the Swirl and Electro-Charged DMG dealt by nearby party members by 1.5%, and their Lunar-Charged DMG dealt by 0.2%. These points will be cleared when his Nightsoul's Blessing state ends.</p>" },
  "n11130003": { title: "Nightsoul's Blessing: Ifa", description: "<p>Continuously consumes Nightsoul points. This state will end when Ifa runs out of Nightsoul points or if he uses this skill again. His Nightsoul's Blessing state has the following properties: · Hovers with Cacucu's help, increasing Ifa's Movement SPD and interruption resistance. In this state, Ifa will continuously consume Nightsoul points to maintain this hovering state. If he sprints or accelerates, he will consume additional points. · When he uses Normal Attacks, he will use different kinds of Supporting Fire depending on whether you Tap or Hold.</p>" },
  "n11130004": { title: "Sedation Mark", description: "<p>This effect will explode after a short delay and disappear, dealing AoE DMG aligned with the corresponding element. The Therapeutic Sedative can apply Sedation Marks to a maximum of 4 hit opponents. A single opponent cannot receive Marks of different elements simultaneously.</p>" },
  "n11130005": { title: "Serpent's Subtlety", description: "<p>Skirk can consume Serpent's Subtlety to maintain her Seven-Phase Flash mode or to use her Elemental Burst, Havoc: Ruin.</p><p>Skirk can gain Serpent's Subtlety points in the following ways: · After using her Elemental Skill, Havoc: Warp. · After triggering the effect of her Passive Talent, Reason Beyond Reason, and absorbing Void Rifts.</p><p>When Skirk leaves the field while in Seven-Phase Flash mode or when Seven-Phase Flash ends, her Serpent's Subtlety points will be removed.</p>" },
  "n11130006": { title: "Seven-Phase Flash", description: "<p>Skirk will switch to this mode for a fixed time when using the Elemental Skill Havoc: Warp. This mode has the following properties: · Continuously consumes Serpent's Subtlety. · Increases Normal and Charged Attack AoE and Skirk's interruption resistance. · Normal, Charged, and Plunging Attacks are converted to Cryo DMG that cannot be overridden by other Elemental infusions. · Her Elemental Burst, Havoc: Ruin is converted to the special Elemental Burst Havoc: Extinction. · Skirk can move on water when she Sprints. · Skirk will exit this mode when Serpent's Subtlety is fully depleted or its duration ends. Then, the Elemental Skill will go on cooldown.</p>" },
  "n11130007": { title: "Reason Beyond Reason", description: "<p>When nearby party members trigger Frozen, Superconduct, Cryo Swirl, or Cryo Crystallize reactions against opponents, a Void Rift will be created near this opponent. This effect can be triggered once every 2.5s. A maximum of 3 Void Rifts created by Skirk herself can exist on the field at once.</p><p>Skirk can use the following methods to absorb nearby Void Rifts: · When she hits an opponent with a Charged Attack in her Seven-Phase Flash mode. · When she uses the special Elemental Burst Havoc: Extinction while in Seven-Phase Flash mode. · When she Holds her Elemental Skill Havoc: Warp to engage in rapid movement.</p><p>Each Rift absorbed will grant her 8 Serpent's Subtlety points.</p>" },
  "n11130008": { title: "Return to Oblivion", description: "<p>When nearby Hydro party members' Hydro attacks hit opponents, or when nearby Cryo party members apart from Skirk hit opponents with Cryo attacks, Skirk will gain the \"Death's Crossing\" effect for 20s. Max 3 stacks, each stack's duration is counted independently. Each character can grant Skirk at most 1 \"Death's Crossing\" stack by this means. Each \"Death's Crossing\" stack increases the Normal Attack DMG dealt by Skirk in Seven-Phase Flash mode to 110%/120%/170% of its original DMG and the DMG dealt when using her Elemental Burst Havoc: Ruin to 105%/115%/160% of its original DMG.</p>" },
  "n11160001": { title: "Birgitta", description: "<p>Ineffa's assistant and companion in battle, she can be summoned to the battlefield via Elemental Skill or Elemental Burst. If there are opponents nearby, Birgitta will quickly move close to an opponent and unleash Discharge attacks every 2s, dealing AoE Electro DMG. Only one Birgitta that has been summoned by Ineffa herself can exist at any one time.</p><p>Additionally, in Nod-Krai, it seems you'll be able to change Birgitta's appearance through certain means...</p>" },
  "nahida_akara": { title: "Akara", description: "<p>Normal Attack Performs up to 4 attacks that deal Dendro DMG to opponents in front of her.</p><p>Charged Attack Consumes a certain amount of Stamina to deal AoE Dendro DMG to opponents in front of her after a short casting time.</p><p>Plunging Attack Calling upon the might of Dendro, Nahida plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Dendro DMG upon impact with the ground.</p>" },
  "nahida_all_schemes_to_know": { title: "All Schemes to Know", description: "<p>Sends forth karmic bonds of wood and tree from her side, dealing AoE Dendro DMG and marking up to 8 opponents hit with the Seed of Skandha. When held, this skill will trigger differently.</p><p>Hold Enters Aiming Mode, which will allow you to select a limited number of opponents within a limited area. During this time, Nahida's resistance to interruption will be increased. When released, this skill deals Dendro DMG to these opponents and marks them with the Seed of Skandha. Aiming Mode will last up to 5s and can select a maximum of 8 opponents.</p><p>Seed of Skandha Opponents who have been marked by the Seed of Skandha will be linked to one another up till a certain distance. After you trigger Elemental Reactions on opponents who are affected by the Seeds of Skandha or when they take DMG from Dendro Cores (including Burgeon and Hyperbloom DMG), Nahida will unleash Tri-Karma Purification on the opponents and all connected opponents, dealing Dendro DMG based on her ATK and Elemental Mastery. You can trigger at most 1 Tri-Karma Purification within a short period of time.</p><p><i>Lo, the god of grass and trees shines her ultimate truth into the void, illuminating the origin and destruction of the three karmas.</i></p>" },
  "nahida_awakening_elucidated": { title: "Awakening Elucidated", description: "Each point of Nahida's Elemental Mastery beyond 200 will grant {text_percent_skill} Bonus DMG and {text_percent_crit} CRIT Rate to Tri-Karma Purification from All Schemes to Know. A maximum of {text_percent_skill_max} Bonus DMG and {text_percent_crit_max} CRIT Rate can be granted to Tri-Karma Purification in this manner." },
  "nahida_compassion_illuminated": { title: "Compassion Illuminated", description: "When unleashing Illusory Heart, the Shrine of Maya will gain the following effects: The Elemental Mastery of the active character within the field will be increased by {text_percent} of the Elemental Mastery of the party member with the highest Elemental Mastery. You can gain a maximum of {text_value_max} Elemental Mastery in this manner." },
  "nahida_illusory_heart": { title: "Illusory Heart", description: "<p>Manifests the Court of Dreams and expands the Shrine of Maya.</p><p>When the Shrine of Maya field is unleashed, the following effects will be separately unleashed based on the Elemental Types present within the party. ·Pyro: While Nahida remains within the Shrine of Maya, the DMG dealt by Tri-Karma Purification from \"All Schemes to Know\" is increased. ·Electro: While Nahida remains within the Shrine of Maya, the interval between each Tri-Karma Purification from \"All Schemes to Know\" is decreased. ·Hydro: The Shrine of Maya's duration is increased.</p><p>If there are at least 2 party members of the aforementioned Elemental Types present when the field is deployed, the aforementioned effects will be increased further.</p><p>Even if Nahida is not on the field, these bonuses will still take effect so long as party members are within the Shrine of Maya.</p><p><i>Perhaps all that dwell under the bowers of trees are naught but a fleeting upside-down dream in the eyes of the God of Wisdom.</i></p>" },
  "nahida_illusory_heart_talent": { description: "When the Shrine of Maya field is unleashed, the following effects will be separately unleashed based on the Elemental Types present within the party. ·Pyro: While Nahida remains within the Shrine of Maya, the DMG dealt by Tri-Karma Purification from All Schemes to Know is increased. ·Electro: While Nahida remains within the Shrine of Maya, the interval between each Tri-Karma Purification from \"All Schemes to Know\" is decreased. ·Hydro: The Shrine of Maya's duration is increased If there are at least 2 party members of the aforementioned Elemental Types present when the field is deployed, the aforementioned effects will be increased further." },
  "nahida_the_fruit_of_reasons_culmination": { title: "The Fruit of Reason's Culmination", description: "When Nahida hits an opponent affected by All Schemes to Know's Seeds of Skandha with Normal or Charged Attacks after unleashing Illusory Heart, she will use Tri-Karma Purification: Karmic Oblivion on this opponent and all connected opponents, dealing Dendro DMG based on {text_percent_dmg} of Nahida's ATK and {text_percent_dmg2} of her Elemental Mastery. DMG dealt by Tri-Karma Purification: Karmic Oblivion is considered Elemental Skill DMG and can be triggered once every 0.2s. This effect can last up to 10s and will be removed after Nahida has unleashed 6 instances of Tri-Karma Purification: Karmic Oblivion." },
  "nahida_the_leaves_of_enlightening_speech": { title: "The Leaves of Enlightening Speech" },
  "nahida_the_root_of_all_fullness": { title: "The Root of All Fullness" },
  "nahida_the_root_of_all_fullness_1": { description: "·Burning, Bloom, Hyperbloom, and Burgeon Reaction DMG they receive can score CRIT Hits. CRIT Rate and CRIT DMG are fixed at {crit_rate_bloom} and {crit_dmg_bloom} respectively." },
  "nahida_the_root_of_all_fullness_2": { description: "Within 8s of being affected by Quicken, Aggravate, Spread, DEF is decreased by {enemy_def_reduce}." },
  "nahida_the_seed_of_stored_knowledge": { title: "The Seed of Stored Knowledge", description: "When the Shrine of Maya is unleashed and the Elemental Types of the party members are being tabulated, the count will add 1 to the number of Pyro, Electro, and Hydro characters respectively." },
  "nahida_the_shoot_of_conscious_attainment": { title: "The Shoot of Conscious Attainment" },
  "nahida_the_stem_of_manifest_inference": { title: "The Stem of Manifest Inference", description: "When 1/2/3/4 (or more) nearby opponents are affected by All Schemes to Know's Seeds of Skandha, Nahida's Elemental Mastery will be increased by 100/120/140/160." },
  "navia_a_ladys_rules_for_keeping_a_courteous_distance": { title: "A Lady's Rules for Keeping a Courteous Distance", description: "Each stack of Crystal Shrapnel consumed when Navia uses Ceremonial Crystalshot will restore 3 Energy to her and decrease the CD of As the Sunlit Sky's Singing Salute by 1s. Up to 9 Energy can be gained this way, and the CD of \"As the Sunlit Sky's Singing Salute\" can be decreased by up to 3s." },
  "navia_as_the_sunlit_skys_singing_salute": { title: "As the Sunlit Sky's Singing Salute", description: "<p>On the orders of the President of the Spina di Rosula, call for a magnificent Rosula Dorata Salute. Unleashes a massive cannon bombardment on opponents in front of her, dealing AoE Geo DMG and providing Cannon Fire Support for a duration afterward, periodically dealing Geo DMG to nearby opponents. When cannon attacks hit opponents, Navia will gain 1 stack of Crystal Shrapnel. This effect can be triggered up to once every 2.4s.</p><p><i>\"The Spina di Rosula's salute is a preemptive celebration of the successful conclusion of our negotiations and is fired just before talks begin. Don't misunderstand, it isn't in any way, shape, or form some kind of threat.\"</i></p>" },
  "navia_blunt_refusal": { title: "Blunt Refusal", description: "<p>Normal Attack Performs up to 4 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous spinning attacks against all nearby opponents. At the end of the sequence, performs a more powerful slash.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "navia_businesswomans_broad_vision": { title: "Businesswoman's Broad Vision" },
  "navia_ceremonial_crystalshot": { title: "Ceremonial Crystalshot", description: "<p>When a character in the party obtains an Elemental Shard created from the Crystallize reaction, Navia will gain 1 Crystal Shrapnel stack. Navia can have up to 6 stacks of Crystal Shrapnel at once. Each time Crystal Shrapnel gain is triggered, the duration of the Crystal Shrapnel stacks you already have will be reset. When she fires, Navia will consume all Crystal Shrapnel stacks and open her elegant yet lethal Gunbrella, firing multiple Rosula Shardshots that can penetrate opponents, dealing Geo DMG to opponents hit. When 0/1/2/3 or more stacks of Crystal Shrapnel are consumed, 5/7/9/11 Rosula Shardshots will be fired respectively. The more Rosula Shardshots that strike a single opponent, the greater the DMG dealt to them. When all 11 Rosula Shardshots strike, 200% of the original amount of DMG is dealt. In addition, when more than 3 stacks of Crystal Shrapnel are consumed, every stack consumed beyond those 3 will increase the DMG dealt by this Gunbrella attack by an additional 15%.</p><p>Hold Enter Aiming Mode, continually collecting nearby Elemental Shards created by Crystallize reactions. When released, fire Rosula Shardshots with the same effect as when the skill is Tapped.</p><p>Two initial charges.</p><p>Arkhe: Ousia Periodically, when Navia fires her Gunbrella, a Surging Blade will be summoned, dealing Ousia-aligned Geo DMG.</p><p><i>\"Maintaining the appropriate distance with those whom distance should be maintained is an essential part of etiquette. Naturally, there are also many ways to do this...\"</i></p>" },
  "navia_mutual_assistance_network": { title: "Mutual Assistance Network", description: "For each Pyro/Electro/Cryo/Hydro party member, Navia gains {text_percent} increased ATK. This effect can stack up to 2 times." },
  "navia_negotiators_resolute_negotiations": { title: "Negotiator's Resolute Negotiations" },
  "navia_the_flexible_finesse_of_the_spinas_president": { title: "The Flexible Finesse of the Spina's President", description: "If more than 3 stacks of Crystal Shrapnel are consumed when using Ceremonial Crystalshot, each stack consumed beyond the first 3 increases the CRIT DMG of that Ceremonial Crystalshot by {text_percent}, and any stacks consumed beyond the first 3 are returned to Navia." },
  "navia_the_oathsworn_never_capitulate": { title: "The Oathsworn Never Capitulate", description: "When As the Sunlit Sky's Singing Salute hits an opponent, that opponent's Geo RES will be decreased by {enemy_res_geo} for 8s." },
  "navia_the_presidents_pursuit_of_victory": { title: "The President's Pursuit of Victory", description: "Each stack of Crystal Shrapnel consumed will increase the CRIT Rate of this Ceremonial Crystalshot instance by {text_percent}. CRIT Rate can be increased by up to {text_percent_max} in this way. In addition, when Ceremonial Crystalshot hits an opponent, one Cannon Fire Support shot from As the Sunlit Sky's Singing Salute will strike near the location of the hit. Up to one instance of Cannon Fire Support can be triggered each time Ceremonial Crystalshot is used, and DMG dealt by said Cannon Fire Support this way is considered Elemental Burst DMG." },
  "navia_undisclosed_distribution_channels": { title: "Undisclosed Distribution Channels", description: "For 4s after using Ceremonial Crystalshot, the DMG dealt by Navia's Normal Attacks, Charged Attacks, and Plunging Attacks will be converted into Geo DMG which cannot be overridden by other Elemental infusions, and the DMG dealt by Navia's Normal Attacks, Charged Attacks, and Plunging Attacks will be increased by {dmg_normal}." },
  "neuvillette_ancient_postulation": { title: "Ancient Postulation" },
  "neuvillette_as_water_seeks_equilibrium": { title: "As Water Seeks Equilibrium", description: "<p>Normal Attack With light flourishes, Neuvillette commands the tides to unleash a maximum of 3 attacks, dealing Hydro DMG.</p><p>Charged Attack Empowerment: Legal Evaluation While charging up, Neuvillette will gather the power of water, forming it into a Seal of Arbitration. In this state, Neuvillette can move and change facing, and also absorb any Sourcewater Droplets in a certain AoE. Every Droplet he absorbs will increase the formation speed of the Seal, and will heal Neuvillette. When the charging is stopped, if the Symbol has yet to be formed, then a Charged Attack will be unleashed. If it has been formed, then a Charged Attack: Equitable Judgment will be unleashed.</p><p>Charged Attack Consumes a fixed amount of Stamina to attack opponents with a rupturing blast of water, dealing AoE Hydro DMG.</p><p>Charged Attack: Equitable Judgment Unleashes surging torrents, dealing continuous AoE Hydro DMG to all opponents in a straight-line area in front of him. Equitable Judgment will not consume any Stamina and lasts 3s. If Neuvillette's HP is above 50%, he will continuously lose HP while using this attack.</p><p>Plunging Attack Gathering the might of Hydro, Neuvillette plunges towards the ground from mid-air, damaging all opponents in his path. Deals AoE Hydro DMG upon impact with the ground.</p>" },
  "neuvillette_axiomatic_judgment": { title: "Axiomatic Judgment" },
  "neuvillette_crown_of_commiseration": { title: "Crown of Commiseration", description: "When Neuvillette is on the field and is healed, 1 Sourcewater Droplet will be generated. This effect can occur once every 4s." },
  "neuvillette_discipline_of_the_supreme_arbitration": { title: "Discipline of the Supreme Arbitration", description: "For each 1% of Neuvillette's current HP greater than 30% of Max HP, he will gain {text_percent_dmg} Hydro DMG Bonus. A maximum bonus of {text_percent_dmg_max} can be obtained this way." },
  "neuvillette_heir_to_the_ancient_seas_authority": { title: "Heir to the Ancient Sea's Authority", description: "When a party member triggers a Vaporize, Frozen, Electro-Charged, Lunar-Charged, Bloom, Hydro Swirl, or a Hydro Crystallize reaction on opponents, 1 stack of Past Draconic Glories will be granted to Neuvillette for 30s. Max 3 stacks. Past Draconic Glories causes Charged Attack: Equitable Judgment to deal {text_percent_dmg_1}/{text_percent_dmg_2}/{text_percent_dmg_3} of its original DMG. The stacks of Past Draconic Glories created by each kind of Elemental Reaction exist independently." },
  "neuvillette_juridical_exhortation": { title: "Juridical Exhortation", description: "The Passive Talent \"Heir to the Ancient Sea's Authority\" will be enhanced: Each stack of Past Draconic Glories will increase the CRIT DMG of Charged Attack: Equitable Judgment by {text_percent}. The maximum increase that can be achieved this way is {text_percent_max}. You must first unlock the Passive Talent \"Heir to the Ancient Sea's Authority.\"" },
  "neuvillette_o_tears_i_shall_repay": { title: "O Tears, I Shall Repay", description: "<p>Summons a Raging Waterfall that will deal AoE Hydro DMG to opponents in front of Neuvillette based on his Max HP. After hitting an opponent, this skill will generate 3 Sourcewater Droplets near that opponent.</p><p>Arkhe: Pneuma At certain intervals, when the Raging Waterfall descends, a Spiritbreath Thorn will descend that will pierce opponents, dealing Pneuma-aligned Hydro DMG.</p><p><i>\"The law can restrict all manner of crimes, but it cannot extirpate evil itself.</i></p>" },
  "neuvillette_o_tides_i_have_returned": { title: "O Tides, I Have Returned", description: "<p>Unleashes waves that will deal AoE Hydro DMG based on Neuvillette's Max HP. After a short interval, 2 waterfalls will descend and deal Hydro DMG in a somewhat smaller AoE, and will generate 6 Sourcewater Droplets within an area in front.</p><p><i>\"The law is only established after its publication, and above that, the laws of nature have governed all species and eras since ancient times.</i></p>" },
  "neuvillette_venerable_institution": { title: "Venerable Institution", description: "When Neuvillette takes the field, he will obtain 1 stack of Past Draconic Glories from the Passive Talent \"Heir to the Ancient Sea's Authority.\" You must first unlock the Passive Talent \"Heir to the Ancient Sea's Authority.\" Additionally, his interruption resistance will be increased while using the Charged Attack Empowerment: Legal Evaluation and the Charged Attack: Equitable Judgment." },
  "neuvillette_wrathful_recompense": { title: "Wrathful Recompense", description: "When using Charged Attack: Equitable Judgment, Neuvillette can absorb nearby Sourcewater Droplets in an AoE. Each absorbed Droplet will increase the duration of Charged Attack: Equitable Judgment by 1s. Additionally, when Equitable Judgment hits opponents, it will fire off 2 additional currents every 2s, each of which will deal {text_percent_dmg} of Neuvillette's Max HP as Hydro DMG. DMG dealt this way will count as DMG dealt by Equitable Judgment." },
  "nilou_beguiling_shadowstep": { title: "Beguiling Shadowstep" },
  "nilou_court_of_dancing_petals": { title: "Court of Dancing Petals" },
  "nilou_court_of_dancing_petals_1": { description: "When all characters in the party are all Dendro or Hydro, and there are at least one Dendro character and one Hydro character: The completion of the third dance step of Nilou's Dance of Haftkarsvar will grant all nearby characters the Golden Chalice's Bounty for 30s. Characters under the effect of Golden Chalice's Bounty will increase the Elemental Mastery of all nearby characters by 100 for 10s whenever they are hit by Dendro attacks." },
  "nilou_court_of_dancing_petals_2": { description: "Also, triggering the Bloom reaction will create Bountiful Cores instead of Dendro Cores. Such Cores will burst very quickly after being created, and they have larger AoEs. Bountiful Cores cannot trigger Hyperbloom or Burgeon, and they share an upper numerical limit with Dendro Cores." },
  "nilou_dance_of_haftkarsvar": { title: "Dance of Haftkarsvar", description: "<p>Enters the Pirouette state, dealing Hydro DMG to nearby opponents based on Nilou's Max HP. While she is in the Pirouette state, Nilou's Normal Attacks and Elemental Skill will cause her to enter the Sword Dance and Whirling Steps stances respectively, causing DMG she deals to be converted to Hydro DMG that cannot be overridden and that is considered Elemental Skill DMG.</p><p>In these stances, Nilou's third dance step will end Pirouette, and has the following effects based on the type of said dance step: ·Sword Dance: unleashes a Luminous Illusion that deals Hydro DMG to opponents it touches and grants Nilou the Lunar Prayer effect. This effect converts Nilou's Normal Attacks into Sword Dance techniques, and her final hit will unleash a Luminous Illusion. ·Whirling Steps: Nilou unleashes a Whirling Water Wheel that deals AoE Hydro DMG and creates a Tranquility Aura that follows your active character around and applies Wet to opponents within its AoE.</p><p>Nilou is unable to perform Charged Attacks when under the effect of Pirouette or Lunar Prayer. These effects will be removed once she leaves the field.</p><p><i>\"Daintily her toes touch the water's face, and the light that ripples forth equals even the seven heavens.\"</i></p>" },
  "nilou_dance_of_samser": { title: "Dance of Samser", description: "<p>Normal Attack Performs up to 3 consecutive sword strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to perform a twirling slash.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "nilou_dance_of_the_waning_moon": { title: "Dance of the Waning Moon", description: "Dance of Haftkarsvar will be enhanced as follows: ·Luminous Illusion DMG is increased by {dmg_skill_nilou}. ·The Tranquility Aura's duration is extended by 6s." },
  "nilou_distant_dreams_listening_spring": { title: "Dance of Abzendegi: Distant Dreams, Listening Spring", description: "<p>Begins the dance of faraway dreams and springs that hear, causing a Lotus of Distant Waters to bloom, dealing AoE Hydro DMG based on Nilou's Max HP and applying the Lingering Aeon effect to all opponents hit. After an interval, opponents affected by Lingering Aeon will take Hydro DMG.</p><p><i>\"We have never witnessed that distant dream, but this dance can bring it to life.\"</i></p>" },
  "nilou_dreamy_dance_of_aeons": { title: "Dreamy Dance of Aeons", description: "Every 1,000 points of Nilou's Max HP above 30,000 will cause the DMG dealt by Bountiful Cores created by characters affected by Golden Chalice's Bounty to increase by 9%. The maximum increase in Bountiful Core DMG that can be achieved this way is 400%." },
  "nilou_fricative_pulse": { title: "Fricative Pulse", description: "After the third dance step of Dance of Haftkarsvar's Pirouette hits opponents, Nilou will gain 15 Elemental Energy, and DMG from her Dance of Abzendegi: Distant Dreams, Listening Spring will be increased by {dmg_burst} for 8s." },
  "nilou_frostbreakers_melody": { title: "Frostbreaker's Melody", description: "For every 1,000 points of Max HP, Nilou's CRIT Rate and CRIT DMG will increase by {text_percent_rate} and {text_percent_dmg} respectively. The maximum increase in CRIT Rate and CRIT DMG via this method is {text_percent_rate_max} and {text_percent_dmg_max} respectively." },
  "nilou_the_starry_skies_their_flowers_rain": { title: "The Starry Skies Their Flowers Rain" },
  "nilou_the_starry_skies_their_flowers_rain_1": { title: "The Starry Skies Their Flowers Rain (Hydro)", description: "After characters affected by the Golden Chalice's Bounty deal Hydro DMG to an opponent, that opponent's Hydro RES will be decreased by {enemy_res_hydro} for 10s." },
  "nilou_the_starry_skies_their_flowers_rain_2": { title: "The Starry Skies Their Flowers Rain (Dendro)", description: "After a triggered Bloom reaction deals DMG to opponents, their Dendro RES will be decreased by {enemy_res_dendro} for 10s. You need to have unlocked the \"Court of Dancing Petals\" Talent." },
  "nilou_twirling_light": { title: "Twirling Light" },
  "ningguang_backup_plan": { title: "Backup Plan", description: "When Ningguang is in possession of Star Jades, her Charged Attack does not consume Stamina." },
  "ningguang_exquisite_be_the_jade_outshining_all_beneath": { title: "Exquisite be the Jade, Outshining All Beneath", description: "Jade Screen increases nearby characters' Elemental RES by {res_anemo}." },
  "ningguang_grandeur_be_the_seven_stars": { title: "Grandeur Be the Seven Stars", description: "When Starshatter is used, Ningguang gains 7 Star Jades." },
  "ningguang_invincible_be_the_jade_screen": { title: "Invincible Be the Jade Screen" },
  "ningguang_jade_screen": { title: "Jade Screen", description: "<p>Ningguang creates a Jade Screen out of gold, obsidian, and her great opulence, dealing AoE Geo DMG.</p><p>Jade Screen ·Blocks opponents' projectiles. ·Endurance scales based on Ningguang's Max HP.</p><p>Jade Screen is considered a Geo Construct and can be used to block certain attacks, but cannot be climbed. Only one Jade Screen may exist at any one time.</p><p><i>The canvas of stars is written upon this jade screen.</i></p>" },
  "ningguang_majesty_be_the_array_of_stars": { title: "Majesty Be the Array of Stars" },
  "ningguang_piercing_fragments": { title: "Piercing Fragments", description: "When a Normal Attack hits, it deals AoE DMG." },
  "ningguang_shock_effect": { title: "Shock Effect", description: "When Jade Screen is shattered, its CD will reset. Can occur once every 6s." },
  "ningguang_sparkling_scatter": { title: "Sparkling Scatter", description: "<p>Normal Attack Shoots gems that deal Geo DMG. Upon hit, this grants Ningguang 1 Star Jade.</p><p>Charged Attack Consumes a certain amount of stamina to fire off a giant gem that deals Geo DMG. If Ningguang has any Star Jades, unleashing a Charged Attack will cause the Star Jades to be fired at the enemy as well, dealing additional DMG.</p><p>Plunging Attack Gathering the might of Geo, Ningguang plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Geo DMG upon impact with the ground.</p>" },
  "ningguang_starshatter": { title: "Starshatter", description: "<p>Gathering a great number of gems, Ningguang scatters them all at once, sending homing projectiles at her opponents that deal massive Geo DMG. If Starshatter is cast when a Jade Screen is nearby, the Jade Screen will fire additional gem projectiles at the same time.</p><p><i>Stars shatter. Silence falls.</i></p>" },
  "ningguang_strategic_reserve": { title: "Strategic Reserve", description: "A character that passes through the Jade Screen will gain a {dmg_geo} Geo DMG Bonus for 10s." },
  "noelle_breastplate": { title: "Breastplate", description: "<p>Summons protective stone armor, dealing Geo DMG to surrounding opponents and creating a shield. The shield's DMG Absorption scales based on Noelle's DEF. The shield has the following properties: ·When Noelle's Normal and Charged Attacks hit a target, they have a certain chance to regenerate HP for all characters. ·Possesses 150% DMG Absorption efficiency against all Elemental and Physical DMG.</p><p>The amount of HP healed when regeneration is triggered scales based on Noelle's DEF.</p><p><i>Noelle is both a dutiful maid and a valiant knight.</i></p>" },
  "noelle_combat_maid": { title: "Combat Maid", description: "Decreases the Stamina Consumption of Noelle's Charged Attacks by {stamina_consume_charged} and increases her Charged Attack DMG by {dmg_charged}." },
  "noelle_devotion": { title: "Devotion", description: "When Noelle is in the party but not on the field, this ability triggers automatically when your active character's HP falls below 30%: Creates a shield for your active character that lasts for 20s and absorbs DMG equal to {text_percent} of Noelle's DEF. The shield has a 150% DMG Absorption effectiveness against all Elemental and Physical DMG. This effect can only occur once every 60s." },
  "noelle_favonius_bladework_maid": { title: "Favonius Bladework - Maid", description: "<p>Normal Attack Performs up to 4 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous spinning attacks against all nearby opponents. At the end of the sequence, performs a more powerful slash. </p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "noelle_favonius_sweeper_master": { title: "Favonius Sweeper Master" },
  "noelle_i_got_your_back": { title: "I Got Your Back", description: "While Sweeping Time and Breastplate are both in effect, the chance of Breastplate's healing effects activating is increased to 100%." },
  "noelle_invulnerable_maid": { title: "Invulnerable Maid" },
  "noelle_must_be_spotless": { title: "Must Be Spotless", description: "Sweeping Time increases Noelle's ATK by an additional {text_percent_dmg} of her DEF. Additionally, every opponent defeated during the skill's duration adds 1s to the duration, up to 10s." },
  "noelle_nice_and_clean": { title: "Nice and Clean", description: "Noelle will decrease the CD of Breastplate by 1s for every 4 Normal or Charged Attack hits she scores on opponents. One hit may be counted every 0.1s." },
  "noelle_sweeping_time": { title: "Sweeping Time", description: "<p>Gathering the strength of stone around her weapon, Noelle strikes the opponents surrounding her within a large AoE, dealing Geo DMG. Afterwards, Noelle gains the following effects: ·Larger attack AoE. ·Converts attack DMG to Geo DMG that cannot be overridden by any other elemental infusion. ·Increased ATK that scales based on her DEF.</p><p><i>Sometimes, it's not just dust that needs sweeping...</i></p>" },
  "noelle_sweeping_time_talent": { description: "Noelle gains the following effects: • Larger attack AoE • Converts attack DMG to Geo DMG that cannot be overridden by any other elemental infusion. • Increased ATK that scales based on her DEF." },
  "noelle_to_be_cleaned": { title: "To Be Cleaned", description: "When Breastplate's duration expires or it is destroyed by DMG, it will deal {text_percent_dmg} of Noelle's ATK as Geo DMG to surrounding opponents." },
  "only_full_party_resonance": { title: "Disable resonance" },
  "only_full_party_resonances": { description: "Does not apply Elemental resonance bonuses while party is not full." },
  "ororon_a_gift_for_the_soul": { title: "A Gift For the Soul" },
  "ororon_as_the_mysteries_of_the_night_wind": { title: "As the Mysteries of the Night Wind", description: "The Supersonic Oculus summoned by the Elemental Burst Dark Voices Echo rotates 25% faster. Additionally, Ororon will restore 8 Energy to himself after using Dark Voices Echo." },
  "ororon_aspect_catalyst": { title: "Aspect Catalyst", description: "When a nearby active party member hits an opponent with Normal, Charged, or Plunging Attacks, that character will restore 3 Energy. If Ororon is off-field, Ororon will also restore 3 Energy. This effect can trigger once every 1s, and can trigger 3 times per duration." },
  "ororon_dark_voices_echo": { title: "Dark Voices Echo", description: "<p>Ororon works an ancient ritual, dealing Nightsoul-aligned AoE Electro DMG, summoning forth a Supersonic Oculus.</p><p>Supersonic Oculus ·Continuously taunts nearby opponents and attracts attacks from them. ·Continuously rotates and fires off sonic waves that deal Nightsoul-aligned Electro DMG.</p><p><i>Those with sharp enough senses can hear the minute voices with which all things speak. That way, they will never lose their way — not even on long, lightless nights.</i></p>" },
  "ororon_king_bee_of_the_hidden_honeyed_wine": { title: "King Bee of the Hidden Honeyed Wine" },
  "ororon_king_bee_of_the_hidden_honeyed_wine_1": { description: "After using his Elemental Burst, Dark Voices Echo, Ororon will obtain the Spiritual Supersense effect for 9s." },
  "ororon_king_bee_of_the_hidden_honeyed_wine_2": { description: "Gain {dmg_electro} Electro DMG Bonus. Additionally, during this time, every additional opponent hit by the Elemental Burst Dark Voices Echo or Supersonic Oculus will grant Ororon a further {dmg_electro} Electro DMG Bonus. The maximum that can be gained this way is {text_percent_max} Electro DMG Bonus." },
  "ororon_nights_sling": { title: "Night's Sling", description: "<p>Ororon manifests an ancient mystical technique from the Masters of the Night-Wind as a Spirit Orb of midnight shade and throws it at his foe, dealing Nightsoul-aligned Electro DMG. When other opponents are nearby, the Spirit Orb will bounce between them, dealing Nightsoul-aligned Electro DMG. Each time Night's Sling is used, each opponent can only be selected as a target once. After 3 bounces, or if there are no eligible targets left, the Orb will disappear.</p><p><i>\"People always wish to foretell the future, but that might be because they have yet to discover that which they must do... Sorry, I'm saying complicated things again, aren't I...\"</i></p>" },
  "ororon_nightshade_synesthesia": { title: "Nightshade Synesthesia" },
  "ororon_nightshade_synesthesia_1": { description: "After a nearby party member triggers Nightsoul Burst, Ororon will gain 40 Nightsoul points. Within 15s after using his Elemental Skill, when other party members' Hydro or Electro attacks hit opponents, Ororon will gain 5 Nightsoul points, an effect that can occur every 0.3s for a maximum of 10 times during this 15s duration. Ororon can have a maximum of 80 Nightsoul points." },
  "ororon_nightshade_synesthesia_2": { description: "Also, when nearby opponents take Electro-Charged or Lunar-Charged reaction DMG or Nightsoul-aligned DMG dealt by other nearby characters, Ororon will consume 10 Nightsoul points (provided he has at least that amount), entering the Nightsoul's Blessing state and triggering the Hypersense effect: Deal Nightsoul-aligned Electro DMG based on {text_percent_dmg} of Ororon's ATK to at most 4 nearby opponents. The aforementioned effect can trigger once every 1.8s." },
  "ororon_ode_to_deep_springs": { title: "Ode to Deep Springs" },
  "ororon_ode_to_deep_springs_1": { description: "After triggering Hypersense through the Passive Talent, Nightshade Synesthesia, your current active character's ATK is increased by {atk_percent} for 9s. Max 3 stacks, each stack is counted independently." },
  "ororon_ode_to_deep_springs_2": { description: "Additionally, when you use the Elemental Burst Dark Voices Echo, you will trigger one instance of an effect equivalent to Hypersense, dealing {text_percent_dmg} of its original DMG. You must unlock the Passive Talent \"Nightshade Synesthesia\" first." },
  "ororon_roosting_bats_spiritcage": { title: "Roosting Bat's Spiritcage" },
  "ororon_special_jump": { title: "Special Jump", description: "<p>If this character is in Natlan, Hold to consume Phlogiston and execute a Rocket Double Jump. When Phlogiston is completely depleted, it will consume Stamina to execute the Double Jump instead.</p>" },
  "ororon_spiritvessel_snapshot": { title: "Spiritvessel Snapshot", description: "<p>Normal Attack Performs up to 3 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, Electro energy will accumulate on the arrowhead. A fully charged arrow will deal Electro DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "ororon_trails_amidst_the_forest_fog": { title: "Trails Amidst the Forest Fog", description: "The Elemental Skill Night's Sling's Spirit Orb can bounce 2 additional times. Additionally, after the Spirit Orb hits an opponent, it will apply the Nighttide effect to them for 12s. Opponents affected by Nighttide take {dmg_skill_ororon} increased DMG from Hypersense triggered by the Passive Talent, \"Nightshade Synesthesia.\" Unlock the aforementioned Passive Talent to trigger this effect." },
  "party_max_mastery": { title: "Party members Max EM" },
  "primordial_jade_winged_spear": { title: "Eagle Spear of Justice" },
  "primordial_jade_winged_spear_1": { description: "On hit, increases ATK by {atk_percent} for 6s. Max 7 stacks. This effect can only occur once every 0.3s." },
  "primordial_jade_winged_spear_2": { description: "While in possession of the maximum possible stacks, DMG dealt is increased by {dmg_all}." },
  "prototype_starglitter": { title: "Magic Affinity", description: "After using an Elemental Skill, increases Normal and Charged Attack DMG by {dmg_normal} for 12s. Max 2 stacks." },
  "qiqi_a_glimpse_into_arcanum": { title: "A Glimpse Into Arcanum", description: "When Qiqi hits opponents with her Normal and Charged Attacks, she has a 50% chance to apply a Fortune-Preserving Talisman to them for 6s. This effect can only occur once every 30s." },
  "qiqi_ancient_sword_art": { title: "Ancient Sword Art", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "qiqi_ascendant_praise": { title: "Ascendant Praise" },
  "qiqi_ascetics_of_frost": { title: "Ascetics of Frost", description: "When the Herald of Frost hits an opponent marked by a Fortune-Preserving Talisman, Qiqi regenerates 2 Energy." },
  "qiqi_crimson_lotus_bloom": { title: "Crimson Lotus Bloom" },
  "qiqi_divine_suppression": { title: "Divine Suppression", description: "Targets marked by the Fortune-Preserving Talisman have their ATK decreased by 20%." },
  "qiqi_frozen_to_the_bone": { title: "Frozen to the Bone", description: "Qiqi's Normal and Charged Attack DMG against opponents affected by Cryo is increased by {dmg_normal}." },
  "qiqi_herald_of_frost": { title: "Adeptus Art: Herald of Frost", description: "<p>Using the Icevein Talisman, Qiqi brings forth the Herald of Frost, dealing Cryo DMG to surrounding opponents.</p><p>Herald of Frost ·On hit, Qiqi's Normal and Charged Attacks regenerate HP for your own party members and nearby teammates. Healing scales based on Qiqi's ATK. ·Periodically regenerates your active character's HP. ·Follows the character around, dealing Cryo DMG to opponents in their path.</p><p><i>I use this to prevent warming and rot... of Dr. Bai's precious ingredients. Yes.</i></p>" },
  "qiqi_life_prolonging_methods": { title: "Life-Prolonging Methods", description: "When a character under the effects of Adeptus Art: Herald of Frost triggers an Elemental Reaction, their Incoming Healing Bonus is increased by {healing_recv} for 8s." },
  "qiqi_preserver_of_fortune": { title: "Adeptus Art: Preserver of Fortune", description: "<p>Qiqi releases the adeptus power sealed within her body, marking nearby opponents with a Fortune-Preserving Talisman that deals Cryo DMG.</p><p>Fortune-Preserving Talisman When opponents affected by this Talisman take DMG, the character that dealt this DMG regenerates HP.</p><p><i>\"I am the Fortune Preserver, the Maiden of Resurrection.\"</i> <i>— Qiqi does not remember these words.</i></p>" },
  "qiqi_rite_of_resurrection": { title: "Rite of Resurrection", description: "Using Adeptus Art: Preserver of Fortune revives all fallen party members nearby and regenerates 50% of their HP. This effect can only occur once every 15 mins." },
  "raiden_shogun_baleful_omen": { title: "Transcendence: Baleful Omen", description: "<p>The Raiden Shogun unveils a shard of her Euthymia, dealing Electro DMG to nearby opponents, and granting nearby party members the Eye of Stormy Judgment.</p><p>Eye of Stormy Judgment ·When characters with this buff attack and deal DMG to opponents, the Eye will unleash a coordinated attack, dealing AoE Electro DMG at the opponent's position. ·Characters who gain the Eye of Stormy Judgment will have their Elemental Burst DMG increased based on the Energy Cost of the Elemental Burst during the Eye's duration.</p><p>The Eye can initiate one coordinated attack every 0.9s per party. Coordinated attacks generated by characters not controlled by you deal 20% of the normal DMG.</p><p><i>Beings of great divinity might affect all that they survey, and the Electro Archon can manipulate the very inauspicious stars themselves to defend her retainers and bring a thundering sentence down on their foes.</i></p>" },
  "raiden_shogun_enlightened_one": { title: "Enlightened One", description: "Each 1% above 100% Energy Recharge that the Raiden Shogun possesses grants her: ·0.6% greater Energy restoration from Musou Isshin ·0.4% Electro DMG Bonus." },
  "raiden_shogun_musou_shinsetsu": { title: "Secret Art: Musou Shinsetsu", description: "<p>Gathering truths unnumbered and wishes uncounted, the Raiden Shogun unleashes the Musou no Hitotachi and deals AoE Electro DMG, using Musou Isshin in combat for a certain duration afterward. The DMG dealt by Musou no Hitotachi and Musou Isshin's attacks will be increased based on the number of Chakra Desiderata's Resolve stacks consumed when this skill is used.</p><p>Musou Isshin While in this state, the Raiden Shogun will wield her tachi in battle, while her Normal, Charged, and Plunging Attacks will be infused with Electro DMG, which cannot be overridden. When such attacks hit opponents, she will regenerate Energy for all nearby party members. Energy can be restored this way once every 1s, and this effect can be triggered 5 times throughout this skill's duration. While in this state, the Raiden Shogun's resistance to interruption is increased, and she is immune to Electro-Charged reaction DMG. While Musou Isshin is active, the Raiden Shogun's Normal, Charged, and Plunging Attack DMG will be considered Elemental Burst DMG.</p><p>The effects of Musou Isshin will be cleared when the Raiden Shogun leaves the field.</p><p>Chakra Desiderata When nearby party members (excluding the Raiden Shogun herself) use their Elemental Bursts, the Raiden Shogun will build up Resolve stacks based on the Energy Cost of these Elemental Bursts. The maximum number of Resolve stacks is 60.</p><p>The Resolve gained by Chakra Desiderata will be cleared 300s after the Raiden Shogun leaves the field.</p><p><i>This is the Raiden Shogun's new secret technique. Abandoning the void-like \"Musou,\" she now shoulders a new \"Musou\" — the dreams and ambitions of all. Just as \"shinsetsu,\" \"the truth,\" also means \"the new,\" so too has Inazuma entered a new chapter.</i></p>" },
  "raiden_shogun_ominous_inscription": { title: "Ominous Inscription", description: "Chakra Desiderata will gather Resolve even faster. When Electro characters use their Elemental Bursts, the Resolve gained is increased by 80%. When characters of other Elemental Types use their Elemental Bursts, the Resolve gained is increased by 20%." },
  "raiden_shogun_origin": { title: "Origin", description: "<p>Normal Attack Performs up to 5 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to perform an upward slash.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "raiden_shogun_pledge_of_propriety": { title: "Pledge of Propriety", description: "When the Musou Isshin state applied by Secret Art: Musou Shinsetsu expires, all nearby party members (excluding the Raiden Shogun) gain {text_percent} bonus ATK for 10s." },
  "raiden_shogun_shinkage_bygones": { title: "Shinkage Bygones" },
  "raiden_shogun_shoguns_descent": { title: "Shogun's Descent" },
  "raiden_shogun_steelbreaker": { title: "Steelbreaker", description: "While using Musou no Hitotachi and in the Musou Isshin state applied by Secret Art: Musou Shinsetsu, the Raiden Shogun's attacks ignore {enemy_def_ignore_burst} of opponents' DEF." },
  "raiden_shogun_wishbearer": { title: "Wishbearer", description: "While in the Musou Isshin state applied by Secret Art: Musou Shinsetsu, attacks by the Raiden Shogun that are considered part of her Elemental Burst will decrease all nearby party members' (not including the Raiden Shogun herself) Elemental Burst CD by 1s when they hit opponents. This effect can trigger once every 1s and can trigger a total of 5 times during Musou Isshin's duration." },
  "raiden_shogun_wishes_unnumbered": { title: "Wishes Unnumbered", description: "When nearby party members gain Elemental Orbs or Particles, Chakra Desiderata gains 2 Resolve stacks. This effect can occur once every 3s." },
  "razor_awakening": { title: "Awakening", description: "Decreases Claw and Thunder's CD by {text_percent_cd}. Using Lightning Fang resets the CD of Claw and Thunder." },
  "razor_bite": { title: "Bite", description: "When casting Claw and Thunder (Press), opponents hit will have their DEF decreased by {enemy_def_reduce} for 7s." },
  "razor_claw_and_thunder": { title: "Claw and Thunder", description: "<p>Hunts his prey using the techniques taught to him by his master and his lupical.</p><p>Press Swings the Thunder Wolf Claw, dealing Electro DMG to opponents in front of Razor. Upon striking an opponent, Razor will gain an Electro Sigil, which increases his Energy Recharge rate. Razor can have up to 3 Electro Sigils simultaneously, and gaining a new Electro Sigil refreshes their duration.</p><p>Hold Gathers Electro energy to unleash a lightning storm over a small AoE, causing massive Electro DMG, and clears all of Razor's Electro Sigils. Each Electro Sigil cleared in this manner will be converted into Energy for Razor.</p><p><i>In the moment when lightning strikes, you can sometimes glimpse the look of a predator sizing up his prey deep within Razor's eyes.</i></p>" },
  "razor_claw_and_thunder_talent": { description: "Swings the Thunder Wolf Claw, dealing Electro DMG to opponents in front of Razor. Upon striking an opponent, nmame{Razor} gains an Electro Sigil, which increases his Energy Recharge rate. Razor can have up to 3 Electro Sigils simultaneously, and gaining a new Electro Sigil refreshes their duration." },
  "razor_hunger": { title: "Hunger", description: "When Razor's Energy is below {recharge}, increases Energy Recharge by {text_percent}." },
  "razor_lightning_fang": { title: "Lightning Fang", description: "<p>Summons the Wolf Within, which deals Electro DMG to all nearby opponents. This clears all of Razor's Electro Sigils, which will be converted into Elemental Energy for him. The Wolf Within will fight alongside Razor for the skill's duration.</p><p>The Wolf Within ·Strikes alongside Razor's normal attacks, dealing Electro DMG. ·Raises Razor's ATK SPD and Electro RES. ·Causes Razor to be immune to DMG inflicted by the Electro-Charged status. ·Disables Razor's Charged Attacks. ·Increases Razor's resistance to interruption.</p><p>These effects end when Razor leaves the battlefield. When Razor leaves the field, a maximum of 10 Energy will be returned to him based off the duration remaining on this skill.</p><p><i>The wolf has awoken. The hunt is on.</i></p>" },
  "razor_lupus_fulguris": { title: "Lupus Fulguris", description: "Every 10s, Razor's sword charges up, causing the next Normal Attack to release lightning that deals {text_percent_dmg} of Razor's ATK as Electro DMG. When Razor is not using Lightning Fang, a lightning strike on an opponent will grant Razor an Electro Sigil for Claw and Thunder." },
  "razor_sharpened_claws": { title: "Sharpened Claws" },
  "razor_soul_companion": { title: "Soul Companion" },
  "razor_steel_fang": { title: "Steel Fang", description: "<p>Normal Attack Performs up to 4 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous spinning attacks against all nearby opponents. At the end of the sequence, performs a more powerful slash. </p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "razor_suppression": { title: "Suppression", description: "Increases CRIT Rate against opponents with less than {text_percent_hp} HP by {crit_rate_enemy}." },
  "razor_wolf_within": { title: "The Wolf Within", description: "• Strikes alongside Razor's normal attacks, dealing Electro DMG. • Raises Razor's ATK SPD and Electro RES. • Disables Razor's Charged Attacks." },
  "razor_wolfs_instinct": { title: "Wolf's Instinct", description: "Picking up an Elemental Orb or Particle increases Razor's DMG by {dmg_all} for 8s." },
  "resonance_anemo": { title: "Impetuous Winds", description: "Decreases Stamina Consumption by {stamina_consume}. Increases Movement SPD by {move_speed}. Shortens Skill CD by {recovery}." },
  "resonance_cryo": { title: "Shattering Ice", description: "Affected by Electro for {text_percent} less time." },
  "resonance_cryo_status": { title: "Enemy affected by Cryo", description: "Increases CRIT Rate against enemies that are Frozen or affected by Cryo by {crit_rate_enemy}." },
  "resonance_dendro": { title: "Sprawling Greenery" },
  "resonance_dendro_1": { description: "Elemental Mastery increased by {mastery}." },
  "resonance_dendro_2": { description: "After triggering Burning, Quicken, or Bloom reactions, all nearby party members gain {mastery} Elemental Mastery for 6s. The durations of the aforementioned effects will be counted independently." },
  "resonance_dendro_3": { description: "After triggering Aggravate, Spread, Hyperbloom, or dendrp{Burgeon} reactions, all nearby party members gain {mastery} Elemental Mastery for 6s. The durations of the aforementioned effects will be counted independently." },
  "resonance_electro": { title: "High Voltage", description: "Affected by Hydro for {text_percent_1} less time. Superconduct, Overloaded, Electro-Charged, Quicken, Aggravate, or Hyperbloom have a {text_percent_2} chance to generate an Electro Elemental Particle (CD: 5s)." },
  "resonance_geo": { title: "Enduring Rock", description: "Increases shield strength by {shield}." },
  "resonance_geo_attack": { title: "Deal damage to enemy", description: "Dealing DMG to enemies will decrease their Geo RES by {text_percent} for 15s." },
  "resonance_geo_shield": { title: "Character protected by a shield", description: "Characters protected by a shield will have DMG dealt increased by {dmg_all}." },
  "resonance_hydro": { title: "Soothing Water", description: "Affected by Pyro for {text_percent} less time. Increases max HP by {hp_percent}." },
  "resonance_none": { title: "Protective Canopy", description: "All Elemental RES +15%, Physical RES +15%." },
  "resonance_pyro": { title: "Fervent Flames", description: "Affected by Cryo for {text_percent} less time. Increases ATK by {atk_percent}." },
  "rosaria_divine_retribution": { title: "Divine Retribution", description: "Rites of Termination's attack decreases opponents' Physical RES by {enemy_res_phys} for 10s." },
  "rosaria_land_without_promise": { title: "Land Without Promise", description: "The duration of the Ice Lance created by Rites of Termination is increased by 4s." },
  "rosaria_last_rites": { title: "Last Rites" },
  "rosaria_painful_grace": { title: "Painful Grace", description: "Ravaging Confession's CRIT Hits regenerate 5 Energy for Rosaria. Can only be triggered once each time Ravaging Confession is cast." },
  "rosaria_ravaging_confession": { title: "Ravaging Confession", description: "<p>Rosaria swiftly shifts her position to appear behind her opponent, then stabs and slashes them with her polearm, dealing Cryo DMG. This ability cannot be used to travel behind opponents of a larger build.</p><p><i>Those who confess to Sister Rosaria will be granted no absolution. All sinners shall be met with the piercing cold of punishment proportionate to the weight of their sins.</i></p>" },
  "rosaria_regina_probationum": { title: "Regina Probationum", description: "When Rosaria strikes an opponent from behind using Ravaging Confession, Rosaria's CRIT Rate increases by {crit_rate} for 5s." },
  "rosaria_rites_of_termination": { title: "Rites of Termination", description: "<p>Rosaria's unique take on this prayer ritual: First, she swings her weapon to slash surrounding opponents; then, she summons a frigid Ice Lance that strikes the ground. Both actions deal Cryo DMG. While active, the Ice Lance periodically releases a blast of cold air, dealing Cryo DMG to surrounding opponents.</p><p><i>Judgment is such a tedious ordeal — much easier to skip that phase and get straight to the last rites. Rosaria was never very devoted to the Anemo God anyway, which makes performing them all too easy.</i></p>" },
  "rosaria_shadow_samaritan": { title: "Shadow Samaritan", description: "Casting Rites of Termination increases CRIT Rate of all nearby party members (except Rosaria herself) by {text_percent} of Rosaria's CRIT Rate for 10s. CRIT Rate Bonus gained this way cannot exceed {text_percent}." },
  "rosaria_spear_of_the_church": { title: "Spear of the Church", description: "<p>Normal Attack Performs up to 5 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "rosaria_the_wages_of_sin": { title: "The Wages of Sin" },
  "rosaria_unholy_revelation": { title: "Unholy Revelation", description: "When Rosaria deals a CRIT Hit, her ATK SPD increases by {atk_speed_normal} and her Normal Attack DMG increases by {dmg_normal} for 4s." },
  "sangonomiya_kokomi_all_streams_flow_to_the_sea": { title: "All Streams Flow to the Sea" },
  "sangonomiya_kokomi_at_waters_edge": { title: "At Water's Edge", description: "While donning the Ceremonial Garment created by Nereid's Ascension, the final Normal Attack in Sangonomiya Kokomi's combo will unleash a swimming fish to deal {text_percent_dmg} of her Max HP as Hydro DMG. This DMG is not considered Normal Attack DMG." },
  "sangonomiya_kokomi_kurages_oath": { title: "Kurage's Oath", description: "<p>Summons a \"Bake-Kurage\" created from water that can heal her allies. Using this skill will apply the Wet status to Sangonomiya Kokomi.</p><p>Bake-Kurage Deals Hydro DMG to surrounding opponents and heals nearby active characters at fixed intervals. This healing is based on Kokomi's Max HP.</p><p><i>Kokomi needs timely \"refreshment\" in order to maintain optimal work efficiency</i>.</p>" },
  "sangonomiya_kokomi_nereids_ascension": { title: "Nereid's Ascension", description: "<p>Summons the might of Watatsumi, dealing Hydro DMG to surrounding opponents, before robing Kokomi in a Ceremonial Garment made from the flowing waters of Sangonomiya.</p><p>Ceremonial Garment ·Sangonomiya Kokomi's Normal Attack, Charged Attack and Bake-Kurage DMG are increased based on her Max HP. ·When her Normal and Charged Attacks hit opponents, Kokomi will restore HP for all nearby party members, and the amount restored is based on her Max HP. ·Increases Sangonomiya Kokomi's resistance to interruption and allows her to walk on the water's surface.</p><p>These effects will be cleared once Sangonomiya Kokomi leaves the field.</p><p><i>Clear light coalesces into robes around Her Excellency, Sangonomiya Kokomi, reflecting her magnificent form.</i></p>" },
  "sangonomiya_kokomi_sango_isshin": { title: "Sango Isshin", description: "While donning the Ceremonial Garment created by Nereid's Ascension, Sangonomiya Kokomi gains a {dmg_hydro} Hydro DMG Bonus for 4s when her Normal and Charged Attacks heal, or would heal, any party member with 80% or more HP." },
  "sangonomiya_kokomi_song_of_pearls": { title: "Song of Pearls", description: "While donning the Ceremonial Garment created by Nereid's Ascension, the Normal and Charged Attack DMG Bonus Sangonomiya Kokomi gains based on her Max HP will receive a further increase based on {text_percent} of her Healing Bonus." },
  "sangonomiya_kokomi_tamakushi_casket": { title: "Tamakushi Casket", description: "If Sangonomiya Kokomi's own Bake-Kurage is on the field when she uses Nereid's Ascension, the Bake-Kurage's duration will be refreshed." },
  "sangonomiya_kokomi_the_clouds_like_waves_rippling": { title: "The Clouds Like Waves Rippling", description: "Sangonomiya Kokomi gains the following Healing Bonuses with regard to characters with 50% or less HP via the following methods: ·Kurage's Oath Bake-Kurage: {text_percent_1} of Kokomi's Max HP. ·Nereid's Ascension Normal and Charged Attacks: {text_percent_2} of Kokomi's Max HP." },
  "sangonomiya_kokomi_the_moon_a_ship_oer_the_seas": { title: "The Moon, A Ship O'er the Seas" },
  "sangonomiya_kokomi_the_moon_overlooks_the_waters": { title: "The Moon Overlooks the Waters", description: "While donning the Ceremonial Garment created by Nereid's Ascension, Sangonomiya Kokomi's Normal Attack SPD is increased by {atk_speed_normal}, and Normal Attacks that hit opponents will restore 0.8 Energy for her. This effect can occur once every 0.2s." },
  "sangonomiya_kokomi_the_shape_of_water": { title: "The Shape of Water", description: "<p>Normal Attack Performs up to 3 consecutive attacks that take the form of swimming fish, dealing Hydro DMG.</p><p>Charged Attack Consumes a certain amount of Stamina to deal AoE Hydro DMG after a short casting time.</p><p>Plunging Attack Gathering the might of Hydro, Kokomi plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Hydro DMG upon impact with the ground.</p>" },
  "sara_tengu_juurai": { title: "Tengu Juurai", description: "Grants the active character within its AoE an ATK Bonus based on Kujou Sara's Base ATK." },
  "sayu_egress_prep": { title: "Egress Prep", description: "Yoohoo Art: Fuuin Dash gains the following effects: ·DMG of Fuufuu Whirlwind Kick in Press Mode increased by {dmg_skill_sayu_hold}. ·Every 0.5s in the Fuufuu Windwheel state will increase the DMG of this Fuufuu Whirlwind Kick by {dmg_skill_sayu_hold}. The maximum DMG increase possible through this method is 66%." },
  "sayu_eh_the_bunshin_can_handle_it": { title: "Eh, the Bunshin Can Handle It" },
  "sayu_fuuin_dash": { title: "Yoohoo Art: Fuuin Dash", description: "<p>The special technique of the Yoohoo Ninja Arts! Sayu curls up into a rolling Fuufuu Windwheel and smashes into opponents at high speed, dealing Anemo DMG. When the duration ends, she unleashes a Fuufuu Whirlwind Kick, dealing AoE Anemo DMG.</p><p>Press Enters the Fuufuu Windwheel state, rolling forward a short distance before using the Fuufuu Whirlwind Kick.</p><p>Hold Rolls about continuously in the Fuufuu Windwheel state, increasing Sayu's resistance to interruption while within that state. During this time, Sayu can control the direction of her roll, and can use the skill again to end her Windwheel state early and unleash a stronger version of the Fuufuu Whirlwind Kick. The Hold version of this skill can trigger Elemental Absorption.</p><p>This skill has a maximum duration of 10s and enters CD once its effects end. The longer Sayu remains in her Windwheel state, the longer the CD.</p><p>Elemental Absorption If Sayu comes into contact with Hydro/Pyro/Cryo/Electro while in her Windwheel state, she will deal additional elemental DMG of that type. Elemental Absorption may only occur once per use of this skill.</p><p><i>Sayu can pull this skill off with her eyes closed. This technique was originally created for escaping, but now that she's got a Vision, might as well make her foes eat dirt while she's at it.</i></p>" },
  "sayu_mujina_flurry": { title: "Yoohoo Art: Mujina Flurry", description: "<p>The other super special technique of the Yoohoo Ninja Arts! It summons a pair of helping hands for Sayu. Deals Anemo DMG to nearby opponents and heals all nearby party members. The amount of HP restored is based on Sayu's ATK. This skill then summons a Muji-Muji Daruma.</p><p>Muji-Muji Daruma At specific intervals, the Daruma will take one of several actions based on the situation around it: ·If the HP of nearby characters is above 70%, it will attack a nearby opponent, dealing Anemo DMG. ·If there are active characters with 70% or less HP nearby, it will heal the active character with the lowest percentage HP left. If there are no opponents nearby, it will heal active characters nearby even if they have 70% HP or more.</p><p><i>People who don't know the first thing about ninjutsu love to watch Sayu show off this skill, and some have tried to learn it from her. But Sayu just wants to sleep and not be disturbed.</i></p>" },
  "sayu_multi_task_no_jutsu": { title: "Multi-Task no Jutsu", description: "The Muji-Muji Daruma created by Yoohoo Art: Mujina Flurry will ignore HP limits and can simultaneously attack nearby opponents and heal characters." },
  "sayu_new_and_improved": { title: "Skiving: New and Improved", description: "Sayu recovers 1.2 Energy when she triggers a Swirl reaction. This effect occurs once every 2s." },
  "sayu_no_work_today": { title: "No Work Today!", description: "The Muji-Muji Daruma created by Yoohoo Art: Mujina Flurry gains the following effects: ·When healing a character, it will also heal characters near that healed character for {text_percent_hp} the amount of HP. ·Increases the AoE of its attack against opponents." },
  "sayu_shuumatsuban_ninja_blade": { title: "Shuumatsuban Ninja Blade", description: "<p>Normal Attack Performs up to 4 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous spinning attacks against all nearby opponents. At the end of the sequence, performs a more powerful slash. </p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "sayu_sleep_oclock": { title: "Sleep O'Clock", description: "The Muji-Muji Daruma created by Sayu's Yoohoo Art: Mujina Flurry will now also benefit from her Elemental Mastery. Each point of Sayu's Elemental Mastery will produce the following effects: ·Increases the damage dealt by the Muji-Muji Daruma's attacks by 0.2% ATK. A maximum DMG increase of 400% ATK can be gained via this method. ·Increases the HP restored by the Muji-Muji Daruma by 3. A maximum of 6,000 additional HP can be restored in this manner." },
  "sayu_someone_more_capable": { title: "Someone More Capable", description: "When Sayu triggers a Swirl reaction while active, she heals all your characters and nearby allies for {text_value} HP. She will also heal an additional {text_value_hp} HP for every point of Elemental Mastery she has. This effect can be triggered once every 2s." },
  "sayu_speed_comes_first": { title: "Speed Comes First" },
  "sethos_beneficent_plumage": { title: "Beneficent Plumage", description: "When a Shadowpiercing Shot or Dusk Bolt strikes 2 or more opponents, all nearby party members gain {mastery} Elemental Mastery for 10s." },
  "sethos_black_kites_enigma": { title: "Black Kite's Enigma", description: "When Aiming, the charging time is decreased by 0.285s based on each point of Sethos's current Elemental Energy. Charging time can be reduced to a minimum of 0.3s through this method and a maximum of 20 Energy can be tallied. If a Shadowpiercing Shot is fired, consume the tallied amount of Elemental Energy; if it is a Charge Level 1 shot, then consume 50% of the tallied amount of Elemental Energy." },
  "sethos_ode_to_the_moonrise_sage": { title: "Ode to the Moonrise Sage" },
  "sethos_papyrus_scripture_of_silent_secrets": { title: "Papyrus Scripture of Silent Secrets", description: "When any of the following conditions are met, Sethos gains a {dmg_electro} Electro DMG Bonus for 10s that may stack twice, with each stack duration counted independently: · Consuming Elemental Energy through Aimed Shots; you must first unlock the Passive Talent \"Black Kite's Enigma\" to trigger this condition. · Regaining Elemental Energy by triggering Elemental Reactions using Ancient Rite: The Thundering Sands. · Using Secret Rite: Twilight Shadowpiercer." },
  "sethos_pylon_of_the_sojourning_sun_temple": { title: "Pylon of the Sojourning Sun Temple", description: "After Shadowpiercing Shot strikes an opponent, the Elemental Energy consumed by the Passive Talent \"Black Kite's Enigma\" will be returned. This effect can be triggered up to once every 15s. You must first unlock the Passive Talent \"Black Kite's Enigma.\"" },
  "sethos_record_of_the_desolate_gods_burning_sands": { title: "Record of the Desolate God's Burning Sands" },
  "sethos_royal_reed_archery": { title: "Royal Reed Archery", description: "<p>Normal Attack Performs up to 3 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, the power of Electro will accumulate on the arrowhead before the arrow is fired. Has different effects based on how long the energy has been charged: ·Charge Level 1: Fires off an arrow carrying the power of lightning that deals Electro DMG. ·Charge Level 2: Fires off a Shadowpiercing Shot which can pierce enemies, dealing Electro DMG to enemies along its path. After the Shadowpiercing Shot is fully charged, Sethos cannot move around.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "sethos_sealed_shrines_spiritsong": { title: "Sealed Shrine's Spiritsong", description: "The CRIT Rate of Shadowpiercing Shot is increased by {crit_rate_sethos}." },
  "sethos_the_sand_kings_boon": { title: "The Sand King's Boon", description: "Sethos gains the \"Scorching Sandshade\" effect, increasing the DMG dealt by Shadowpiercing Shots by {text_percent} of Sethos's Elemental Mastery. The Scorching Sandshade effect will be canceled when any of the following conditions are met: · 5s after a Shadowpiercing Shot first hits an opponent. · After 4 Shadowpiercing Shots strike opponents. When a Shadowpiercing Shot affected by Scorching Sandshade first hits an opponent, Sethos will regain Scorching Sandshade after 15s." },
  "sethos_the_thundering_sands": { title: "Ancient Rite: The Thundering Sands", description: "<p>Gathers the might of thunder, dealing AoE Electro DMG and quickly retreating. If this attack triggers Electro-Charged, Lunar-Charged, Superconduct, Overloaded, Quicken, Aggravate, Hyperbloom, or Electro Swirl reactions, Sethos recovers a certain amount of Elemental Energy.</p><p><i>\"The God indwelt Priest, the Magi who turned pits to springs, the singers of the sea of sand still spread their stories... But I know those are not legends, for they are our ancestors.\"</i></p>" },
  "sethos_twilight_shadowpiercer": { title: "Secret Rite: Twilight Shadowpiercer", description: "<p>Perform a secret rite, entering the \"Twilight Meditation\" state, during which Sethos's Normal Attacks will be converted into enemy-piercing Dusk Bolts: Deal Electro DMG to opponents in its path, with DMG increased based on Sethos's Elemental Mastery. Sethos cannot perform Aimed Shots while in this state. DMG dealt by Dusk Bolts is considered Charged Attack DMG. This effect will be canceled when Sethos leaves the field.</p><p><i>The archives of the Temple of Silence preserve many tomes left behind by Akhtamun, from the era of King Deshret. Many secret rituals of great power are recorded within, but even among the Temple of Silence, very few could master them.</i></p>" },
  "shenhe_centered_spirit": { title: "Centered Spirit", description: "Divine Maiden's Deliverance lasts for 6 seconds longer. Active characters within the skill's field deals {crit_dmg_cryo} increased Cryo CRIT DMG." },
  "shenhe_clarity_of_heart": { title: "Clarity of Heart", description: "Spring Spirit Summoning can be used 1 more time." },
  "shenhe_dawnstar_piercer": { title: "Dawnstar Piercer", description: "<p>Normal Attack Performs up to 5 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "shenhe_deific_embrace": { title: "Deific Embrace", description: "An active character within the field created by Divine Maiden's Deliverance gains {dmg_cryo} Cryo DMG Bonus." },
  "shenhe_divine_attainment": { title: "Divine Attainment" },
  "shenhe_divine_maidens_deliverance": { title: "Divine Maiden's Deliverance", description: "<p>Unleashes the power of the Talisman Spirit, allowing it to roam free in this plane, dealing AoE Cryo DMG. The Talisman Spirit then creates a field that decreases the Cryo RES and Physical RES of opponents within it. It also deals periodic Cryo DMG to opponents within the field.</p><p><i>The way of the adepti is not defined only by the mysterious and fantastical. Only by observing the changes in the heavens and the earth, and understanding the laws of cause and effect in this realm, may its essence be understood.</i></p>" },
  "shenhe_icy_quill": { title: "Icy Quill", description: "When Normal, Charged, and Plunging Attacks, Elemental Skills, and Elemental Bursts deal Cryo DMG to opponents, the DMG dealt is increased based on Shenhe's current ATK." },
  "shenhe_insight": { title: "Insight", description: "When characters under the effect of Icy Quill applied by Shenhe trigger its DMG Bonus effects, Shenhe will gain a Skyfrost Mantra stack: · When Shenhe uses Spring Spirit Summoning, she will consume all stacks of Skyfrost Mantra, increasing the DMG of that Spring Spirit Summoning by 5% for each stack consumed. · Max 50 stacks. Stacks last for 60s." },
  "shenhe_mystical_abandon": { title: "Mystical Abandon", description: "When characters trigger Icy Quill's effects using Normal and Charged Attack DMG, it does not count toward the Trigger Quota." },
  "shenhe_seclusion": { title: "Seclusion" },
  "shenhe_spirit_communion_seal": { title: "Spirit Communion Seal" },
  "shenhe_spirit_communion_seal_1": { description: "After Shenhe uses Spring Spirit Summoning, she will grant all nearby party members the following effects: · Press: Elemental Skill and Elemental Burst DMG increased by {dmg_skill} for 10s." },
  "shenhe_spirit_communion_seal_2": { description: "After Shenhe uses Spring Spirit Summoning, she will grant all nearby party members the following effects: · Hold: Normal, Charged, and Plunging Attack DMG increased by {dmg_normal} for 15s." },
  "shenhe_spirit_field": { title: "Within The Talisman Spirit's Field" },
  "shenhe_spirit_seal_hold": { title: "Spirit Communion Seal (Hold)" },
  "shenhe_spirit_seal_press": { title: "Spirit Communion Seal (Press)" },
  "shenhe_spring_spirit_summoning": { title: "Spring Spirit Summoning", description: "<p>The frosted dew, silvery and dense, shall exorcise all demons. Grants all nearby party members the Icy Quill effect and deals Cryo DMG in different ways based on whether it is pressed or held.</p><p>Press Rushes forward together with a Talisman Spirit, dealing Cryo DMG to opponents along the path.</p><p>Hold Commands the Talisman Spirit to deal AoE Cryo DMG.</p><p>Icy Quill When Normal, Charged, and Plunging Attacks, Elemental Skills, and Elemental Bursts deal Cryo DMG to opponents, the DMG dealt is increased based on Shenhe's current ATK.</p><p>The Icy Quill's effects will be cleared once its duration ends or after being triggered a certain number of times. When held rather than pressed, the Icy Quill's effect lasts longer and can be triggered more times. When one Cryo DMG instance strikes multiple opponents, the effect is triggered multiple times based on the number of opponents hit. The number of times the effect is triggered is calculated independently for each party member with the Icy Quill.</p><p><i>The power of the spirits is no falsehood. Burdened with her orders, the divine maiden hurries on!</i></p>" },
  "shenhe_talisman_spirit": { title: "The Talisman Spirit", description: "The Talisman Spirit creates a field that decreases the Cryo RES and Physical RES of opponents within it." },
  "shikanoin_heizou_curious_casefiles": { title: "Curious Casefiles", description: "Each Declension stack will increase the CRIT Rate of the Heartstopper Strike unleashed by {crit_rate_heizou1}. When Heizou possesses Conviction, this Heartstopper Strike's CRIT DMG is increased by {crit_dmg_heizou4}." },
  "shikanoin_heizou_esoteric_puzzle_book": { title: "Esoteric Puzzle Book" },
  "shikanoin_heizou_fudou_style_martial_arts": { title: "Fudou Style Martial Arts", description: "<p>Normal Attack Performs up to 5 fisticuffs empowered by a mighty wind, dealing Anemo DMG.</p><p>Charged Attack Consumes a certain amount of Stamina and performs a sweeping kick that deals Anemo DMG.</p><p>Plunging Attack Calling upon the surging wind, Heizou plunges towards the ground from mid-air, damaging all opponents in his path. Deals AoE Anemo DMG upon impact with the ground.</p>" },
  "shikanoin_heizou_heartstopper_strike": { title: "Heartstopper Strike", description: "<p>Tap Wields the swift winds to launch a Heartstopper Strike that deals Anemo DMG.</p><p>Hold Charges energy to unleash an even stronger blow. He will obtain the Declension effect while charging, which will increase the power of the Heartstopper Strike. When the skill button is released or the skill finishes charging, he will strike forward, dealing Anemo DMG.</p><p>Declension Increases the power of the next Heartstopper Strike. Max 4 stacks. When you possess 4 Declension stacks, the Conviction effect will be produced, which will cause the next Heartstopper Strike to be even stronger and have a larger AoE.</p><p><i>This seemingly ordinary strike contains Heizou's desire for criminals to honestly confess and repent.</i></p>" },
  "shikanoin_heizou_investigative_collection": { title: "Investigative Collection", description: "The pull effect of the Arresting Windtunnel created by Windmuster Kick is enhanced, and its duration is increased to 1s." },
  "shikanoin_heizou_named_juvenile_casebook": { title: "Named Juvenile Casebook", description: "For 5s after Shikanoin Heizou takes the field, his Normal Attack SPD is increased by {atk_speed_normal}. He also gains 1 Declension stack for Heartstopper Strike. This effect can be triggered once every 10s." },
  "shikanoin_heizou_paradoxical_practice": { title: "Paradoxical Practice", description: "When Shikanoin Heizou activates a Swirl reaction while on the field, he will gain 1 Declension stack for Heartstopper Strike. This effect can be triggered once every 0.1s." },
  "shikanoin_heizou_penetrative_reasoning": { title: "Penetrative Reasoning", description: "After Shikanoin Heizou's Heartstopper Strike hits an opponent, increases all party members' (excluding Shikanoin Heizou) Elemental Mastery by {text_value} for 10s." },
  "shikanoin_heizou_secret_archive": { title: "Secret Archive" },
  "shikanoin_heizou_tome_of_lies": { title: "Tome of Lies", description: "The first Windmuster Iris explosion in each Windmuster Kick will regenerate 9 Elemental Energy for Shikanoin Heizou. Every subsequent explosion in that Windmuster Kick will each regenerate an additional 1.5 Energy for Heizou. One Windmuster Kick can regenerate a total of 13.5 Energy for Heizou in this manner." },
  "shikanoin_heizou_windmuster_kick": { title: "Windmuster Kick", description: "<p>Leaps into the air and uses the Fudou Style Vacuum Slugger and kicks his opponent. The Vacuum Slugger will explode upon hit and create an Arresting Windtunnel that pulls in nearby objects and opponents, dealing AoE Anemo DMG. When Vacuum Slugger hits opponents affected by Hydro/Pyro/Cryo/Electro, these opponents will be afflicted with Windmuster Iris. This Windmuster Iris will explode after a moment and dissipate, dealing AoE DMG of the corresponding aforementioned elemental type. Vacuum Slugger can afflict a maximum of 4 opponents with the Windmuster Iris. A single opponent cannot be under the effect of Windmuster Irises of different elements at the same time.</p><p><i>A unique technique that gathers Anemo in one place before unleashing it all in one kick. Is always there in a pinch to land on some criminal's fleeing back.</i></p>" },
  "sigewinne_can_the_happiest_of_spirits_understand_anxiety": { title: "\"Can the Happiest of Spirits Understand Anxiety?\"", description: "Rebound Hydrotherapy's Bolstering Bubblebalm can bounce 3 extra times, and the first 3 bounces will not cause big Bubblebalms to become smaller. The Passive Talent \"Requires Appropriate Rest\" is enhanced: Each Bubblebalm bounce adds 1 stack to her Convalescence tally, and the values for the Convalescence stacks' DMG bonus will be modified to: Every 1,000 max HP Sigewinne has above 30,000 increases the DMG by 100. The maximum DMG increase for Elemental Skills that can be gained in this way is 3,500. You must first unlock the Passive Talent \"Requires Appropriate Rest.\"" },
  "sigewinne_can_the_healthiest_of_spirits_cure_fevers": { title: "\"Can the Healthiest of Spirits Cure Fevers?\"" },
  "sigewinne_can_the_loveliest_of_spirits_keep_decay_at_bay": { title: "\"Can the Loveliest of Spirits Keep Decay at Bay?\"", description: "The duration of Super Saturated Syringing is extended by 3s." },
  "sigewinne_can_the_most_joyful_of_spirits_alleviate_agony": { title: "\"Can the Most Joyful of Spirits Alleviate Agony?\"" },
  "sigewinne_can_the_most_merciful_of_spirits_defeat_its_foes": { title: "\"Can the Most Merciful of Spirits Defeat Its Foes?\"" },
  "sigewinne_can_the_most_merciful_of_spirits_defeat_its_foes_1": { description: "When using Rebound Hydrotherapy and Super Saturated Syringing, Sigewinne can create a Bubbly Shield worth {text_percent} of her Max HP that absorbs Hydro DMG with 250% efficiency. The Bubbly Shield will persist until Sigewinne finishes using relevant skills." },
  "sigewinne_can_the_most_merciful_of_spirits_defeat_its_foes_2": { description: "Additionally, after Rebound Hydrotherapy's Bolstering Bubblebalm or Super Saturated Syringing hits an opponent, that opponent's Hydro RES will be decreased by {enemy_res_hydro} for 8s." },
  "sigewinne_can_the_most_radiant_of_spirits_pray_for_me": { title: "\"Can the Most Radiant of Spirits Pray For Me?\"", description: "When Sigewinne performs healing, she will increase the CRIT Rate and CRIT DMG of her Super Saturated Syringing based on her Max HP. Every 1,000 Max HP she has will increase CRIT Rate by {text_percent_1} and CRIT DMG by {text_percent_2} for 15s. The maximum increase achievable this way is {text_percent_1_max} CRIT Rate and {text_percent_2_max} CRIT DMG." },
  "sigewinne_detailed_diagnosis_thorough_treatment": { title: "Detailed Diagnosis, Thorough Treatment", description: "When Sigewinne performs healing, the amount healed for this instance is increased based on the total current value of the Bonds of Life on all party members: For each 1,000 HP worth of Bonds of Life, the outgoing healing is increased by {text_percent}. The amount of healing provided can be increased by up to {text_percent_max} in this way." },
  "sigewinne_rebound_hydrotherapy": { title: "Rebound Hydrotherapy", description: "<p>Blows a Bolstering Bubblebalm that can stimulate blood flow and help patients drift off to sleep using a bubblegun specially made in the Fortress of Meropide. Bolstering Bubblebalms will bounce between nearby opponents, dealing Hydro DMG based on Sigewinne's max HP to opponents it hits. When it bounces, it will restore HP to all nearby party members except Sigewinne herself. The amount healed is based on Sigewinne's max HP. After bouncing 5 times, the Bolstering Bubblebalm will disappear and restore HP to Sigewinne based on her max HP value. When no opponents are present, the Bolstering Bubblebalm will bounce nearby. Only one Bolstering Bubblebalm created by a Sigewinne may exist at once. When Held, the Bolstering Bubblebalm can be boosted to an even bigger size.</p><p>Hold Enter Aiming Mode to begin blowing an even bigger, even more breathtaking Bolstering Bubblebalm! The Bolstering Bubblebalm will grow bigger the longer the skill is Held, until it grows up to two tiers in size. Each tier it grows increases its DMG by 5% and healing by 5%. When a Bolstering Bubblebalm bounces, it will drop down a tier in size, until it returns to being a normal Bolstering Bubblebalm. After weaker opponents are hit by big Bolstering Bubblebalms, they will be imprisoned and will be unable to move.</p><p>In addition, 2 Sourcewater Droplets will be created near Sigewinne when she uses this Skill. Each Sourcewater Droplet Sigewinne collects will grant her a Bond of Life worth 10% of her Max HP. When Sigewinne's Bond of Life is cleared, she regains 1 Elemental Energy for every 2,000 HP worth of the Bond of Life that was cleared. Sigewinne can regain up to 5 Elemental Energy in this way.</p><p>Arkhe: Ousia Bolstering Bubblebalms periodically call down a Surging Blade on the position they hit, dealing Ousia-aligned Hydro DMG based on Sigewinne's max HP.</p><p><i>\"What do you think? Not only can this kind of hydrotherapy stimulate the circulatory system, but it can also cheer patients up, ooh, and that's not all, it can even help patients who ought to get some rest have a nice nap...\"</i></p>" },
  "sigewinne_requires_appropriate_rest": { title: "Requires Appropriate Rest" },
  "sigewinne_requires_appropriate_rest_1": { description: "Sigewinne grants herself the \"Semi-Strict Bedrest\" effect for 18s after using Rebound Hydrotherapy: Sigewinne gains an {dmg_hydro} Hydro DMG Bonus and 10 stacks of Convalescence." },
  "sigewinne_requires_appropriate_rest_2": { description: "When the Elemental Skills of your nearby off-field party members other than Sigewinne deal DMG, consume 1 stack of Convalescence, and increase the DMG dealt by this instance of Elemental Skill DMG. Every 1,000 Max HP Sigewinne has above {text_value_hp} increases the DMG by {text_value_dmg}. The maximum DMG increase for Elemental Skills that can be gained in this way is {text_value_max}." },
  "sigewinne_super_saturated_syringing": { title: "Super Saturated Syringing", description: "<p>Takes out a special Fortress of Meropide-made syringe and assault the area in front with waves of kindness and medicine, dealing AoE Hydro DMG based on Sigewinne's max HP. In addition, Sigewinne absorbs up to 2 nearby Sourcewater Droplets within a certain range when she uses this skill.</p><p><i>\"Hey, overdosing on medicine is no different from poison, you know, it's real dangerous! But patients need care and concern, and nobody can overdose on that!\"</i></p>" },
  "sigewinne_targeted_treatment": { title: "Targeted Treatment", description: "<p>Normal Attack Performs up to 3 consecutive attacks.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, the power of Hydro will continually accumulate on the arrow. After fully charging, Sigewinne will periodically fire slow-moving Mini-Stration Bubbles toward the target, dealing Hydro DMG. When released, an arrow imbued with torrential energy will deal Hydro DMG to the opponent hit.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "skirk_end_of_wishes": { title: "End of Wishes" },
  "skirk_far_to_fall": { title: "Far to Fall", description: "Enhances the effects of the Passive Talent Reason Beyond Reason: Every Void Rift absorbed will summon a crystal blade to attack nearby opponents, dealing {text_percent_dmg} of Skirk's ATK as Cryo DMG. This DMG is considered Charged Attack DMG. You must first unlock the Passive Talent Reason Beyond Reason." },
  "skirk_fractured_flow": { title: "Fractured Flow", description: "Enhances the effects of the Passive Talent Return to Oblivion: Each Death's Crossing stack also increases Skirk's ATK by 10%/20%/40%. You must first unlock the Passive Talent Return to Oblivion." },
  "skirk_into_the_abyss": { title: "Into the Abyss" },
  "skirk_into_the_abyss_1": { description: "After unleashing her Elemental Skill Havoc: Warp, Skirk will gain 10 additional Serpent's Subtlety points. When using her Elemental Burst Havoc: Ruin, the DMG of this Elemental Burst instance will be increased by taking up to 10 more Serpent's Subtlety points into account." },
  "skirk_into_the_abyss_2": { description: "Additionally, within 12.5s after Skirk unleashes the special Elemental Burst Havoc: Extinction while in her Seven-Phase Flash mode, her ATK is increased by 70%. This effect will be canceled when she leaves the Seven-Phase Flash mode." },
  "skirk_mutual_weapons_mentorship": { title: "Mutual Weapons Mentorship", description: "When all party members are either Hydro or Cryo, and if there is at least 1 Hydro and 1 Cryo character, your own party members' Elemental Skill Level is increased by 1." },
  "skirk_reason_beyond_reason": { title: "Reason Beyond Reason", description: "When nearby party members trigger Frozen, Superconduct, Cryo Swirl, or Cryo Crystallize reactions against opponents, a Void Rift will be created near this opponent. This effect can be triggered once every 2.5s. 3 Void Rifts created by Skirk herself can exist on the field at once. Skirk can use the following methods to absorb nearby Void Rifts: · When she hits an opponent with a Charged Attack in her Seven-Phase Flash mode. · When she uses the special Elemental Burst Havoc: Extinction while in Seven-Phase Flash mode. · When she Holds her Elemental Skill Havoc: Warp to engage in rapid movement. Each Rift absorbed will grant her 8 Serpent's Subtlety points." },
  "skirk_return_to_oblivion": { title: "Return to Oblivion", description: "When nearby Hydro party members' Hydro attacks hit opponents, or when nearby Cryo party members apart from Skirk hit opponents with Cryo attacks, Skirk will gain the \"Death's Crossing\" effect for 20s. Max 3 stacks, each stack's duration is counted independently. Each character can grant Skirk at most 1 \"Death's Crossing\" stack by this means. Each \"Death's Crossing\" stack increases the Normal Attack DMG dealt by Skirk in Seven-Phase Flash mode to 110%/120%/170% of its original DMG and the DMG dealt when using her Elemental Burst Havoc: Ruin to 105%/115%/160% of its original DMG." },
  "skirk_ruin": { title: "Havoc: Ruin", description: "<p>Skirk's Elemental Burst is not reliant on Elemental Energy but instead on Serpent's Subtlety. When Skirk has at least 50 Serpent's Subtlety, she can expend all her Serpent's Subtlety to unleash her Elemental Burst, ripping the space before her apart and using rapid consecutive slashes that deal AoE Cryo DMG. At the same time, the DMG dealt by an instance of this Elemental Burst will be increased by every point of Serpent's Subtlety over 50 when it is unleashed. Up to 12 points can be counted for this purpose.</p><p>When Skirk is in Seven-Phase Flash mode, Havoc: Ruin will be replaced by Havoc: Extinction.</p><p>Havoc: Extinction A special Elemental Burst that can be used even without consuming Serpent's Subtlety. After using it, Skirk will gain the \"All Shall Wither\" effect, which will last until Seven-Phase Flash ends. After unlocking the Passive Talent Reason Beyond Reason, she can also absorb nearby Void Rifts. While \"All Shall Wither\" is active, every 0.1s, after Skirk's Normal Attack hits an opponent, that Normal Attack will deal increased DMG. If she absorbed any Void Rifts while using Havoc: Extinction, this Normal Attack's DMG will be further increased based on the number of Rifts absorbed. This effect will be canceled when it has triggered 10 times.</p>" },
  "skirk_serendipitous_sin": { title: "Serendipitous Sin" },
  "skirk_sunder": { title: "Havoc: Sunder", description: "<p>Normal Attack Performs up to 5 consecutive attacks.</p><p>Charged Attack Consumes a certain amount of Stamina to hurl a spinning crystal spear, dealing DMG to opponents ahead.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "skirk_to_the_source": { title: "To the Source", description: "Each Void Rift Skirk absorbs via the effects of the Passive Talent Reason Beyond Reason will grant her 1 Havoc: Sever stack. She can consume such stacks to initiate coordinated attacks and decrease the DMG she takes while in Seven-Phase Flash mode. These stacks last for 15s, and each stack's duration is counted independently (max 3 stacks). You must first unlock the Passive Talent \"Reason Beyond Reason.\" Sever · When Skirk uses the Elemental Burst Havoc: Ruin, she will consume all Sever stacks to initiate a coordinated attack in which each Sever stack will deal {text_percent_dmg_1} of Skirk's ATK as Cryo DMG. This DMG is considered Elemental Burst DMG. · When she uses Normal Attacks while in Seven-Phase Flash mode, 1 Sever stack will be consumed when her third or fifth sequenced attacks hit an opponent to launch 3 coordinated attacks. Each coordinated attack deals {text_percent_dmg_2} of Skirk's ATK as Cryo DMG. This damage is considered Normal Attack DMG. · When Skirk takes DMG while in Seven-Phase Flash mode, 1 Sever stack will be consumed to decrease this DMG instance by 80% and attack nearby opponents 3 times, with each attack dealing {text_percent_dmg_2} of Skirk's ATK as Cryo DMG. This DMG is considered Charged Attack DMG." },
  "skirk_warp": { title: "Havoc: Warp", description: "<p>Imitates the combat style of \"The Foul.\" Produces different effects depending on whether you Tap or Hold.</p><p>Tap Skirk gains 45 Serpent's Subtlety and switches to Seven-Phase Flash mode.</p><p>Hold Skirk gains 45 Serpent's Subtlety and will continuously move at high speed. Her interruption resistance is increased in this state. During this time, Skirk can control her movement direction and move atop water. She can also use this Skill again to end rapid movement prematurely.</p>" },
  "sucrose_alchemania": { title: "Alchemania", description: "Sucrose will reduce the CD of Astable Anemohypostasis Creation - 6308 by 1-7s for every 7 Normal or Charged Attack hits she scores against opponents. One hit may be counted every 0.1s." },
  "sucrose_astable_anemohypostasis_creation_6308": { title: "Astable Anemohypostasis Creation - 6308", description: "<p>Creates a small Wind Spirit that pulls opponents and objects towards its location, launches opponents within its AoE, and deals Anemo DMG.</p><p><i>This is a little embarrassing, but though the elemental lifeforms birthed through this procedure dissipate very rapidly, they are incredibly useful when adventuring. Even failed experiments can have practical applications.</i></p>" },
  "sucrose_catalyst_conversion": { title: "Catalyst Conversion", description: "When Sucrose triggers a Swirl reaction, all characters in the party with the matching element (excluding Sucrose) have their Elemental Mastery increased by {text_value} for 8s." },
  "sucrose_chaotic_entropy": { title: "Chaotic Entropy", description: "If Forbidden Creation - Isomer 75 / Type II triggers an Elemental Absorption, all party members gain a 20% Elemental DMG Bonus for the corresponding absorbed element during its duration." },
  "sucrose_clustered_vacuum_field": { title: "Clustered Vacuum Field", description: "Astable Anemohypostasis Creation - 6308 gains 1 additional charge." },
  "sucrose_flawless_alchemistress": { title: "Flawless Alchemistress" },
  "sucrose_forbidden_creation_isomer_75_type_ii": { title: "Forbidden Creation - Isomer 75 / Type II", description: "<p>Sucrose hurls an unstable concoction that creates a Large Wind Spirit. While it persists, the Large Wind Spirit will continuously pull in surrounding opponents and objects, launch nearby opponents, and deal Anemo DMG.</p><p>Elemental Absorption If the Wind Spirit comes into contact with Hydro/Pyro/Cryo/Electro energy, it will deal additional elemental DMG of that type. Elemental Absorption may only occur once per use.</p><p><i>Sucrose used to give names to her volatile Anemo Hypostases, but their line of heirs quickly grew to surpass Baron Bunny the 893rd.</i></p>" },
  "sucrose_mollis_favonius": { title: "Mollis Favonius", description: "When Astable Anemohypostasis Creation - 6308 or Forbidden Creation - Isomer 75 / Type II hits an opponent, increases all party members' (excluding Sucrose) Elemental Mastery by an amount equal to {text_percent} of Sucrose's Elemental Mastery for 8s." },
  "sucrose_standard_flask": { title: "Caution: Standard Flask" },
  "sucrose_unbound_form": { title: "Beth: Unbound Form", description: "The duration of Forbidden Creation - Isomer 75 / Type II is increased by 2s." },
  "sucrose_wind_spirit_creation": { title: "Wind Spirit Creation", description: "<p>Normal Attack Performs up to 4 attacks using Wind Spirits, dealing Anemo DMG.</p><p>Charged Attack Consumes a certain amount of Stamina and deals AoE Anemo DMG after a short casting time.</p><p>Plunging Attack Calling upon the power of her Wind Spirits, Sucrose plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Anemo DMG upon impact with the ground.</p>" },
  "tartaglia_annihilation": { title: "Havoc: Annihilation", description: "When Havoc: Obliteration is cast in Melee Stance, the CD of Foul Legacy: Raging Tide is reset. This effect will only take place once Tartaglia returns to his Ranged Stance." },
  "tartaglia_cutting_torrent": { title: "Cutting Torrent", description: "<p>Normal Attack Performs up to 6 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, the power of Hydro will accumulate on the arrowhead. An arrow fully charged with the torrent will deal Hydro DMG and apply the Riptide status.</p><p>Riptide Opponents affected by Riptide will suffer from AoE Hydro DMG effects when attacked by Tartaglia in various ways. DMG dealt in this way is considered Normal Attack DMG. ·Riptide Flash: A fully-charged Aimed Shot that hits an opponent affected by Riptide deals consecutive bouts of AoE DMG. Can occur once every 0.7s. ·Riptide Burst: Defeating an opponent affected by Riptide creates a Hydro burst that inflicts the Riptide status on nearby opponents hit.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact. When Tartaglia is in Foul Legacy: Raging Tide's Melee Stance, he cannot perform a plunging attack.</p>" },
  "tartaglia_formless_blade": { title: "Havoc: Formless Blade" },
  "tartaglia_hydrospout": { title: "Abyssal Mayhem: Hydrospout", description: "If Tartaglia is in Foul Legacy: Raging Tide's Melee Stance, triggers Riptide Slash against opponents on the field affected by Riptide every 4s, otherwise, triggers Riptide Flash. Riptide Slashes and Riptide Flashes triggered by this Constellation effect are not subject to the time intervals that would typically apply to these two Riptide effects, nor do they have any effect on those time intervals." },
  "tartaglia_master_of_weaponry": { title: "Master of Weaponry", description: "Increases your own party members' Normal Attack Level by 1." },
  "tartaglia_never_ending": { title: "Never Ending", description: "Extends Riptide duration by 8s." },
  "tartaglia_obliteration": { title: "Havoc: Obliteration", description: "<p>Performs different attacks based on what stance Tartaglia is in when casting.</p><p>Ranged Stance: Flash of Havoc Swiftly fires a Hydro-imbued magic arrow, dealing AoE Hydro DMG and applying the Riptide status. Returns a portion of its Energy Cost after use.</p><p>Melee Stance: Light of Obliteration Performs a slash with a large AoE, dealing massive Hydro DMG to all surrounding opponents, which triggers Riptide Blast.</p><p>Riptide Blast When the obliterating waters hit an opponent affected by Riptide, it clears their Riptide status and triggers a Hydro Explosion that deals AoE Hydro DMG. DMG dealt in this way is considered Elemental Burst DMG.</p><p><i>Rushing waters are rarely seen in his snowy homeland. Perhaps his ability to command water is due to his understanding of just how precious it is.</i></p>" },
  "tartaglia_raging_tide": { title: "Foul Legacy: Raging Tide", description: "<p>Unleashes a set of weaponry made of pure water, dealing Hydro DMG to surrounding opponents and entering Melee Stance. In this Stance, Tartaglia's Normal and Charged Attacks are converted to Hydro DMG that cannot be overridden by any other elemental infusion and change as follows:</p><p>Normal Attack Performs up to 6 consecutive Hydro strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash a cross slash, dealing Hydro DMG.</p><p>Riptide Slash Hitting an opponent affected by Riptide with a melee attack unleashes a Riptide Slash that deals AoE Hydro DMG. DMG dealt in this way is considered Elemental Skill DMG, and can only occur once every 1.5s.</p><p>After 30s, or when the ability is unleashed again, this skill will end. Tartaglia will return to his Ranged Stance and this ability will enter CD. The longer Tartaglia stays in his Melee Stance, the longer the CD. If the return to a ranged stance occurs automatically after 30s, the CD is even longer.</p><p><i>He chose the bow as his weapon precisely to overcome his weakness with it. But a serious fight demands that he gets serious...</i></p>" },
  "tartaglia_raging_tide_talent": { description: "Unleashes a set of weaponry made of pure water, dealing Hydro DMG to surrounding opponents and entering Melee Stance. In this Stance, Tartaglia's Normal and Charged Attacks are converted to Hydro DMG that cannot be overridden by any other elemental infusion." },
  "tartaglia_sword_of_torrents": { title: "Sword of Torrents", description: "When Tartaglia is in Foul Legacy: Raging Tide's Melee Stance, on dealing a CRIT hit, Normal and Charged Attacks apply the Riptide status effect to opponents." },
  "tartaglia_tide_withholder": { title: "Foul Legacy: Tide Withholder", description: "Decreases the CD of Foul Legacy: Raging Tide by {text_percent_cd}." },
  "tartaglia_understream": { title: "Foul Legacy: Understream", description: "When opponents affected by Riptide are defeated, Tartaglia regenerates 4 Elemental Energy." },
  "tartaglia_vortex_of_turmoil": { title: "Abyssal Mayhem: Vortex of Turmoil" },
  "thoma_a_comrades_duty": { title: "A Comrade's Duty", description: "When a character protected by Thoma's own Blazing Barrier (Thoma excluded) is attacked, Thoma's own Blazing Blessing CD is decreased by 3s, while his own Crimson Ooyoroi's CD is decreased by 3s. This effect can be triggered once every 20s." },
  "thoma_a_subordinates_skills": { title: "A Subordinate's Skills", description: "Crimson Ooyoroi's duration is increased by 3s." },
  "thoma_blazing_blessing": { title: "Blazing Blessing", description: "<p>Thoma vaults forward with his polearm and delivers a flame-filled flying kick that deals AoE Pyro DMG, while also summoning a defensive Blazing Barrier. At the moment of casting, Thoma's Elemental Skill applies Pyro to himself. The DMG Absorption of the Blazing Barrier scales off Thoma's Max HP. The Blazing Barrier has the following traits: ·Absorbs Pyro DMG 250% more effectively. ·When a new Blazing Barrier is obtained, the remaining DMG Absorption of an existing Blazing Barrier will stack and its duration will be refreshed.</p><p>The maximum DMG Absorption of the Blazing Barrier will not exceed a certain percentage of Thoma's Max HP.</p><p><i>As a guest from afar, only the most burning passion would allow one to master the pure and precise spear arts of Inazuma. Thoma's mastery, indeed, is not limited to being the \"swiftest-studying student\" or \"a master of the spear,\" but he has imbued his will to protect others and fend off foes into his art as well.</i></p>" },
  "thoma_burning_heart": { title: "Burning Heart", description: "When a Blazing Barrier is obtained or refreshed, the DMG dealt by all party members' Normal, Charged, and Plunging Attacks is increased by {dmg_normal} for 6s." },
  "thoma_crimson_ooyoroi": { title: "Crimson Ooyoroi", description: "<p>Thoma spins his polearm, slicing at his foes with roaring flames that deal AoE Pyro DMG and weave themselves into a Scorching Ooyoroi.</p><p>Scorching Ooyoroi While Scorching Ooyoroi is in effect, the active character's Normal Attacks will trigger Fiery Collapse, dealing AoE Pyro DMG and summoning a Blazing Barrier. Fiery Collapse can be triggered once every 1s.</p><p>Except for the amount of DMG they can absorb, the Blazing Barriers created in this way are identical to those created by Thoma's Elemental Skill, Blazing Blessing: ·Absorbs Pyro DMG 250% more effectively. ·When a new Blazing Barrier is obtained, the remaining DMG Absorption of an existing Blazing Barrier will stack and its duration will be refreshed.</p><p>The maximum DMG Absorption of the Blazing Barrier will not exceed a certain percentage of Thoma's Max HP.</p><p>If Thoma falls, the effects of Scorching Ooyoroi will be cleared.</p><p><i>\"I will not forget my initial promise. Let this burning flame protect those I cherish, and may it never be extinguished.\"</i></p>" },
  "thoma_flaming_assault": { title: "Flaming Assault", description: "DMG dealt by Crimson Ooyoroi's Fiery Collapse is increased by {text_percent} of Thoma's Max HP." },
  "thoma_fortified_resolve": { title: "Fortified Resolve" },
  "thoma_imbricated_armor": { title: "Imbricated Armor", description: "When your current active character obtains or refreshes a Blazing Barrier, this character's Shield Strength will increase by {shield} for 6s. This effect can be triggered once every 0.3s seconds. Max 5 stacks." },
  "thoma_long_term_planning": { title: "Long-Term Planning", description: "After using Crimson Ooyoroi, 15 Energy will be restored to Thoma." },
  "thoma_raging_wildfire": { title: "Raging Wildfire" },
  "thoma_swiftshatter_spear": { title: "Swiftshatter Spear", description: "<p>Normal Attack Performs up to 4 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "tighnari_beginnings_determined_at_the_roots": { title: "Beginnings Determined at the Roots", description: "Tighnari's Charged Attack CRIT Rate is increased by {crit_rate_charged}." },
  "tighnari_comprehension_amidst_the_flowers": { title: "Comprehension Amidst the Flowers" },
  "tighnari_fashioners_tanglevine_shaft": { title: "Fashioner's Tanglevine Shaft", description: "<p>Combines the power of all seeds to fire 6 Tanglevine Shafts that can track opponents and deal Dendro DMG. After they hit, the Tanglevine Shafts will create a secondary wave of Tanglevine Shafts that can also track nearby opponents and deal Dendro DMG on hit.</p><p><i>\"Do not seek to escape so easily. The vines grow and regrow ever on. Things might get dicey if you don't clear every last one of them out.\"</i></p>" },
  "tighnari_fortunes_read_amongst_the_branches": { title: "Fortunes Read Amongst the Branches" },
  "tighnari_karma_adjudged_from_the_leaden_fruit": { title: "Karma Adjudged From the Leaden Fruit", description: "Wreath Arrow's charging time is decreased by 0.9s, and will produce 1 additional Clusterbloom Arrow upon hit. This arrow deals {text_percent_dmg} of Tighnari's ATK as DMG." },
  "tighnari_keen_sight": { title: "Keen Sight", description: "After Tighnari fires a Wreath Arrow, his Elemental Mastery is increased by {mastery} for 4s." },
  "tighnari_khanda_barrier_buster": { title: "Khanda Barrier-Buster", description: "<p>Normal Attack Performs up to 4 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, the power of Dendro will accumulate on the arrowhead before the arrow is fired. Has different effects based on how long the energy has been charged: ·Charge Level 1: Fires off an arrow carrying the power of flora that deals Dendro DMG. ·Charge Level 2: Fires off a Wreath Arrow that deals Dendro DMG. Upon hit, the Wreath Arrow will create 4 Clusterbloom Arrows that will track nearby opponents automatically and deal Dendro DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "tighnari_origins_known_from_the_stem": { title: "Origins Known From the Stem", description: "When there are opponents within the Vijnana-Khanda Field created by Vijnana-Phala Mine, Tighnari gains {dmg_dendro} Dendro DMG Bonus. The effect will last up to 6s if the field's duration ends or if it no longer has opponents within it." },
  "tighnari_scholarly_blade": { title: "Scholarly Blade", description: "For every point of Elemental Mastery Tighnari possesses, his Charged Attack and Fashioner's Tanglevine Shaft DMG are increased by 0.06%. The maximum DMG Bonus obtainable this way is 60%." },
  "tighnari_vijnana_phala_mine": { title: "Vijnana-Phala Mine", description: "<p>Tighnari throws a Vijnana Stormheart ahead that deals AoE Dendro DMG, creating a Vijnana-Khanda Field that creates mysterious illusions that taunt opponents and draw their fire. Additionally, Tighnari gains the Vijnana Suffusion effect, which will decrease the Wreath Arrow's charging time by 2.4s. This effect will dissipate once the skill duration ends or after Tighnari has fired 3 Wreath Arrows.</p><p><i>\"If seeds wither apart from the soil, they will remain a single seed. But if returned to the soil, they shall multiply ten-million fold.\"</i></p>" },
  "tighnari_withering_glimpsed_in_the_leaves": { title: "Withering Glimpsed in the Leaves" },
  "tighnari_withering_glimpsed_in_the_leaves_1": { description: "When Fashioner's Tanglevine Shaft is unleashed, all nearby party members gain {mastery} Elemental Mastery for 8s." },
  "tighnari_withering_glimpsed_in_the_leaves_2": { description: "If the Fashioner's Tanglevine Shaft triggers a Burning, Bloom, Quicken, or Spread reaction, their Elemental Mastery will be further increased by {mastery}. This latter case will also refresh the buff state's duration." },
  "traveler_abundance_amulet": { title: "Abundance Amulets", description: "When a character is near an Abundance Amulet, they will absorb it and obtain the following effects: ·Restores Elemental Energy ·Increases Energy Recharge during the Abundance Amulet's duration." },
  "traveler_aquacrest_saber": { title: "Aquacrest Saber", description: "<p>Unleashes a torrent that can cleanse the world.</p><p>Press Sends a Torrent Surge forward that will deal Hydro DMG to opponents it comes into contact with.</p><p>Hold Enter Aiming Mode and constantly fire off Dewdrops in the direction in which you are aiming, dealing Hydro DMG to opponents they hit. When the skill ends, it will send a Torrent Surge forward that will deal Hydro DMG to opponents it comes into contact with. Suffusion: When using the Hold configuration of this skill, if the Traveler's HP is higher than 50%, the DMG dealt by Dewdrops will increase based on the Traveler's Max HP, and the Traveler will lose a fixed amount of HP every second.</p><p>Arkhe: Pneuma At certain intervals, after using Torrent Surge, this skill will unleash a Spiritbreath Thorn that pierces opponents, dealing Pneuma-aligned Hydro DMG.</p><p><i>You studied the ripples in the water with Paimon.</i></p>" },
  "traveler_bellowing_thunder": { title: "Bellowing Thunder", description: "<p>You call upon the protection of lightning, knocking nearby opponents back and dealing Electro DMG to them.</p><p>Lightning Shroud When your active character's Normal or Charged Attacks hit opponents, they will call Falling Thunder forth, dealing Electro DMG. When Falling Thunder hits opponents, it will regenerate Energy for that character. One instance of Falling Thunder can be generated every 0.5s.</p><p><i>You and Paimon studied the light that flashes through the clouds.</i></p>" },
  "traveler_cherishing_breezes": { title: "Cherishing Breezes", description: "Reduces DMG taken while casting Palm Vortex by {text_percent_reduce}." },
  "traveler_churning_whirlpool": { title: "Churning Whirlpool" },
  "traveler_clear_waters": { title: "Clear Waters", description: "If HP has been consumed via Suffusion while using the Hold Mode Aquacrest Saber, the Torrent Surge at the skill's end will deal Bonus DMG equal to {text_percent_dmg} of the total HP the Traveler has consumed in this skill use via Suffusion. The maximum DMG Bonus that can be gained this way is {text_value_max}." },
  "traveler_embers_unspent": { title: "Embers Unspent", description: "After the current active character inside a Blazing Threshold or Scorching Threshold triggers a Pyro-related reaction, the Traveler will regain 5 Energy. This can occur once every 12s. Additionally, when a nearby party member triggers a Nightsoul Burst, the Traveler will regain 4 Energy." },
  "traveler_ever_lit_candle": { title: "Ever-Lit Candle", description: "Within 12s of using the Elemental Skill Flowfire Blade, after nearby party members trigger a Pyro-related reaction on an opponent, the Traveler will regain 14 Nightsoul points. Each use of Flowfire Blade will restore at most 28 Nightsoul points in this way." },
  "traveler_everlasting_boulder": { title: "Everlasting Boulder", description: "The barrier created by Wake of Earth lasts 5s longer. The meteorite created by Starfell Sword lasts 10s longer." },
  "traveler_fickle_cloudstrike": { title: "Fickle Cloudstrike", description: "When a character obtains Abundance Amulets generated by Lightning Blade, if this character's Energy is less than {text_percent1}, the Energy restored by the Abundance Amulets is increased by {text_percent2}." },
  "traveler_flowfire_blade": { title: "Flowfire Blade", description: "<p>Wields a searing flame that can incinerate the very earth. Has different effects when Tapped or Held.</p><p>Tap Call forth flames in a raging blaze. When used, the Traveler gains 42 Nightsoul points and enters the Nightsoul's Blessing state, summoning a Blazing Threshold that follows the current active character. When the Blazing Threshold gets close to opponents, it will deal Nightsoul-aligned Pyro DMG to nearby opponents at intervals.</p><p>Hold Unleash fire in a composed manner, dealing Nightsoul-aligned AoE Pyro DMG to nearby opponents. When used, the Traveler gains 42 Nightsoul points and enters the Nightsoul's Blessing state, summoning a Scorching Threshold that follows the current active character. When the current active character within a Scorching Threshold deals DMG to opponents, the Threshold will launch a Coordinated Attack that deals Nightsoul-aligned Pyro DMG based on the Traveler's ATK. This effect can occur once every 3s.</p><p>Nightsoul's Blessing: Traveler Continuously consumes Nightsoul points. The Traveler's Nightsoul's Blessing state lasts 12s at maximum, and when their Nightsoul points are exhausted, this state will end. If this Elemental Skill is used again while active, the Traveler's Nightsoul points will be reset to 42 points. Blazing and Scorching Thresholds will disappear once the Traveler's Nightsoul's Blessing state ends, and only 1 Blazing or Scorching Threshold summoned by the Traveler themselves can exist at any one time.</p><p><i>Together, you and Paimon watched the shifting colors of the flowing flames.</i></p>" },
  "traveler_foreign_blaze": { title: "Foreign Blaze", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "traveler_foreign_fieldcleaver": { title: "Foreign Fieldcleaver", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "traveler_foreign_ironwind": { title: "Foreign Ironwind", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "traveler_foreign_rockblade": { title: "Foreign Rockblade", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "traveler_foreign_stream": { title: "Foreign Stream", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "traveler_foreign_thundershock": { title: "Foreign Thundershock", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "traveler_frenzied_rockslide": { title: "Frenzied Rockslide", description: "The final hit of a Normal Attack combo triggers a collapse, dealing {text_percent_dmg} of ATK as AoE Geo DMG." },
  "traveler_green_resilience": { title: "Green Resilience", description: "Lea Lotus Lamp's duration is increased by 3s." },
  "traveler_gust_surge": { title: "Gust Surge", description: "<p>Guiding the path of the wind currents, you summon a forward-moving tornado that pulls objects and opponents towards itself, dealing continuous Anemo DMG.</p><p>Elemental Absorption If the tornado comes into contact with Hydro/Pyro/Cryo/Electro, it will deal additional elemental DMG of that type. Elemental Absorption may only occur once per use.</p><p><i>You and Paimon studied the flapping of a butterfly's wings.</i></p>" },
  "traveler_intertwined_winds": { title: "Intertwined Winds", description: "Targets who take DMG from Gust Surge have their nameo{Anemo RES} decreased by {enemy_res_anemo}." },
  "traveler_intertwined_winds_element": { description: "If an Elemental Absorption occurred, then their RES towards the corresponding Element is also decreased by 20%." },
  "traveler_invincible_stonewall": { title: "Invincible Stonewall", description: "Party members within the radius of Wake of Earth have their CRIT Rate increased by {crit_rate} and have increased resistance against interruption." },
  "traveler_lightning_blade": { title: "Lightning Blade", description: "<p>Unleashes three swift thunder shadows that deal Electro DMG to opponents and leave an Abundance Amulet behind after hitting an opponent. 2 Abundance Amulets can be created initially. Using this skill will reset any Abundance Amulets that were generated.</p><p>Abundance Amulets When a character is near an Abundance Amulet, they will absorb it and obtain the following effects: ·Restores Elemental Energy ·Increases Energy Recharge during the Abundance Amulet's duration.</p><p><i>You and Paimon discuss the paths by which electricity might flow.</i></p>" },
  "traveler_palm_vortex": { title: "Palm Vortex", description: "<p>Grasping the wind's might, you form a vortex of vacuum in your palm, causing continuous Anemo DMG to opponents in front of you. The vacuum vortex explodes when the skill duration ends, causing a greater amount of Anemo DMG over a larger area.</p><p>Hold DMG and AoE will gradually increase.</p><p>Elemental Absorption If the vortex comes into contact with Hydro/Pyro/Cryo/Electro, it will deal additional elemental DMG of that type. Elemental Absorption may only occur once per use.</p><p><i>You discussed the way to grasp the formless wind with Paimon.</i></p>" },
  "traveler_plains_scorcher": { title: "Plains Scorcher", description: "<p>Condense the flames into a mark, dealing Nightsoul-aligned AoE Pyro DMG to opponents up ahead. The Traveler restores 7 Nightsoul points per second for the next 4s.</p><p><i>Together, you and Paimon studied the principles behind an undying flame.</i></p>" },
  "traveler_pouring_descent": { title: "Pouring Descent", description: "When using Aquacrest Saber, an Aquacrest Aegis that can absorb {text_percent_hp} of the Traveler's Max HP in DMG will be created and will absorb Hydro DMG with 250% effectiveness. It will persist until the Traveler finishes using the skill. Once every 2s, after a Dewdrop hits an opponent, if the Traveler is being protected by Aquacrest Aegis, the DMG Absorption of the Aegis will be restored to {text_percent_hp_2} of the Traveler's Max HP. If the Traveler is not presently being protected by an Aegis, one will be redeployed." },
  "traveler_raging_vortex": { title: "Raging Vortex", description: "Palm Vortex pulls in opponents and objects within a 5m radius." },
  "traveler_ravaging_flame": { title: "Ravaging Flame", description: "After using the Elemental Burst Plains Scorcher, the Traveler gains {dmg_pyro} Pyro DMG Bonus for 9s." },
  "traveler_razorgrass_blade": { title: "Razorgrass Blade", description: "<p>With a flourish of your blade, you unleash a spray of razor-sharp leaves that go before you and deal Dendro DMG.</p><p><i>You and Paimon observed the flowing edges of grass and leaf.</i></p>" },
  "traveler_reaction_force": { title: "Reaction Force", description: "The shockwave triggered by Wake of Earth regenerates 5 Energy for every opponent hit. A maximum of 25 Energy can be regenerated in this manner at any one time." },
  "traveler_relayed_beacon": { title: "Relayed Beacon" },
  "traveler_resounding_roar": { title: "Resounding Roar", description: "Increases the Energy Recharge effect granted by Lightning Blade's Abundance Amulet by {text_percent} of the Traveler's Energy Recharge." },
  "traveler_rising_waters": { title: "Rising Waters", description: "<p>Unleashes a slow-moving floating bubble that deals continuous Hydro DMG to nearby opponents.</p><p><i>You studied the ebb and flow of the tides with Paimon.</i></p>" },
  "traveler_rockcore_meltdown": { title: "Rockcore Meltdown", description: "When the meteorite created by Starfell Sword is destroyed, it will also explode, dealing additional AoE Geo DMG equal to the amount of damage dealt by Starfell Sword." },
  "traveler_second_wind": { title: "Second Wind", description: "Palm Vortex kills regenerate {text_percent_hp} HP for 5s. This effect can only occur once every 5s." },
  "traveler_shattered_darkrock": { title: "Shattered Darkrock", description: "Reduces Starfell Sword's CD by 2s." },
  "traveler_slitting_wind": { title: "Slitting Wind", description: "The last hit of a Normal Attack combo unleashes a wind blade, dealing {text_percent_dmg} of ATK as Anemo DMG to all opponents in its path." },
  "traveler_special_training": { title: "Skirk's Special Training", description: "Base ATK increased by {atk_base}, elemental mastery by {mastery} and base HP by {hp_base}." },
  "traveler_spotless_waters": { title: "Spotless Waters", description: "After the Dewdrop fired by the Hold Mode of the Aquacrest Saber hits an opponent, a Sourcewater Droplet will be generated near to the Traveler. If the Traveler picks it up, they will restore {text_percent_heal} HP. 1 Droplet can be created this way every second, and each use of Aquacrest Saber can create 4 Droplets at most." },
  "traveler_spring_thunder_of_fertility": { title: "Spring Thunder of Fertility", description: "The number of Abundance Amulets that can be generated using Lightning Blade is increased to 3." },
  "traveler_starfell_sword": { title: "Starfell Sword", description: "<p>You disgorge a meteorite from the depths of the earth, dealing AoE Geo DMG. The meteorite is considered a Geo Construct, and can be climbed or used to block attacks.</p><p>Hold This skill's positioning may be adjusted.</p><p><i>You spoke with Paimon about the final destination of falling stars.</i></p>" },
  "traveler_starfires_flowing_light": { title: "Starfire's Flowing Light" },
  "traveler_starfires_flowing_light_1": { description: "While Blazing Threshold or Scorching Threshold are active, the current active character deals {dmg_all} increased DMG." },
  "traveler_starfires_flowing_light_2": { description: "If said character is in the Nightsoul's Blessing state, they will deal an additional {dmg_all} DMG." },
  "traveler_surgent_manifestation": { title: "Surgent Manifestation", description: "<p>Calling upon the might of the flora all around you, you create a Lea Lotus Lamp. This Lamp will deal continuous Dendro DMG to opponents within its AoE.</p><p>Lotuslight Transfiguration The Lea Lotus Lamp will undergo the following changes after it comes into contact with Hydro/Electro/Pyro: ·Hydro: the Lamp's AoE and the AoE of its attacks are increased. ·Electro: the Lamp's ATK SPD is increased. ·Pyro: the Lamp will explode after a short delay and then disappear, dealing AoE Dendro DMG. The Lea Lotus Lamp can only undergo one Lotuslight Transfiguration in its duration.</p><p>Only one Lamp created by the Traveler can exist at any one time.</p><p><i>You and Paimon studied the sounds of plants that sprout after the rain.</i></p>" },
  "traveler_swelling_lake": { title: "Swelling Lake", description: "Picking up a Sourcewater Droplet will restore 2 Energy to the Traveler. Requires the Passive Talent \"Spotless Waters.\"" },
  "traveler_swordfighting_techniques": { title: "Swordfighting Techniques VIII", description: "Base ATK increased by {atk_base}." },
  "traveler_symbiotic_creeper": { title: "Symbiotic Creeper", description: "After Razorgrass Blade hits an opponent, it will regenerate 3.5 Energy for the Traveler." },
  "traveler_the_fire_inextinguishable": { title: "The Fire Inextinguishable" },
  "traveler_the_sacred_flame_imperishable": { title: "The Sacred Flame Imperishable", description: "While in the Nightsoul's Blessing state, the Traveler's Normal, Charged, and Plunging Attacks will be converted to Nightsoul-aligned Pyro DMG that cannot be overridden, and the CRIT DMG of these attacks is increased by {crit_dmg_normal}." },
  "traveler_thunderflash": { title: "Thunderflash", description: "When another nearby character in the party obtains an Abundance Amulet created by Lightning Blade, Lightning Blade's CD is decreased by 1.5s." },
  "traveler_tides_of_justice": { title: "Tides of Justice", description: "When the Traveler picks up a Sourcewater Droplet, they will restore HP to a nearby party member with the lowest remaining HP percentage based on {text_percent_hp} of said member's Max HP." },
  "traveler_treacle_grass": { title: "Treacle Grass", description: "After the Lea Lotus Lamp triggers a Lotuslight Transfiguration, it will obtain 5 stacks of the Overflowing Lotuslight effect from the Passive Talent \"Verdant Overgrowth.\" You must have unlocked this Passive Talent first." },
  "traveler_trickling_purity": { title: "Trickling Purity", description: "The Movement SPD of Rising Waters' bubble will be decreased by 30%, and its duration increased by 3s." },
  "traveler_true_flame_of_incineration": { title: "True Flame of Incineration", description: "When the Traveler has over 20 Nightsoul points, the attack AoE of the Blazing and Scorching Thresholds from the Elemental Skill Flowfire Blade after they hit opponents is increased." },
  "traveler_turbulent_ripples": { title: "Turbulent Ripples" },
  "traveler_uprising_whirlwind": { title: "Uprising Whirlwind", description: "Increases Energy Recharge by {recharge}." },
  "traveler_verdant_luxury": { title: "Verdant Luxury", description: "Every point of Elemental Mastery the Traveler possesses increases the DMG dealt by Razorgrass Blade by 0.15% and the DMG dealt by Surgent Manifestation by 0.1%." },
  "traveler_verdant_overgrowth": { title: "Verdant Overgrowth", description: "Lea Lotus Lamp will obtain one level of Overflowing Lotuslight every second it is on the field, increasing the Elemental Mastery of active character(s) within its AoE by {mastery}. Overflowing Lotuslight has a maximum of 10 stacks." },
  "traveler_violet_vehemence": { title: "Violet Vehemence", description: "When Falling Thunder created by Bellowing Thunder hits an opponent, it will decrease their Electro RES by {enemy_res_electro} for 8s." },
  "traveler_viridian_transience": { title: "Viridian Transience" },
  "traveler_wake_of_earth": { title: "Wake of Earth", description: "<p>Energizing the Geo deep underground, you set off expanding shockwaves. Launches surrounding opponents back and deals AoE Geo DMG. A stone wall is erected at the edges of the shockwave. The stone wall is considered a Geo Construct, and may be used to block attacks.</p><p><i>You and Paimon studied the pulse of the mountains.</i></p>" },
  "traveler_whirling_weeds": { title: "Whirling Weeds" },
  "traveler_withering_aggregation": { title: "Withering Aggregation" },
  "traveler_withering_aggregation_1": { description: "The Dendro DMG Bonus of the character under the effect of Overflowing Lotuslight as created by the Lea Lotus Lamp is increased by {dmg_dendro}." },
  "traveler_withering_aggregation_2": { description: "If the Lamp has experienced a Lotuslight Transfiguration previously, the character will also gain 12% DMG Bonus for the corresponding element." },
  "traveler_world_shaker": { title: "World-Shaker", description: "Every 2 Falling Thunder attacks triggered by Bellowing Thunder will increase the DMG dealt by the next Falling Thunder by {text_percent_dmg}, and will restore an additional 1 Energy to the current character." },
  "varesa_a_hero_of_justices_triumph": { title: "A Hero of Justice's Triumph", description: "Varesa restores 30 Energy when she enters Apex Drive. Her Plunging Attacks and Elemental Burst Guardian Vent! gain {crit_rate_plunge} CRIT Rate and {crit_dmg_plunge} CRIT DMG. Additionally, when Varesa uses the Hold version of her Elemental Skill Riding the Night-Rainbow, or Taps her Elemental Skill while in the Sudden Onrush mode, she will restore Nightsoul points up to her maximum." },
  "varesa_beyond_the_edge_of_light": { title: "Beyond the Edge of Light", description: "Varesa will enter Apex Drive after using a Plunging Attack, regardless of whether she is in the Fiery Passion state or not. When Apex Drive is active, Varesa's interruption resistance will also further increase. Additionally, Varesa will restore 11.5 Energy when her Plunging Attack ground impact hits an opponent." },
  "varesa_by_the_horns": { title: "By the Horns", description: "<p>Normal Attack Gotta try... to do battle like the greatest champion luchadors do! Varesa launches up to 3 strikes, dealing Electro DMG.</p><p>Charged Attack Consumes a certain amount of Stamina to headbutt opponents in front, dealing Nightsoul-aligned Electro DMG and using the momentum to leap into the air.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing Nightsoul-aligned AoE Electro DMG upon impact. If Varesa is in a combat state upon landing, or if the shockwave from her plunging attack hits an opponent, she will gain 25 Nightsoul points. She enters the Fiery Passion state upon reaching maximum Nightsoul points through this method.</p><p>Fiery Passion In this state, Varesa's Normal, Charged, and Plunging Attacks will gain corresponding buffs:</p><p>Normal Attack Fight like a superstar champion luchador! Launches up to 3 fierce strikes, dealing greater Electro DMG.</p><p>Charged Attack Consumes a certain amount of Stamina to slam into her opponents, dealing greater amounts of Nightsoul-aligned Electro DMG and using the momentum to leap into the air.</p><p>Plunging Attack Consumes all her Nightsoul points and slams down on the ground from mid-air, dealing DMG to opponents in her path and dealing greater amounts of Nightsoul-aligned AoE Electro DMG upon hitting the ground.</p>" },
  "varesa_guardian_vent": { title: "Guardian Vent!", description: "<p>Leaps into the air before using the momentum of the drop to unleash a powerful flying kick, dealing Nightsoul-aligned AoE Electro DMG to opponents — just like those heroes of justice in woven scrolls for kids! After using this Skill, Varesa's Nightsoul points will be restored to maximum and she will enter the Fiery Passion state.</p><p>In the Fiery Passion state, Varesa's Elemental Burst will deal a greater amount of Nightsoul-aligned AoE Electro DMG.</p><p>Additionally, she will briefly activate Apex Drive after using a Plunging Attack while in her Fiery Passion state.</p><p>Apex Drive Increases Varesa's interruption resistance. While affected by Apex Drive, Varesa can ignore her Elemental Burst CD and consume less Energy to use her special Elemental Burst, \"Guardian Vent: Volcano Kablam\": This causes her to use the especially powerful Plunging Attack, the \"Thunderous Tornado Eruption,\" which deals Nightsoul-aligned AoE Electro DMG upon landing before causing her to exit Apex Drive. This DMG is considered Plunging Attack DMG. Varesa will exit Apex Drive after using her Elemental Skill.</p><p><i>In truth, the original name Varesa gave this move was the \"Invincible Dynamic Heroic Justice Super Mega Ultimate Thundercrash Sky-Splitting Supersonic Boom Kick.\" Alas, this name proved too long, and she was too embarrassed to shout it in front of everyone, even with her mask on. As such, she changed it to its present title instead.</i></p>" },
  "varesa_riding_the_night_rainbow": { title: "Riding the Night-Rainbow", description: "<p>With footwork swift as lightning and fierce as thunder, Varesa displays the true spirit of lucha libre, rushing forward a certain distance and dealing Nightsoul-aligned Electro DMG to opponents in her path. After using this Skill, Varesa gains 20 Nightsoul points and gains the \"Follow-Up Strike\" effect: Varesa has increased interruption resistance during this time, and upon pressing her Normal Attack, she will quickly unleash a Charged Attack that does not consume Stamina. \"Follow-Up Strike\" will be canceled after Varesa uses a Charged Attack. She will use different techniques based on whether the skill is Tapped or Held.</p><p>Tap Quickly rush a certain distance forward.</p><p>Hold Varesa enters the Nightsoul's Blessing state and switches to Sudden Onrush mode.</p><p>Sudden Onrush Continuously consumes Nightsoul points. In this state, Varesa's Movement SPD and interruption resistance are increased. She can use terrain to execute flying leaps or consume additional Nightsoul points to traverse atop water or liquid Phlogiston while remaining immune to DMG from the latter.</p><p>Nightsoul's Blessing: Varesa When she runs out of Nightsoul points, her Nightsoul's Blessing state will be canceled. When Varesa is in the Sudden Onrush state or Fiery Passion state, she will always be counted as being in the Nightsoul's Blessing state.</p><p>Has 2 charges. When Varesa enters the Fiery Passion state, she will obtain an additional Tap charge of her Elemental Skill and its DMG will be increased.</p><p>Fiery Passion · While not in the Fiery Passion state, Varesa can use Plunging Attacks to gain Nightsoul points. She will enter Fiery Passion when she reaches maximum Nightsoul points via this method, or when she uses her Elemental Burst Guardian Vent! · While in the Fiery Passion state, her Normal Attacks, Elemental Skill, and Elemental Burst will gain unique buffs. She can also use a special Elemental Burst shortly after using a Plunging Attack. · The Fiery Passion state lasts for up to 15s and will end when she runs out of Nightsoul points or after she leaves combat for a period of time.</p><p><i>\"Right now, I'm my own hero.\"</i></p>" },
  "varesa_tag_team_triple_jump": { title: "Tag-Team Triple Jump!" },
  "varesa_tag_team_triple_jump_1": { description: "After using the Elemental Skill Riding the Night-Rainbow, Varesa gains \"Rainbow Crash\" for 5s. During this time, when Varesa uses a Plunging Attack, the shockwave DMG dealt when she hits the ground is increased by {text_percent} of her ATK. The Rainbow Crash effect will be canceled once a ground impact hits an opponent, or when its duration expires." },
  "varesa_tag_team_triple_jump_2": { description: "If Varesa is in the Fiery Passion state, this ground impact DMG is increased by {text_percent} of her ATK instead." },
  "varesa_the_courage_to_press_on": { title: "The Courage to Press On" },
  "varesa_the_courage_to_press_on_1": { description: "Varesa will receive various buffs based on her state when using her Elemental Burst Guardian Vent! If Varesa: · Has neither Fiery Passion nor Apex Drive active, she will gain Diligent Refinement for 15s, which will increase her Plunging Attack ground impact DMG by {text_percent} of her ATK, with a maximum increase of {text_value_max} DMG. This effect will be canceled once the ground impact hits an opponent, or if its duration ends." },
  "varesa_the_courage_to_press_on_2": { description: "Varesa will receive various buffs based on her state when using her Elemental Burst Guardian Vent! If Varesa: · If she has either Fiery Passion or Apex Drive active, this instance of her Elemental Burst Guardian Vent! deals {dmg_burst_varesa} increased DMG." },
  "varesa_the_hero_twice_returned": { title: "The Hero Twice-Returned!", description: "When a nearby party member triggers a Nightsoul Burst, Varesa's ATK increases by {atk_percent} for 12s. Max 2 stacks. Each stack's duration is counted independently." },
  "varesa_thoughts_floating_on_the_warm_breeze": { title: "Thoughts Floating on the Warm Breeze" },
  "varesa_unbowed_resolve": { title: "Unbowed Resolve" },
  "varesa_undying_passion": { title: "Undying Passion", description: "The effects of the Passive Talent \"Tag-Team Triple Jump!\" are enhanced: When performing the Special Plunging Attack \"Thunderous Tornado Eruption,\" Varesa will also gain \"Rainbow Crash\" for 5s. When \"Rainbow Crash\" is in effect, Varesa's Plunging Attack ground impact DMG is increased by {text_percent} of her ATK, whether she is in the Fiery Passion state or not. You must first unlock the Passive Talent \"Tag-Team Triple Jump!\" to access the above effect. Additionally, when Varesa is in the Sudden Onrush mode of her Nightsoul's Blessing, she consumes 30% less Nightsoul points or Phlogiston." },
  "venti_breeze_of_reminiscence": { title: "Breeze of Reminiscence" },
  "venti_breeze_of_reminiscence_1": { description: "Skyward Sonnet decreases opponents' Anemo RES and Physical RES by {enemy_res_anemo} for 10s." },
  "venti_breeze_of_reminiscence_2": { description: "Opponents launched by Skyward Sonnet suffer an additional {enemy_res_anemo} Anemo RES and Physical RES decrease while airborne." },
  "venti_concerto_dal_cielo": { title: "Concerto dal Cielo" },
  "venti_divine_marksmanship": { title: "Divine Marksmanship", description: "<p>Normal Attack Performs up to 6 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, favorable winds will accumulate on the arrowhead. A fully charged wind arrow will deal Anemo DMG.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "venti_embrace_of_winds": { title: "Embrace of Winds", description: "Holding Skyward Sonnet creates an upcurrent that lasts for 20s." },
  "venti_hurricane_of_freedom": { title: "Hurricane of Freedom", description: "When Venti picks up an Elemental Orb or Particle, he receives a {dmg_anemo} Anemo DMG Bonus for 10s." },
  "venti_ode_to_thousand_winds": { title: "Ode to Thousand Winds" },
  "venti_skyward_sonnet": { title: "Skyward Sonnet", description: "<p>O wind upon which all hymns and songs fly, bear these earth-walkers up into the sky!</p><p>Press Summons a Wind Domain at the opponent's location, dealing AoE Anemo DMG and launching opponents into the air.</p><p>Hold Summons an even larger Wind Domain with Venti as the epicenter, dealing AoE Anemo DMG and launching affected opponents into the air. After unleashing the Hold version of this ability, Venti rides the wind into the air.</p><p>Opponents hit by Skyward Sonnet will fall to the ground slowly.</p><p><i>In the days when gods and men walked the earth together, the heavens were filled with countless songs. This melody has long since been forgotten.</i></p>" },
  "venti_splitting_gales": { title: "Splitting Gales", description: "Fires 2 additional arrows per Aimed Shot, each dealing {text_percent_dmg} of the original arrow's DMG." },
  "venti_storm_of_defiance": { title: "Storm of Defiance" },
  "venti_storm_of_defiance_1": { description: "Targets who take DMG from Wind's Grand Ode have their Anemo RES decreased by {enemy_res_anemo}." },
  "venti_storm_of_defiance_2": { description: "If an Elemental Absorption occurred, then their RES towards the corresponding Element is also decreased by 20%." },
  "venti_stormeye": { title: "Stormeye", description: "Regenerates 15 Energy for Venti after the effects of Wind's Grand Ode end. If an Elemental Absorption occurred, this also restores 15 Energy to all characters of that corresponding element in the party." },
  "venti_winds_grand_ode": { title: "Wind's Grand Ode", description: "<p>Fires off an arrow made of countless coalesced winds, creating a huge Stormeye that sucks in opponents and deals continuous Anemo DMG.</p><p>Elemental Absorption If the Stormeye comes into contact with Hydro/Pyro/Cryo/Electro, it will deal additional elemental DMG of that type. Elemental Absorption may only occur once per use.</p><p><i>Many hymns written in praise of the Anemo Archon have been lost to time. This one sings of his mastery over the wind.</i></p>" },
  "wanderer_ancient_illuminator_from_abroad": { title: "Matsuban: Ancient Illuminator From Abroad" },
  "wanderer_five_ceremonial_plays": { title: "Kyougen: Five Ceremonial Plays", description: "<p>Compresses the atmosphere into a singular vacuum that grinds all troubles away, dealing multiple instances of AoE Anemo DMG. If the character is in the Windfavored state due to the skill \"Hanega: Song of the Wind,\" Windfavored state will end after casting.</p><p><i>\"Bright be the narrowed gaze of the sky, casting its sight on dreams both past and present, like radiance washing over dust on the winds.\"</i></p>" },
  "wanderer_gales_of_reverie": { title: "Gales of Reverie", description: "When the Wanderer hits opponents with Kuugo: Fushoudan or Kuugo: Toufukai in his Windfavored state, he has a 16% chance to obtain the Descent effect: The next time the Wanderer accelerates in mid-air while in this instance of the Windfavored state, this effect will be removed, this acceleration instance will not consume any Kuugoryoku Points, and he will fire off 4 wind arrows that deal {text_percent_dmg} of his ATK as Anemo DMG each. For each Kuugo: Fushoudan and Kuugo: Toufukai that does not produce this effect, the next attack of those types will have a 12% increased chance of producing it. The calculation of the effect production is done once every 0.1s." },
  "wanderer_isle_amidst_white_waves": { title: "Niban: Isle Amidst White Waves", description: "When in the Windfavored state, Kyougen: Five Ceremonial Plays will see its DMG increased by 4% per point of difference between the max amount of Kuugoryoku Points contrasted with Kuugoryoku's present capacity when using this skill. Through this method, you can increase Kyougen: Five Ceremonial Plays's DMG by a maximum of 200%." },
  "wanderer_jade_claimed_flower": { title: "Jade-Claimed Flower", description: "If Song of the Wind comes into contact with Hydro/Pyro/Cryo/Electro when it is unleashed, this instance of the Windfavored state will obtain buffs according to the contacted element(s): ·Hydro: Kuugoryoku Point cap increases by 20. ·Pyro: ATK increases by 30%. ·Cryo: CRIT Rate increases by 20%. ·Electro: When Normal and Charged Attacks hit an opponent, 0.8 Energy will be restored. Energy can be restored this way once every 0.2s. You can have up to 2 different kinds of these buffs simultaneously." },
  "wanderer_moonflower_kusemai": { title: "Sanban: Moonflower Kusemai" },
  "wanderer_ostentatious_plumage": { title: "Shoban: Ostentatious Plumage", description: "When in the Windfavored state, the Attack SPD of the Wanderer's Kuugo: Fushoudan and Kuugo: Toufukai is increased by {atk_speed_normal}. Additionally, the wind arrows fired by the Passive Talent \"Gales of Reverie\" will deal an additional {text_percent_dmg} of his ATK as DMG. You must unlock the Passive Talent \"Gales of Reverie\" first." },
  "wanderer_set_adrift_into_spring": { title: "Yonban: Set Adrift into Spring", description: "When casting Song of the Wind, should the Passive Talent \"Jade-Claimed Flower\" be triggered, the character will gain buffs in correspondence to the contacted Elemental Type(s), and also obtain a random untriggered buff. A maximum of 3 such corresponding elemental buffs can exist simultaneously. You must unlock the Passive Talent \"Jade-Claimed Flower\" first." },
  "wanderer_song_of_the_wind": { title: "Hanega: Song of the Wind", description: "<p>Concentrates the power of the winds to break free from the shackles of the earth, dealing AoE Anemo DMG before leaping into the air and entering the Windfavored state.</p><p>Windfavored The Wanderer cannot perform Plunging Attacks in this state. When he uses Normal and Charged Attacks, they will be converted into Kuugo: Fushoudan and Kuugo: Toufukai respectively; the DMG they deal and their AoE will be increased, and their DMG will be considered Normal and Charged Attack DMG respectively. Kuugo: Toufukai will not consume Stamina. The Wanderer will hover persistently during this time. While this state is active, the Wanderer's movements gain the following properties: ·Persistently consumes Kuugoryoku Points to maintain this hovering state. ·When sprinting, additional Kuugoryoku Points will be consumed for the Wanderer to accelerate mid-air. Holding sprint will cause persistent Kuugoryoku Point consumption to maintain speed. This effect will replace his default sprint. ·Jumping expends extra Kuugoryoku Points to increase hovering height. Holding jump will cause persistent Kuugoryoku Point consumption to keep increasing hovering height.</p><p>Running out of Kuugoryoku Points will end the Windfavored state. A second cast during the duration of Windfavored will also end it.</p><p><i>\"The world dances in a weightless whirl, presenting a secret that can only be found in the flowers.\"</i></p>" },
  "wanderer_the_curtains_melancholic_sway": { title: "Shugen: The Curtains' Melancholic Sway", description: "When the Wanderer actively hits an opponent with Kuugo: Fushoudan while in the Windfavored state, the following effects will occur: ·Deals an additional instance of Kuugo: Fushoudan at the position hit, dealing {text_percent_dmg} of the attack's original DMG. This DMG will be considered Normal Attack DMG. ·When the Wanderer falls below 40 Kuugoryoku Points, restores 4 Points to him. Kuugoryoku Points can be restored in this manner once every 0.2s. This restoration can occur up to 5 times within one Windfavored duration." },
  "wanderer_windfavored": { title: "Windfavored", description: "The Wanderer cannot perform Plunging Attacks in this state. When he uses Normal and Charged Attacks, they will be converted into Kuugo: Fushoudan and Kuugo: Toufukai respectively; the DMG they deal and their AoE will be increased, and their DMG will be considered Normal and Charged Attack DMG respectively." },
  "wanderer_yuuban_meigen": { title: "Yuuban Meigen", description: "<p>Normal Attack Performs up to 3 attacks using wind blades, dealing Anemo DMG.</p><p>Charged Attack Consumes a certain amount of Stamina, gathers a build up of high wind pressure, and deals AoE Anemo DMG after a short casting time.</p><p>Plunging Attack Calling upon the power of Anemo, the Wanderer plunges towards the ground from mid-air, damaging all opponents in his path. Deals AoE Anemo DMG upon impact with the ground.</p>" },
  "weapon_alley_flash": { title: "Itinerant Hero", description: "Increases DMG dealt by the character equipping this weapon by {dmg_all}. Taking DMG disables this effect for 5s." },
  "weapon_alley_hunter": { title: "Urban Guerrilla", description: "While the character equipped with this weapon is in the party but not on the field, their DMG increases by {dmg_all} every second up to a max of {text_percent_max}. When the character is on the field for more than 4s, the aforementioned DMG buff decreases by {text_percent_reduce} per second until it reaches 0%." },
  "weapon_amenoma_kageuta_blade": { title: "Iwakura Succession", description: "After casting an Elemental Skill, gain 1 Succession Seed. This effect can be triggered once every 5s. The Succession Seed lasts for 30s. Up to 3 Succession Seeds may exist simultaneously. After using an Elemental Burst, all Succession Seeds are consumed and after 2s, the character regenerates {text_decimal} Energy for each seed consumed." },
  "weapon_amos_bow": { title: "Strong-Willed", description: "After a Normal or Charged Attack is fired, DMG dealt increases by a further {dmg_normal} every 0.1 seconds up to 5 times." },
  "weapon_amos_bow_passive": { description: "Increases Normal and Charged Attack DMG by {dmg_normal}." },
  "weapon_aquila_favonia": { title: "Falcon's Defiance", description: "Triggers on taking DMG: the soul of the Falcon of the West awakens, holding the banner of resistance aloft, regenerating HP equal to {text_percent_hp} of ATK and dealing {text_percent_dmg} of ATK as DMG to surrounding opponents. This effect can only occur once every 15s." },
  "weapon_bane_flame_water": { title: "Bane of Flame and Water", description: "Increases DMG against opponents affected by Hydro or Pyro by {dmg_all}." },
  "weapon_bane_of_fire_and_thunder": { title: "Bane of Fire and Thunder", description: "Increases DMG against enemies affected by Pyro or Electro by {dmg_all}." },
  "weapon_bane_of_flame_and_water": { title: "Bane of Flame and Water", description: "Increases DMG against opponents affected by Hydro or Pyro by {dmg_all}." },
  "weapon_bane_of_storm_and_tide": { title: "Bane of Storm and Tide", description: "Increases DMG against opponents affected by Hydro or Electro by {dmg_all}." },
  "weapon_bane_of_water_and_ice": { title: "Bane of Water and Ice", description: "Increases DMG against opponents affected by Hydro or Cryo by {dmg_all}." },
  "weapon_black_sword": { title: "Justice", description: "Increases DMG dealt by Normal and Charged Attacks by {dmg_normal}. Additionally, regenerates {text_percent} of ATK as HP when Normal and Charged Attacks score a CRIT Hit. This effect can occur once every 5s." },
  "weapon_black_tassel": { title: "Bane of the Soft", description: "Increases DMG against slimes by {dmg_all}." },
  "weapon_calamity_queller": { title: "Extinguishing Precept", description: "Gain {dmg_pyro} All Elemental DMG Bonus." },
  "weapon_calamity_queller_2": { description: "Obtain Consummation for 20s after using an Elemental Skill, causing ATK to increase by {atk_percent} per second. This ATK increase has a maximum of 6 stacks." },
  "weapon_calamity_queller_3": { description: "When the character equipped with this weapon is not on the field, Consummation's ATK increase is doubled." },
  "weapon_catch": { title: "Shanty", description: "Increases Elemental Burst DMG by {dmg_burst} and Elemental Burst CRIT Rate by {crit_rate_burst}." },
  "weapon_cinnabar_spindle": { title: "Spotless Heart", description: "Elemental Skill DMG is increased by {text_percent} of DEF. The effect will be triggered no more than once every 1.5s and will be cleared 0.1s after the Elemental Skill deals DMG." },
  "weapon_compound_bow": { title: "Infusion Arrow", description: "Normal Attack and Charged Attack hits increase ATK by{atk_percent} and Normal ATK SPD by {atk_speed_normal} for 6s. Max 4 stacks. Can only occur once every 0.3s." },
  "weapon_courage": { title: "Courage", description: "On hit, Normal or Charged Attacks increase ATK by {atk_percent} for 6s. Max 4 stacks. Can only occur once every 0.5s." },
  "weapon_crescent_pike": { title: "Infusion Needle", description: "After picking up an Elemental Orb/Particle, Normal and Charged Attacks deal an additional {text_percent} ATK as DMG for 5s." },
  "weapon_cull_the_weal": { title: "Cull the Weak", description: "Defeating an opponent restores {text_percent} HP." },
  "weapon_dark_iron_sword": { title: "Overloaded", description: "Upon causing an Overloaded, Superconduct, Electro-Charged, Quicken, Aggravate, Hyperbloom, or Electro-infused Swirl reaction, ATK is increased by {atk_percent} for 12s." },
  "weapon_deathmatch_1": { title: "Gladiator (at least 2 opponents nearby)", description: "If there are at least 2 opponents nearby, ATK is increased by {atk_percent} and DEF is increased by {def_percent}." },
  "weapon_deathmatch_2": { title: "Gladiator (less than 2 opponents nearby)", description: "If there are less than 2 opponents nearby, ATK is increased by {atk_percent}." },
  "weapon_debate_club": { title: "Blunt Conclusion", description: "After using an Elemental Skill, on hit, Normal and Charged Attacks deal additional DMG equal to {text_percent_dmg} of ATK in a small AoE. Effect lasts 15s. DMG can only occur once every 3s." },
  "weapon_demon_slayer_bow": { title: "Full Draw" },
  "weapon_demon_slayer_bow_1": { description: "Increases Normal Attack DMG by {dmg_normal} and Charged ATK DMG by {dmg_charged}.;Increases Normal Attack DMG by {dmg_normal} and Charged ATK DMG by {dmg_charged}." },
  "weapon_demon_slayer_bow_2": { description: "When the equipping character's Energy reaches 100%, this effect is increased by 100%." },
  "weapon_dodoco_tales": { title: "Dodoco Tales" },
  "weapon_dodoco_tales_1": { description: "Normal Attack hits on opponents increase Charged Attack DMG by {dmg_charged} for 6s." },
  "weapon_dodoco_tales_2": { description: "Charged Attack hits on opponents increase ATK by {atk_percent} for 6s." },
  "weapon_elegy_for_the_end": { title: "Millennial Movement: Farewell Song", description: "Increases Elemental Mastery by {text_value} and increases ATK by {text_percent}. Once this effect is triggered, you will not gain Sigils of Remembrance for 20s. Of the many effects of the \"Millennial Movement,\" buffs of the same type will not stack." },
  "weapon_elegy_for_the_end_passive": { title: "The Parting Refrain", description: "A part of the \"Millennial Movement\" that wanders amidst the winds. Increases Elemental Mastery by {mastery}. When the Elemental Skills or Elemental Bursts of the character wielding this weapon hit opponents, that character gains a Sigil of Remembrance. This effect can be triggered once every 0.2s and can be triggered even if said character is not on the field. When you possess 4 Sigils of Remembrance, all of them will be consumed and all nearby party members will obtain the \"Millennial Movement: Farewell Song\" effect for 12s." },
  "weapon_emerald_orb": { title: "Rapids", description: "Upon causing a Vaporize, Electro-Charged, Frozen, Bloom, or a Hydro-infused Swirl reaction, increases ATK by {atk_percent} for 12s." },
  "weapon_everlasting_moonglow": { title: "Byakuya Kougetsu" },
  "weapon_everlasting_moonglow_1": { description: "Healing Bonus increased by {healing}, Normal Attack DMG is increased by {normal_base_hp_percent} of the Max HP of the character equipping this weapon." },
  "weapon_everlasting_moonglow_2": { description: "For 12s after using an Elemental Burst, Normal Attacks that hit opponents will restore 0.6 Energy. Energy can be restored this way once every 0.1s." },
  "weapon_eye_of_perception": { title: "Echo", description: "Normal and Charged Attacks have a {text_percent_chance} chance to fire a Bolt of Perception, dealing {text_percent_dmg} ATK as DMG. This bolt can bounce between opponents a maximum of 4 times. This effect can occur once every {text_cd}s." },
  "weapon_fading_twilight_1": { title: "Evengleam" },
  "weapon_fading_twilight_2": { title: "Afterglow" },
  "weapon_fading_twilight_3": { title: "Dawnblaze" },
  "weapon_fading_twilight_dmg": { description: "Increase DMG dealt by {dmg_all}" },
  "weapon_favonoius_passive": { title: "Windfall", description: "CRIT Hits have a {text_percent} chance to generate a small amount of Elemental Particles, which will regenerate 6 Energy for the character. Can only occur once every {text_cooldown}s." },
  "weapon_festering_desire": { title: "Undying Admiration", description: "Increases Elemental Skill DMG by {dmg_skill} and Elemental Skill CRIT Rate by {crit_rate_skill}." },
  "weapon_fillet_blade": { title: "Gash", description: "On hit, has a 50% chance to deal {text_percent_dmg} ATK DMG to a single opponent. Can only occur once every 15s." },
  "weapon_flute": { title: "Chord", description: "Normal or Charged Attacks grant a Harmonic on hits. Gaining 5 Harmonics triggers the power of music and deals {text_percent_dmg} ATK DMG to surrounding opponents. Harmonics last up to 30s, and a maximum of 1 can be gained every 0.5s." },
  "weapon_focus": { title: "Focus", description: "Upon dealing damage to an opponent, increases CRIT Rate by {crit_rate}. Max 5 stacks. A CRIT hit removes all existing stacks." },
  "weapon_freedom_sworn": { title: "Millennial Movement: Song of Resistance", description: "Increases Normal, Charged and Plunging Attack DMG by {text_percent_2} and increases ATK by {text_percent}. Once this effect is triggered, you will not gain Sigils of Rebellion for 20s. Of the many effects of the \"Millennial Movement,\" buffs of the same type will not stack." },
  "weapon_freedom_sworn_passive": { title: "Revolutionary Chorale", description: "A part of the \"Millennial Movement\" that wanders amidst the winds. Increases DMG by {dmg_all}. When the character wielding this weapon triggers Elemental Reactions, they gain a Sigil of Rebellion. This effect can be triggered once every 0.5s and can be triggered even if said character is not on the field. When you possess 2 Sigils of Rebellion, all of them will be consumed and all nearby party members will obtain \"Millennial Movement: Song of Resistance\" for 12s." },
  "weapon_frost_burial": { title: "Frost Burial", description: "Opponents affected by Cryo are dealt {text_percent_dmg} ATK DMG instead by the icicle." },
  "weapon_frost_burial_passive": { description: "Hitting an opponent with Normal and Charged Attacks has a {text_percent_chance} chance of forming and dropping an Everfrost Icicle above them, dealing AoE DMG equal to {text_percent_dmg} of ATK." },
  "weapon_golden_majesty": { title: "Golden Majesty", description: "Scoring hits on opponents increases ATK by {atk_percent} for 8s." },
  "weapon_golden_majesty_passive": { description: "Increases Shield Strength by {shield}." },
  "weapon_golden_majesty_shield": { description: "While protected by a shield, this ATK increase effect is increased by 100%." },
  "weapon_grasscutters_light": { title: "Timeless Dream: Eternal Stove" },
  "weapon_grasscutters_light_1": { description: "ATK increased by {text_percent} of Energy Recharge over the base 100%. You can gain a maximum bonus of {text_percent_max} ATK." },
  "weapon_grasscutters_light_2": { description: "Gain {recharge} Energy Recharge for 12s after using an Elemental Burst." },
  "weapon_halberd": { title: "Heavy", description: "Normal Attacks deal an additional {text_percent_dmg} ATK as DMG. Can only occur once every 10s." },
  "weapon_harbinger_of_dawn": { title: "Vigorous", description: "When HP is above 90%, increases CRIT Rate by {crit_rate}." },
  "weapon_infusion_blade": { title: "Infusion Blade", description: "On hit, Normal or Charged Attacks increase ATK and DEF by {atk_percent} for 6s. Max 4 stacks. Can only occur once every 0.5s." },
  "weapon_iron_sting": { title: "Infusion Stinger", description: "Dealing Elemental DMG increases all DMG by {dmg_all} for 6s. Max 2 stacks. Can only occur once every 1s." },
  "weapon_kagotsurube_isshin": { title: "Isshin Art Clarity", description: "When a Normal, Charged, or Plunging Attack hits an opponent, it will whip up a Hewing Gale, dealing AoE DMG equal to {text_percent} of ATK and increasing ATK by {atk_percent} for 8s. This effect can be triggered once every 8s." },
  "weapon_kaguras_verity": { title: "Kagura Dance of the Sacred Sakura" },
  "weapon_kaguras_verity_1": { description: "Gains the Kagura Dance effect when using an Elemental Skill, causing the Elemental Skill DMG of the character wielding this weapon to increase by {dmg_skill} for 12s. Max 3 stacks." },
  "weapon_kaguras_verity_2": { description: "This character will gain {dmg_pyro} All Elemental DMG Bonus when they possess 3 stacks." },
  "weapon_lithic_axiome": { title: "Lithic Axiom - Unity", description: "For every character in the party who hails from Liyue, the character who equips this weapon gains {atk_percent} ATK increase and {crit_rate} CRIT Rate increase. This effect stacks up to 4 times ({weapon_lithic_stacks})." },
  "weapon_lithic_axiome_liyue": { title: "Current character is from Liyue" },
  "weapon_lost_prayer": { title: "Boundless Blessing", description: "When in battle, gain an {dmg_pyro} Elemental DMG Bonus every 4s. Max 4 stacks. Lasts until the character falls or leaves combat." },
  "weapon_luxurious_sea_lord": { title: "Oceanic Victory", description: "Increases Elemental Burst DMG by {dmg_burst}. When Elemental Burst hits opponents, there is a 100% chance of summoning a titanic tuna that charges and deals {text_percent_dmg} ATK as AoE DMG. This effect can occur once every 15s." },
  "weapon_mappa_mare": { title: "Infusion Scroll", description: "Triggering an Elemental reaction grants a {dmg_pyro} Elemental DMG Bonus for 10s. Max 2 stacks." },
  "weapon_messenger": { title: "Archer's Message", description: "Charged Attack hits on weak points deal an additional {text_percent_dmg} ATK DMG as CRIT DMG. Can only occur once every 10s." },
  "weapon_mistsplitters_reforged": { title: "Mistsplitter's Edge" },
  "weapon_mistsplitters_reforged_1": { description: "Gain a {dmg_pyro} Elemental DMG Bonus for all element and receive the might of the Mistsplitter's Emblem." },
  "weapon_mistsplitters_reforged_2": { description: "At stack levels 1/2/3, the Mistsplitter's Emblem provides a {dmg_own} Elemental DMG Bonus for the character's Elemental Type. The character will obtain 1 stack of Mistsplitter's Emblem in each of the following scenarios: • Normal Attack deals Elemental DMG (stack lasts 5s) • casting Elemental Burst (stack lasts 10s) • Energy is less than 100% (stack disappears when Energy is full). Each stack's duration is calculated independently." },
  "weapon_mitternachts_waltz": { title: "Evernight Duet" },
  "weapon_mitternachts_waltz_1": { description: "Normal Attack hits on opponents increase Elemental Skill DMG by {dmg_skill} for 5s." },
  "weapon_mitternachts_waltz_2": { description: "Elemental Skill hits on opponents increase Normal Attack DMG by {dmg_normal} for 5s." },
  "weapon_oathsworn_eye": { title: "People of the Faltering Light", description: "Increases Energy Recharge by {recharge} for 10s after using an Elemental Skill." },
  "weapon_otherworldly_story": { title: "Energy Shower", description: "Picking up an Elemental Energy Orb/Particle recovers {text_percent_hp} HP." },
  "weapon_polar_star": { title: "Daylight's Augury" },
  "weapon_polar_star_1": { description: "Elemental Skill and Elemental Burst DMG increased by {dmg_burst}." },
  "weapon_polar_star_2": { description: "After a Normal Attack, Charged Attack, Elemental Skill or Elemental Burst hits an opponent, 1 stack of Ashen Nightstar will be gained for 12s. When effect of Ashen Nightstar is present, ATK is increased by {atk_percent}. The stack of Ashen Nightstar created by the Normal Attack, Charged Attack, Elemental Skill or Elemental Burst will be counted independently of the others." },
  "weapon_press_the_advantage": { title: "Press the Advantage", description: "After defeating an opponent, ATK is increased by {atk_percent} for 30s. This effect has a maximum of 3 stacks, and the duration of each stack is independent of the others." },
  "weapon_primordial_jade_cutter": { title: "Protector's Virtue", description: "HP increased by {hp_percent}. Additionally, provides an ATK Bonus based on {text_percent} of the wielder's Max HP." },
  "weapon_prototype_amber": { title: "Gilding", description: "Using an Elemental Burst regenerates {text_decimal} Energy every 2s for 6s. All party members will regenerate {text_percent} HP every 2s for this duration." },
  "weapon_prototype_archaic": { title: "Crush", description: "On hit, Normal or Charged Attacks have a {text_percent_chance} chance to deal an additional {text_percent_dmg} ATK DMG to opponents within a small AoE. Can only occur once every 15s." },
  "weapon_prototype_crescent": { title: "Unreturning", description: "Charged Attack hits on weak points increase Movement SPD by {move_speed} and ATK by {atk_percent} for 10s." },
  "weapon_prototype_rancour": { title: "Smashed Stone", description: "On hit, Normal or Charged Attacks increase ATK and DEF by {atk_percent} for 6s. Max 4 stacks. Can only occur once every 0.3s." },
  "weapon_rebellious_guardian": { title: "Rebellious Guardian", description: "While protected by the shield, the character gains {dmg_all} increased DMG." },
  "weapon_rebellious_guardian_passive": { description: "Taking DMG generates a shield which absorbs DMG up to {text_percent_hp} of Max HP. This shield lasts for 10s or until broken, and can only be triggered once every 45s." },
  "weapon_redhorn_stonethresher": { title: "Gokadaiou Otogibanashi", description: "DEF is increased by {def_percent}. Normal and Charged Attack DMG is increased by {normal_base_def_percent} of DEF." },
  "weapon_royal_avg_crit_rate": { title: "Average Crit Rate bonus", description: "Use Crit Rate increase corresponding to average activation chance of Focus" },
  "weapon_rust_passive": { title: "Rapid Firing", description: "Increases Normal Attack DMG by {dmg_normal} but decreases Charged Attack DMG by {text_percent}." },
  "weapon_sacrificial_passive": { title: "Composed", description: "After damaging an opponent with an Elemental Skill, the skill has a {text_percent} chance to end its own CD. Can only occur once every {text_cooldown}s." },
  "weapon_samurai_conduct": { title: "Samurai Conduct" },
  "weapon_samurai_conduct_1": { description: "Increases Elemental Skill DMG by {dmg_skill}." },
  "weapon_samurai_conduct_2": { description: "After Elemental Skill hits an opponent, lose 3 Energy but regenerate {text_decimal} Energy every 2s for the next 6s. This effect can occur once every 10s. Can be triggered even when the character is not on the field." },
  "weapon_sharpshooter_oath": { title: "Precise", description: "Increases DMG against weak spots by {dmg_weak}. Shots to weak spots can be activated at Enemy tab." },
  "weapon_skyrider_sword": { title: "Determination", description: "Using an Elemental Burst grants a {atk_percent} increase in ATK and Movement SPD for 15s." },
  "weapon_skyward_atlas": { title: "Wandering Clouds", description: "Increases Elemental DMG Bonus by {dmg_pyro}." },
  "weapon_skyward_blade": { title: "Sky-Piercing Fang", description: "Gains Skypiercing Might upon using Elemental Burst: Increases Movement SPD by {move_speed}, increases ATK SPD by {atk_speed_normal}, and Normal and Charged hits deal additional DMG equal to {text_percent} of ATK. Skypiercing Might lasts for 12s." },
  "weapon_skyward_harp": { title: "Echoing Ballad", description: "Hits have a {text_percent_chance} chance to inflict a small AoE attack, dealing {text_percent_dmg} Physical ATK DMG. Can only occur once every {text_decimal_cd}s." },
  "weapon_skyward_pride": { title: "Sky-ripping Dragon Spine", description: "Increases all DMG by {dmg_all}." },
  "weapon_skyward_spine": { title: "Black Wing", description: "Increases CRIT Rate by {crit_rate} and increases Normal ATK SPD by {atk_speed_normal}." },
  "weapon_skyward_spine_2": { description: "Normal and Charged Attacks hits on opponents have a 50% chance to trigger a vacuum blade that deals {text_percent} of ATK as DMG in a small AoE. This effect can occur no more than once every 2s." },
  "weapon_slingshot": { title: "Slingshot", description: "If a Normal or Charged Attack hits a target within 0.3s of being fired, increases DMG by {text_percent}. Otherwise, decreases DMG by 10%." },
  "weapon_solar_pearl": { title: "Solar Shine" },
  "weapon_solar_pearl_1": { description: "Normal Attack hits increase Elemental Skill and Elemental Burst DMG by {dmg_burst} for 6s." },
  "weapon_solar_pearl_2": { description: "Elemental Skill or Elemental Burst hits increase Normal Attack DMG by {dmg_normal} for 6s." },
  "weapon_song_of_broken_pines": { title: "Millennial Movement: Banner-Hymn", description: "Increases Normal ATK SPD by {text_percent_2} and increases ATK by {text_percent}. Once this effect is triggered, you will not gain Sigils of Whispers for 20s. Of the many effects of the \"Millennial Movement\" buffs of the same type will not stack." },
  "weapon_song_of_broken_pines_passive": { title: "Rebel's Banner-Hymn", description: "Increases ATK by {atk_percent}, and when Normal or Charged Attacks hit opponents, the character gains a Sigil of Whispers. This effect can be triggered once every 0.3s. When you possess 4 Sigils of Whispers, all of them will be consumed and all nearby party members will obtain the \"Millennial Movement: Banner-Hymn\" effect for 12s." },
  "weapon_staff_of_homa": { title: "Reckless Cinnabar", description: "When the wielder's HP is less than 50%, this ATK bonus is increased by an additional {text_percent} of Max HP." },
  "weapon_staff_of_homa_passive": { description: "HP increased by {hp_percent}. Additionally, provides an ATK Bonus based on {text_percent} of the wielder's Max HP." },
  "weapon_stringless": { title: "Arrowless Song", description: "Increases Elemental Skill and Elemental Burst DMG by {dmg_burst}." },
  "weapon_talent_unknown": { title: "???" },
  "weapon_thrilling_tales": { title: "Heritage", description: "When switching characters, the new character taking the field has their ATK increased by {text_percent} for 10s. This effect can only occur once every 20s." },
  "weapon_thundering_pulse": { title: "Rule by Thunder", description: "Increases ATK by {atk_percent} and grants the might of the Thunder Seal." },
  "weapon_thundering_pulse_2": { description: "At stack levels 1/2/3, the Thunder Seal increases Normal Attack DMG by {dmg_normal}. The character will obtain 1 stack of Thunder Seal in each of the following scenarios: • Normal Attack deals DMG (stack lasts 5s) • Casting Elemental Skill (stacks lasts 10s) • Energy is less than 100% (stack disappears when Energy is full) Each stack's duration is calculated independently." },
  "weapon_travelers_handy_sword": { title: "Journey", description: "Each Elemental Orb or Particle collected restores {text_percent_hp} HP." },
  "weapon_twin_nephrite": { title: "Guerilla Tactic", description: "Defeating an opponent increases Movement SPD and ATK by {atk_percent} for 15s." },
  "weapon_unbending": { title: "Unbending", description: "When HP falls below {text_percent_hp}, increases Charged Attack DMG by {dmg_charged}, and Charged Attacks become much harder to interrupt." },
  "weapon_viridescent_hunt": { title: "Verdant Wind", description: "Upon hit, Normal and Aimed Shot Attacks have a {text_percent_chance} chance to generate a Cyclone, which will continuously attract surrounding opponents, dealing {text_percent_dmg} of ATK as DMG to these opponents every 0.5s for 4s. This effect can only occur once every {text_number_cd}s." },
  "weapon_watatsumi_wavewalker": { title: "Watatsumi Wavewalker", description: "For every point of the entire party's combined maximum Energy capacity, the Elemental Burst DMG of the character equipping this weapon is increased by {text_percent_bonus}. A maximum of {text_percent_cap} increased Elemental Burst DMG can be achieved this way." },
  "weapon_wavesplitter": { title: "Wavesplitter", description: "Every 4s a character is on the field, they will deal {dmg_all} more DMG and take {dmg_recieved} more DMG. This effect has a maximum of 5 stacks and will not be reset if the character leaves the field, but will be reduced by 1 stack when the character takes DMG." },
  "weapon_white_dragon_ring": { title: "Sakura Saiguu", description: "After the character equipped with this weapon triggers an Electro elemental reaction, nearby party members of an Elemental Type involved in the elemental reaction receive a {dmg_own} Elemental DMG Bonus for their element, lasting 6s. Elemental Bonuses gained in this way cannot be stacked." },
  "weapon_white_tassel": { title: "Sharp", description: "Increases Normal Attack DMG by {dmg_normal}." },
  "weapon_widsith": { title: "Debut", description: "When the character takes the field, they will gain a random theme song for 10s. This can only occur once every 30s." },
  "weapon_widsith_1": { title: "Recitative", description: "ATK is increased by {atk_percent}." },
  "weapon_widsith_2": { title: "Aria", description: "Increases all Elemental DMG by {dmg_pyro}." },
  "weapon_widsith_3": { title: "Interlude", description: "Elemental Mastery is increased by {mastery}." },
  "weapon_widsith_avg": { title: "Rough average", description: "All song themes bonuses divided by 9 are applied." },
  "weapon_windblume_ode": { title: "Windblume Wish", description: "After using an Elemental Skill, receive a boon from the ancient wish of the Windblume, increasing ATK by {atk_percent} for 6s." },
  "weapon_wine_and_song": { title: "Ever-Changing", description: "Hitting an opponent with a Normal Attack decreases the Stamina consumption of Sprint or Alternate Sprint by {text_percent} for 5s. Additionally, using a Sprint or Alternate Sprint ability increases ATK by {atk_percent} for 5s." },
  "weapon_wolfish_tracker": { title: "Wolfish Tracker", description: "On hit, attacks against opponents with less than 30% HP increase all party members' ATK by {atk_percent} for 12s. Can only occur once every 30s." },
  "wriothesley_darkgold_wolfbite": { title: "Darkgold Wolfbite", description: "<p>Activating his boxing gloves, Wriothesley strikes out with an icy straight, then uses Icicle Impact to cause multiple instances of AoE Cryo DMG in a frontal area.</p><p>Arkhe: Ousia After Icicle Impact ends, a Surging Blade will descend upon the opponent's position, dealing Ousia-aligned Cryo DMG.</p><p><i>There are some things that even the Duke of the Fortress of Meropide can do little about — for example, complicated paperwork, the trivialities of a supervisor, or even... little kids pasting a whole host of cute but difficult-to-remove stickers on his boxing gloves.</i></p>" },
  "wriothesley_esteem_for_the_innocent": { title: "Esteem for the Innocent", description: "The CRIT Rate of Rebuke: Vaulting Fist will be increased by {crit_rate_charged_wriothesley}, and its CRIT DMG by {crit_dmg_charged_wriothesley}. When unleashed, it will also create an additional icicle that deals 100% of Rebuke: Vaulting Fist's Base DMG as Cryo DMG. DMG dealt this way is regarded as Charged Attack DMG. You must first unlock the Passive Talent \"There Shall Be a Plea for Justice.\"" },
  "wriothesley_forceful_fists_of_frost": { title: "Forceful Fists of Frost", description: "<p>Normal Attack Coalescing frost about his fist, Wriothesley will unleash powerful Repelling Fists, performing up to 5 rapid attacks that deal Cryo DMG. Apart from this, Normal Attack combo count will not reset for a short time after using Icefang Rush or sprinting.</p><p>Charged Attack Consumes a fixed amount of Stamina to leap and unleash a Vaulting Fist, dealing AoE Cryo DMG.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE Cryo DMG upon impact.</p>" },
  "wriothesley_icefang_rush": { title: "Icefang Rush", description: "<p>Adjusting his breathing, rhythm, and pace, Wriothesley sprints forward a short distance, entering the Chilling Penalty state and unleashing more powerful attacks than before.</p><p>Chilling Penalty ·Increases Wriothesley's interruption resistance ·When his HP is above 50%, it will enhance the Repelling Fists of Normal Attack: Forceful Fists of Frost and increase its DMG. When such an attack hits, it will consume a fixed amount of Wriothesley's HP. HP can be lost this way once every 0.1s. This effect will be canceled should Wriothesley leave the field.</p><p><i>\"Past convictions are past. It is our future choices that we must grasp.\" \"Defy your fate, or else this glutton be, to pay your fate's due, by the crime and thee.\"</i></p>" },
  "wriothesley_mercy_for_the_wronged": { title: "Mercy for the Wronged" },
  "wriothesley_punishment_for_the_frauds": { title: "Punishment for the Frauds" },
  "wriothesley_redemption_for_the_suffering": { title: "Redemption for the Suffering" },
  "wriothesley_redemption_for_the_suffering_1": { description: "The HP restored to Wriothesley through Rebuke: Vaulting Fist will be increased to 50% of his Max HP. You must first unlock the Passive Talent \"There Shall Be a Plea for Justice.\" Additionally, when Wriothesley is healed, if the amount of healing overflows, the following effects will occur depending on whether he is on the field or not. These two methods of increasing ATK SPD cannot stack." },
  "wriothesley_redemption_for_the_suffering_2": { description: "If he is on the field, his ATK SPD will be increased by {atk_speed_normal} for 4s." },
  "wriothesley_redemption_for_the_suffering_3": { description: "If he is off-field, all of your own party members' ATK SPD will be increased by {atk_speed_normal} for 6s." },
  "wriothesley_redemption_for_the_suffering_4": { description: "Additionally, when Wriothesley is healed, if the amount of healing overflows, the following effects will occur depending on whether he is on the field or not. If he is off-field, all of your own party members' ATK SPD will be increased by {atk_speed_normal} for 6s." },
  "wriothesley_shackles_for_the_arrogant": { title: "Shackles for the Arrogant", description: "When using Darkgold Wolfbite, each Prosecution Edict stack from the Passive Talent \"There Shall Be a Reckoning for Sin\" will increase said ability's DMG dealt by {text_percent}. You must first unlock the Passive Talent \"There Shall Be a Reckoning for Sin.\"" },
  "wriothesley_terror_for_the_evildoers": { title: "Terror for the Evildoers", description: "The Gracious Rebuke from the Passive Talent \"There Shall Be a Plea for Justice\" is changed to this: When Wriothesley's HP is less than 60% or while he is in the Chilling Penalty state caused by Icefang Rush, when the fifth attack of Repelling Fists hits, it will create a Gracious Rebuke. 1 Gracious Rebuke effect can be obtained every 2.5s. Additionally, Rebuke: Vaulting Fist will obtain the following enhancement: ·The DMG Bonus gained will be further increased to {text_percent_dmg}. ·When it hits while Wriothesley is in the Chilling Penalty state, that state's duration is extended by 4s. 1 such extension can occur per 1 Chilling Penalty duration. You must first unlock the Passive Talent \"There Shall Be a Plea for Justice.\"" },
  "wriothesley_there_shall_be_a_plea_for_justice": { title: "There Shall Be a Plea for Justice", description: "When Wriothesley's HP is less than 60%, he will obtain a Gracious Rebuke. The next Charged Attack of his Normal Attack: Forceful Fists of Frost will be enhanced to become Rebuke: Vaulting Fist. It will not consume Stamina, will deal {dmg_charged_wriothesley} increased DMG, and after hitting will restore HP for Wriothesley equal to 30% of his Max HP. You can gain a Gracious Rebuke this way once every 5s." },
  "wriothesley_there_shall_be_a_reckoning_for_sin": { title: "There Shall Be a Reckoning for Sin", description: "When Wriothesley's current HP increases or decreases, if he is in the Chilling Penalty state conferred by Icefang Rush, Chilling Penalty will gain one stack of Prosecution Edict. Max 5 stacks. Each stack will increase Wriothesley's ATK by {atk_percent}." },
  "xiangling_beware_its_super_hot": { title: "Beware, It's Super Hot!", description: "When Guoba Attack's effect ends, Guoba leaves a chili pepper on the spot where it disappeared. Picking up a chili pepper increases ATK by {atk_percent} for 10s." },
  "xiangling_condensed_pyronado": { title: "Condensed Pyronado", description: "For the duration of Pyronado, all party members receive a {dmg_pyro} Pyro DMG Bonus." },
  "xiangling_crispy_outside_tender_inside": { title: "Crispy Outside, Tender Inside", description: "Opponents hit by Guoba's attacks have their Pyro RES reduced by {enemy_res_pyro} for 6s." },
  "xiangling_crossfire": { title: "Crossfire", description: "Increases the flame range of Guoba by {text_percent}." },
  "xiangling_deepfry": { title: "Deepfry" },
  "xiangling_dough_fu": { title: "Dough-Fu", description: "<p>Normal Attack Performs up to 5 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "xiangling_guoba_attack": { title: "Guoba Attack", description: "<p>Summons Guoba, who will continuously breathe fire at opponents, dealing AoE Pyro DMG.</p><p><i>Guoba loves to eat spicy food. Problem is, his stomach can't handle something this spicy.</i></p>" },
  "xiangling_guoba_mad": { title: "Guoba Mad" },
  "xiangling_oil_meets_fire": { title: "Oil Meets Fire", description: "The last attack in a Normal Attack sequence applies the Implode status onto the opponent for 2s. An explosion will occur once this duration ends, dealing {text_percent_dmg} of Xiangling's ATK as AoE Pyro DMG." },
  "xiangling_pyronado": { title: "Pyronado", description: "<p>Displaying her mastery over both fire and polearms, Xiangling sends a Pyronado whirling around her. The Pyronado will move with your character for the ability's duration, dealing Pyro DMG to all opponents in its path.</p><p><i>There will never be enough heat. Never.</i></p>" },
  "xiangling_slowbake": { title: "Slowbake", description: "Pyronado's duration is increased by {text_percent}." },
  "xianyun_aloof_from_the_world": { title: "Aloof From the World" },
  "xianyun_aloof_from_the_world_1": { description: "After using a Skyladder from White Clouds at Dawn, Xianyun's ATK will be increased by {atk_percent} for 15s." },
  "xianyun_aloof_from_the_world_2": { description: "Additionally, the effects of the Passive Talent \"Consider, the Adeptus in Her Realm\" will be enhanced: When the Starwicker created by Stars Gather at Dusk has Adeptal Assistance stacks, nearby active characters' Plunging Attack shockwave DMG will be increased by {text_percent_atk} of Xianyun's ATK. The maximum DMG increase that can be achieved this way is {text_value_max}. Each Plunging Attack shockwave DMG instance can only apply this increased DMG effect to a single opponent. Each character can trigger this effect once every 0.4s. You must first unlock the Passive Talent \"Consider, the Adeptus in Her Realm.\"" },
  "xianyun_astride_rose_colored_clouds": { title: "Astride Rose-Colored Clouds" },
  "xianyun_consider_the_adeptus_in_her_realm": { title: "Consider, the Adeptus in Her Realm", description: "When the Starwicker created by Stars Gather at Dusk has Adeptal Assistance stacks, nearby active characters' Plunging Attack shockwave DMG will be increased by {text_percent_atk} of Xianyun's ATK. The maximum DMG increase that can be achieved this way is {text_value_max}. Each Plunging Attack shockwave DMG instance can only apply this increased DMG effect to a single opponent. Each character can trigger this effect once every 0.4s." },
  "xianyun_creations_of_star_and_moon": { title: "Creations of Star and Moon" },
  "xianyun_galefeather_pursuit": { title: "Galefeather Pursuit", description: "Each opponent hit by Driftcloud Waves from White Clouds at Dawn will grant all nearby party members 1 stack of Storm Pinion for 20s. Max 4 stacks. These will cause the characters' Plunging Attack CRIT Rate to increase by {text_percent_1}/{text_percent_2}/{text_percent_3}/{text_percent_4} respectively. Each Storm Pinion created by hitting an opponent has an independent duration." },
  "xianyun_mystery_millet_gourmet": { title: "Mystery Millet Gourmet", description: "After using Skyladder 1/2/3 times during one White Clouds at Dawn Cloud Transmogrification state, when a Driftcloud Wave unleashed during that instance hits an opponent, it will heal all nearby party members for {text_percent_1}/{text_percent_2}/{text_percent_3} of Xianyun's ATK. This effect can be triggered once every 5s." },
  "xianyun_purifying_wind": { title: "Purifying Wind", description: "White Clouds at Dawn gains 1 additional charge." },
  "xianyun_stars_gather_at_dusk": { title: "Stars Gather at Dusk", description: "<p>Brings forth a sacred breeze that deals AoE Anemo DMG and heals all nearby characters based on Xianyun's ATK. It will also summon the \"Starwicker\" mechanism.</p><p>Starwicker ·Continuously follows the active character and periodically heals all nearby party members based on Xianyun's ATK. ·Starts with 8 stacks of Adeptal Assistance. While Adeptal Assistance is active, nearby active characters in the party will have their jump height increased. ·When the active character completes a Plunging Attack, Starwicker will consume 1 stack of Adeptal Assistance and deal AoE Anemo DMG. Only 1 Starwicker can exist simultaneously.</p><p><i>This is the newest invention in the \"Lunastar Artifices\" series, of which previous creations include the Supreme Cuisine Machine, the Snowdrift Mechanism, the Supreme Housekeeping Machine, the Floating Toting Device, and the Bloom Pruner. This series was intended for young humans Cloud Retainer held in great esteem, and so was not designed with a certain half-adeptus in mind. However, when offered Starwicker, a certain female disciple of hers had these emotionless words to say: \"No thank you.\" Cloud Retainer thus had no choice but to keep it herself.</i></p>" },
  "xianyun_they_call_her_cloud_retainer": { title: "They Call Her Cloud Retainer", description: "After Xianyun uses 1/2/3 Skyladders within one Cloud Transmogrification caused by White Clouds at Dawn, the CRIT DMG of a Driftcloud Wave created in this instance of Cloud Transmogrification will be increased by {text_percent_1}/{text_percent_2}/{text_percent_3}. Within 16s after Xianyun has used Stars Gather at Dusk, White Clouds at Dawn will not enter CD. This effect will be canceled once she has used White Clouds at Dawn 8 times." },
  "xianyun_white_clouds_at_dawn": { title: "White Clouds at Dawn", description: "<p>Xianyun enters the Cloud Transmogrification state, in which she will not take Fall DMG, and uses Skyladder once. In this state, her Plunging Attack will be converted into Driftcloud Wave instead, which deals AoE Anemo DMG and ends the Cloud Transmogrification state. This DMG is considered Plunging Attack DMG. Each use of Skyladder while in this state increases the DMG and AoE of the next Driftcloud Wave used.</p><p>Skyladder Can be used while in mid-air. Xianyun leaps forward, dealing Anemo DMG to targets along her path. During each Cloud Transmogrification state Xianyun enters, Skyladder may be used up to 3 times and only 1 instance of Skyladder DMG can be dealt to any one opponent. If Skyladder is not used again in a short period, the Cloud Transmogrification state will be canceled.</p><p>If Xianyun does not use Driftcloud Wave while in this state, the next CD of White Clouds at Dawn will be decreased by 3s.</p><p><i>Do not shake Cloud Retainer's hand too tightly; cranes are quite adept at gripping.</i></p>" },
  "xianyun_word_of_wind_and_flower": { title: "Word of Wind and Flower", description: "<p>Normal Attack Summons swirling winds to perform up to 4 attacks, dealing Anemo DMG.</p><p>Charged Attack Consumes a certain amount of Stamina and launches a Breeze Bolt in a straight line that deals Anemo DMG to opponents along its path.</p><p>Plunging Attack Gathers the power of Anemo and plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Anemo DMG upon impact with the ground.</p>" },
  "xiao_bane_of_all_evil": { title: "Bane of All Evil", description: "<p>Xiao dons the Yaksha Mask that set gods and demons trembling millennia ago.</p><p>Yaksha's Mask ·Greatly increases Xiao's jumping ability. ·Increases his attack AoE and attack DMG. ·Converts attack DMG into Anemo DMG, which cannot be overridden by any other elemental infusion.</p><p>In this state, Xiao will continuously lose HP. The effects of this skill end when Xiao leaves the field.</p><p><i>Donning the Mask of the Yaksha, Xiao takes the terrifying, demon-conquering form of the Vigilant Yaksha. But this great power has also brought him great suffering. Some call him \"The Bane of All Evil.\"</i></p>" },
  "xiao_blossom_of_kaleidos": { title: "Annihilation Eon: Blossom of Kaleidos", description: "When in the party and not on the field, Xiao's Energy Recharge is increased by {recharge}." },
  "xiao_destroyer_of_worlds": { title: "Dissolution Eon: Destroyer of Worlds", description: "Increases Lemniscatic Wind Cycling's charges by 1." },
  "xiao_extinction_of_suffering": { title: "Transcension: Extinction of Suffering", description: "When Xiao's HP falls below {text_percent_hp}, he gains a {def_percent} DEF Bonus." },
  "xiao_guardian_yaksha": { title: "Conqueror of Evil: Guardian Yaksha", description: "While under the effects of Bane of All Evil, hitting at least 2 opponents with Xiao's Plunging Attack will immediately grant him 1 charge of Lemniscatic Wind Cycling, and for the next 1s, he may use Lemniscatic Wind Cycling while ignoring its CD." },
  "xiao_heaven_fall": { title: "Dissolution Eon: Heaven Fall", description: "Using Lemniscatic Wind Cycling increases the DMG of subsequent uses of Lemniscatic Wind Cycling by {dmg_skill_xiao}. This effect lasts for 7s, and has a maximum of 3 stacks. Gaining a new stack refreshes the effect's duration." },
  "xiao_lemniscatic_wind_cycling": { title: "Lemniscatic Wind Cycling", description: "<p>Xiao lunges forward, dealing Anemo DMG to opponents in his path. Can be used in mid-air. Starts with 2 charges.</p><p><i>According to the legends of another land, the world will someday be crushed by two great wind wheels. Xiao's mastery over polearms is transcendent, ripping his foes apart like those legendary wind wheels.</i></p>" },
  "xiao_origin_of_ignorance": { title: "Evolution Eon: Origin of Ignorance" },
  "xiao_tamer_of_demons": { title: "Conqueror of Evil: Tamer of Demons", description: "While under the effects of Bane of All Evil, all DMG dealt by Xiao increases by {dmg_all}. DMG increases by a further {dmg_all} for every 3s the ability persists. The maximum DMG Bonus is 25%." },
  "xiao_whirlwind_thrust": { title: "Whirlwind Thrust", description: "<p>Normal Attack Performs up to 6 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to perform an upward thrust.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact. Xiao does not take DMG from performing Plunging Attacks.</p>" },
  "xiao_wrath_deity": { title: "Conqueror of Evil: Wrath Deity" },
  "xiao_yaksha_mask": { title: "Yaksha's Mask", description: "• Greatly increases Xiao's jumping ability. • Increases his attack AoE and attack DMG. • Converts attack DMG into Anemo DMG, which cannot be overridden by any other elemental infusion." },
  "xilonen_chiucue_mix": { title: "Chiucue Mix", description: "Xilonen's Geo Source Samples will always remain active. Additionally, when her Source Samples activate, all nearby party members will gain effects corresponding to the active Source Sample that matches their Elemental Type: ·Geo: DMG dealt +{text_percent_geo}. ·Pyro: ATK +{text_percent_pyro}. ·Hydro: Max HP +{text_percent_hydro}. ·Cryo: CRIT DMG +{text_percent_cryo}. ·Electro: Restore 25 Energy, decrease Elemental Burst CD by 6s." },
  "xilonen_ehecatls_roar": { title: "Ehecatl's Roar", description: "<p>Normal Attack Performs up to 3 rapid strikes.</p><p>Charged Attack Consumes a fixed amount of Stamina and performs a forward kick.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact, both based on Xilonen's DEF.</p><p>Nightsoul's Blessing: Blade Roller When in the Nightsoul's Blessing state, Xilonen will enter the Blade Roller mode. While in this mode, Xilonen's Normal Attacks will allow her to perform up to 4 kicks using her roller blades, and she will be unable to use Charged Attacks. When her Normal and Plunging Attacks are used in this mode, they will switch to being based on her DEF, and Xilonen will deal Nightsoul-aligned Geo DMG that cannot be overridden.</p>" },
  "xilonen_imperishable_night_carnival": { title: "Imperishable Night Carnival", description: "When Xilonen is in the Nightsoul's Blessing state, when she sprints, leaps, or uses Normal or Plunging Attacks, she will gain Imperishable Night's Blessing, ignoring the limitations of her Nightsoul's Blessing state and increasing the DMG dealt by her Normal and Plunging Attacks for 5s. During this time: ·Her Nightsoul's Blessing time limit countdown will be paused. Xilonen's Nightsoul points, Phlogiston, and Stamina will not decrease, and when her Nightsoul points reach the maximum, her Nightsoul's Blessing state will not end either. ·Xilonen deals {normal_base_def_percent} of her DEF as increased Normal and Plunging Attack DMG while in the Nightsoul's Blessing state. ·She heals nearby party members for {text_percent_heal} of her DEF every 1.5s. She can gain 1 Imperishable Night's Blessing once every 15s." },
  "xilonen_netotiliztlis_echoes": { title: "Netotiliztli's Echoes" },
  "xilonen_netotiliztlis_echoes_1": { description: "While in the Nightsoul's Blessing state: If Xilonen has at least 2 Source Samples that have had their Elemental Types changed, she gains 35 Nightsoul points when her Normal or Plunging Attacks hit opponents. Can be triggered once every 0.1s." },
  "xilonen_netotiliztlis_echoes_2": { description: "While in the Nightsoul's Blessing state: If Xilonen has fewer than 2 Source Samples that have had their Elemental Types changed, her Normal and Plunging Attacks deal {dmg_normal} increased DMG." },
  "xilonen_ocelotlicue_point": { title: "Ocelotlicue Point!", description: "<p>Activates the Phlogiston Stereo DJ Controller (Portable) at full power, dealing Nightsoul-aligned AoE Geo DMG based on Xilonen's DEF.</p><p>Additionally, she will trigger the following effects based on her different Source Samples: ·If she has at least 2 Source Samples that have had their Elemental Types changed, Xilonen will play an Ebullient rhythm, healing nearby active characters at intervals based on her DEF. ·If she has fewer than 2 Source Samples that have had their Elemental Types changed, Xilonen will start up an Ardent rhythm, which will play two additional beats that deal Nightsoul-aligned AoE Geo DMG based on her DEF.</p><p><i>\"Alright, time for a time-out!\" \"It's cool, I recorded those beats just now. Let's see what we get when we mix our rhythms!\"</i></p>" },
  "xilonen_portable_armored_sheath": { title: "Portable Armored Sheath", description: "While in the Nightsoul's Blessing state, when Xilonen's Nightsoul points reach the maximum, she will trigger an effect equal to that of her Nightsoul Burst. This effect can be triggered once every 14s. Additionally, when nearby party members trigger a Nightsoul Burst, Xilonen's DEF is increased by {def_percent} for 15s." },
  "xilonen_sabbatical_phrase": { title: "Sabbatical Phrase", description: "Xilonen's Nightsoul point and Phlogiston consumption in her Nightsoul's Blessing state is decreased by 30%, and her Nightsoul point time limit is extended by 45%. Additionally, when Xilonen's Source Samples are active, she can also increase nearby active characters' interruption resistance." },
  "xilonen_suchitls_trance": { title: "Suchitl's Trance", description: "After Xilonen uses Yohual's Scratch, she will grant all nearby party members the Blooming Blessing effect for 15s. Characters with Blooming Blessing deal {text_percent_dmg} of Xilonen's DEF as increased Normal, Charged, and Plunging Attack DMG. This effect will be removed after triggering 6 times or when the duration ends. When you hit more than one opponent, trigger counts will be consumed based on the number of opponents hit. The counts for each party member with Blooming Blessing are counted independently." },
  "xilonen_tlaltecuhtlis_crossfade": { title: "Tlaltecuhtli's Crossfade" },
  "xilonen_tonalpohuallis_loop": { title: "Tonalpohualli's Loop" },
  "xilonen_yohuals_scratch": { title: "Yohual's Scratch", description: "<p>Let the rhythms of passion resound throughout the land! Xilonen switches to high-speed combat blading gear and rushes forward a certain distance before dealing Nightsoul-aligned Geo DMG based on her DEF. After using this, Xilonen will gain 45 Nightsoul points and enter the Nightsoul's Blessing state. In this state, she will shift to the Blade Roller mode.</p><p>Source Samples Xilonen has 3 Samplers with her that can generate different Soundscapes based on her other party members' Elemental Types, decreasing nearby opponents' corresponding Elemental RES while active. The initial recorded Source Sample within each Sampler will be Geo, and for each party member who is Pyro/Hydro/Cryo/Electro, 1 Geo Sample will change to that corresponding Element. While Xilonen is in the Nightsoul's Blessing state, the Geo Source Sample she carries will always be active. After unlocking her Passive Talent, \"Netotiliztli's Echoes,\" Xilonen can trigger said Passive Talent's effects to regenerate Nightsoul points for herself. When her Nightsoul points hit the maximum, she will consume all her Nightsoul points and activate the 3 Source Samples she has on hand for 15s. When the Source Samples are active, nearby opponents' corresponding Elemental RES will decrease. Source Sample effects of the same Elemental Type cannot stack. Xilonen can trigger these effects even when off-field.</p><p>Nightsoul's Blessing: Xilonen Continuously consume Nightsoul points. When these points are depleted or if used again, this Nightsoul's Blessing state will end. This state has the following traits: ·Switches to the Blade Roller mode, increasing Xilonen's Movement SPD and climbing speed, and she can perform high-speed leaps in Ocelot Form while climbing. ·Xilonen's Nightsoul's Blessing has the following restrictions: When in this state, Xilonen's Nightsoul points have a 9s time limit. After this limit passes, her Nightsoul points will immediately expire.</p><p>After Xilonen's Nightsoul points have expired while she is in the Nightsoul's Blessing state, she will no longer be able to generate Nightsoul points via the Passive Talent \"Netotiliztli's Echoes.\"</p><p><i>In some ways, gem-craft and music-mixing share similar principles: Filtering out impurities and retaining only the most radiant things. Xilonen isn't picky about the two, however. She enjoys both immensely, after all!</i></p>" },
  "xingqiu_blades_amidst_raindrops": { title: "Blades Amidst Raindrops", description: "Xingqiu gains a {dmg_hydro} Hydro DMG Bonus." },
  "xingqiu_embrace_of_rain": { title: "Embrace of Rain" },
  "xingqiu_evilsoother": { title: "Evilsoother", description: "Throughout the duration of Guhua Sword: Raincutter, the DMG dealt by Guhua Sword: Fatal Rainscreen is increased by {text_percent}." },
  "xingqiu_fatal_rainscreen": { title: "Guhua Sword: Fatal Rainscreen", description: "<p>Xingqiu performs twin strikes with his sword, dealing Hydro DMG. At the same time, this ability creates the maximum number of Rain Swords, which will orbit your active character. The Rain Swords have the following properties: ·When a character takes DMG, the Rain Sword will shatter, reducing the amount of DMG taken. ·Increases the character's resistance to interruption.</p><p>20% of Xingqiu's Hydro DMG Bonus will be converted to additional DMG Reduction for the Rain Swords.</p><p>The maximum amount of additional DMG Reduction that can be gained this way is 24%. The initial maximum number of Rain Swords is 3. Using this ability applies the Wet status onto the character.</p><p><i>\"Easier to slay a rain dragon than to sever the rain.\"</i></p>" },
  "xingqiu_guhua_style": { title: "Guhua Style", description: "<p>Normal Attack Performs up to 5 rapid strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to unleash 2 rapid sword strikes.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "xingqiu_hence_call_them_my_own_verses": { title: "Hence, Call Them My Own Verses", description: "Activating 2 of Guhua Sword: Raincutter's sword rain attacks greatly enhances the third sword rain attack. On hit, the third sword rain attack also regenerates 3 Energy for Xingqiu." },
  "xingqiu_hydropathic": { title: "Hydropathic", description: "When a Rain Sword is shattered or when its duration expires, it regenerates the current character's HP based on 6% of Xingqiu's Max HP." },
  "xingqiu_rainbow_upon_the_azure_sky": { title: "Rainbow Upon the Azure Sky" },
  "xingqiu_rainbow_upon_the_azure_sky_1": { description: "Extends the duration of Guhua Sword: Raincutter by 3s." },
  "xingqiu_rainbow_upon_the_azure_sky_2": { description: "Decreases the Hydro RES of opponents hit by sword rain attacks by {enemy_res_hydro} for 4s." },
  "xingqiu_raincutter": { title: "Guhua Sword: Raincutter", description: "<p>Initiate Rainbow Bladework and fight using an illusory sword rain, while creating the maximum number of Rain Swords.</p><p>Rainbow Bladework ·Your active character's Normal Attacks will trigger consecutive sword rain attacks, dealing Hydro DMG. ·Rain Swords will remain at the maximum number throughout the ability's duration.</p><p><i>The \"Way of the Rain Cutter\" is one of the esoteric secret techniques of the Guhua Sect.</i></p>" },
  "xingqiu_the_scent_remained": { title: "The Scent Remained", description: "Increases the maximum number of Rain Swords by 1." },
  "xingqiu_weaver_of_verses": { title: "Weaver of Verses" },
  "xinyan_dance_on_fire": { title: "Dance on Fire", description: "<p>Normal Attack Performs up to 4 consecutive strikes.</p><p>Charged Attack Drains Stamina over time to perform continuous spinning attacks against all nearby opponents. At the end of the sequence, performs a more powerful slash. </p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "xinyan_double_stop": { title: "Double-Stop" },
  "xinyan_fatal_acceleration": { title: "Fatal Acceleration", description: "Upon scoring a CRIT Hit, increases ATK SPD of Xinyan's Normal and Charged Attacks by {atk_speed_normal} for 5s. Can only occur once every 5s." },
  "xinyan_impromptu_opening": { title: "Impromptu Opening", description: "Riff Revolution's Physical DMG has its CRIT Rate increased by 100%, and will form a shield at Shield Level 3: Rave when cast." },
  "xinyan_now_thats_rock_n_roll": { title: "\"...Now That's Rock 'N' Roll!\"", description: "Characters shielded by Sweeping Fervor deal {dmg_phys} increased Physical DMG." },
  "xinyan_riff_revolution": { title: "Riff Revolution", description: "<p>Strumming rapidly, Xinyan launches nearby opponents and deals Physical DMG to them, hyping up the crowd. The sheer intensity of the atmosphere will cause explosions that deal Pyro DMG to nearby opponents.</p><p><i>Xinyan used to end all her performances with this move. She didn't stop because it was dangerous, however, but because she didn't have a more epic finale in case someone shouted \"Encore!\"</i></p>" },
  "xinyan_rockin_in_a_flaming_world": { title: "Rockin' in a Flaming World", description: "Decreases the Stamina Consumption of Xinyan's Charged Attacks by {text_percent}. Additionally, Xinyan's Charged Attacks gain an ATK Bonus equal to 50% of her DEF." },
  "xinyan_screamin_for_an_encore": { title: "Screamin' for an Encore" },
  "xinyan_sweeping_fervor": { title: "Sweeping Fervor", description: "<p>Xinyan brandishes her instrument, dealing Pyro DMG on nearby opponents, forming a shield made out of her audience's passion. The shield's DMG Absorption scales based on Xinyan's DEF and on the number of opponents hit. ·Hitting 0–1 opponents grants Shield Level 1: Ad Lib. ·Hitting 2 opponents grants Shield Level 2: Lead-In. ·Hitting 3 or more opponents grants Shield Level 3: Rave, which will also deal intermittent Pyro DMG to nearby opponents.</p><p>The shield has the following special properties: ·When unleashed, it infuses Xinyan with Pyro. ·It has 250% DMG Absorption effectiveness against Pyro DMG.</p><p><i>Xinyan insists that these pyrotechnics are the apex of performative art, and that they are physical phenomena that have nothing to do with her Vision.</i></p>" },
  "xinyan_the_show_goes_on_even_without_an_audience": { title: "\"The Show Goes On, Even Without an Audience...\"", description: "Decreases the number of opponents Sweeping Fervor must hit to trigger each level of shielding. ·Shield Level 2: Lead-In requirement reduced to 1 opponent hit. ·Shield Level 3: Rave requirement reduced to 2 opponents hit or more." },
  "xinyan_wildfire_rhythm": { title: "Wildfire Rhythm", description: "Sweeping Fervor's swing DMG decreases opponent's Physical RES by {enemy_res_phys} for 12s." },
  "yae_miko_daisesshou": { title: "Forbidden Art: Daisesshou", description: "The Sesshou Sakura's attacks will ignore {enemy_def_ignore_skill} of the opponents' DEF." },
  "yae_miko_enlightened_blessing": { title: "Enlightened Blessing", description: "Every point of Elemental Mastery Yae Miko possesses will increase Sesshou Sakura DMG by {text_percent}." },
  "yae_miko_foxs_mooncall": { title: "Fox's Mooncall", description: "Sesshou Sakura start at Level 2 when created, their max level is increased to 4, and their attack range is increased by {text_percent}." },
  "yae_miko_mischievous_teasing": { title: "Mischievous Teasing" },
  "yae_miko_sakura_channeling": { title: "Sakura Channeling", description: "When Sesshou Sakura lightning hits opponents, the Electro DMG Bonus of all nearby party members is increased by {dmg_electro} for 5s." },
  "yae_miko_sesshou_sakura": { title: "Yakan Evocation: Sesshou Sakura", description: "<p>To Yae, such dull tasks as can be accomplished by driving spirits out need not be done personally. Moves swiftly, leaving a Sesshou Sakura behind.</p><p>Sesshou Sakura Has the following properties: · Periodically strikes one nearby opponent with lightning, dealing Electro DMG · When there are other Sesshou Sakura nearby, their level will increase, boosting the DMG dealt by these lightning strikes.</p><p>This skill has three charges. A maximum of 3 Sesshou Sakura can exist simultaneously. The initial level of each Sesshou Sakura is 1, and the initial highest level each sakura can reach is 3. If a new Sesshou Sakura is created too close to an existing one, the existing one will be destroyed.</p><p><i>\"The kitsune spirits sealed in the branches are all yakan who stooped to preying upon humans. The yakan are two grades lower than us Sky Kitsune, and so, I hardly see the problem with... asking that they do my bidding. Now, this doesn't mean that you humans should go learning from our grading systems, no indeed — and as for which of us, kitsune or human, is higher up in the pecking order... Heh, wouldn't you like to know?\"</i></p>" },
  "yae_miko_spiritfox_sin_eater": { title: "Spiritfox Sin-Eater", description: "<p>Normal Attack Summons forth kitsune spirits, initiating a maximum of 3 attacks that deal Electro DMG.</p><p>Charged Attack Consumes a certain amount of Stamina to deal AoE Electro DMG after a short casting time.</p><p>Plunging Attack Plunges towards the ground from mid-air, damaging all opponents in her path with thunderous might. Deals AoE Electro DMG upon impact with the ground.</p>" },
  "yae_miko_tenko_kenshin": { title: "Great Secret Art: Tenko Kenshin", description: "<p>Legends of \"kitsunetsuki,\" or the manifestation of a kitsune's might, are common in Inazuma's folktales. One that particularly captures the imagination is that of the Sky Kitsune, said to cause lightning to fall down upon the foes of the Grand Narukami Shrine. Summons a lightning strike, dealing AoE Electro DMG. When she uses this skill, Yae Miko will unseal nearby Sesshou Sakura, destroying their outer forms and transforming them into Tenko Thunderbolts that descend from the skies, dealing AoE Electro DMG. Each Sesshou Sakura destroyed in this way will create one Tenko Thunderbolt.</p><p><i>Only at times like these will Yae reveal her Sky Kitsune form and wield lightning itself. None have seen the Lady Guuji's tails and lived to tell the story... so remember, as far as you are concerned, Lady Yae does not have a tail.</i></p>" },
  "yae_miko_the_seven_glamours": { title: "The Seven Glamours" },
  "yae_miko_the_shrines_sacred_shade": { title: "The Shrine's Sacred Shade", description: "When casting Great Secret Art: Tenko Kenshin, each Sesshou Sakura destroyed resets the cooldown for 1 charge of Yakan Evocation: Sesshou Sakura." },
  "yae_miko_yakan_offering": { title: "Yakan Offering", description: "Each time Great Secret Art: Tenko Kenshin activates a Tenko Thunderbolt, Yae Miko will restore 8 Elemental Energy for herself." },
  "yanfei_abiding_affidavit": { title: "Abiding Affidavit" },
  "yanfei_blazing_eye": { title: "Blazing Eye", description: "When Yanfei's Charged Attack deals a CRIT Hit to opponents, she will deal an additional instance of AoE Pyro DMG equal to {text_percent_dmg} of her ATK. This DMG counts as Charged Attack DMG." },
  "yanfei_brilliance": { title: "Brilliance", description: "Has the following effects: • Grants Yanfei a Scarlet Seal at fixed intervals. • Increases the DMG dealt by her Charged Attacks." },
  "yanfei_done_deal": { title: "Done Deal", description: "<p>Triggers a spray of intense flames that rush at nearby opponents, dealing AoE Pyro DMG, granting Yanfei the maximum number of Scarlet Seals, and applying Brilliance to her.</p><p>Brilliance Has the following effects: ·Grants Yanfei a Scarlet Seal at fixed intervals. ·Increases the DMG dealt by her Charged Attacks. The effects of Brilliance will end if Yanfei leaves the field or falls in battle.</p><p><i>\"Here are the full terms for this matter of life and death — by which I mean my life and your death!\"</i></p>" },
  "yanfei_extra_clause": { title: "Extra Clause", description: "Increases the maximum number of Scarlet Seals by 1." },
  "yanfei_proviso": { title: "Proviso", description: "When Yanfei consumes Scarlet Seals by using a Charged Attack, each Scarlet Seal will increase Yanfei's Pyro DMG Bonus by {text_percent_dmg}. This effect lasts for 6s. When a Charged Attack is used again during the effect's duration, it will dispel the previous effect." },
  "yanfei_right_of_final_interpretation": { title: "Right of Final Interpretation", description: "Increases Yanfei's Charged Attack CRIT Rate by {crit_rate_charged} against enemies below {text_percent_hp} HP." },
  "yanfei_samadhi_fire_forged": { title: "Samadhi Fire-Forged" },
  "yanfei_scarlet_seal": { title: "Scarlet Seals", description: "Each Scarlet Seal will decrease Yanfei's Stamina consumption by {stamina_consume} and will disappear when she leaves the field." },
  "yanfei_seal_of_approval": { title: "Seal of Approval", description: "<p>Normal Attack Shoots fireballs that deal up to three counts of Pyro DMG. When Yanfei's Normal Attacks hit enemies, they will grant her a single Scarlet Seal. Yanfei may possess a maximum of 3 Scarlet Seals, and each time this effect is triggered, the duration of currently possessed Scarlet Seals will refresh. Each Scarlet Seal will decrease Yanfei's Stamina consumption and will disappear when she leaves the field.</p><p>Charged Attack Consumes Stamina and all Scarlet Seals before dealing AoE Pyro DMG to opponents after a short casting time. This Charged Attack's AoE and DMG will increase according to the amount of Scarlet Seals consumed.</p><p>Plunging Attack Gathering the power of Pyro, Yanfei plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Pyro DMG upon impact with the ground.</p>" },
  "yanfei_signed_edict": { title: "Signed Edict", description: "<p>Summons blistering flames that deal AoE Pyro DMG. Opponents hit by the flames will grant Yanfei the maximum number of Scarlet Seals.</p><p><i>Apart from their legal uses, Yanfei's seals also come with her customized additional terms and conditions. Well, it's not as if the Ministry of Civil Affairs can change the laws of nature.</i></p>" },
  "yanfei_supreme_amnesty": { title: "Supreme Amnesty", description: "When Done Deal is used: Creates a shield that absorbs up to {text_percent_hp} of Yanfei's Max HP for 15s. This shield absorbs Pyro DMG 250% more effectively." },
  "yanfei_the_law_knows_no_kindness": { title: "The Law Knows No Kindness", description: "When Yanfei uses her Charged Attack, each existing Scarlet Seal additionally reduces the stamina cost of this Charged Attack by {text_percent} and increases resistance against interruption during its release." },
  "yaoyao_adeptal_legacy": { title: "Adeptal Legacy", description: "·Yaoyao's Movement SPD is increased by {move_speed}. ·Yaoyao's Dendro RES will be increased by {res_dendro}." },
  "yaoyao_adeptus_tutelage": { title: "Adeptus' Tutelage", description: "When White Jade Radishes explode, active characters within their AoE will gain {dmg_dendro} Dendro DMG Bonus for 8s and have 15 Stamina restored to them. This form of Stamina Restoration can only be triggered every 5s." },
  "yaoyao_beneficent": { title: "Beneficent", description: "For every 2 White Jade Radishes Yuegui: Throwing Mode throws out, the next throw will also release a Mega Radish that will have a larger AoE than the standard White Jade Radish and have the following effects upon exploding: ·Deals AoE Dendro DMG based on {text_percent_atk} of Yaoyao's ATK. ·Restores HP for the active character based on {text_percent_heal} of Yaoyao's Max HP. Every Yuegui: Throwing Mode can throw out a maximum of 2 Mega Radishes." },
  "yaoyao_compassionate": { title: "Compassionate" },
  "yaoyao_in_others_shoes": { title: "In Others' Shoes", description: "When White Jade Radishes explode, active characters within their AoE will regain HP every 1s based on {text_percent_hp} of Yaoyao's Max HP. This effect lasts 5s." },
  "yaoyao_innocent": { title: "Innocent", description: "While affected by the Adeptal Legacy state caused by Moonjade Descent, if White Jade Radish explosions hit opponents, 3 Energy will be restored to Yaoyao. This form of Energy regeneration can occur once every 0.8s." },
  "yaoyao_loyal_and_kind": { title: "Loyal and Kind" },
  "yaoyao_moonjade_descent": { title: "Moonjade Descent", description: "<p>At the enjoinment of a certain adeptus, Yuegui's full potential can be unleashed in an emergency, dealing Dendro DMG to nearby opponents and entering an (in some sense) unsurpassed Adeptal Legacy state.</p><p>Adeptal Legacy ·White Jade Radishes generated will be changed to heal and deal DMG according to this skill. Explosions will heal all nearby party members, and the Dendro DMG that they deal will be viewed as Elemental Burst DMG instead. ·Summons \"Yuegui: Jumping Mode\" at intervals until their limit has been reached. The behavior of this version of Yuegui is the same as that of \"Yuegui: Throwing Mode\" in the Elemental Skill, Raphanus Sky Cluster. A maximum of 3 Yuegui: Jumping Mode can exist at any one time. ·Yaoyao's Movement SPD is increased by 15%. ·Yaoyao's Dendro RES will be increased.</p><p>The Adeptal Legacy state will end once Yaoyao is off-field, and all remaining Yuegui: Jumping Mode will be cleared once this state ends.</p><p><i>\"Eh? Which one of these is actually Yuegui, you ask? Aren't they all Yuegui?\"</i></p>" },
  "yaoyao_raphanus_sky_cluster": { title: "Raphanus Sky Cluster", description: "<p>Calls upon \"Yuegui: Throwing Mode,\" a special device created by a certain adeptus to help Yaoyao solve her problems. This skill will be used differently in Holding Mode.</p><p>Hold Enters Aiming Mode to adjust the throw direction.</p><p>Yuegui: Throwing Mode Throws out White Jade Radishes that will explode upon hitting characters or opponents, dealing Dendro DMG to opponents within a certain AoE, and healing characters within that same AoE based on Yaoyao's Max HP. If a radish does not hit either an opponent or a character, the radish will remain where it is and explode on contact with a character or opponent, or will explode after its duration expires. Yuegui: Throwing Mode will choose its radish-throw targets. ·If all nearby characters have more than 70% HP remaining, then it will throw the radish at a nearby opponent. ·If nearby characters have 70% or less HP remaining, it will throw a radish at the character with the lowest HP percentage remaining. If no opponents exist nearby, Yuegui will also throw White Jade Radishes at characters if they all have more than 70% HP and less than 100% HP remaining. Otherwise, it will throw radishes into the area at random.</p><p>A maximum of 2 instances of Yuegui: Throwing Mode can exist at any one time.</p><p><i>\"A radish a day keeps trouble away! ... Oh, this isn't about a radish's medical properties, exactly, but it does have some health benefits, yeah!\"</i></p>" },
  "yaoyao_starscatter": { title: "Starscatter", description: "While affected by the Adeptal Legacy state caused by Moonjade Descent, Yaoyao will constantly throw White Jade Radishes at nearby opponents when she is sprinting, jumping, or running. She can throw 1 White Jade Radish this way once every 0.6s." },
  "yaoyao_toss_n_turn_spear": { title: "Toss 'N' Turn Spear", description: "<p>Normal Attack Performs up to 4 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "yaoyao_winsome": { title: "Winsome", description: "After using Raphanus Sky Cluster or Moonjade Descent, Yaoyao's Elemental Mastery will be increased based on {text_percent_hp} of her Max HP for 8s. The maximum Elemental Mastery she can gain this way is {text_value_max}." },
  "yelan_adapt_with_ease": { title: "Adapt With Ease", description: "So long as an Exquisite Throw is in play, your own active character deals 1% more DMG. This increases by a further 3.5% DMG every second. The maximum increase to DMG dealt is 50%. The pre-existing effect will be dispelled if Depth-Clarion Dice is recast during its duration." },
  "yelan_bait_and_switch": { title: "Bait-and-Switch", description: "Increases all party members' Max HP by {hp_percent} for 25s for every opponent marked by Lifeline when the Lifeline explodes. A maximum increase of {text_percent_max} Max HP can be attained in this manner." },
  "yelan_beware_the_tricksters_dice": { title: "Beware the Trickster's Dice" },
  "yelan_dealers_sleight": { title: "Dealer's Sleight" },
  "yelan_depth_clarion_dice": { title: "Depth-Clarion Dice", description: "<p>Deals AoE Hydro DMG and creates an \"Exquisite Throw,\" which aids her in battle.</p><p>Exquisite Throw Follows the character around and will initiate a coordinated attack under the following circumstances, dealing Hydro DMG based on Yelan's Max HP: ·Can occur once every second when your active character uses a Normal Attack. ·Will occur each time Yelan's Lifeline explodes and hits opponents.</p><p><i>\"A gambling addiction is going to do you no good. I mean, let me just do the math for you as the dealer. What do you think your odds of beating me are, when I have seven dice and you, only one?\"</i></p>" },
  "yelan_enter_the_plotters": { title: "Enter the Plotters", description: "Lingering Lifeline gains 1 additional charge." },
  "yelan_lingering_lifeline": { title: "Lingering Lifeline", description: "<p>Fires off a Lifeline that allows her to move rapidly, entangling and marking opponents along its path. When this rapid movement ends, the Lifeline will explode, dealing Hydro DMG to the marked opponents based on Yelan's Max HP.</p><p>Tap Moves a certain distance forward swiftly.</p><p>Hold Engages in continuous, swift movement, during which Yelan's resistance to interruption is increased. During this time, Yelan can control this rapid movement and end it by using this Skill again.</p><p>Additionally, each opponent marked by the Lifeline when it explodes grants Yelan a 34% chance to reset her Breakthrough state.</p><p><i>Not until she begins to tug on the strings do evildoers, crooks, and scheming villains alike know that there is no escape.</i></p>" },
  "yelan_stealthy_bowshot": { title: "Stealthy Bowshot", description: "<p>Normal Attack Performs up to 4 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, flowing water will accumulate on the arrowhead. A fully charged torrential arrow will deal Hydro DMG.</p><p>Breakthrough Yelan will enter a \"Breakthrough\" state after spending 5s out of combat, which will cause her next Charged Aimed Shot to have 80% decreased charge time, and once charged, she can fire a \"Breakthrough Barb\" that will deal AoE Hydro DMG based on Yelan's Max HP.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "yelan_taking_all_comers": { title: "Taking All Comers", description: "When Exquisite Throw conducts a coordinated attack, it will fire an additional water arrow that will deal {text_percent} of Yelan's Max HP as Hydro DMG. This effect can trigger once every 1.8s." },
  "yelan_turn_control": { title: "Turn Control", description: "When the party has 1/2/3/4 Elemental Types, Yelan's Max HP is increased by 6/12/18/30%." },
  "yelan_winner_takes_all": { title: "Winner Takes All", description: "After using Depth-Clarion Dice, Yelan will enter the Mastermind state. In this state, all of Yelan's Normal Attacks will be special Breakthrough Barbs. These Breakthrough Barbs will have similar abilities to normal ones and the DMG dealt will be considered Charged Attack DMG, dealing {text_percent} of a normal Breakthrough Barb's DMG. The Mastermind state lasts 20s and will be cleared after Yelan fires 5 arrows." },
  "yoimiya_a_procession_of_bonfires": { title: "A Procession of Bonfires", description: "When Yoimiya's Pyro DMG scores a CRIT Hit, Yoimiya will gain a {dmg_pyro} Pyro DMG Bonus for 6s. This effect can be triggered even when Yoimiya is not the active character." },
  "yoimiya_a_summer_festivals_eve": { title: "A Summer Festival's Eve" },
  "yoimiya_agate_ryuukin": { title: "Agate Ryuukin", description: "The Aurous Blaze created by Ryuukin Saxifrage lasts for an extra 4s. Additionally, when an opponent affected by Aurous Blaze is defeated within its duration, Yoimiya's ATK is increased by {atk_percent} for 20s." },
  "yoimiya_firework_flare_up": { title: "Firework Flare-Up", description: "<p>Normal Attack Performs up to 5 consecutive shots with a bow.</p><p>Charged Attack Performs a more precise Aimed Shot with increased DMG. While aiming, flames will accumulate on the arrowhead before being fired off as an attack. Has different effects based on how long the energy has been charged: ·Charge Level 1: Fires off a flaming arrow that deals Pyro DMG. ·Charge Level 2: Generates a maximum of 3 Kindling Arrows based on time spent charging, releasing them as part of this Aimed Shot. Kindling Arrows will home in on nearby opponents, dealing Pyro DMG on hit.</p><p>Plunging Attack Fires off a shower of arrows in mid-air before falling and striking the ground, dealing AoE DMG upon impact.</p>" },
  "yoimiya_naganohara_meteor_swarm": { title: "Naganohara Meteor Swarm", description: "During Niwabi Fire-Dance, Yoimiya's Normal Attacks have a {text_percent_chance} chance of firing an extra Blazing Arrow that deals {text_percent_dmg} of its original DMG. This DMG is considered Normal Attack DMG." },
  "yoimiya_niwabi_fire_dance": { title: "Niwabi Fire-Dance", description: "<p>Yoimiya waves a sparkler and causes a ring of saltpeter to surround her.</p><p>Niwabi Enshou During this time, arrows fired by Yoimiya's Normal Attack will be Blazing Arrows, and their DMG will be increased and converted to Pyro DMG. During this time, Normal Attack: Firework Flare-Up will not generate Kindling Arrows at Charge Level 2.</p><p>This effect will deactivate when Yoimiya leaves the field.</p><p><i>\"Niwabi\" is a form of incense firework created by Yoimiya herself. Its ability to be lit without any prior training or preparation has made it a real hit. After many fire-related incidents, the Tenryou Commission ordered the use of \"Niwabi\" banned, but small, bright sparks can often still be seen springing up at night. If seen from above, they look almost like little twinkling stars.</i></p>" },
  "yoimiya_pyrotechnic_professional": { title: "Pyrotechnic Professional", description: "When Yoimiya's own Aurous Blaze triggers an explosion, Niwabi Fire-Dance's CD is decreased by 1.2s." },
  "yoimiya_ryuukin_saxifrage": { title: "Ryuukin Saxifrage", description: "<p>Yoimiya leaps into the air along with her original creation, the \"Ryuukin Saxifrage,\" and fires forth blazing rockets bursting with surprises that deal AoE Pyro DMG and mark one of the hit opponents with Aurous Blaze.</p><p>Aurous Blaze All Normal/Charged/Plunging Attacks, Elemental Skills, and Elemental Bursts by any party member other than Yoimiya that hit an opponent marked by Aurous Blaze will trigger an explosion, dealing AoE Pyro DMG. When an opponent affected by Aurous Blaze is defeated before its duration expires, the effect will pass on to another nearby opponent, who will inherit the remaining duration.</p><p>One Aurous Blaze explosion can be triggered every 2s. When Yoimiya is down, Aurous Blaze effects created through her skills will be deactivated.</p><p><i>Fireworks are man-made starlight, comets fired into the sky. Though they last for but an instant, the memory of their brilliance shall surely live on.</i></p>" },
  "yoimiya_summer_nights_dawn": { title: "Summer Night's Dawn" },
  "yoimiya_summer_nights_dawn_1": { description: "Using Ryuukin Saxifrage causes nearby party members (not including Yoimiya) to gain a {text_percent} ATK increase for 15s. Additionally, a further ATK Bonus will be added on based on the number of \"Tricks of the Trouble-Maker\" stacks Yoimiya possesses when using Ryuukin Saxifrage. Each stack increases this ATK Bonus by {text_percent_2}." },
  "yoimiya_summer_nights_dawn_2": { description: "Using Ryuukin Saxifrage causes nearby party members (not including Yoimiya) to gain a {text_percent} ATK increase for 15s." },
  "yoimiya_summer_nights_dawn_3": { description: "Additionally, a further ATK Bonus will be added on based on the number of \"Tricks of the Trouble-Maker\" stacks Yoimiya possesses when using Ryuukin Saxifrage. Each stack increases this ATK Bonus by {text_percent_2}." },
  "yoimiya_teika_enshou": { title: "Niwabi Enshou", description: "During this time, arrows fired by Yoimiya's Normal Attack will be Blazing Arrows, and their DMG will be increased and converted to Pyro DMG. During this time, Normal Attack: Firework Flare-Up will not generate Kindling Arrows at Charge Level 2. This effect will deactivate when Yoimiya leaves the field." },
  "yoimiya_tricks_of_the_trouble_maker": { title: "Tricks of the Trouble-Maker", description: "During Niwabi Fire-Dance, shots from Yoimiya's Normal Attack will increase her Pyro DMG Bonus by {dmg_pyro} on hit. This effect lasts for 3s and can have a maximum of 10 stacks." },
  "yoimiya_tricksters_flare": { title: "Trickster's Flare" },
  "yumemizuki_mizuki_aisa_utamakura_pilgrimage": { title: "Aisa Utamakura Pilgrimage", description: "<p>Weaves memories of lovely dreams, entering a Dreamdrifter state where Yumemizuki Mizuki floats above the ground, and dealing 1 instance of AoE Anemo DMG to nearby opponents.</p><p>Dreamdrifter ·While in the Dreamdrifter state, Yumemizuki Mizuki will continuously drift forward, dealing AoE Anemo DMG to nearby opponents at regular intervals. ·During this time, Yumemizuki Mizuki can control her direction of drift, and the pick-up distance of Yumemi Style Special Snacks from the Elemental Burst Anraku Secret Spring Therapy will be increased. ·Increases the Swirl DMG that nearby party members deal based on Yumemizuki Mizuki's Elemental Mastery. ·Dreamdrifter will end when Mizuki leaves the field or uses her Elemental Skill again.</p><p><i>\"Our dreams touch at midnight, their song ringing on in our hearts.\"</i></p>" },
  "yumemizuki_mizuki_anraku_secret_spring_therapy": { title: "Anraku Secret Spring Therapy", description: "<p>Summons forth countless lovely dreams and nightmares that pull in nearby objects and opponents, dealing AoE Anemo DMG and summoning a Mini Baku.</p><p>Mini Baku: Follows the current active character. At regular intervals, the Mini Baku will create 1 Yumemi Style Special Snack nearby. After one of your own party members picks up a Special Snack, if their HP is higher than 70%, the Snack will explode and unleash a Munen Shockwave, dealing 1 instance of AoE Anemo DMG to nearby opponents. Otherwise, it will heal the character who picked it up based on Yumemizuki Mizuki's Elemental Mastery. When Yumemizuki Mizuki triggers healing by picking up a Yumemi Style Special Snack, the amount of healing is increased by 100%. If a Snack is not picked up after a period of time, it will explode and release a Munen Shockwave, dealing 1 instance of AoE Anemo DMG to surrounding opponents.</p><p><i>\"If you bury dark emotions for too long, they will become nightmares. With that in mind, why don't we turn them into 'delicious snacks' while we've got the time?\"</i></p>" },
  "yumemizuki_mizuki_as_setting_moon_brings_years_end": { title: "As Setting Moon Brings Year's End" },
  "yumemizuki_mizuki_bright_moons_restless_voice": { title: "Bright Moon's Restless Voice", description: "When Yumemizuki Mizuki triggers Swirl while in her Dreamdrifter state, Dreamdrifter's duration increases by 2.5s. This effect can trigger once every 0.3s for a maximum of 2 times per Dreamdrifter state." },
  "yumemizuki_mizuki_buds_warm_lucid_springs": { title: "Buds Warm Lucid Springs", description: "Picking up a Yumemi Style Special Snack from the Elemental Burst Anraku Secret Spring Therapy will both deal DMG and heal, and will restore 5 Energy to Yumemizuki Mizuki. Energy can be restored this way 4 times per Anraku Secret Spring Therapy duration." },
  "yumemizuki_mizuki_in_mist_like_waters": { title: "In Mist-Like Waters", description: "When Yumemizuki Mizuki is in the Dreamdrifter state, she will continuously apply the \"Twenty-Three Nights' Awaiting\" effect to nearby opponents for 3s every 3.5s. When an opponent is affected by Anemo DMG-triggered Swirl reactions while the aforementioned effect is active, the effect will be canceled and this Swirl instance has its DMG against this opponent increased by {text_percent_dmg} of Mizuki's Elemental Mastery." },
  "yumemizuki_mizuki_pure_heart_pure_dreams": { title: "Pure Heart, Pure Dreams", description: "<p>Normal Attack Performs up to 3 attacks, dealing Anemo DMG.</p><p>Charged Attack Consumes a certain amount of Stamina and deals AoE Anemo DMG after a short casting time.</p><p>Plunging Attack Calling upon the power of Anemo, she plunges towards the ground from mid-air, damaging all opponents in her path. Deals AoE Anemo DMG upon impact with the ground.</p>" },
  "yumemizuki_mizuki_the_heart_lingers_long": { title: "The Heart Lingers Long", description: "While Yumemizuki Mizuki is in the Dreamdrifter state, Swirl DMG dealt by nearby party members can score CRIT Hits, with CRIT Rate fixed at {crit_rate_swirl}, and CRIT DMG fixed at {crit_dmg_swirl}." },
  "yumemizuki_mizuki_thoughts_by_day_bring_dreams_by_night": { title: "Thoughts by Day Bring Dreams by Night", description: "While Yumemizuki Mizuki is in the Dreamdrifter state, when other nearby party members hit opponents with Pyro, Hydro, Cryo, or Electro attacks, her Elemental Mastery will increase by {mastery} for 4s." },
  "yumemizuki_mizuki_till_dawns_moon_ends_night": { title: "Till Dawn's Moon Ends Night" },
  "yumemizuki_mizuki_your_echo_i_meet_in_dreams": { title: "Your Echo I Meet in Dreams", description: "When Yumemizuki Mizuki enters the Dreamdrifter state, every Elemental Mastery point she has will increase all nearby party members' Pyro, Hydro, Cryo, and Electro DMG Bonuses by {text_percent_dmg} until the Dreamdrifter state ends." },
  "yun_jin_breaking_conventions": { title: "Breaking Conventions", description: "The Normal Attack DMG Bonus granted by Flying Cloud Flag Formation is further increased by 2.5/5/7.5/11.5% of Yun Jin's DEF when the party contains characters of 1/2/3/4 Elemental Types, respectively." },
  "yun_jin_cliffbreakers_banner": { title: "Cliffbreaker's Banner", description: "<p>Deals AoE Geo DMG and grants all nearby party members a Flying Cloud Flag Formation.</p><p>Flying Cloud Flag Formation When Normal Attack DMG is dealt to opponents, Bonus DMG will be dealt based on Yun Jin's current DEF.</p><p>The effects of this skill will be cleared after a set duration or after being triggered a specific number of times. When one Normal Attack hits multiple opponents, the effect is triggered multiple times according to the number of opponents hit. The number of times that the effect is triggered is counted independently for each member of the party with Flying Cloud Flag Formation.</p><p><i>As the drums resound, as swords and halberds weave and clash, the doyenne is transformed into a mighty general.</i> <i>As the instruments on stage strum in unison, lo, see how she vanquishes these demons!</i></p>" },
  "yun_jin_cloud_grazing_strike": { title: "Cloud-Grazing Strike", description: "<p>Normal Attack Performs up to 5 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, dealing damage to opponents along the way.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "yun_jin_decorous_harmony": { title: "Decorous Harmony", description: "Characters under the effects of the Flying Cloud Flag Formation have their Normal ATK SPD increased by {text_percent}." },
  "yun_jin_famed_throughout_the_land": { title: "Famed Throughout the Land" },
  "yun_jin_flower_and_a_fighter": { title: "Flower and a Fighter", description: "When Yun Jin triggers the Crystallize Reaction, her DEF is increased by {def_percent} for 12s." },
  "yun_jin_myriad_mise_en_scene": { title: "Myriad Mise-En-Scène", description: "After Cliffbreaker's Banner is unleashed, all nearby party members' Normal Attack DMG is increased by {dmg_normal} for 12s." },
  "yun_jin_opening_flourish": { title: "Opening Flourish", description: "<p>Ms. Yun may just be acting out fights on stage, but her skills with the spear are real enough to defend against her foes.</p><p>Press Flourishes her polearm in a cloud-grasping stance, dealing Geo DMG.</p><p>Hold Takes up the Opening Flourish stance and charges up, forming a shield. DMG Absorption is based on Yun Jin's Max HP and has 150% effectiveness against all Elemental DMG and Physical DMG. The shield lasts until she finishes unleashing her Elemental Skill. When the skill is released, when its duration ends, or when the shield breaks, Yun Jin will unleash the charged energy as an attack, dealing Geo DMG. Based on the time spent charging, it will either unleash an attack at Charge Level 1 or Level 2.</p><p><i>One glorious moment on-stage, a decade of preparation behind it.</i></p>" },
  "yun_jin_seafaring_general": { title: "Seafaring General" },
  "yun_jin_thespian_gallop": { title: "Thespian Gallop", description: "Opening Flourish's CD is decreased by 18%." },
  "yun_jin_true_to_oneself": { title: "True to Oneself", description: "Using Opening Flourish at the precise moment when Yun Jin is attacked will unleash its Level 2 Charged (Hold) form." },
  "yunjin_flag": { title: "Flying Cloud Flag Formation", description: "When Normal Attack DMG is dealt to opponents, Bonus DMG will be dealt based on Yun Jin's current DEF." },
  "zhongli_chrysos_bounty_of_dominator": { title: "Chrysos, Bounty of Dominator", description: "When the Jade Shield takes DMG, {text_percent_dmg} of that incoming DMG is converted to HP for the current character. A single instance of regeneration cannot exceed {text_percent_hp} of that character's Max HP." },
  "zhongli_dominance_of_earth": { title: "Dominance of Earth", description: "Zhongli deals bonus DMG based on his Max HP: ·Normal Attack, Charged Attack, and Plunging Attack DMG is increased by {normal_base_hp_percent} of Max HP. ·Dominus Lapidis' Stone Stele, resonance, and hold DMG is increased by {skill_base_hp_percent} of Max HP. ·Planet Befall's DMG is increased by {burst_base_hp_percent} of Max HP." },
  "zhongli_dominus_lapidis": { title: "Dominus Lapidis", description: "<p>Every mountain, rock and inch of land is filled with the power of Geo, but those who can wield such powers freely are few and far between.</p><p>Press Commands the power of earth to create a Stone Stele.</p><p>Hold Causes nearby Geo energy to explode, causing the following effects: ·If their maximum number hasn't been reached, creates a Stone Stele. ·Creates a shield of jade. The shield's DMG Absorption scales based on Zhongli's Max HP. ·Deals AoE Geo DMG. ·If there are nearby targets with the Geo element, it will drain a large amount of Geo element from a maximum of 2 such targets. This effect does not cause DMG.</p><p>Stone Stele When created, deals AoE Geo DMG. Additionally, it will intermittently resonate with other nearby Geo constructs, dealing Geo DMG to nearby opponents. The Stone Stele is considered a Geo construct that can both be climbed and used to block attacks. Only one Stele created by Zhongli himself may initially exist at any one time.</p><p>Jade Shield Possesses 150% DMG Absorption against all Elemental and Physical DMG. Characters protected by the Jade Shield will decrease the Elemental RES and Physical RES of opponents in a small AoE by 20%. This effect cannot be stacked.</p><p><i>A true master of stone may carve jade and shape gold.</i></p>" },
  "zhongli_jade_shield": { title: "Jade Shield", description: "Characters protected by the Jade Shield will decrease the Elemental RES and Physical RES of opponents in a small AoE by {enemy_res_phys}. This effect cannot be stacked." },
  "zhongli_jade_shimmering_through_darkness": { title: "Jade, Shimmering through Darkness" },
  "zhongli_lazuli_herald_of_the_order": { title: "Lazuli, Herald of the Order" },
  "zhongli_planet_befall": { title: "Planet Befall", description: "<p>Brings a falling meteor down to earth, dealing massive Geo DMG to opponents caught in its AoE and applying the Petrification status to them.</p><p>Petrification Opponents affected by the Petrification status cannot move.</p><p><i>The falling meteor punishes the unjust.</i></p>" },
  "zhongli_rain_of_stone": { title: "Rain of Stone", description: "<p>Normal Attack Performs up to 6 consecutive spear strikes.</p><p>Charged Attack Consumes a certain amount of Stamina to lunge forward, causing stone spears to fall along his path.</p><p>Plunging Attack Plunges from mid-air to strike the ground below, damaging opponents along the path and dealing AoE DMG upon impact.</p>" },
  "zhongli_resonant_waves": { title: "Resonant Waves", description: "When the Jade Shield takes DMG, it will Fortify: ·Fortified characters have {shield} increased Shield Strength. Can stack up to 5 times, and lasts until the Jade Shield disappears." },
  "zhongli_rock_the_backbone_of_earth": { title: "Rock, the Backbone of Earth", description: "Increases the maximum number of Stone Steles created by Dominus Lapidis that may exist simultaneously to 2." },
  "zhongli_stone_the_cradle_of_jade": { title: "Stone, the Cradle of Jade", description: "Planet Befall grants nearby characters on the field a Jade Shield when it descends." },
  "zhongli_topaz_unbreakable_and_fearless": { title: "Topaz, Unbreakable and Fearless", description: "Increases Planet Befall's AoE by 20% and increases the duration of Planet Befall's Petrification effect by 2s." },
};
